window.PIYUT_DATA = {"slots": [{"id": "rh", "he": "ראש השנה"}, {"id": "teshuva", "he": "עשרת ימי תשובה"}, {"id": "selichot", "he": "סליחות (יום לא צוין)"}, {"id": "yk", "he": "יום הכפורים"}, {"id": "sukkos", "he": "סוכות"}, {"id": "shmini", "he": "שמיני עצרת"}, {"id": "chanukah", "he": "חנוכה"}, {"id": "esther", "he": "תענית אסתר"}, {"id": "shekalim", "he": "פרשת שקלים"}, {"id": "zachor", "he": "פרשת זכור"}, {"id": "parah", "he": "פרשת פרה"}, {"id": "hachodesh", "he": "פרשת החודש"}, {"id": "hagadol", "he": "שבת הגדול"}, {"id": "pesach", "he": "פסח"}, {"id": "tishabav", "he": "תשעה באב"}, {"id": "everyday", "he": "כל השנה"}, {"id": "azharos", "he": "אזהרות (היום לא אומת)"}, {"id": "unknown", "he": "מקום אמירתו לא צוין"}], "sections": [{"id": "torah", "he": "רש\"י על התורה"}, {"id": "nach", "he": "רש\"י על נביאים וכתובים"}, {"id": "shas", "he": "רש\"י על הש\"ס"}, {"id": "tosafos", "he": "תוספות"}], "lit": {"shekalim": {"ref": "Siddur Sefard, Yotzerot, Parashat Sekalim", "he": "יוצר לפרשת שקלים", "nusach": "סידור ספרד (תורת אמת)", "version": "Torat Emet 357", "source": "http://www.toratemetfreeware.com/index.html?downloads", "url": "https://www.sefaria.org/Siddur_Sefard%2C_Yotzerot%2C_Parashat_Sekalim", "segs": ["<b><b><big><b>יוצרות</b></big></b></b>", "<b><b><big><b>יוצר לפרשת שקלים</b></big></b></b>", "<b>אֲדֹנָי</b> שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי אַבְרָהָם. אֱלֹהֵי יִצְחָק. וֵאלֹהֵי יַעֲקֹב. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן. גּוֹמֵל חֲסָדִים טוֹבִים. קוֹנֵה הַכֹּל. וְזוֹכֵר חַסְדֵי אָבוֹת. וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה: מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן:", "<b>מִסּוֹד</b> חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בְּשִׁיר וּרְנָנִים. לְהוֹדוֹת וּלְהַלֵּל פְּנֵי שׁוֹכֵן מְעוֹנִים:", "<b>אָז</b> מֵאָז זַמּוֹתָ בְּכָל פּוֹעַל. בְּמִסְפָּר בְּמִשְׁקָל כֹּל לְךָ לְהַעַל. גַּדְתָּ בְּכֵן לְמָשׁוּי מִמֵּי שַׁעַל. דַּעַת מִפְקַד יוֹפִי פַּעֲמֵי נָעַל. הַעַל הֵמִירוּ כְּבוֹד רֵעַ בְּבַעַל. וְזֶה לְלֹא זֶה פָּצְחוּ בְּמַעַל. זֻנְּחוּ בַּחֲרוֹן אַף וְנֶגֶף וָגַעַל. חָל בַּעֲדָם חֶבֶר וְהַצֳּרִי תַעַל: טוֹרַח מַשָּׂאָם הֻגַּד לוֹ שְׂאֵת. יָשְׁרָם לְהָלִיץ תְּלוּי רֹאשׁ לָשֵׂאת:", "<b><b><small>חזן:</small> <b>כָּפְרָם</b> פָּץ תֵּת לְאֻמִּים מַשְׂאֵת. לְנַטְּלָם לְנַשְּׂאָם בְּכִי תִשָּׂא אֶת: </b></b>", "<b>רֹאשִׁי</b> עַל כָּל רֹאשׁ נִשֵׂאתָ. גֵּוִי עַל גַּפֵּי מְרוֹמֵי קֶרֶת הִתְנַשֵּׂאתָה:", "<b><b><small>חזן:</small> <b>אַהֲבָה</b> עַל כָּל פֶּשַׁע כִּסִּיתָ. בְּגִין צֵל יְמִינְךָ לְגוֹנְנִי הִתְנַשֵּׂאתָ:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה. מָגֵן אַבְרָהָם:", "<b>אַתָּה</b> גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מַשִׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם:", "<b>מְכַלְכֵּל</b> חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה: וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים:", "<b>מַעְתִּיק</b> פְּלוּסִים צָר וּבוֹרֵא רוּחַ. מְמַדֵּד וּמְשַׁקֵּל נֶזֶל עִם רוּחַ. נֶגֶף לְבַל יַזִּיק לְנִדְכְּאֵי רוּחַ. נוֹבַבְתָּם תֵּת פִּדְיוֹן לְכָל רוּחַ: שְׂרִיג זֵד שֵׂעִיר טֶרֶם עָמַד. סָקַרְתָּ כִּי לְמוֹקֵשׁ וְלִצְנִין יָעֳמַד. עַצְתָּ זֶה לָזֶה שֶׁמַע בְּמַעֲמַד. עִתּוּד שְׁקָלִים מֵרֹאשׁ חוֹדֶשׁ לִלְמַד: פָּרָשָׁה זֹאת לַהֲגוֹת בְּקֵץ זֶה. פְּלָסֶיהָ לְהַקְדִּים לְפֶלֶס צַר וּבוֹזֶה.", "<b><b><small>חזן:</small> <b>צוּרַת</b> מַטְבֵּעַ כְּחָז אֲבִי חוֹזֶה. צִוָּה צוּר לְצִיר כֵּן תֵּת מַתַּן זֶה: </b></b>", "<b>שְׁמוֹ</b> מְשֻׁתָּף בְּעַם לוֹ עֲמוּתִים. וְעָלָיו כָּל הַיּוֹם הֵם מוּמָתִים:", "<b><b><small>חזן:</small> <b>יָעִיר</b> וְיַחֲשׂוֹף זְרוֹעַ וְיַד מִמְּתִים. בְּזִיל נִטְפֵי לֶקֶשׁ לְהַחֲיוֹת מֵתִים:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<b>קְצוּבָה</b> הִיא זֹאת לְשׁוֹעִים וְקַלִּים. קְצִינִים וְרָשִׁים יַחַד בָּהּ שְׁקוּלִים. קָצִין לְבַל יָעוֹז מוּל מַקְהֵלִים. קְרוֹא לוֹמַר הוֹנִי פְּדָעַנִי מֵעִקּוּלִים: רוֹב עָם אֲשֶׁר לֹא יִסָּפֵר. רַב עִם צָעִיר מֵעֶשְׂרִים לְהִסָּפֵר. רְאוּיִם לְעוֹנֶשׁ וְזַהַר בְּסֵדֶר לְהִתָּפֵר. רֶשַׁע וְכָל פֶּשַׁע לְכַפֵּר וּלְהָפֵר: שְׁעוּרִים בָּזֶה שִׁעוּר בְּמִפְקַד לְהַגְבֵּר. שְׁתִילֵמוֹ לִנְשִׂיאַת רֹאשׁ אוֹתָם לְחַבֵּר:", "<b><b><small>חזן:</small> <b>שִׁקְלֵי</b> כֶסֶף כִּפּוּרִים כָּפְרָם לְהַדְבֵּר. שְׁמוּרִים לְזִכָּרוֹן תֵּת לְכָל הָעוֹבֵר:</b></b>", "<b>תָּמְדוּ</b> מֵאָז כָּל עֲדַת קְדוֹשִׁים. תְּרוֹם בִּשְׁלֹשָׁה פְרָקִים תְּרוּמַת קָדָשִׁים:", "<b><b><small>חזן:</small> <b>תְּכוּנָה</b> לְבֶדֶק הַבַּיִת וְכָל אִשִׁים. תֵּת בְּיַד הַכֹּהֲנִים כֶּסֶף הַקֳּדָשִׁים:</b></b>", "<b>תֵּפֶן</b> בְּאוֹן פִּיד טִיט רִפְשֵׁנוּ. תַּבִּיט בְּדָכְיֵנוּ וְעוֹד בַּל תַּכְפִּישֵׁנוּ:", "<b><b><small>חזן:</small> <b>תִּקְרָא</b> דְרוֹר כְּמֵאָז בּוֹ לְהַחְפִּישֵׁנוּ. תֵּת הֲמוֹן לְאֻמִּים תַּחַת נַפְשֵׁנוּ:</b></b>", "<b>תִּזְכּוֹר</b> לְהַעֲלוֹת נְשׂוּאֵי רַחַם מִדָּכְיָם. תְּמוּכִים נְזוּרִים בְּהוֹד טוֹב עֶדְיָם:", "<b><b><small>חזן:</small> <b>תּוֹקֶף</b> עוֹז אִדְּרוּךָ עַל יָם. תִּזְכּוֹר לְעָם מִסְפָּרָם כְּחוֹל הַיָּם. </b></b>", "<b><b><small>חו\"ק:</small> <b>יִמְלוֹךְ</b> יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל אֵל נָא:</b></b>", "<b>מִי</b> יוּכַל לְשַׁעֵר כָּל הַפְּקוּדִים. אֲשֶׁר בְּחֶבֶל וּבְחֶלֶשׁ לֹא נִפְקָדִים. בְּרִית כְּרוּתָה לָמוֹ מֵאָז בְּפִקוּדִים. לְבַל יֶחְסַר הַמָּזֶג מֵחוֹמֶשׁ פִּקּוּדִים: וְאִם כְּתוֹרֶן וְכַנֵּס יֻשְׂרְדוּ מֻפְקָדִים. לֹא יֻמְעֲטוּ מִשִׁשִׁים רִבּוֹא מְנֻקָּדִים. וְאִם לְנֶגֶף וָאֶנֶף בְּאַף מוּפְקָדִים. כֶּסֶף תֵּת כּוֹפֶר הֵם מְפֻקָדִים. וּבְכָל עֶרֶב נִשְׁמָתָם בְּיָדְךָ מַפְקִידִים. וּבְכָל רִגְעֵי בוֹקֶר נִבְחָנִים וְנִפְקָדִים. וְלִי מַה יָקְרוּ עָלַי הַפְּקוּדִים. אֵלֶה הַפְּקוּדִים וְהַמִּתְפָּקְדִים. שְׁמוֹר פִּקוּדִים וְנִפְקָדִים וְשׁוֹקְדִים. הֱיוֹת מְשֻׁקָּדִים. וּלְךָ קוֹדִים.", "<b><b><small>חו\"ק:</small> <b>חַי</b> וְקַיָם נוֹרָא וּמָרוֹם וְקָדוֹשׁ:</b></b>", "<b>אוֹמֵן</b> בְּשָׁמְעוֹ כִּי תִשָׂא אֶת רֹאשׁ. חָל וַיֵּחַת אֵיךְ אוֹתָם דְּרוֹשׁ: לְעַם אֲשֶׁר לֹא יִמַּד וְלֹא יִסָּפֵר. אֵיכָכָה אֶסְפְּרֵם וְלֹא נִתְּנוּ לְהִסָפֵר: עִקָרָם כְּנֶאֱמַר לוֹ הַבֵּט וּסְפוֹר. שָׁב וַיוּשַׁב אִם תּוּכַל לִסְפּוֹר: זַרְעָם כְּחוֹל יַמִּים וְכוֹכָבִים סְפוּרִים. וַאֲנִי אֵיךְ אֶסְפְּרֵם וְלָעַד פָּרִים: רָם חִוָּה לוֹ אוֹת מִסְפָּרָם. אֵיךְ לִמְנוֹתָם וְלַעֲמוֹד עַל סִפְרָם: בִּקּוּר רָאשֵׁי שְׁמוֹתָם לְחֶשְׁבּוֹן תְּעַלֶּה. וּמִדַּת מִנְיָנָם בְּיָדְךָ אָז תַּעֲלֶה: יָקָר שְׁלִישִׁי בְּתוֹכָם לֹא הָפְקַד. כִּי לִגְיוֹן מֶלֶךְ לְבַדּוֹ נִפְקַד: רָשׁוּם מִבֶּטֶן לְהִפָּקֵד בְמִשְׁמֶרֶת הַקֹּדֶשׁ. וּצְבָאוֹ וּפְקוּדָיו נִמְנִים מִבֶּן חוֹדֶשׁ: בְּשָׁמְעוֹ אֹמֶר וְנָתְנוּ אִישׁ כּוֹפֶר. פָּץ בַּמֶּה יִתְרַצֶּה אֶשְׁכּוֹל הַכּוֹפֶר: יְצִיר מַה יִתֵּן פִּדְיוֹן נַפְשׁוֹ. וְיִמְצָא חֲנִינָה פְּנֵי שָׂם נַפְשׁוֹ: קָדוֹשׁ כְּחָפֵץ לְהַצְדִּיק עַם זֶה. כְּמִין מַטְבֵּעַ אֵשׁ הֶרְאָהוּ בַּמַּחֲזֶה: לִמְּדוֹ זֶה יִתְּנוּ וְלֹא יִתְמַתְנוּ. וְלַכֹּל יְתַנוּ אֵת אֲשֶׁר נָתְנוּ: יָהּ לֹא מְצָאנוּךָ שַׂגִּיא כֹּחַ. כַּאֲשֶׁר נִקֵיתָ חֵטְא גִּבּוֹרֵי כֹּחַ:", "<b><b><small>חזן:</small> <b>רַחוּם</b> כְּרִחַמְתָּ נְשׂוּאֶיךָ בְּכֶסֶף כִּפּוּרִים. כֵּן שְׁעֵה שְׂפָתֵינוּ בְּשִׁלּוּם פָּרִים:</b></b>", "<b>אֵל</b> נָא לְעוֹלָם תָּעֳרָץ. וּלְעוֹלָם תֻּקְדָּשׁ. וּלְעוֹלְמֵי עוֹלָמִים תִּמְלוֹךְ וְתִתְנַשֵׂא. הָאֵל מֶלֶךְ נוֹרָא מָרוֹם וְקָדוֹשׁ. כִּי אַתָּה הוּא מֶלֶךְ מַלְכֵי הַמְּלָכִים. מַלְכוּתוֹ נֶצַח. נוֹרְאוֹתָיו שִׂיחוּ. סַפְּרוּ עֻזּוֹ. פָּאֲרוּהוּ צְבָאָיו. קַדְּשׁוּהוּ רוֹמְמוּהוּ. רוֹן שִׁיר וָשֶׁבַח. תּוֹקֶף תְּהִלוֹת תִּפְאַרְתּוֹ.", "<b><b><small>חו\"ק:</small> <b>עַד</b> אֶשָּׂא רֹאשׁ. כְּמוֹ מֵרֹאשׁ. לְהַקְדִּישׁ לְקָדוֹשׁ:</b></b>", "<b><b><small>חו\"ק:</small> <b>עַד</b> בְּמֹאזְנֵי צֶדֶק. יַכְרִיעֵנִי לְצֶדֶק. נוֹרָא וְקָדוֹשׁ:</b></b>", "<b>אֵלֶה</b> אֶזְכְּרָה אֵת אֲשֶׁר נַעֲשָׂה. בִּהְיוֹתִי בֶּטַח וְשָׁקֵט בְּנָכוֹן וְנִשָׂא. גּוֹעַלְתִּי בְּעֵבֶר וּשְׁקָלַי אֵיךְ אֶשָׂא: דֵּי שְׁקָלַי עַד לֹא שָׁקַלְתִּי. הִנָם לְמַס עוֹבֵד הַיוֹם שָׁקַלְתִּי. וּבְחֵטְא עִווּל שֶׁקֶל לְרָשָׁע נִשְׁקַלְתִּי: זוּזַי לְלֹא תַתִּי לְשָׁכְנִי בְגִילָה. חַבְתִּי לְתַשְׁלוּם דַּרְכְּמוֹן לְעוֹלֵי גוֹלָה. טֻבְּעוּ גַם הֵם וְהוּעֲרַמְתִּי מְגֻלָּה: יוֹשֶׁר שָׁלֹשׁ קֻפּוֹת מְשֻׁלָּשׁוֹת סְאִים. כְּנוּסוֹת לְמִקַּח שַׁי מְרִיאִים וְשֵׂיִים. לֻקְּחוּ וְאֵין עוֹד בִּצְעִי נוֹשְׂאִים: מִדַּת שׁוֹפְרוֹת תַּקְלִין חַדְתִּין וְעַתִּיקִין. נְדָבוֹת אֲשֶׁר בָּם הָיוּ מְעַתְּקִין. סָרוּ כַּמָּה מֶנִּי וְהַדְּבָרִים עַתִּיקִין: עוֹצֶם הֲמוֹן חוֹגֵג שׁוֹטֵף כַּנָהָר. פֻּזַר וְנוֹתַרְתִּי כְּתֹרֶן בְּרֹאשׁ הָהָר. צֶדֶק מְלוֹנִי שׁוּעֲרָר כְּתֵל הָר: קַן צִפּוֹר קָרָא לִמְרוֹם הָרִים. רֹאשׁ נְשׂוּאֶיךָ כְּמֵאָז בּוֹ לְהָרִים. שִׁבְעָה וּשְׁמוֹנָה עֲלֵיהֶם לְרֹאשׁ תָּרִים:", "<b><b><small>חזן:</small> <b>עַד</b> אֶשָׂא רֹאשׁ. כְּמוֹ מֵרֹאשׁ. לְהַקְדִּישׁ לְקָדוֹשׁ:</b></b>", "<b>וּבְכֵן</b> וּלְךָ תַעֲלֶה קְדוּשָׁה כִּי אַתָּה קְדוֹשׁ יִשְׂרָאֵל וּמוֹשִׁיעַ:", "<b>אָז</b> רָאִיתָ וְסִפַּרְתָּ. וְהֵכַנְתָּ וְחָקַרְתָּ. וּמָדַדְתָּ וְכַלְתָּ וְשָׁקַלְתָּ. וְאָמַדְתָּ וְצָבַרְתָּ. וּפָקַדְתָּ וְחָשַׁבְתָּ וְסִכַּמְתָּ. וּמָנִיתָ וְסָפַרְתָּ. וְקָצַבְתָּ וְחָרַצְתָּ וְגָזַרְתָּ. וְטִפַּחְתָּ וְשִׁעַרְתָּ וְהִבַּטְתָּ. וְהֵבַנְתָּ וְהִשְׂכַּלְתָּ וְשַׁרְתָּ וְסָקַרְתָּ. וְכָתַבְתָּ וְחָרַטְתָּ. וְחָקַקְתָּ וְצִיַּנְתָּ וְחָרַתָּ וְלִמַּדְתָּ וְהוֹדַעְתָּ וְחִוִיתָ וְהוֹרֵיתָ. וְגָזַרְתָּ וְצִוִּיתָ וְקָרָאתָ וְעָנִיתָ וְדִבַּרְתָּ וְאָמַרְתָּ: כָּל מִנְיָן וּמִפְקָד וְחֶשְׁבּוֹן וּמִסְפָּרָיו. כָּל מִשְׁקָל וָפֶלֶס וְכִיס וְגִזוּרָיו. כָּל כַּיִל לַח וְיָבֵשׁ וּמְשׂוּרָיו. כָּל קַו וָקֶצֶב וּמֶדֶד וְשִׁעוּרָיו: הֵיךְ לְדַקְדֵּק חֶשְׁבּוֹן לְכָל דָבָר. לְבַל יֻגְלַם חֶשְׁבּוֹן וְיִשְׁטַף וְיוּעֲבָר:", "<b>מַתְחִיל</b> בִּמְדִידָה מֵחֲמֵשׁ מֵאוֹת שָׁנָה. עַד שֶׁהוּא מְכַלֶה בְּאֶצְבַּע הַקְטַנָה: דֶּרֶךְ יוֹם הוּא בְּעֶשֶׂר פַּרְסָה. וְאַרְבַּעַת מִיל הִיא כָּל פַּרְסָה: וּמִדַּת הַמִּיל שִׁבְעָה וּמֶחֱצָה רִיס. וּבִשְׁלֹשִׁים קָנִים הוּא קֶצֶב הָרִיס: וְשִׁעוּר הַקָּנֶה שֵׁשׁ אַמּוֹת וָזֶרֶת. וְכָל אַמָּה מוֹדֶדֶת שְׁלִישׁ בַּזֶרֶת: וְהַזֶרֶת מוֹתַחַת עַד שְׁנַיִם בַּסִּיט. וְאַרְבַּע אֶצְבָּעוֹת הוּא הַטֶּפַח וְהַסִּיט: וּכְמוֹ נִתְּנָה מִדָּה לִמְדִידַת הָאָרֶץ. כֵּן נִתַּן כַּיִל לְתוֹלְדוֹת הָאָרֶץ: מַתְחִיל מִמֵּאָה וְשִׁשִׁים וָשֵׁשׁ שָׁנָה עַד שֶׁהוּא מְכַלֶה בִּשְׁתּוּת אֶצְבַּע קְטַנָּה:", "<b>זֶה</b> הַיָּם הַגָּדוֹל בִּשְׁלִישׁ יוֹשֵׁב. בְּמֵאָה וְשִׁשִׁים וְשֵׁשׁ וָעוֹד מִתְחַשֵׁב: וְעָמְקוֹ בְּעֶשְׂרִים וְאַרְבָּעָה לְמֵתַח סוּף. וְסוּף בְּשִׁבְעִים וּשְׁנַיִם לְעוֹגֶל גִיחוֹן. וְגִיחוֹן מַכְפִּיל שִׁשִׁים כְּמִדַּת פְּרָת. וְהַפְּרָת תָּקְפוֹ כְּנֶגֶד שְׁנֵי הַנְּהָרוֹת. וּשְׁנֵי הַנְּהָרוֹת מַעְדִּיפִים בְּאֹרֶךְ הַיַּרְדֵּן. וְהַיַּרְדֵּן מַרְחִיב חֲמִשָׁה כְּיַם הַזְּבוּל. וְיַם הַזְּבוּל מֵאָה וַחֲמִשִׁים מִקְוָאוֹת. וּמִדַּת הַמִּקְוָה כִּשְׁנֵי חֳמָרִים בְּיָבֵשׁ. וְשִׁעוּר כָּל חוֹמֶר כִּשְׁנֵי לְתָכִים. וְכָל לֶתֶךְ יָכִיל חָמֵשׁ אֵיפוֹת. וְכָל אֵיפָה עוֹשָׂה עֲשָׂרָה עֳמָרִים. וְכָל עוֹמֶר שִׁבְעַת רֶבַע וּכְלָה. וְהַכְּלָה אֶחָד מִמֵּאָה וָעוֹבִּסְאָה. וּסְאַת יָבֵשׁ חֲסֵרָה שְׁלִישׁ בַּלַח. וּסְאַת הַלַּח אֶחָד מִשְׁלשָׁה בַּבַּת. וְכָל בַּת מַחֲזֶקֶת שִׁשָׁה בַּהִין. וְהַהִין כֻּלוֹ שְׁנֵים עָשָׂר לוֹג. וָעוֹד, הַלוֹג מִתְחַלֵּק לְאַרְבַּעַת רְבָעִים וְרֶבַע מוּכָן לְרִבּוּעַ כּוֹס יְשׁוּעות. וְהַכּוֹס סוֹבֵב אֶצְבָּעַיִם עַל אֶצְבָּעַיִם. וְעַל גוֹבַהּ חָסֵר שְׁתוּת מֵאֶצְבָּעַיִם:", "<b>וּכְמוֹ</b> נִתַּן כַּיִל לְתוֹלְדוֹת הָאָרֶץ. כֵּן נִתַּן קֵץ לִימֵי הָאָרֶץ. מַתְחִיל לִמְנוֹת מִשֵׁשֶׁת אַלְפֵי עֶרֶץ. עַד שֶׁהוּא מְכַלֶּה בְּרִגְעֵי אָרֶץ. כִּי כָל הָעוֹלָם כֻּלּוֹ שֵׁשֶׁת אֲלָפִים. עוֹשִׂים חֲמִשָׁה וּשְׁתֵּי יָדַיִם מַחֲזוֹרוֹת. וּמִנְיַן הַמַּחֲזוֹר בְּעֶשְׂרִים וּשְׁנַיִם יוֹבְלוֹת. וּשְׁנַת הַיוֹבֵל שֶׁבַע שַׁבְּתוֹת הַשָׁנִים. וְשַׁבְּתוֹת הַשָׁנִים בְּעֶשְׂרִים וּשְׁמוֹנֶה תְּקוּפוֹת. וִימוֹת הַתְּקוּפָה תִּשְׁעִים וְאֶחָד יוֹם וּשְׁלִישׁ. וְעוֹנוֹת הַיוֹם חֲמֵשׁ מֵאוֹת וְשִׁבְעִים וָשֵׁשׁ. וְרִגְעֵי הָעוֹנָה כְּעוֹנוֹת כָּל הַיוֹם. וְהַמְדַקְדֵּק מְחַלֵּק הָרֶגַע לְכַמָּה רְגָעִים:", "<b>וּכְמוֹ</b> נִתַּן חֶשְׁבּוֹן עַל כֹּל. כֵּן נִתַּן מִשְׁקַל וָפֶלֶס לַכֹּל. מַתְחִיל מִכִּכָּר עַד פְּרוּטָה הַקְטַנָּה: כִּכָּר הַגָּדוֹל כְּגֹדֶל שְׁנֵי מָנֶה. <small> <small>(נוסח הגר\"א כִּכָּר הַגָּדוֹל כְּגֹדֶל שִׁשִּׁים מָנֶה, וְהַמָּנֶה מִתְחַשֵּׁב בְּעֶשְׂרִים וְחָמֵשׁ סֶלַע וְהַסֶּלַע וכו' כי בקע ושקל הכל אחד)</small> </small>, וְהַמָּנֶה עוֹלֶה עַד שִׁשִׁים שֶׁקֶל. וְהַשֶׁקֶל מִתְחַשֵׁב בְּעֶשְׂרִים וְחָמֵשׁ סֶלַע. וְהַסֶּלַע חֶצְיוֹ בֶּקַע וּרְבִיעַ זוּז. וְהַזוּז מִתְחַלֵק לְפֶלֶג וְחוֹמְשׁוֹ מָעָה. נִמְצָא הַזוּז חָמֵשׁ מָעוֹת כֶּסֶף. וְהַמָּעָה שְׁתֵּי פוּנְדְּיוֹנוֹת. בְּאִסָּר דָת. וְהָאִסָּר עוֹלֶה עַד שְׁמוֹנֶה פְּרוּטוֹת. נִמְצָא הַבֶּקַע כְּאַרְבַּע מֵאוֹת פְּרוּטוֹת. וְהֵם בִּכְתָב חֲרוּטוֹת. וּבְפֶה מְפוֹרָטוֹת:", "<b>וְעַד</b> מָקוֹם שֶׁאֱנוֹשׁ יָכוֹל לִמְנוֹת. נִמְסַר לוֹ לִמְדּוֹד וְגַם לִמְנוֹת: לְפִי כֹחוֹ וּלְפִי מִעוּט חֵילוֹ. הָקְצַב לוֹ מִעוּט הוֹן שִׁקְלוֹ. וּלְפִי שִׂכְלוֹ כֵּן יְהִי הִלּוּלוֹ. גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ חֵילוֹ. עַל כֵּן אוֹחִיל לוֹ: כִּי מִדָתוֹ וְשִׁקְלוֹ לְפִי גָדְלוֹ. כָּל אוֹצְרוֹת שֶׁלֶג וְרוּחַ פִּלֵס בְּמִשְׁקָלוֹ: וּמֵי בְּרֵאשִׁית מָדַד מְלֹא שָׁעֳלוֹ. וּשְׁמֵי רוֹם תִּכֵּן זֶרְתּוֹ מְלֹא. וְכָל הַרְרֵי קֶדֶם בְּאֶצְבָּעוֹ שְׁקָלוֹ. וְגִבְעוֹת עוֹלָם תָּמַךְ בְּהוֹד אֲגֻדָּלוֹ. גֵּיא וְכָל עֲפָרָהּ בִּצְרָדָה הֱכִילוֹ. לְחוֹלֵל תַּנִין מְיֻמֶּנֶת הֵכִין לוֹ: נִמְצֵאת כָּל מִדַּת יְצִירַת עוֹלָמוֹ. כִּמְלֹא פִסַּת יָד הִיא רִשׁוּמוֹ. וּכְקָמֵיעַ בְּיַד גִּבּוֹר בִּזְרוֹעַ חוֹתָמוֹ. וְאֵין לִקְצוֹב רוֹב מֶחְקְרֵי תַעֲצוּמוֹ. אֲשֶׁר מָדַד וְקָצַב וְשִׁעֵר בִּמְרוֹמוֹ. עַל כָּל מִדַת כִּסְאוֹ וַהֲדוֹמוֹ: מִדַּת בַּת מֶלֶךְ בַּכֹּל מְעֻלָה. בְּאֹרֶךְ בְּרוֹחַב בְּעוֹמֶק בְּגּוֹבַהּ מִתְעַלָּה. כִּי יֵשׁ קֵץ לְכָל תִּכְלָה. וְאִמְרָהּ רְחָבָה לָעַד לֹא כָלָה: מִדַּת עוֹלָם כִּמְלֹא פִסַּת יָד. וּמִדָּתָהּ נְתוּנָה בִּימִין וּזְרוֹעַ וָיָד: מִדַּת עוֹלָם כְּמִזֶּרֶת וְעַד אֲגֻדָּל. וּמִדָּתָהּ בְּקַו אֲשֶׁר מְאֹד גָּדָל: מִדַּת עוֹלָם נִמְדֶּדֶת בִּשְׁלִישׁ אַמָּה. וּמִדָּתָהּ עוֹלָה וְנוֹסֶבֶת כְּאַלְפַּיִם אַמָּה: כְּמַרְאֵה הַמִּדָּה אֲשֶׁר צִיר רָאָה. מְגִלָּה עֶשְׂרִים עַל עֶשֶׂר אַמָּה. עָפָה אַרְבָּעִים עַל עֶשְׂרִים וּשְׁמוֹנֶה מֵאוֹת אַמָּה. וְכָל הָעוֹלָם כֻּלּוֹ בִּשְׁלִישׁ אַמָּה: נִמְצֵאת דָּת בְּמִדוֹתֶיהָ רְחָבָה וַאֲרֻכָּה. אַלְפַּיִם וְאַרְבַּע מֵאוֹת בָּעוֹלָם מַאֲרִיכָה. וְהִיא נָתְנָה לָעוֹלָם מַרְפֵּא וַאֲרוּכָה. וּבִימִינָהּ קוֹצֶבֶת כָּל יְמֵי אַרְכָה, וּבִשְׂמֹאלָהּ שׁוֹקֶלֶת עוֹשֶׁר וְכָבוֹד וּבְרָכָה: וְהִיא הוֹדִיעָה אֶת כָּל חֶבְיוֹן סְתוּרוֹת. וְהוּא קָצְבָה כָּל מִדּוֹת סְפוּרוֹת. וְהִיא פָּתְחָה אֶת כָּל סְגוּרוֹת. וְהִיא שָׁקְלָה וְאָצְרָה אֶת כָּל אוֹצָרוֹת: וְהִיא חָקְרָה הֲמוֹן מִפְקַד תַּחְתּוֹנִים. וְהִיא נָתְנָה מִסְפַּר גְּדוּדֵי עֶלְיוֹנִים: וְהִיא שִׁעֲרָה קוֹמַת אַלְפֵי שִׁנְאַנִּים. אֲשֶׁר זֶה מִזֶּה בְּקוֹמָתָם מְשֻׁנִּים: יֵשׁ כְּמִדַּת הַיָּם הַגָּדוֹל קוֹמָתָם. וְיֵשׁ כַּחֲלָלוֹ שֶׁל עוֹלָם הֲקָמָתָם. וְיֵשׁ כִּמְלֹא כָל הָעוֹלָם תְּקוּמָתָם. יֵשׁ לִשְׁתֵּי טִיסוֹת טָסִים עוֹלָם. וְיֵשׁ לְטִיסָה אַחַת עָפִים עוֹלָם. וְכָל אֶחָד וְאֶחָד בְּמַחֲנֵהוּ נֶעְלָם. וּבִמְחִיצָתוֹ צָג וְחָשׁ וְדוּמָם וְנֶאֱלָם. עַד יִתֵּן רְשׁוּת מֶלֶךְ הָעוֹלָם. וְחָשִׁים עַד יַמְלִיכוּהוּ עַם עוֹלָם. וְאָז יִפְצְחוּ לְפָאֵר אֱלֹהֵי עוֹלָם. וּמִשֶׁהֵם מְפָאֲרִים עוֹד לֹא שׁוֹנִים. כִּי בִנְהַר דִינוֹר שָׂחִים וְנִתָּנִים. וְעוֹד מֶנּוּ נֶחֱצָבִים וּמִתְחַדְשִׁים כָּרִאשׁוֹנִים. שֶׁבַח וְהַלֵל וָרוֹן לָאֵל מְשַׁנְּנִים. וְכִפֵּי קֶשֶׁת עִם כְּנַף רְנָנִים. זֶמֶר וָשִׁיר וְעוֹז וָרֶנֶן מְרַנְּנִים. וּשְׂרָפִים הַמְעֻלִּים עַל כָּל שִׁנְאֲנִּים. שֵׁשׁ שֵׁשׁ כְּנָפַיִם בְּגֶוְיָם חֲנוּנִים. מִמַעַל לְיוֹשֵׁב עֲרָבוֹת בַּכֵּס נְתוּנִים. וּלְיוֹשֵׁב עַל כִּסֵּא בְּחִילָה מְנַגְּנִים. מְצוֹא חֵן בְּנִגּוּנָם הֵם מְחַנְּנִים. וְקוֹדֶם לְכָל צְבָא מַעַל עוֹנִים. וְשִׁלוּשׁ קְדֻשָׁה לְרָם וְנִשָׂא נוֹתְנִים. כּוֹרְעִים וּמִשְׁתַּחֲוִים הֲמוֹנִים הֲמוֹנִים. לְנַעֲרָץ בְּסוֹד הֲמוֹן גְּדוּדֵי עֶלְיוֹנִים. וְנִקְדָּשׁ בְּאַלְפֵי רִבְבוֹת תַּחְתּוֹנִים:", "<b><b><small> קדושה</small></b></b>", "<small><b><b><small>נַקְדִּישָׁךְ וְנַעֲרִיצָךְ כְּנֹעַם שִׂיחַ סוֹד שַׂרְפֵי קֹדֶשׁ. הַמְּשַׁלְּשִׁים לְךָ קְדֻשָּׁה. כַּכָּתוּב עַל יַד נְבִיאֶךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר: </small></b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>קָדוֹשׁ</b> קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: <small>חזן:</small> <b>אָז.</b> בְּקוֹל רַעַשׁ גָּדוֹל אַדִּיר וְחָזָק. מַשְׁמִיעִים קוֹל. מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>בָּרוּךְ</b> כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>חזן:</small> מִמְּקוֹמְךָ מַלְכֵּנוּ תוֹפִיעַ. וְתִמְלוֹךְ עָלֵינוּ <small> <small>(מְהֵרָה)</small> </small> כִּי מְחַכִּים אֲנַחְנוּ לָךְ. מָתַי תִּמְלֹךְ בְּצִיּוֹן. בְּקָרוֹב בְּיָמֵינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן. תִּתְגַּדֵּל וְתִתְקַדֵּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵצַח נְצָחִים. וְעֵינֵינוּ תִרְאֶינָה מַלְכוּתֶךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּךָ. עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>יִמְלֹךְ</b> יְהֹוָה לְעוֹלָם. אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר. הַלְלוּיָהּ:</b></b></small><b><b> </b></b>", "<b>אַתָּה קָדוֹשׁ</b>, וְשִׁמְךָ קָדוֹשׁ, וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. כִּי אֵל מֶלֶךְ גָדוֹל וְקָדוֹשׁ אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה, הָאֵל הַקָּדוֹשׁ:", "<b>יִשְׂמַח מֹשֶׁה</b> בְּמַתְּנַת חֶלְקוֹ, כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּוֹ. כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ, בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לוּחוֹת אֲבָנִים הוֹרִיד בְּיָדוֹ, וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת, וְכֵן כָּתוּב בְּתוֹרָתֶךָ:", "<b>וְשָׁמְרוּ</b> בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְהֹוָה אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:", "<b>וְלֹא</b> נְתַתּוֹ יְהֹוָה אֱלֹהֵינוּ לְגוֹיֵי הָאֲרָצוֹת, וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים, גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים, כִּי לְעַמְּךָ יִשְׂרָאֵל נְתַתּוֹ בְּאַהֲבָה, לְזֶרַע יַעֲקֹב אֲשֶׁר בָּם בָּחָרְתָּ:", "<b>יִשְׂמְחוּ</b> בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עוֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּוֹ וְקִדַּשְׁתּוֹ. חֶמְדַת יָמִים אוֹתוֹ קָרָאתָ. זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<b>אֱלֹהֵינוּ</b> וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךְ, וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶאֱמֶת, וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבָּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ. בָּרוּךְ אַתָּה יְהֹוָה, מְקַדֵּשׁ הַשַּׁבָּת:", "<b>רְצֵה</b> יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל, וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<b><b><small> <small><b><small>בראש חודש</small></b> אומרים כאן \"יעלה ויבא\":</small></small></b></b>", "<small><b><b><small> אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, יַעֲלֶה וְיָבֹא, וְיַגִּיעַ וְיֵרָאֶה וְיֵרָצֶה, וְיִשָּׁמַע וְיִפָּקֵד וְיִזָּכֵר, זִכְרוֹנֵנוּ וּפִקְדוֹנֵנו וְזִכְרוֹן אֲבוֹתֵינוּ, וְזִכְרוֹן מָשִׁיחַ בֶּן דָּוִד עַבְדָּךְ, וְזִכְרוֹן יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ, וְזִכְרוֹן כָּל עַמְּךָ בֵּית יִשְׂרָאֵל לְפָנֶיךָ, לִפְלֵטָה, לְטוֹבָה, לְחֵן וּלְחֶסֶד וּלְרַחֲמִים לְחַיִּים טוֹבִים וּלְשָׁלוֹם בְּיוֹם:</small></b></b></small>", "<small><b><b><small><b>רֹאשׁ הַחֹדֶשׁ</b> הַזֶּה. זָכְרֵנוּ יְהֹוָה אֱלֹהֵינוּ בּוֹ לְטוֹבָה, וּפָּקְדֵנוּ בוֹ לִבְרָכָה, וְהוֹשִׁיעֵנוּ בוֹ לְחַיִּים טוֹבִים, וּבִּדְבַר יְשׁוּעָה וְרַחֲמִים. חוּס וְחָנֵּנוּ, וְרַחֵם עָלֵינוּ וְהוֹשִׁיעֵנוּ, כִּי אֵלֶיךָ עֵינֵינוּ, כִּי אֵל מֶלֶךְ חַנּוּן וְרַחוּם אָתָּה:</small></b></b></small>", "<b>וְתֶחֱזֶינָה</b> עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. בָּרוּךְ אַתָּה יְהֹוָה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:", "<b>מוֹדִים</b> אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדֹר וָדֹר. נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶיךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם. הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְּרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b><b><small> מודים דרבנן<small><b><small>בחזרת הש\"ץ</small></b> כשהוא אומר מודים, אומרים הקהל:</small> </small></b></b>", "<small><b><b><small>מוֹדִים אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׁר, יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמֹר חֻקֶּיךָ וְלַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְךָ בְלֵבָב שָׁלֵם, עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת.</small></b></b></small>", "<b>וְעַל</b> כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָמִיד לְעוֹלָם וָעֶד.", "<b>וְכֹל</b> הַחַיִּים יוֹדוּךָ סֶּלָה: וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל, בֶּאֱמֶת, לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<b><b>ברכת כהנים</b></b>", "<b>שִׂים שָׁלוֹם</b> טוֹבָה וּבְרָכָה, חַיִּים, חֵן וָחֶסֶד, וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד <small>(יַחַד)</small> בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים, וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים, וְחַיִּים וְשָׁלוֹם. <small>(וְכָל טוּב)</small> וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרֹב עֹז וְשָׁלוֹם.", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה, הַמְּבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>אֱלֹהַי.</b> נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וְאַחֲרֵי מִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַקָּמִים וְהַחוֹשְׁבִים עָלַי לְרָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:", "<b><b><small>יש אומרים כאן תפילה זו:</small></b></b>", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי. שֶׁלֹּא תַעֲלֶה קִנְאַת אָדָם עָלַי וְלֹא קִנְאָתִי עַל אֲחֵרִים. וְשֶׁלֹּא אֶכְעוֹס הַיֹּום וְשֶׁלֹּא אַכְעִיסֶךָ. וְתַצִּילֵנִי מִיֵּצֶר הָרָע. וְתֵן בְּלִבִּי הַכְנָעָה וַעֲנָוָה. מַלְכֵּנוּ וֵאלֹהֵינוּ אֱלֹהַּ כָּל בָּשָׂר. יַחֵד שִׁמְךָ בְּעוֹלָמֶךָ בְּנֵה עִירֶךָ יַסֵּד בֵּיתֶךָ וְשַׁכְלֵל הֵיכָלֶךָ. וְקַבֵּץ קִבּוּץ גָּלֻיּוֹת וּפְדֵה צֹאנֶךָ וְשַׂמַּח עֲדָתֶךָ: <b>עֲשֵׂה</b> לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי:", "<b><b><small>נוהגים לומר כאן פסוק המתחיל וגומר באוֹת שבה מתחיל וגומר שמו הפרטי</small></b></b>", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>עֹשֶׂה שָׁלוֹם</b> בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b>וְעָרְבָה</b> לַיהֹוָה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b><b><small><b>בראש חודש</b> אומרים כאן הלל...</small></b></b>", "<b><b><small>קדיש שלם</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>תִּתְקַבֵּל</b> צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא, וְאִמְרוּ אָמֵן:", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small>שיר של יום</small></b></b>", "<b><b><small><b>הַיּוֹם</b> יוֹם שַׁבָּת קֹדֶשׁ שֶׁבּו הָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ:</small></b></b>", "<b>מִזְמוֹר שִׁיר</b> לְיוֹם הַשַּׁבָּת: טוֹב לְהֹדוֹת לַיהֹוָה וּלְזַמֵּר לְשִׁמְךָ עֶלְיוֹן: לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ וֶאֱמוּנָתְךָ בַּלֵּילוֹת: עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל עֲלֵי הִגָּיוֹן בְּכִנּוֹר: כִּי שִׂמַּחְתַּנִי יְהֹוָה בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשֶׂיךָ יְהֹוָה מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ: אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת: בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרוֹם לְעֹלָם יְהֹוָה: כִּי הִנֵּה אֹיְבֶיךָ יְהֹוָה כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה: שְׁתוּלִים בְּבֵית יְהֹוָה בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ: עוֹד יְנוּבוּן בְּשֵׂיבָה דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר יְהֹוָה צוּרִי וְלֹא עַוְלָתָה בּוֹ:", "<b><b><small>קדיש יתום</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small><small>בראש חדש אחר שיר של יום אומרים ברכי נפשי</small></small></b></b>", "<small><b>בָּרֲכִי</b> נַפְשִׁי אֶת יְהֹוָה יְהֹוָה אֱלֹהַי גָּדַלְתָּ מְּאֹד הוֹד וְהָדָר לָבָשְׁתָּ: עֹטֶה אוֹר כַּשַּׂלְמָה נוֹטֶה שָׁמַיִם כַּיְרִיעָה: הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו הַשָּׂם עָבִים רְכוּבוֹ הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ: עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט: יָסַד אֶרֶץ עַל מְכוֹנֶיהָ בַּל תִּמּוֹט עוֹלָם וָעֶד: תְּהוֹם כַּלְּבוּשׁ כִּסִּיתוֹ עַל הָרִים יַעַמְדוּ מָיִם: מִן גַּעֲרָתְךָ יְנוּסוּן מִן קוֹל רַעַמְךָ יֵחָפֵזוּן: יַעֲלוּ הָרִים יֵרְדוּ בְקָעוֹת אֶל מְקוֹם זֶה יָסַדְתָּ לָהֶם: גְּבוּל שַׂמְתָּ בַּל יַעֲבֹרוּן בַּל יְשׁוּבוּן לְכַסּוֹת הָאָרֶץ: הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים בֵּין הָרִים יְהַלֵּכוּן: יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם: עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן מִבֵּין עֳפָאיִם יִתְּנוּ קוֹל: מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו מִפְּרִי מַעֲשֶׂיךָ תִּשְׂבַּע הָאָרֶץ: מַצְמִיחַ חָצִיר לַבְּהֵמָה וְעֵשֶׂב לַעֲבֹדַת הָאָדָם לְהוֹצִיא לֶחֶם מִן הָאָרֶץ: וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ לְהַצְהִיל פָּנִים מִשָּׁמֶן וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד: יִשְׂבְּעוּ עֲצֵי יְהֹוָה אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע: אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ: הָרִים הַגְּבֹהִים לַיְּעֵלִים סְלָעִים מַחְסֶה לַשְׁפַנִּים: עָשָׂה יָרֵחַ לְמוֹעֲדִים שֶׁמֶשׁ יָדַע מְבוֹאוֹ: תָּשֶׁת חֹשֶׁךְ וִיהִי לָיְלָה בּוֹ תִרְמֹשׂ כָּל חַיְתוֹ יָעַר: הַכְּפִירִים שֹׁאֲגִים לַטָּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם: תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן וְאֶל מְעוֹנֹתָם יִרְבָּצוּן: יֵצֵא אָדָם לְפָעֳלוֹ וְלַעֲבֹדָתוֹ עֲדֵי עָרֶב: מָה רַבּוּ מַעֲשֶׂיךָ יְהֹוָה כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךָ: זֶה הַיָּם גָּדוֹל וּרְחַב יָדָיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדֹלוֹת: שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ: כֻּלָּם אֵלֶיךָ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ: תִּתֵּן לָהֶם יִלְקֹטוּן תִּפְתַּח יָדְךָ יִשְׂבְּעוּן טוֹב: תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן תֹּסֵף רוּחָם יִגְוָעוּן וְאֶל עֲפָרָם יְשׁוּבוּן: תְּשַׁלַּח רוּחֲךָ יִבָּרֵאוּן וּתְחַדֵּשׁ פְּנֵי אֲדָמָה: יְהִי כְבוֹד יְהֹוָה לְעוֹלָם יִשְׂמַח יְהֹוָה בְּמַעֲשָׂיו: הַמַּבִּיט לָאָרֶץ וַתִּרְעָד יִגַּע בֶּהָרִים וְיֶעֱשָׁנוּ: אָשִׁירָה לַיהֹוָה בְּחַיָּי אֲזַמְּרָה לֵאלֹהַי בְּעוֹדִי: יֶעֱרַב עָלָיו שִׂיחִי אָנֹכִי אֶשְׂמַח בַּיהוָה: יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם בָּרֲכִי נַפְשִׁי אֶת יְהֹוָה הַלְלוּיָהּ:</small>", "<small><b><b><small>קדיש יתום</small></b></b></small>", "<small><b><b><small> <b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b></small>", "<small><b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:</b></b></small><b><b>"]}, "zachor": {"ref": "Siddur Sefard, Yotzerot, Parashat Zachor", "he": "יוצר לפרשת זכור", "nusach": "סידור ספרד (תורת אמת)", "version": "Torat Emet 357", "source": "http://www.toratemetfreeware.com/index.html?downloads", "url": "https://www.sefaria.org/Siddur_Sefard%2C_Yotzerot%2C_Parashat_Zachor", "segs": ["<b><b><big><b>יוצר לפרשת זכור</b></big></b></b>", "<b>אֲדֹנָי</b> שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי אַבְרָהָם. אֱלֹהֵי יִצְחָק. וֵאלֹהֵי יַעֲקֹב. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן. גּוֹמֵל חֲסָדִים טוֹבִים. קוֹנֵה הַכֹּל. וְזוֹכֵר חַסְדֵי אָבוֹת. וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה: מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן:", "<b>מִסּוֹד</b> חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בְּשִׁיר וּרְנָנִים. לְהוֹדוֹת וּלְהַלֵּל פְּנֵי שׁוֹכֵן מְעוֹנִים:", "<b>אַזְכִּיר</b> סֶלָה זִכְרוֹן מַעֲשִׂים. בַּיָמִים הָאֵלֶּה נִזְכָּרִים וְנַעֲשִׂים. גָחוֹן גָּח מִבֵּין עֲכָסִים. דֵּרְאוֹנוֹ לְהַזְכִּיר לְרֶקֶב כְּעָסִים: הַחוֹחַ הֵנֵץ מִגַּלְגַּל וְדַרְדַּר. וּמִדּוֹר לְדוֹר גֻּלְגַּל וְדֻרְדַּר. זֵכֶר עֲוֹן אֲבוֹתָיו הָקְדַּר. חַטַּאת אִמּוֹ בְּלִי לְהַעְדַּר: טָרַף אַף וַיַּשְׁחֵת רַחַם. יְחוּמָתוֹ מִקְּלוֹט בְּהֵרָיוֹן יַחַם. כְּהָפְקַד לְשָׁלִישׁוֹ חֵטְא נוֹחַם. לֻבַּט לְהִלָּחֵם בְּלוֹחֲמֵי לָחֶם: מַהֲלַךְ אַרְבַּע מֵאוֹת פַּרְסָה. נָע וְנָד מִכְמוֹרֶת לְפָרְסָה סָע מִשֵׂעִיר וְהִכְמִין פְּרוּסָה. עָיֵף וְיָגֵעַ מְבוּשָׁיו לְסָרְסָה: פּוֹעֵל שְׂטִימַת בְּכוֹרָה לַעֲכוֹר. צְמִיתוּת צֹאן קָדָשִׁים לִמְכּוֹר. קְלוֹנוֹ הָחֳרַט בָּעֵט לִזְכּוֹר. רֵאשִׁית גּוֹיִם לְגַלַּע בְּזָכוֹר: שַׁדַּי זָכַר לַיְלָה חוֹלֵק. שֹׁרֶשׁ וְעָנָף בַּחֲלַקְלַק לְהַחֲלֵק:", "<b><b><small>חזן:</small> <b>תְּמוּר</b> כִּי חֲשָׁלָיו הִמְלֵק. תָּבַע לְהִזָּכֵר מַעַשׂ עֲמָלֵק:</b></b>", "<b>לָאַחֲרוֹנָה</b> יִסְעוּ שֶׁבָּם שָׁלַט. כִּי הֶעָנָן מַטָּם פָּלַט:", "<b><b><small>חזן:</small> <b>לְעֵת</b> יִמָּחֶה וְלֹא יֻמְלַט. יְגוֹנֵן עַם גָּנוֹן וּמוּפְלָט:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה. מָגֵן אַבְרָהָם: אַתָּה גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מַשִׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם:", "<b>מְכַלְכֵּל</b> חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה: וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים:", "<b>תְּמִימִים</b> בְּעוֹדָם בְּסִין רְפוּדִים. שִׁבּוּץ עֲדִי עֲדָיִים אֲפוּדִים. רָצוּ שְׁלוֹל מַתַּן לַפִּידִים. קָפְצוּ יָדַיִם רָפוֹת בִּרְפִידִים: צוֹרֵר אִסֵּף כָּל אֲסַפְסוּף. פּוֹשֵׁעַ סְבִיבוֹת מַחֲנָם אָסוּף. עֲלוֹת פְּעָמֵימוֹ מִמְּצוּלוֹת סוּף. סִבֵּר לְקָמְלָם כְּקָנֶה וָסוּף: נֻדַּד וַיָּעָף שָׁלֹשׁ פְּעָמִים. מְחַזֵּר בְּנִינֵי חֲמִשָּׁה עֲמָמִים. לֵץ הֻכָּה וּפֶתִי הֶעֱמִים. כֻּלַּל לְהִתְיַחֵס נְדִיבֵי עַמִּים: יָהַר לֵץ וְהֶעֱמִיד מְסִלָּה. טִכּוּס בַּחוּרַי בְּזִמָּה סִלָּה. חַמּוּקֵי יְרֵכַי בָּם לְפָסְלָה. זֶרַע לְהַרְבִּיעַ וּלְהַתְעִיב סְגֻלָּה: וַיִּשְׂטוֹם שְׂטִימַת יְשִׁישׁוֹ הַמְּחֻבָּא. הֵחֵל לָבוֹא מֵרֹאשׁ בַּמַּחְבָּא. דָּגַר שֵׁנִית בְּחֶרֶב לְהוּבָה. גָּשׁ בַּשְּׁלִישִׁי בַּעֲלִיל בְּחוֹבָה: בְּמָשְׁלוֹ שֶׁשְׁכִי בְּאוֹם מוֹשְׁלִים. בְּפֶרֶק עָמַד מְסוֹר נְשׁוּלִים.", "<b><b><small>חזן:</small> <b>אָמְרוּ</b> לְכוּ וְנַכְחִיד נִכְשָׁלִים. אָז כְּמֵאָז זִנֵּב כָּל הַנֶּחֱשָׁלִים:</b></b>", "<b>שׂוֹנְאֶיךָ</b> הֵם יִלְבְּשׁוּ בשֶׁת. כְּמוֹ בְּצַלְעִי שָׂמְחוּ בַיַּבָּשֶׁת:", "<b><b><small>חזן:</small> <b>בַּעֲטוֹתְךָ</b> עֲשֶׂרֶת עֶדְיֵי תִלְבּוֹשֶׁת. לְהַגְשִׁים תֶּחִי לְצוֹלַעַת תַּחְבּוֹשֶׁת:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<b>אֲצִילֵי</b> מְרֵעִי נֶכֶד שֵׂעִיר. תּוֹלְדוֹת אֵלֶּה בְּנֵי שֵׂעִיר. בְּקַשָּׁם אָצוּ אִשִׁי לְהַבְעִיר. שְׁאוֹנָם חָרְשׁוּ כְּשָׂדֶה עִיר: גּוֹי גָּדוֹל שֶׁלֹּא הִזְכַּרְתָּ. רִשְׁיוֹנוֹתָיו לָמָה אָז זָכַרְתָּ. דְּגָלִים בְּלֹא הוֹן מָכַרְתָּ. קְדוֹשִׁים בַּזּוֹנָה וּבַיַּיִן הִמְכַּרְתָּ: הִזָּכֵר לָאֲדוֹמִים נָוֶה נִאֲרוּ. צָרִים אֲשֶׁר חוֹמוֹת עִרְעֲרוּ. וְעַד הַיְסוֹד עָרוּ עָרוּ. פִּימוֹ דִּבְּרוּ בְגֵאוּת וּפָעָרוּ: זֶה אֵין לְפָנֶיךָ שִׁכְחָה. עֶבְרָתָם שְׁמָרָה נֶצַח מִלְּשַׁכְּחָה. חֵלֶף לֹא יָדְעוּ עֲשׂוֹת נְכוֹחָה. סִפְרָם חֲתוֹם לְיוֹם תּוֹכֵחָה: טַעַם חוֹק בְּדָת מוּכַח. נִזָּכֵר כִּי לֹא תִשָּׁכַח.", "<b><b><small>חזן:</small> <b>יוֹם</b> בֹּא עִמָּם לְהִתְוַכַּח. מִכַּאן צִוִיתָ לְעַמְּךָ לֹא תִּשְׁכָּח:</b></b>", "<b>יָקַשׁ</b> לֵץ לְחָרֵף צְבָאוֹת. הַחֲתוּמֵי בְרִית בְּצָבָא וָאוֹת. וְהוּפְקַד מִדָּה בְּמִדָּה לְתוֹצָאוֹת:", "<b><b><small>חזן:</small> <b>דַעַת</b> כִּי לְעֵת הַמְּצִיאוֹת. הוּא יִפָּקֵד בְּשֵׁם יְהֹוָה צְבָאוֹת:</b></b>", "<b><b><small>חו\"ק:</small> <b>יִמְלוֹךְ</b> יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל אֵל נָא:</b></b>", "<b>אֵל</b> נָא בְּלָשׁוֹן אֲשֶׁר הִזְכַּרְתָּ לְזוֹכְרֶיךָ זְכוֹר. בּוֹ בְלָשׁוֹן הִזְכִּירוּךָ נָא אַתָּה זְכוֹר. וְאִם הֵמָּה כְּאָדָם עָבְרוּ בְרִית מִלִּזְכּוֹר. וְאַתָּה אֵל וְלֹא אִישׁ לָמָּה לֹא תִזְכּוֹר. בְּזֹאת יָדַעְתִּי כִּי יֵשׁ לְךָ לִזְכּוֹר. אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי עַד זָכוֹר תִּזְכּוֹר. וּמַה כֹּחִי כִּי אֲיַחֵל לְקֵץ זָכוֹר. וּמַה קִּצִּי כִּי אַאֲרִיךְ נַפְשִׁי עַד שֶׁתִּזְכּוֹר. אִם לֹא לְמַעֲנִי תִּזְכּוֹר. לְמַעַנְךָ וּלְמַעַן יְרוּשָׁלַיִם זְכוֹר. חוֹק כִּי לֹא תִשָּׁכַח עֵדוּת זְכוֹר. וְאוֹמֵר אִם אֶשְׁכָּחֵךְ עַתָּה לָהּ זְכוֹר. וְתִפְקוֹד וְתִזְכּוֹר. כְּאֵב צָר לַעֲכוֹר. פִּיהוּ לִסְכּוֹר. לָנוּעַ כַּשִּׁכּוֹר. וְעוֹד בַּל תִּמְכּוֹר. נְקוּבֵי בֵּן בְּכוֹר:", "<b><b><small>חזן:</small> <b>נְכוּרֵי</b> בְלֶתֶךְ וָכוֹר. וּפְאֵרָךְ אֶזְכּוֹר. וַאֲרַצְּךָ לִזְכּוֹר. בְּפָרָשַׁת זָכוֹר:</b></b>", "<b><b><small>חו\"ק:</small> <b>חַי</b> וְקַיָּם נוֹרָא וּמָרוֹם וְקָדוֹשׁ:</b></b>", "<b>אָץ</b> קוֹצֵץ בֶּן קוֹצֵץ. קְצוּצַי לְקַצֵּץ. בְּדִבּוּר מְפוֹצֵץ. רְצוּצַי לְרַצֵּץ: לֵץ בְּבֹא לְלוֹצֵץ. פֻּלַץ וְנִתְלוֹצֵץ. כְּעָץ מְחַצְּצִים לְחַצֵּץ. כְּנֵץ עַל צִפּוֹר לְנַצֵּץ: עָב בָּקַע מֵרֹאשׁ. יְחִידִים מֶנּוּ גְרוֹשׁ. חָל וַיֵּלֶךְ וַיִּפְרוֹשׁ. וַיָּשָׁב עַל גַּבִּי חֲרוֹשׁ: זֻמַּן וְהָנְקַב לְרֹאשׁ. רֵאשִׁית גּוֹיִם לָרַע לִדְרוֹשׁ. הֱיוֹת לְכָל בּוֹגְדִים רֹאשׁ. וְצִפְעוֹ תְּלוֹת בְּמִבְחַר בְּרוֹשׁ: רָץ וְהִקְרָה בַּדֶּרֶךְ. עֲיֵפֵי טַרְחוּת דֶּרֶךְ. וּפָץ לֹא זוֹ הַדֶּרֶךְ. תָּעוּ בַמִּדְבָּר בִּישִׁימוֹן דָּרֶךְ: כְּנָחָשׁ עֲלֵי דֶרֶךְ. שָׁלַח יָד בְּחַמּוּקֵי יֶרֶךְ. וְעַל כָּל רֹאשׁ דֶּרֶךְ. זִנֵּב כָּל עוֹבְרֵי דָּרֶךְ: יָעַף וְעָף וְחָשׁ. וּמֵחוּר פֶּתֶן רָחַשׁ. וְנוֹדַע כִּי הוּחָשׁ. מִשּׁוֹרֶשׁ נָחָשׁ: רָגַשׁ וְלָחַשׁ. וְעֵת לֵדָתוֹ נִחַשׁ. וּבִכְשָׁפָיו הָכְחַשׁ. וּבְחַלָּשׁ נֶחֱלַשׁ וְלֹא חָשׁ: בִּכְשָׁפָיו הִלְלוֹ. וּבִקְסָמָיו חִלְּלוֹ. יוֹם הֶעֱמִיד וְזִלְלוֹ. שֶׁמֶשׁ הִדְמִים וְזִלְזְלוֹ: יָגַע וְלֹא הוּנַּח לוֹ. וְלַחֲרָפוֹת נִחֲלוֹ. עַד בֹּא הַשֶּׁמֶשׁ הִזְחִילוֹ. לְהִמָּחוֹת הוּא וְכָל חֵילוֹ: קָט וְשֵׁן חָרַק. וְנֶאָצוֹת שָׁרַק. זְמוֹרָה בְּאַפּוֹ הֵרַק. וְחַרְבּוֹ הִבְרַק: לַמִּילָה פֵּרַק. וּכְלַפֵּי מַעֲלָה זָרַק. וּלְשֵׁם שֶׁמֶן תּוּרַק. בְּעַזּוּת יָרוֹק יָרַק: יָהּ אֶשְׁכּוֹל הַכּוֹפֶר. צָו אֶל מְשׁוּל עוֹפֶר. זִכְרוֹן מִשְׁלֵי אֵפֶר. כְּתוֹב זֹאת זִכָּרוֹן בַּסֵּפֶר: רֻשַׁם בְּזֶה סֵפֶר. בַּתּוֹרָה וּבַנְּבִיאִים וּבַכְּתוּבִים לְהֵחָפֵר. לְהִמָּחוֹת מִסֵּפֶר. וְלֹא יִכָּתֵב עִם כָּל הַכָּתוּב לַחַיִּים בַּסֵּפֶר:", "<b>אֵל</b> נָא לְעוֹלָם תָּעֳרָץ. וּלְעוֹלָם תֻּקְדָּשׁ. וּלְעוֹלְמֵי עוֹלָמִים תִּמְלוֹךְ וְתִתְנַשֵׂא. הָאֵל מֶלֶךְ נוֹרָא מָרוֹם וְקָדוֹשׁ. כִּי אַתָּה הוּא מֶלֶךְ מַלְכֵי הַמְּלָכִים. מַלְכוּתוֹ נֶצַח. נוֹרְאוֹתָיו שִׂיחוּ. סַפְּרוּ עֻזּוֹ. פָּאֲרוּהוּ צְבָאָיו. קַדְשׁוּהוּ רוֹמְמוּהוּ. רוֹן שִׁיר וָשֶׁבַח. תּוֹקֶף תְּהִלוֹת תִּפְאַרְתּוֹ:", "<b>וּבְכֵן זָכוֹר אֵת אֲשֶׁר עָשָׂה לְךָ עֲמָלֵק:</b>", "<b><b><small>חו\"ק:</small> <b>וּמַח</b> שְׁמוֹ וְזִכְרוֹ. וְנִמַּח זְכוּרוֹ מִלְּהַזְכִּירוֹ. בְּזִכְרוֹן קָדוֹשׁ:</b></b>", "<b><b><small>חו\"ק:</small> <b>יַעַן</b> אֲשֶׁר לֹא זָכַר. וְנֶחְשַׁב כַּנֵכָר. מִלְּהִזָּכֵר בְּזִכְרוֹן קָדוֹשׁ:</b></b>", "<b>זָכוֹר</b> אִישׁ אֲשֶׁר הִגְוִיעַ אָב לְלֹא עִתּוֹ. בְּרָצוֹחַ וְגָנוֹב וְנָאוֹף בִּעֲתוֹ. גָּרַע חָמֵשׁ שָׁנִים מִמִחְיָתוֹ: זָכוֹר בּוֹזֶה עַל גְּמִילוּת חֶסֶד. גּוֹעֵל אָח עָשׂ לִזְקֵנוֹ חֶסֶד. דּוֹמֶה לַמָּס מֵרֵעֵהוּ חָסֶד: זָכוֹר גִלָּה עֶרְוַת מְצוּאַת שָׂדֶה. דָּם שָׁפַךְ בְּבוֹאוֹ מִן הַשָׂדֶה. הָפַךְ לֵב אָב שָׂח בַּשָׂדֶה: זָכוֹר דָּחוּי בְּאֹזֶן הָעֲרֵלָה. הַבּוֹזֶה בְּכוֹרָה בְּכוֹס הַתַּרְעֵלָה. וּפָרַק מֶנּוּ עוֹל וּמָשַׁךְ לוֹ עָרְלָה: זָכוֹר הֲפַכְפַּךְ דֶּרֶךְ אִישׁ וָזָר. וְהִכְהָה מְאוֹר אָב בַּעֲשַׁן עֲבוֹדַת זָר. זָמַם בְּלֵב הֱיוֹת לְאָח לְאַכְזָר: זָכוֹר וְנִתְעוֹלֵל לְרֶבַע כְּאִשָּׁה. זְדוֹן לִבּוֹ הִשִׁיאוֹ בָּאְשָׁה. חַתּוּ גִבּוֹרָיו לִהְיוֹת כְּלֵב אִשָּׁה: זָכוֹר זֶרַע מְרֵעִים נִתְעָב וְנֶאֱלָח. חָלַק לְהַשְׁחִית וְלוֹמַר הֶאָח. טָמְנוּ גֵּאִים פַּח לְחַבֵּל אָח: זָכוֹר חָנַט מֶנּוּ עֲמָלֵקִי. טָס כְּיֶלֶק לְאַבֵּד חֶלְקִי. יָרוֹעַ כַּבִּירִים לְעֵין כֹּל לְלוֹקְקִי: זָכוֹר טָפַשׁ מֵהַעֲרִימָה. יָרַד וְכִתֵּת עַמִּי עַד חָרְמָה. כְּמוֹ כֵן חֻיַּב לְהַחֲרִימָה: זָכוֹר יוֹשֵׁב הַנֶּגֶב בְּלִי עוֹל כַּעֲרָד. כְּסוּת וְלָשׁוֹן שִׁנָּה הֱיוֹת מֶלֶךְ עֲרָד. לִשְׁבּוֹת שֶׁבִי מָרַד וְחָרַד: זְכוֹר כְּסִיל שׁוֹנֶה בְּאִוַּלְתּוֹ. לְתַעֲרוּבַת מִדְיָן בַּעֲלוֹתוֹ. מִהֵר יְרֻבֶּשֶׁת וְגִלָּה נַבְלוּתוֹ: זָכוֹר לְקַעֲקֵעַ בִּצָתוֹ מִשׁוֹרֶשׁ. מִלַעֲזוֹב לוֹ עָנָף וְגַם שׁוֹרֶשׁ. נֶעֱנַשׁ קִישִׁי כִּי הִשְׁאִיר לוֹ שׁוֹרֶשׁ: זָכוֹר מַעֲשֵׂה אֲגַג מַעֲדַנּוֹת. נָשִׁים כְּשִׁכְּלָה חַרְבּוֹ לְעַנוֹת. סוֹרַס שְׁאֵרוֹ לְשִׁסוּף יַעֲנוֹת: זָכוֹר נָגִיד לְחָמְלוֹ הִסְכִּים. סָר מִמְּלוּכָה מִבֵּין נְסִיכִים. עוֹלֵל הַנּוֹתָר עָמַד לְשִׂכִּים: זָכוֹר סִבֵּב צִקְלַג וָנֶגֶב. עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. פִּגְרוֹ טוֹב רוֹאִי מְנַשֵׁף בְּעֻגָב: זָכוֹר עָרִיץ בְּעַמּוֹנִים נֶחְבָּא. פֶּרֶץ כַּרְמֵי עֵין גֶּדִי כְּהוּבָא. צוֹרְבוּ אִישׁ בְּאָחִיו בְּחֶרֶב לְהוּבָה: זָכוֹר פְּלֵטִים אֲשֶׁר בְּאַף הִסְעִיר. צְבָאַי בְּלֶכְתָּם אֶל הַר שֵּׂעִיר. קַנֹּא לִנְקוֹם עֲיָרוֹת שֵׂעִיר: זָכוֹר צָג בְּפֶרֶק לְהַסְגִּיר שְׂרִידַי. קָם בְּרֹאשׁ דְּרָכִים לִסְעוֹד אֶת רוֹדַי. רָדַף וּמָסַר בְּיָדָם פְּרוּדַי רְפוּדַי: זָכוֹר קָפַץ לְשַׁעַר הַשָׁמַיִם. רָעַשׁ וְשָׁאַג מִי לִי בַּשָׁמַיִם. שָׁלַט וַיִּגְדַּל עַד לַשָׁמָיִם: זָכוֹר רָד אֶל חָנֵף לְהַחֲנִיף מַמְלֶכֶת. שִׁמְשַׁי אֲשֶׁר שִׁמְשׁוֹ מְאַמֶּשֶׁת וְהוֹלֶכֶת. תַּמָה הִלְשִׁין לְרַפּוֹתָהּ מִמְלֶאכֶת: זָכוֹר שָׁקַל אֲלָפִים עֲשָׂרָה. שְׁתִילִים מֵאָה הֶחֶנִיט לְשִׂבְרָה. שִׁעֵר מֵהֶם עֲשָׂרָה לִשְׂרָרָה: זָכוֹר תָּבַע לְהָפֵר חֻמָּשִׁים. תְּמִימָה קָצַב לְכַלּוֹת חֲמֻשִׁים. תַּכְלִית שִׁבְעִים נִתְלָה עַל חֲמִשִׁים:", "<b>וּבְכֵן</b> וּלְךָ תַעֲלֶה קְדֻשָּׁה כִּי אַתָּה קְדוֹשׁ יִשְׂרָאֵל וּמוֹשִׁיעַ:", "<b>אֱלֹהִים</b> אַל דֳּמִי לָךְ. בְּקוֹל מַיִם רַבִּים נִשְׁמַע קוֹלָךְ. מַשְׁמִיעַ וּמְצַוֶּה לְעַמְּךָ בְּקִנְיַן פָּעֳלָךְ:", "<b>זָכוֹר</b> אֵת אֲשֶׁר עָשָׂה לָךְ. אֲשֶׁר קָרְךָ וַיַּחֲשִׁילָךְ. וְהָיָה בְּהָנִיחַ יְהֹוָה אֱלֹהֶיךָ לָךְ. תִּמְחֶה זִכְרוֹ מִכָּל גְּבוּלָךְ. וְהֵם יָשִׁיבוּ וְיֹאמְרוּ לָךְ. וּמִשֶׁלָּךְ עוֹד יִתְּנוּ לָךְ. אָנָא הָקֵם אֶת דְּבַר מִלּוּלָךְ. עַד שָׁאַתָּה מְצַוֵּנוּ הִזָּכֵר לָךְ. אַתָּה זְכוֹר אֵת אֲשֶׁר עָשׂוּ לָךְ. זְכוֹר יְהֹוָה אֶת יוֹם זְבוּלָךְ. הַמִּתְגָּאִים וְנוֹאֲמִים פֹּה מַה לָךְ. הַשׁוֹלְחִים זְמוֹרוֹת בְּאַף לְחַלְּלָךְ. זְכוֹר כִּסֵּא כְּבוֹד גָּדְלָךְ. אֲשֶׁר מִגְּרוּ וְנִאֲצוּ לְמוּלָךְ. וְשִׁלְחוּ בָּאֵשׁ הֵיכָלָךְ. וַיַּשִּׁימוּ כָּל גְּבוּלָךְ. וְשִׁדְּדוּ וְנִתְּקוּ יְרִיעוֹת אָהֳלָךְ. אֲשֶׁר צִוִּיתָה לֹא יָבֹאוּ בַקָּהָל לָךְ. אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי בִּגְלָלָךְ. וְלֹא יִזָּכֵר שֵׁם הִלּוּלָךְ. עָלֶיךָ יַעֲזוֹב חֵילָךְ. וְיוֹתֵר מֵאֲשֶׁר עָשׂוּ לָנוּ עָשׂוּ לָךְ: אוֹתָנוּ בַּמִּדְבָּר נִלְחָמוּ. וְאוֹתְךָ בְּיִשׁוּב נִתְלָחֲמוּ. אוֹתָנוּ חוּץ לַמַּחֲנֶה הָמוּ. וְאוֹתְךָ בְּקֶרֶב הַמַּחֲנֶה נָהָמוּ. אוֹתָנוּ פְּלֵיטֵי עָנָן זָמָמוּ. וְאוֹתְךָ כַּפּוֹרֶת עָנָן גָּמָמוּ. אוֹתָנוּ לַחֲשׁוּלֵי עָב דִּמּוּ. וְאוֹתְךָ עֲלוֹת עַל בָּמֳתֵי עָב דָּמָמוּ. אוֹתָנוּ חוּץ מִמְּחִיצָה קָמוּ. וְאוֹתְךָ לִפְנַי וְלִפְנִים קִדְּמוּ. אוֹתָנוּ בְּרִחוּק מָקוֹם אִשְׁמוּ. וְאוֹתְךָ בְּקֶרֶב מְקוֹמְךָ שִׁמְּמוּ. אוֹתָנוּ חוּץ מִישִׁיבָתֵנוּ רָמוּ. וְאוֹתְךָ בִּמְכוֹן שִׁבְתְּךָ דַּמוּ. אוֹתָנוּ אוֹת בְּרִית מִשְׁאֵר הֵרִימוּ. וְאוֹתְךָ עֲשֶׂרֶת אַבִּירֵי בְרִית הֶחֱרִימוּ. אוֹתָנוּ בְהַנָחַת יְדֵי עָנָיו הֵרִימוּ. וְאוֹתְךָ תְּלוֹת יָד לְמוּלְךָ הֵרִימוּ. אוֹתָנוּ נִתְיַעֲצוּ וְסוֹד הֶעֱרִימוּ. וְאוֹתְךָ כְּרוּבֵי סוֹדְךָ לַחֲרָפוֹת הִגְרִימוּ: וְאַתָּה יְהֹוָה לְעוֹלָם תֵּשֵׁב. וְהוּא נֶגְדְּךָ בְּמַטָּה יוֹשֵׁב. תָּפוּשׂ מִדְבָּר וְכָל הַיִשׁוּב. אֲנִי וְאַפְסִי עוֹד בְּלֵב מִתְחַשֵׁב. אִם לֹא עַתָּה תָקוּם וְתַקְשֵׁב. בִּשְׁלֹשׁ עֶשְׂרֵה קִימוֹת נְקָמוֹת לְחַשֵּׁב. בְּפַחַד וָפַחַת וָפַח לִפְקוֹד עַל הַיּוֹשֵׁב. וְאִם אַיִן כַּגֵּר תֵּחָשֵׁב. וְכָל הַמּוֹנֶה וְסוֹפֵר וְחוֹשֵׁב. קֵץ הַפְּלָאוֹת לְהָבִין וּלְחַשֵׁב. נָשְׁתָה גְבוּרָתוֹ מִמְּחַשֵׁב. וְלֹא יִמְצָא מַעֲנֶה לְהָשֵׁב. וְיֶחֱשֶׁה דוּמִיָּה מֵהַקְשֵׁב. וּבֶאֱמוּנָה כְּסָלָיו יְיַשֵׁב. וְזֹאת עַל לִבּוֹ יָשֵׁב. וְיֹאמַר עַד יַשְׁקִיף וְיֵרֶא וְיַקְשֵׁב: וְנֶחֱשַׁבְתִּי כְּעֵד זוֹמֵם. כָּל הַיּוֹם מְדַמֵּם. וְנַפְשִׁי נִבְהֲלָה מְאֹד וּמִשְׁתּוֹמֵם. וְאַתָּה יְהֹוָה עַד מָתַי רוֹאֶה וְדוֹמֵם. זְכוֹר בֵּית מִקְדָּשְׁךָ הַשָׁמֵם. כָּל עוֹבֵר עָלָיו מִשְׁתּוֹמֵם. מָתַי תִּתְנַשֵׂא וְתִתְרוֹמֵם. וְזֶכֶר אֹמֶר פִּיךָ קוֹמֵם. בְּשָׁלֹשׁ עִתּוֹת עֲמָלֵק לְהָמֵם. בְּשָׁלֹשׁ מִיתוֹת זִכְרָם לְהַדְמֵם. בִּשְׁלֹשֶׁת יְמֵי אֲפֵלָה נָגְהָם לְהַעֲמֵם. בְּשִׁבְעָה יְמֵי עֶבְרָה לְהַרְשִׁימֵם. בַּעֲשֶׂרֶת מִינֵי שְׁמָד לְהַאֲשִׁימֵם: וּכְמוֹ מֵעֲשָׂרָה דְבָרִים עִכְּבוּ עָם מֵעֲנוֹת. וּמִשֶׁבַע מִצְוֹת הַמְּיֻשָׁנוֹת. כֵּן בְּעֶשֶׂר וָשֶׁבַע יֻשְׁכְּרוּ לְעַנּוֹת. וּבַת קוֹל תֵּצֵא מִמְּעוֹנוֹת. וּתְפוֹצֵץ בְּכָל הַמַּחֲנוֹת. זִכְרוֹן דְּבָרִים לְהַגִּיד וְלַעֲנוֹת. אַל תִּזְכְּרוּ רִאשׁוֹנוֹת. בִּינוּ נָא יְשׁוּעוֹת אַחֲרוֹנוֹת. וְהַזְכִּירוּ זֵכֶר רְנָנוֹת. עֲמָלֵק אֲשֶׁר בָּא וְעִוֵּת מַחֲנוֹת. וְהֵקַר אֶתְכֶם בִּפְנֵי בָנוֹת. וְיָצָא לוֹ שֵׁם בְּכָל הַמְּדִינוֹת. רְאוּ עַתָּה זֹאת לְתַנּוֹת. אֵיךְ נִמְחֶה בְּחֶתֶף בְּכָל פִּנּוֹת. וּצְבָא הַמָּרוֹם אֲשֶׁר בִּמְעוֹנוֹת. אֲשֶׁר הוּסְמַךְ עֲלֵיהֶם בְּמַשְׁעֵנוֹת. יִפְקוֹד עֲלֵיהֶם אֶת הָעֲוֹנוֹת. לְרוֹב יָמִים לְהִמָּנוֹת. לַחֲשׁוֹב לָהֶם חִשְׁבּוֹנוֹת. לְהַפִּילָם לְתוֹפֶת דֵּרְאוֹנוֹת. וַהֲמוֹן לְאֻמִּים וְכָל הַלְּשׁוֹנוֹת. עַל עוֹזֵר וְעָזוּר יִשְׂאוּ קִינוֹת. וְכָשַׁל עוֹזֵר וְנָפַל עָזוּר מְקוֹנְנוֹת: וְיֵדַע כָּל פָּעוּל כִּי לֹא שָׁכַחְתָּ. וְיָבִין כָּל יְצִיר כִּי שְׁמָם שִׁכַּחְתָּ. וְשֵׂעִיר וְשָׂרָיו אָז וִכַּחְתָּ. וַעֲמָלֵק וְטַפְסְרָיו הוֹכַחְתָּ. וְאִתָּם בַּמִּשְׁפָּט נִתְוַכַּחְתָּ. וְיֻזְכְּרוּ עַם אֲשֶׁר זָכַרְתָּ. כִּי לְטוֹבָה אוֹתָם זָכַרְתָּ. וּבְזִכְרוֹן טוֹב אִתָּם נִזְכַּרְתָּ:", "<b><b><small>חזן:</small> <b>וְהַמַּזְכִּירִים</b> אֶת יְהֹוָה. יֹאמְרוּ תָמִיד יִגְדַּל יְהֹוָה. וְיֹאמְרוּ גְּאוּלֵי יְהֹוָה. כֵּן יֹאבְדוּ כָּל אֹיְבֶיךָ יְהֹוָה. וְהָעוֹמְדִים בְּבֵית יְהֹוָה. וְהַבּוֹטְחִים בַּיהֹוָה. וְהַשְּׁתוּלִים בְּבֵית יְהֹוָה. יֶחֱזוּ בְּנוֹעַם יְהֹוָה. וְיַגִּידוּ כִּי אֵין קָדוֹשׁ כַּיהֹוָה. כִּי אֵל רַחוּם יְהֹוָה. אַשְׁרֵי כָּל יְרֵא יְהֹוָה. טוֹב לְהוֹדוֹת לַיהֹוָה. טוֹב לַחֲסוֹת בַּיהֹוָה. רַנְנוּ צַדִיקִים בַּיהֹוָה. קוֹל אוֹמְרִים הוֹדוּ אֶת יְהֹוָה. כִּי הֵם זֶרַע בֵּרַךְ יְהֹוָה. זֶה הַיּוֹם עָשָׂה יְהֹוָה. כִּי אֵל גָּדוֹל יְהֹוָה. בָּרוּךְ הַבָּא בְּשֵׁם יְהֹוָה. שׂוֹשׂ אָשִׂישׂ בַּיהֹוָה. ע\"כ: וְאִם כָּל הַמּוֹעֲדִים יִהְיוּ בְּטֵלִים. יְמֵי הַפּוּרִים לֹא נִבְטָלִים. וְזִכְרָם לֹא יָסוּף מִנֻּטָּלִים. וְיֻזְכְּרוּ לָעַד גְּאוּלִים. לְשָׂשׂוֹן וּלְשִׂמְחַת גִּילִים. מִפְעֲלוֹת אֱלֹהִים מְגַלִּים. וֶעֱזוּז נוֹרְאוֹתָיו מַגְדִּילִים. וְשָׁרִים כְּחוֹלְלִים. בַּעֲשֶׂרֶת מִינֵי עָשׂוֹר מְסַלְסְלִים. בְּכִנּוֹרוֹת וּבִנְבָלִים. בַּעֲשֶׂרֶת מִינֵי הַלֵּל מְהַלְלִים. בַּעֲשֶׂרֶת מִינֵי שִׂמְחָה צֹהֲלִים. וְשַׂרְפֵי הַקֹּדֶשׁ הַמְּעֻלִים. כְּתַלְמִיד לָרַב יִהְיוּ לָמוֹ שׁוֹאֲלִים. מַה פָּעַל אֵל אֵלִים: כִּי אֵלֶּה יִהְיוּ מִבִּפְנִים. וְאֵלֶּה מִלִּפְנֵיהֶם מְפַנִּים וְאֵלֶּה חוּצָה לָּמוֹ פּוֹנִים. וְאֵלֶּה לִפְנַי וְלִפְנִים. בְּצֵל שַׁדַּי מִתְלוֹנְנִים. וּבַחֲמִשָּׁה קוֹלוֹת הַצְּפוּנִים. קוֹל רִנָּה וִישׁוּעָה מַצְפִּינִים. בְּאָהֳלֵי צַדִיקִים צְפוּנִים. הַהוֹגִים בִּיקָרָה מִפְּנִינִים. וְקִדְּמוּ שָׁרִים אַחַר נוֹגְנִים. לָדַעַת אֵיךְ הֵם מְנַגְּנִים. בְּגַאֲוַת אֲפִיקֵי מָגִנִּים. בְּצִלָּם הֱיוֹת גְּנוּנִים. וּבְאֶבְרָתָם מִתְגּוֹנְנִים. וְעַל חוֹמוֹתָם מִתְמַנִּים. לַשׁוֹעֲרִים וּלְשׁוֹמְרִים מְמֻנִּים. כָּל הַיּוֹם וְכָל הַלַּיְלָה מְזֻמָּנִים. לְהַזְכִּיר קְדֻשַּׁת נוֹצֵר אֱמוּנִים. לְהַעֲרִיץ זְכִירַת גּוֹי שׁוֹמֵר אֱמוּנִים. וּבְשֵׁם יִשְׂרָאֵל מִתְכַּנִּים. וּבְשִׁלּוּשׁ קְדֻשָּׁה לְקָדוֹשׁ מִתְכַּוְּנִים. שְׁתַּיִם בְּרֹאשׁ בָּנִים מַשְׁכִּינִים. וְאַחַת בְּרֹאשׁ מַלְכָּם מַתְקִינִים. וּבִשְׁלָשְׁתָּם הֵם נְכוֹנִים. כִּסֵא שָׁלֵם וְשֵׁם שָׁלֵם מְכִינִים. וּבְשִׁלּוּשׁ קְדֻּשָּׁה עֲנוֹת כְּאָז מְבִינִים. קְרוֹא זֶה אֶל זֶה מְכַוְּנִים. וּבְכִנּוּי שֵׁם קָדוֹשׁ קוֹרְאִים וּמְכַנִּים:</b></b>", "<b><b><small> קדושה</small></b></b>", "<small><b><b><small>נַקְדִּישָׁךְ וְנַעֲרִיצָךְ כְּנֹעַם שִׂיחַ סוֹד שַׂרְפֵי קֹדֶשׁ. הַמְּשַׁלְּשִׁים לְךָ קְדֻשָּׁה. כַּכָּתוּב עַל יַד נְבִיאֶךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר: </small></b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>קָדוֹשׁ</b> קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: <small>חזן:</small> <b>אָז.</b> בְּקוֹל רַעַשׁ גָּדוֹל אַדִּיר וְחָזָק. מַשְׁמִיעִים קוֹל. מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>בָּרוּךְ</b> כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>חזן:</small> מִמְּקוֹמְךָ מַלְכֵּנוּ תוֹפִיעַ. וְתִמְלוֹךְ עָלֵינוּ <small> <small>(מְהֵרָה)</small> </small> כִּי מְחַכִּים אֲנַחְנוּ לָךְ. מָתַי תִּמְלֹךְ בְּצִיּוֹן. בְּקָרוֹב בְּיָמֵינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן. תִּתְגַּדֵּל וְתִתְקַדֵּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵצַח נְצָחִים. וְעֵינֵינוּ תִרְאֶינָה מַלְכוּתֶךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּךָ. עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>יִמְלֹךְ</b> יְהֹוָה לְעוֹלָם. אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר. הַלְלוּיָהּ:</b></b></small><b><b> </b></b>", "<b>אַתָּה קָדוֹשׁ</b>, וְשִׁמְךָ קָדוֹשׁ, וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. כִּי אֵל מֶלֶךְ גָדוֹל וְקָדוֹשׁ אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה, הָאֵל הַקָּדוֹשׁ:", "<b>יִשְׂמַח מֹשֶׁה</b> בְּמַתְּנַת חֶלְקוֹ, כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּוֹ. כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ, בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לוּחוֹת אֲבָנִים הוֹרִיד בְּיָדוֹ, וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת, וְכֵן כָּתוּב בְּתוֹרָתֶךָ:", "<b>וְשָׁמְרוּ</b> בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְהֹוָה אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:", "<b>ולֹא</b> נְתַתּוֹ יְהֹוָה אֱלֹהֵינוּ לְגוֹיֵי הָאֲרָצוֹת, וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים, גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים, כִּי לְעַמְּךָ יִשְׂרָאֵל נְתַתּוֹ בְּאַהֲבָה, לְזֶרַע יַעֲקֹב אֲשֶׁר בָּם בָּחָרְתָּ:", "<b>יִשְׂמְחוּ</b> בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עוֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּוֹ וְקִדַּשְׁתּוֹ. חֶמְדַת יָמִים אוֹתוֹ קָרָאתָ. זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<b>אֱלֹהֵינוּ</b> וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךְ, וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶאֱמֶת, וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבָּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ. בָּרוּךְ אַתָּה יְהֹוָה, מְקַדֵּשׁ הַשַּׁבָּת:", "<b>רְצֵה</b> יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל, וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<b>וְתֶחֱזֶינָה</b> עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. בָּרוּךְ אַתָּה יְהֹוָה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:", "<b>מוֹדִים</b> אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדֹר וָדֹר. נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶיךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם. הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְּרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b><b><small> מודים דרבנן<small><b><small>בחזרת הש\"ץ</small></b> כשהוא אומר מודים, אומרים הקהל:</small> </small></b></b>", "<small><b><b><small>מוֹדִים אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׁר, יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמֹר חֻקֶּיךָ וְלַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְךָ בְלֵבָב שָׁלֵם, עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת.</small></b></b></small>", "<b>וְעַל</b> כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָמִיד לְעוֹלָם וָעֶד.", "<b>וְכֹל</b> הַחַיִּים יוֹדוּךָ סֶּלָה: וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל, בֶּאֱמֶת, לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<b><b>ברכת כהנים</b></b>", "<b>שִׂים שָׁלוֹם</b> טוֹבָה וּבְרָכָה, חַיִּים, חֵן וָחֶסֶד, וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד <small>(יַחַד)</small> בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים, וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים, וְחַיִּים וְשָׁלוֹם. <small>(וְכָל טוּב)</small> וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרֹב עֹז וְשָׁלוֹם.", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה, הַמְּבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>אֱלֹהַי.</b> נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וְאַחֲרֵי מִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַקָּמִים וְהַחוֹשְׁבִים עָלַי לְרָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:", "<b><b><small>יש אומרים כאן תפילה זו:</small></b></b>", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי. שֶׁלֹּא תַעֲלֶה קִנְאַת אָדָם עָלַי וְלֹא קִנְאָתִי עַל אֲחֵרִים. וְשֶׁלֹּא אֶכְעוֹס הַיֹּום וְשֶׁלֹּא אַכְעִיסֶךָ. וְתַצִּילֵנִי מִיֵּצֶר הָרָע. וְתֵן בְּלִבִּי הַכְנָעָה וַעֲנָוָה. מַלְכֵּנוּ וֵאלֹהֵינוּ אֱלֹהַּ כָּל בָּשָׂר. יַחֵד שִׁמְךָ בְּעוֹלָמֶךָ בְּנֵה עִירֶךָ יַסֵּד בֵּיתֶךָ וְשַׁכְלֵל הֵיכָלֶךָ. וְקַבֵּץ קִבּוּץ גָּלֻיּוֹת וּפְדֵה צֹאנֶךָ וְשַׂמַּח עֲדָתֶךָ: <b>עֲשֵׂה</b> לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי:", "<b><b><small>נוהגים לומר כאן פסוק המתחיל וגומר באוֹת שבה מתחיל וגומר שמו הפרטי</small></b></b>", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>עֹשֶׂה שָׁלוֹם</b> בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b>וְעָרְבָה</b> לַיהֹוָה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b><b><small>קדיש שלם</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>תִּתְקַבֵּל</b> צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא, וְאִמְרוּ אָמֵן:", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small>שיר של יום</small></b></b>", "<b><b><small><b>הַיּוֹם</b> יוֹם שַׁבָּת קֹדֶשׁ שֶׁבּו הָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ:</small></b></b>", "<b>מִזְמוֹר שִׁיר</b> לְיוֹם הַשַּׁבָּת: טוֹב לְהֹדוֹת לַיהֹוָה וּלְזַמֵּר לְשִׁמְךָ עֶלְיוֹן: לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ וֶאֱמוּנָתְךָ בַּלֵּילוֹת: עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל עֲלֵי הִגָּיוֹן בְּכִנּוֹר: כִּי שִׂמַּחְתַּנִי יְהֹוָה בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשֶׂיךָ יְהֹוָה מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ: אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת: בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרוֹם לְעֹלָם יְהֹוָה: כִּי הִנֵּה אֹיְבֶיךָ יְהֹוָה כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה: שְׁתוּלִים בְּבֵית יְהֹוָה בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ: עוֹד יְנוּבוּן בְּשֵׂיבָה דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר יְהֹוָה צוּרִי וְלֹא עַוְלָתָה בּוֹ:", "<b><b><small>קדיש יתום</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:"]}, "parah": {"ref": "Siddur Sefard, Yotzerot, Parashat Parah", "he": "יוצר לפרשת פרה", "nusach": "סידור ספרד (תורת אמת)", "version": "Torat Emet 357", "source": "http://www.toratemetfreeware.com/index.html?downloads", "url": "https://www.sefaria.org/Siddur_Sefard%2C_Yotzerot%2C_Parashat_Parah", "segs": ["<b><b><big><b>יוצר לפרשת פרה </b></big></b></b>", "<b>אֲדֹנָי</b> שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי אַבְרָהָם. אֱלֹהֵי יִצְחָק. וֵאלֹהֵי יַעֲקֹב. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן. גּוֹמֵל חֲסָדִים טוֹבִים. קוֹנֵה הַכֹּל. וְזוֹכֵר חַסְדֵי אָבוֹת. וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה: מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן:", "<b>מִסּוֹד</b> חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בְּשִׁיר וּרְנָנִים. לְהוֹדוֹת וּלְהַלֵּל פְּנֵי שׁוֹכֵן מְעוֹנִים:", "<b>אֲצוּלַת</b> אוֹמֶן בְּצֵרוּף זְקוּקָה. בִּנְבָכֶיהָ זֹאת בַּלָּט פְּקוּקָה. גְּלוּמָה עֲלוּמָה וּנְקוּקָה. דִבּוּרָה עַל אוֹפָן חֲקוּקָה. הַמְסֻקָּלָה וְהַמְעֻזָּקָה. וְדִשּׁוּנָהּ דִּשּׁוּן לְמִשְׁמָר חֻקָּה. זֵר שִׁבְעָתַיִם מְזֻקָּקָה. חוֹק טָהוֹר מִטָּמֵא מְחֻזָּקָה. טְבוּעָה בְּלֹא רְחוֹקָה. וְהִיא רְחוֹקָה. יְחוּסָה אֲטוּרָה וּדְחוּקָה.", "<b><b><small>חזן:</small> כִּתְמַת חֲמּוּקָה. בָּהּ מְחוּקָה. לְטָהֳרַת חֲשׁוּקָה. נֶחֱקָקָה זֹאת חֻקָּה: מְקוֹמָהּ יִגְלֶה. מַעֲמַקֶּיהָ יִדְלֶה.  </b></b>", "<b><b><small>חזן:</small> לְעֵת יִגָּלֶה. גְּנוּנָיו יַעֲלֶּה: </b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה. מָגֵן אַבְרָהָם: אַתָּה גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מַשִׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם:", "<b>מְכַלְכֵּל</b> חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה: וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים:", "<b>מִמָּרָה</b> חֻקָּהּ גָזָר. מִגַּבְנוּן אִמְרָהּ נִגְזָר. נֶאֱמָן לְאַזְּנָהּ נִתְאַזָּר. נֶצַח עֲדֵי כֵן בְּנִזְרָהּ נֻזָּר. סְלוֹל צְפוּנֶיהָ חֵלֶץ אָזָר. סָקֵר בְּאִבֶּיהָ וְנֶחְשַׁב לְמוּזָר. עָרַךְ בָּהּ חוֹק לְעַם מְפֻזָּר. עֲבוּר מִלְּפַתֵּל עִקֵּשׁ כְּמִין וָזָר. פְּאֵר בִּקוּרֶיהָ בְּאֶגֶד מְשֻׁזָר. פְּעֻלָּתָהּ בְּסֶגֶן בַּעֲדִי מָשְׁזָר:", "<b><b><small>חזן:</small> צְפוּנָה לְטָהֳרַת עַם אֵל עָזָר. צִוָּה צוּר לְצִיר. צוֹר צְרוּרָה לְאֶלְעָזָר: </b></b>", "<b>עוֹלָם</b> וּמְלוֹאוֹ שֶׁלָּךְ. חָפַצְתָּ לְהַצְדִּיק קְהָלָךְ:", "<b><b><small>חזן:</small> עַל כֵּן אוֹחִיל לָךְ. לְהַגְשִׁים תֶּחִי אֲטוּמֵי פָעֳלָךְ: </b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<b>קִפְּאוֹן</b> חוֹק אֶלְפַּת הַיְקָר. לוּטָה בְּאוֹר יָקָר. חֲשׂוֹף לְעַם מְיֻקָּר. לַעֲמוֹד עַל עִקָּר: רְעֵבִים לְפַעֲנֵחַ דָּתֶיהָ. פֵּעֲנֵחַ מִדּוֹתֶיהָ. צְמֵאִים גְּמוֹת חִידוֹתֶיהָ. גַּלֵּה לָהֶם עֵדוֹתֶיהָ: שֶׁמֶץ דְּגָלִים טַהֵר. מְצָרֵף וּמְטַהֵר. הֶרֶב לְכַבְּסָם תְּמַהֵר. מֵעִוּוּיָם אוֹתָם לְטַהֵר: תִּקְרָא כֹהֵן. בְּחַטְּאָךְ בְּאֵזוֹב מִתְכַּהֵן:", "<b><b><small>חזן:</small> טְהוֹרִים זְרוֹק כִּמְכַהֵן. תְּמוּר דַּם מִקַּח אֶלְעָזָר הַכֹּהֵן: </b></b>", "<b><b><small>חו\"ק:</small> <b>יִמְלוֹךְ</b> יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל אֵל נָא: </b></b>", "<b>אָמַרְתִּי</b> אֶחְכָּמָה וְהִיא רְחוֹקָה. שָׂח אִיתִיאֵל עֲדֵי זֹאת חֻקָּה. בְּלֹא נִפְלֵאת הִיא וְלֹא רְחוֹקָה. זֹאת פְּלִיאָה הִיא וּמְרֻחָקָה. מִלְפָנֶיהָ מִשְׁפָּט וְחֻקָּה. וּמֵאַחֲרֶיהָ תּוֹרָה וְחֻקָּה. בֶּחָרוּת חֲקוּקָה. וּבְלוּחַ לֵב מְחֻקָּה. מִדּוֹק תְּלוּלָה וּמִשְׁאוֹל עֲמוּקָּה. וּמִדָיְרֵי אַרְקָא. מְסִלָּתָהּ חֲמּוּקָה. בְּכֵן אֵין לַעֲמוֹד בְּסוֹדָהּ. וְאֵין לְהַגִּיעַ יְסוֹדָהּ. וְאֵין לַחֲקוֹר חֻקָּהּ. וְאֵין לְהַחֲלִישׁ חֶלְקָהּ: וְאֵין לֵידַע עֶרְכָּהּ. וְאֵין לְהָבִין דַּרְכָּהּ. אֱלֹהִים הֵבִין דַּרְכָּהּ:", "<b><b><small>חו\"ק:</small> <b>חַי</b> וְקַיָּם נוֹרָא וּמָרוֹם וְקָדוֹשׁ: </b></b>", "<b>אֲצוּרָה</b> וּמֻפְרָשָׁה. עֲצוּרָה וְלֹא מְפוֹרָשָׁה. זֹאת חֻקַּת הַפָּרָשָׁה. בְּכָל שָׁנָה מִתְפָּרְשָׁה: לְבַעֲלֵי אֲסוּפוֹת. חִידוֹתֶיהָ חֲשׂוּפוֹת. וְכָל צְרוּרוֹת כְּסוּפוֹת. דִּקְדּוּקֶיהָ סְפוֹת: עֲרוּכָה וּשְׁמוּרָה. קְצוּבָה וּגְמוּרָה. דְּרוּשָׁה וַאֲמוּרָה. בְּקַּלָה וַחֲמוּרָה: זִיְנָהּ לֶעָנָיו. בִּפְנִינֵי מְעוֹנָיו. וְהִגִּיהַּ עֵינָיו. בְּפוּץ מַעְיָנָיו: רָעַד כְּהִסְכִּית טַעַם תְּחִלַּת מִשְׁנָתָהּ. פָּרָה בַּת שְׁתַּיִם עֶגְלָה בַּת שְׁנָתָהּ: בִּצֵּר צִיר תַּחַן כְּקָשַׁב שְׁמוּעָתָהּ. נָא מֶנִּי יִפְרֶה מוֹרֶה הֲלָכָה לְשַׁעְתָּהּ: יִדְעוֹ בָהּ הֲלִיכוֹת. וְשִׁנּוּן הֲלָכוֹת. אֵלֶּה הַנֶּעֱרָכוֹת. וְאֵלֶּה הַמִּתְהַלְכוֹת: רְאִיָּתָהּ אֵיךְ לַחֲזוֹת. דָּמָהּ אֵיךְ לְהַזוֹת. בֵּאוּרָה מִלְהַבְזוֹת. לְחַוּוֹת לְמִי זֹאת: בְּדִבּוּר אֱמוֹר אֶל הַכֹּהֲנִים שֻׁנָּה עוֹז פָּנָיו. שָׁב וַיַּעֲרָךְ זֹאת לְפָנָיו וְהֵאִיר עֵינָיו: יַעַן כְּנֶאֱמַר לוֹ וְלָקְחוּ לַטָּמֵא. פַּלָּצוּת בִּעֲתַתּוּ וְשָׂח מִי יִתֵּן טָהוֹר מִטָּמֵא: קוֹשְׁטְ אִמְרֵי פָרָה. כָּל טָהוֹר מְטַמְּאָה. וְאֵיךְ הִיא תַּעֲבִיר רוּחַ הַטֻּמְאָה: לוֹ הִגִּיד אֵל חֻקָּה חַקְתִּי. וּמַה תְּיַגַע לֵידַע. עֲמוּקָּה מִשְׁאוֹל מַה תֵּדָע: יָבֹא אֵפֶר פָּרָה. לְהַלְבִּין טִנּוּף בֶּן פָּרָה. הֱיוֹת כַּפָּרָה. לְסוֹרֵרָה כְּפָרָה:", "<b><b><small>חזן:</small> רֻמַז בִּוְיִקְחוּ אֵלֶיךָ. הֱיוֹת פָּרָתוֹ מוּתְמֶדֶת. שֶׁכָּל הַפָּרוֹת כָּלוֹת וְשֶׁלְךָ לָעַד עוֹמֶדֶת: </b></b>", "<b>אֵל</b> נָא לְעוֹלָם תֻּעֲרָץ. וּלְעוֹלָם תֻּקְדָּשׁ. וּלְעוֹלְמֵי עוֹלָמִים תִּמְלוֹךְ וְתִתְנַשֵׂא. הָאֵל מֶלֶךְ נוֹרָא מָרוֹם וְקָדוֹשׁ. כִּי אַתָּה הוּא מֶלֶךְ מַלְכֵי הַמְּלָכִים. מַלְכוּתוֹ נֶצַח. נוֹרְאוֹתָיו שִׂיחוּ. סַפְּרוּ עֻזּוֹ. פָּאֲרוּהוּ צְבָאָיו. קַדְשׁוּהוּ רוֹמְמוּהוּ. רוֹן שִׁיר וָשֶׁבַח. תּוֹקֶף תְּהִלוֹת תִּפְאַרְתּוֹ:", "<b><b><small>חו\"ק:</small> לְטַהֵר טְמֵאִים. לְטַמֵא טְהוֹרִים. בְּאוֹמֶר קָדוֹשׁ: </b></b>", "<b>אִמְרָה</b> סְנוּנָה וּצְרוּפָה. בְּדוּלָה בְּדָתָהּ מֵעֲרוּפָה. גְּדֵלָה כְּרַעֲנָן לִתְרוּפָה: דְרוּשָׁה בְּזִקוּק שִׁבְעָה מִשִׁבְעָה. הַזָּיוֹת טְבִילוֹת וְכִבּוּסִים שִׁבְעָה. וּפָרוֹת וְכֹהֲנִים טְהוֹרִים וּטְמֵאִים שִׁבְעָה: זִקְנֵי גָזִית תְּמִימִים מִמּוּם. חֲבוּאֶיהָ יְבַקְרוּ לְבַל הֱיוֹת בָּהּ מוּם. טְהוֹרָה תִּהְיֶה לְאַדְמוּת כְּמִמּוּם: יֵעָשֶׂה מֵהוֹן כֹּהֵן כֶּבֶשׁ פָּרָה. כִּפָּה מוּל אֹטֶם בְּהוֹד תִּפְאָרָה. לְהוֹצִיא בָהּ תְּמִימָה חֵטְא תַּמָּה מְפִירָה: מְסַעֲדָיו אִתּוֹ יָצְאוּ לְהַר הַמִּשְׁחָה. נָחַץ טְבוֹל שֵׁנִית עֲבוּר כּוֹרֶה שׁוּחָה. סִדֵר מַעֲרֶכֶת וְלֹא שָׁהָה: עָמַד מִקֶּדֶם וּפָנָיו לְמַעֲרָב. פָּרָה שָׁחַט וְדָם לֹא עֵרַב. צָת בָּהּ חֲרָיוֹת וּמוֹקְדָהּ הֵרַב: קָם מוּל שַׁעַר אִיתוֹן וְדָם שֶׁבַע יַזֶּה. רַעֲנַן אֶרֶז וְאֵזוֹב וְשָׁנִי יֶחֱזֶה. שִׁמַּע לַכֹּל עֵץ אֶרֶז זֶה וְאֵזוֹב זֶה: תִּרְגְּלָה וְחִלְּקָהּ לִשְׁלֹשָׁה חֲלָקִים. כָּל מִשְׁמָרוֹת הָיוּ מֶנָּה מְחַלְּקִים. תְּכוּנָה לְמִשְׁמֶרֶת עַד נְקוּקִים יָקִים:", "<b>וּבְכֵן</b> וּלְךָ תַעֲלֶה קְדֻשָּׁה כִּי אַתָּה קְדוֹשׁ יִשְׂרָאֵל וּמוֹשִׁיעַ:", "<b>אֵין</b> לְשׂוֹחֵחַ עוֹצֶם נִפְלְאוֹתֶיךָ. <small>(בכ\"י נוסף אֵין לְהַרְהֵר אַחַר מִדוֹתֶיךָ)</small> אֵין לְהַגִּיד חֵקֶר דָּתוֹתֶיךָ. אֵין לְהָבִין תּוֹקֶף מִפְעֲלוֹתֶיךָ. אֵין לְפַעֲנֵחַ עוֹמֶק פְּלָאוֹתֶיךָ. אֵין לַעֲמוֹד עַל סֵפֶן מִדּוֹתֶיךָ. אֵין לַחֲקוֹר סוֹד <small>(נ\"א חֵקֶר)</small> חִידוֹתֶיךָ. אֵין לְהַשְׁמִיעַ כָּל תְּהִלּוֹתֶיךָ. אֵין לְגַלּוֹת סוֹד עֵדוֹתֶיךָ: הַמְפוֹרָשׁוֹת סְתוּמוֹת. הַגְּלוּיוֹת עֲלוּמוֹת. הַמְּבֹאָרוֹת חֲתוּמוֹת. הַמְּשֻׁנָּנוֹת עֲצוּמוֹת. הַחֲקוּקוֹת רְשׁוּמוֹת: הַחֲסֵרוֹת מְיֻתָּרוֹת. הָאֲסוּרוֹת מֻתָּרוֹת. הַשְּׁחוֹרוֹת צְחוֹרוֹת. הַחֲשׂוּפוֹת אֲטוּרוֹת. הַפְּרוּטוֹת אֲצוּרוֹת. הַכְּלוּלוֹת עֲצוּרוֹת. הַקַּלּוֹת חֲמוּרוֹת. מוֹצִיא מִזָּלוֹת יְקָרוֹת. מַתִּיר מֵאֲסוּרוֹת מֻתָּרוֹת. נוֹתֵן מִטְּמֵאוֹת טְהוֹרוֹת: מִן הַחֵלֶב. שֹׁמֶן הַלֵּב. וּמִן הַדָּם טְחוֹל <small>(נ\"א וְכָּבֵד)</small> הַדָּם. וּמִבָּשָׂר בֶּחָלָב. כְּחַל הֶחָלָב. מִכִּלְאֵי בְגָדִים. תְּכֵלֶת בַּסָּדִין. מֵאֵשֶׁת אָח. יִבּוּם הֶאָח. מֵאֵשֶׁת אִישׁ. יְפַת תּוֹאַר לְאִישׁ. מִטֻּמְאַת נִדַּת אִשָׁה. טָהֳרַת בְּתוּלֵי אִשָּׁה: מֵהַתֵּר אִסּוּר. וּמֵאִסּוּר הַתֵּר. מִטָּמֵא טָהוֹר. וּמִטָּהוֹר טָמֵא. בַּהֶרֶת מְמוּעָט תְּטַמֵּא. פָּרְחָה בְּכֻלּוֹ עוֹד בַּל תְּטַמֵּא. הַמֵּת בַּבַּיִת אֵינוֹ טָמֵא. יָצָא מִמֶּנּוּ אוֹתוֹ מְטַמֵּא. שְׂעִיר יוֹם כִּפּוּר מְכַפֵּר עַל כָּל טָמֵא. וְכָל מַעֲסִיקָיו בְּגָדִים מְטַמֵא. פָּרָה אֲדֻמָּה עוֹשֶׂיהָ מְטַמְּאָה. וְהִיא עֲשׂוּיָה לְטַהֵר כָּל טֻמְאָה. וְאֶפְרָהּ נַעֲשֶׂה אַב הַטֻּמְאָה. וְהִיא מְטַהֶרֶת אֲבִי אֲבוֹת הַטֻּמְאָה:", "<b>בְּכֵן</b> אֵין לְהָבִין סוֹד תּוֹרָתֶךָ. וְלֹא זִקּוּק אִמְרָתֶךָ. וְלֹא צֵרוּף גְּזֵרוֹתֶיךָ: בְּכֵן אֵין לְהָמִיר. וְלֹא לְהַתְמִיר. אֵין לְהַרְהֵר. וְלֹא לְחַרְחֵר. אֵין לֵידַע וְלֹא לְיַדַּע. עֲמוּקָּה מִשְּׁאוֹל מַה תֵּדָע. נָעוּ מַעְגְּלוֹתֶיהָ לֹא תֵדָע: זוֹ בַּאֲמִירָה וְזוֹ בִּגְזֵרָה. זוֹ בַּאֲסִיפָה וְזוֹ בַּחֲסִיפָה. זוֹ בִּנְשִׁיקָה וְזוֹ בִּתְשׁוּקָה. זוֹ בִּכְבִישָׁה וְזוֹ בְּהַפְרָשָׁה. זוֹ בִדְרִישָׁה וְזוֹ בַּחֲרִישָׁה: וְכָל אִמְרָהּ הֶחָקוּק בָּהּ חֻקָּה. אֵין לְהַרְהֵר וְלוֹמַר עַל מַה נֶחֱקָקָה. שֶׁכַּךְ נִתְּנָה בִּנְשִׁיקָה: וְכֻלָּם נְכוֹחִים לַמֵּבִין. וְכָל הַמַּשְׂכִּיל יָבִין. חוּץ מִטַּעֲמֵי פָרָה שֶׁאֵין לְהָבִין. וְכָל חֲכַם לֵב יִדַּל מִבִּין. חֲפָצֶיהָ אֵין לְהָבִין: וּבִשְׁמוֹת תְּעוּדָה הִיא נְקוּבָה. לְכָל קָרְבַּן שַׁי לֹא שָׁוָה. שֶׁהֵם זְכָרִים וְהִיא נְקֵבָה. לְטַהֵר שִׁמְצַת עֵגֶל תּוֹעֵבָה:", "<b>הֵם</b> הֵמִירוּ כָּבוֹד בְּבֶן פָּרָה. וְסָרְרוּ בוֹ כְּפָרָה. תָּבֹא אִמּוֹ אֲשֶׁר הִיא פָרָה. וְתִהְיֶה לָעָם כַּפָּרָה: הֵם הֶאֱדִּימוּ בוֹ פָּנִים. וְאָדְמוּ עֶצֶם מִפְּנִינִים. תָּבֹא אִמּוֹ אֲשֶׁר הִיא אֲדֻמַּת פָּנִים. וּבָהּ צַח וְאָדוֹם יִשָּׂא פָנִים: הֵם חֲרָטוּהוּ הֱיוֹת צָג כְּתָמִים. וּבָהּ חֻיְּבוּ מִהְיוֹת תְּמִימִים. תָּבֹא אִמּוֹ תְּמִימַת תְּמִימִים. וּבָהּ יְטַהֵר תַּמָּה הַצּוּר תָּמִים: הֵם שָׁחֲחוּ לְפֶסֶל כָּל מוּם. וְנֶעֱנְשׁוּ בוֹ הֱיוֹת בַּעֲלֵי מוּם. תָּבֹא אִמּוֹ אֲשֶׁר אֵין בָּהּ מוּם. לְהָדִיחַ דְּמֵי יָפָה וְאֵין בָּהּ מוּם: הֵם זָמְמוּ בְּעֵגֶל לִמְעוֹל. וַיִּזְבְּחוּ לוֹ וַיִּפְרְקוּ עוֹל. תָּבֹא אִמּוֹ אֲשֶׁר לֹא עָלָה עָלֶיהָ עוֹל. וְתִנָּתֵן עַל שִׁכְמָם כְּעוֹל: הֵם נִקְהֲלוּ עֲבוּרוֹ אֶל כֹּהֵן. וְאֻנַּף בְּהַשְׁמִיד אִישׁ מְכַהֵן. תָּבֹא אִמּוֹ וְתִנָּתֵן לַכֹּהֵן. וִיכֻפַּר בָּהּ עֲוֹן כֹּהֵן:", "<b>וּכְמוֹ</b> בָּאֵשׁ נִשְׂרָף. כֵּן בָּאֵשׁ תּוּשְׂרָף: וּכְמוֹ טוּחַן וְהוּדַּק עַד עָפָר. כֵּן תּוּדַּק וְתֵעָשֶׂה עָפָר: וּכְמוֹ הָשְׁלַךְ עֲפָרוֹ אֶל הַמַּיִם. כֵּן תֻּשְׁלַךְ אֲפָרָהּ אֶל הַמָּיִם: וּכְמוֹ נָפְלוּ בוֹ שְׁלשֶׁת אַלְפֵי יוֹשֶׁר. כֵּן יִפְּלוּ בָהּ שְׁלֹשֶׁת מִינֵי כוֹשֶׁר: וּכְמוֹ טִנֵּף עַם טָהוֹר. כֵּן תְּטַמֵּא בְּמַגַּע כָּל טָהוֹר: וּכְמוֹ טִהֵר עַם בּוֹ נִטְמָא. כֵּן תְּטַהֵר אִישׁ אֲשֶׁר נִטְמָא: וּכְמוֹ פֻּזַּר פִּשְׁעוֹ לְכָל דּוֹר שָׁמוּר לְחַטָּאת. כֵּן תְּהֵא לְמִשְׁמֶרֶת לְמֵי חַטָּאת: לְהָדִיחַ דָּמִים. לְכַבֵּס כְּתָמִים. לְנַקּוֹת טִנּוּפִים. לְהַרְחִיץ צוֹאִים. לְהַלְבִּין חֲטָאִים. לְטַהֵר טְמֵאִים. לְקַדֵּשׁ קְדוֹשִׁים. לְהַצְדִיק עֲמוּסִים: בְּעֵץ אֶרֶז. לַעֲנוּפִים כְּאֶרֶז. בְּאֵזוֹב. לְנִדְכָּאִים כָּאֵזוֹב. בְּשָׁנִי. לְשִׂפְתוֹתֶיהָ כַּשָּׁנִי. בְּתוֹלַעַת. לְאַל תִּירְאִי תּוֹלַעַת. לְבַל יִתְגָּאֶה מִתְגָּאֶה כְּאֶרֶז. שֶׁאִם לֹא יִמַּךְ כְּאֵזוֹב וְיֵחָשֵׁב כְּתוֹלַעַת. לֹא יְטֻּהַר בְּאֵזוֹב וּבִשְׁנִי תוֹלַעַת: וְאִם לֹא יִשְׁפּוֹךְ לֵב כַּמַּיִם. לֹא יֻטְהַר בִּזְרִיקַת מָיִם: וּמַה יִתְגָּאֶה חָצִיר יָבֵשׁ. נוֹכַח אֵשׁ אוֹכְלָה אֵשׁ: וּמַה יָּעוֹז צִיץ גֵּאֶה. נוֹכַח אֵל גָּאֹה גָּאָה: וְהוּא רוֹכֵב שְׁחָקִים בְּגַאֲוָה. גֵּאָה עַל גֵּאִים. מִתְנַשֵּׂא עַל נִשָּׂאִים. וּמִתְגָּאֶה כְּאֶרֶז עַל מִתְגָּאִים. וְעָנָיו כְּאֵזוֹב עַל נִדְכָּאִים. וְצָר בְּעוֹלָמוֹ חֲמִשָּׁה מִינֵי גֵאִים. שׁוֹר בַּבְּהֵמָה. אַרְיֵה בַּחַיָּה. נֶשֶׁר בַּמְּעוֹפְפִים. אֶרֶז בָּעֵצִים. וְאָדָם בְּכֻלָּם. וּמֶלֶךְ מִתְגָּאֶה עַל כֻּלָּם. לָבֵשׁ גֵּאוּת מִכֻּלָּם: חֲקָקָם בְּכֵס שְׁבִיבֵי אֵשׁ. אַרְבָּעָה בְּכֵס מַעְלָּה. וְאֶחָד בְּכֵס מַטָּה. כִּי כֵס מַעְלָה מְכֻוָּן כְּנֶגֶד כֵּס מַטָּה. וְכָל אֲשֶׁר יֵשׁ בְּמַעְלָה יֵשׁ בְּמַטָּה. כִּסֵּא מוּל כִּסֵּא. הֵיכָל מוּל הֵיכָל. מִקְדָּשׁ מוּל מִקְדָּשׁ. זְבוּל מוּל זְבוּל. מִזְבֵּחַ מוּל מִזְבֵּחַ. בָּנִים מוּל בָּנִים. עֲבָדִים מוּל עֲבָדִים. מַלְאָכִים מוּל מַלְאָכִים. מְשָׁרְתִים מוּל מְשָׁרְתִים. צְבָאוֹת מוּל צְבָאוֹת. כְּרוּבִים מוּל כְּרוּבִים. אֲלָפִים מוּל אֲלָפִים. רְבָבוֹת מוּל רְבָבוֹת. קְדוֹשִׁים מוּל קְדוֹשִׁים. מַחֲנוֹת מוּל מַחֲנוֹת. מַעֲרִיצִים מוּל מַעֲרִיצִים. מַקְדִּישִׁים מוּל מַקְדִּישִׁים. וּקְדֻשָּׁה לְקָדוֹשׁ מְשַׁלְּשִׁים:", "<b><b><small> קדושה </small></b></b>", "<small><b><b><small>נַקְדִּישָׁךְ וְנַעֲרִיצָךְ כְּנֹעַם שִׂיחַ סוֹד שַׂרְפֵי קֹדֶשׁ. הַמְּשַׁלְּשִׁים לְךָ קְדֻשָּׁה. כַּכָּתוּב עַל יַד נְבִיאֶךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר:  </small></b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>קָדוֹשׁ</b> קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: <small>חזן:</small> <b>אָז.</b> בְּקוֹל רַעַשׁ גָּדוֹל אַדִּיר וְחָזָק. מַשְׁמִיעִים קוֹל. מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים:  </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>בָּרוּךְ</b> כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>חזן:</small> מִמְּקוֹמְךָ מַלְכֵּנוּ תוֹפִיעַ. וְתִמְלוֹךְ עָלֵינוּ <small> <small>(מְהֵרָה)</small> </small> כִּי מְחַכִּים אֲנַחְנוּ לָךְ. מָתַי תִּמְלֹךְ בְּצִיּוֹן. בְּקָרוֹב בְּיָמֵינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן. תִּתְגַּדֵּל וְתִתְקַדֵּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵצַח נְצָחִים. וְעֵינֵינוּ תִרְאֶינָה מַלְכוּתֶךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּךָ. עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ:  </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>יִמְלֹךְ</b> יְהֹוָה לְעוֹלָם. אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר. הַלְלוּיָהּ:</b></b></small><b><b>  </b></b>", "<b>אַתָּה קָדוֹשׁ</b>, וְשִׁמְךָ קָדוֹשׁ, וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. כִּי אֵל מֶלֶךְ גָדוֹל וְקָדוֹשׁ אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה, הָאֵל הַקָּדוֹשׁ:", "<b>יִשְׂמַח מֹשֶׁה</b> בְּמַתְּנַת חֶלְקוֹ, כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּוֹ. כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ, בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לוּחוֹת אֲבָנִים הוֹרִיד בְּיָדוֹ, וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת, וְכֵן כָּתוּב בְּתוֹרָתֶךָ:", "<b>וְשָׁמְרוּ</b> בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְהֹוָה אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:", "<b>ולֹא</b> נְתַתּוֹ יְהֹוָה אֱלֹהֵינוּ לְגוֹיֵי הָאֲרָצוֹת, וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים, גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים, כִּי לְעַמְּךָ יִשְׂרָאֵל נְתַתּוֹ בְּאַהֲבָה, לְזֶרַע יַעֲקֹב אֲשֶׁר בָּם בָּחָרְתָּ:", "<b>יִשְׂמְחוּ</b> בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עוֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּוֹ וְקִדַּשְׁתּוֹ. חֶמְדַת יָמִים אוֹתוֹ קָרָאתָ. זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<b>אֱלֹהֵינוּ</b> וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךְ, וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶאֱמֶת, וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבָּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ. בָּרוּךְ אַתָּה יְהֹוָה, מְקַדֵּשׁ הַשַּׁבָּת:", "<b>רְצֵה</b> יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל, וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<b>וְתֶחֱזֶינָה</b> עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. בָּרוּךְ אַתָּה יְהֹוָה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:", "<b>מוֹדִים</b> אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדֹר וָדֹר. נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶיךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם. הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְּרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b><b><small> מודים דרבנן<small><b><small>בחזרת הש\"ץ</small></b> כשהוא אומר מודים, אומרים הקהל:</small>  </small></b></b>", "<small><b><b><small>מוֹדִים אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׁר, יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמֹר חֻקֶּיךָ וְלַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְךָ בְלֵבָב שָׁלֵם, עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת.</small> </b></b></small>", "<b>וְעַל</b> כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָמִיד לְעוֹלָם וָעֶד.", "<b>וְכֹל</b> הַחַיִּים יוֹדוּךָ סֶּלָה: וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל, בֶּאֱמֶת, לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<b><b>ברכת כהנים </b></b>", "<b>שִׂים שָׁלוֹם</b> טוֹבָה וּבְרָכָה, חַיִּים, חֵן וָחֶסֶד, וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד <small>(יַחַד)</small> בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים, וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים, וְחַיִּים וְשָׁלוֹם. <small>(וְכָל טוּב)</small> וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרֹב עֹז וְשָׁלוֹם.", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה, הַמְּבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>אֱלֹהַי.</b> נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וְאַחֲרֵי מִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַקָּמִים וְהַחוֹשְׁבִים עָלַי לְרָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:", "<b><b><small>יש אומרים כאן תפילה זו:</small> </b></b>", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי. שֶׁלֹּא תַעֲלֶה קִנְאַת אָדָם עָלַי וְלֹא קִנְאָתִי עַל אֲחֵרִים. וְשֶׁלֹּא אֶכְעוֹס הַיֹּום וְשֶׁלֹּא אַכְעִיסֶךָ. וְתַצִּילֵנִי מִיֵּצֶר הָרָע. וְתֵן בְּלִבִּי הַכְנָעָה וַעֲנָוָה. מַלְכֵּנוּ וֵאלֹהֵינוּ אֱלֹהַּ כָּל בָּשָׂר. יַחֵד שִׁמְךָ בְּעוֹלָמֶךָ בְּנֵה עִירֶךָ יַסֵּד בֵּיתֶךָ וְשַׁכְלֵל הֵיכָלֶךָ. וְקַבֵּץ קִבּוּץ גָּלֻיּוֹת וּפְדֵה צֹאנֶךָ וְשַׂמַּח עֲדָתֶךָ: <b>עֲשֵׂה</b> לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי:", "<b><b><small>נוהגים לומר כאן פסוק המתחיל וגומר באוֹת שבה מתחיל וגומר שמו הפרטי</small> </b></b>", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>עֹשֶׂה שָׁלוֹם</b> בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b>וְעָרְבָה</b> לַיהֹוָה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b><b><small>קדיש שלם</small> </b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן:  </small></b></b>", "<b>תִּתְקַבֵּל</b> צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא, וְאִמְרוּ אָמֵן:", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small>שיר של יום</small> </b></b>", "<b><b><small><b>הַיּוֹם</b> יוֹם שַׁבָּת קֹדֶשׁ שֶׁבּו הָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ:</small> </b></b>", "<b>מִזְמוֹר שִׁיר</b> לְיוֹם הַשַּׁבָּת: טוֹב לְהֹדוֹת לַיהֹוָה וּלְזַמֵּר לְשִׁמְךָ עֶלְיוֹן: לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ וֶאֱמוּנָתְךָ בַּלֵּילוֹת: עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל עֲלֵי הִגָּיוֹן בְּכִנּוֹר: כִּי שִׂמַּחְתַּנִי יְהֹוָה בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשֶׂיךָ יְהֹוָה מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ: אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת: בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרוֹם לְעֹלָם יְהֹוָה: כִּי הִנֵּה אֹיְבֶיךָ יְהֹוָה כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה: שְׁתוּלִים בְּבֵית יְהֹוָה בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ: עוֹד יְנוּבוּן בְּשֵׂיבָה דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר יְהֹוָה צוּרִי וְלֹא עַוְלָתָה בּוֹ:", "<b><b><small>קדיש יתום</small> </b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן:  </small></b></b>", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:"]}, "hagadol": {"ref": "Siddur Sefard, Yotzerot, Shabbat HaGadol", "he": "יוצר לשבת הגדול", "nusach": "סידור ספרד (תורת אמת)", "version": "Torat Emet 357", "source": "http://www.toratemetfreeware.com/index.html?downloads", "url": "https://www.sefaria.org/Siddur_Sefard%2C_Yotzerot%2C_Shabbat_HaGadol", "segs": ["<b><b><big><b>יוצר לשבת הגדול</b></big></b></b>", "<b>אֲדֹנָי</b> שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי אַבְרָהָם. אֱלֹהֵי יִצְחָק. וֵאלֹהֵי יַעֲקֹב. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן. גּוֹמֵל חֲסָדִים טוֹבִים. קוֹנֵה הַכֹּל. וְזוֹכֵר חַסְדֵי אָבוֹת. וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה: מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן:", "<b>מִסּוֹד</b> חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בְּשִׁיר וּרְנָנִים. לְהוֹדוֹת וּלְהַלֵּל פְּנֵי שׁוֹכֵן מְעוֹנִים:", "<b>אֱלֹהִים</b> בְּצַעְדְּךָ הַכּוֹת פַּתְרוֹס. בִּתַּקְתָּ חֵילָם מִבְצָרֵיהֶם לַהֲרוֹס. גָּאַלְתָּ עַמְּךָ בְּנֵבֶל קַתְרוֹס. דְּרַרְתָּם וְהִבְרַרְתָּם כְּסוֹלֶת לָרוֹס: הִגַּרְתָּ לַגַּי הֲמוֹן פִּיבֶסֶת. וְנִקְּתָה לָאָרֶץ בִּטְרִיָה נֶחְבֶּסֶת. זְנוּחָה זָרְחָה בְּדַם מִתְבּוֹסֶסֶת. חֻלָּצָה וְנִגְהָצָה בִּרְחִיצָה וְתִכְבּוֹסֶת: טֶרֶם מֵרוּר מִמְּעֻנִּים יֻשְׁבַּת. יְשׁוּעָה צָמְחָה לִנְצוּרֵי כְּבָבַת:", "<b><b><small>חזן:</small> <b>כִּתַּרְתָּ</b> כְלִיל לְנֶפֶשׁ מְשִׁיבַת. לְשֶׁעָבַר קִדַּמְתָּ מַתַּן שַׁבָּת:</b></b>", "<b>סֶלָה</b> אֲרוֹמִמְךָ מוֹשִׁיעַ וְשַׁלִּיט. מוֹצִיאִי לַחָפְשִׁי מִבֵּית מַעֲלִיט:", "<b><b><small>חזן:</small> <b>סַכּוֹתָה</b> לְרֹאשִׁי לְהַשְׁאִיר פָּלִיט. גָּנוֹן וְהִצִיל פָּסוֹחַ וְהִמְלִיט:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה. מָגֵן אַבְרָהָם: אַתָּה גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מַשִׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם:", "<b>מְכַלְכֵּל</b> חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה: וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים:", "<b>מִמַּסְגֵּר</b> אַסִּיר בְּצֵאת לְחוֹפֶשׁ. נִתְנוֹסֵס נֵס בִּטְבִיעַת רֶפֶשׁ. סִגַּבְתָּם חוֹק מַרְגּוֹעַ וָנוֹפֶשׁ. עֲרוֹךְ תְּחִלָּה לִמְשִׁיבַת נָפֶשׁ: פֵּרוּשׁוֹ וְטַעֲמוֹ צִוִּיתָ בְּמָרָה. צִחֲצוּחַ דָּתוֹ לְהָבִין וּלְגוֹמְרָה. קְבִיעַת קְדֻשָּׁתוֹ בִּזְכִירָה וּשְׁמִירָה. רוֹן לְהָפִיק בְּתוֹדָה וְזִמְרָה: שְׁפָטִים גְּדוֹלִים עָשִׂיתָ בְצוֹעַן. שִׁפְרַרְתָּ אֹהֶל בַּל יִצְעָן:", "<b><b><small>חזן:</small> <b>תְּעוּבִים</b> פַּסּוּ בְּאַף לְהַכְנִיעָן. תָּקְפָה חֲרָדָה בַּעֲמָלֵק וּכְנָעַן:</b></b>", "<b>לִבְּךָ</b> וְעֵינֶיךָ לְהֵיכָלְךָ תְּשׁוֹבֵב. דָּשֵׁן וְשָׁמֵן לְעַמְּךָ יְנוֹבֵב:", "<b><b><small>חזן:</small> <b>תְּכוֹנֵן</b> אֻלָמְךָ מִזְבֵּחַ וְסוֹבֵב. לְהַגְשִׁים תֶּחִי יְשֵׁנִים דוֹבֵב:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<b>יִשְׁעִי</b> וּכְבוֹדִי מִשְׂגַּבִּי וּמְנוּסִי. וְנִצָּב לָרִיב עַל אוֹנְסִי. סוֹכְכִי בְּאֶבְרָתוֹ יְהֹוָה נִסִּי. פּוֹרֵעַ וְגוֹבֶה דִין קְנָסִי. בְּהִלּוֹ נֵרוֹ עֲלֵי רֹאשִׁי. רָכַב עַל עָב קַל מֵעִנּוּי לְגָרְשִׁי. שִׁחֵת מִבְצָר מַחֲלִישִׁי וְחוֹרְשִׁי. מְלוֹן קִצּוֹ נָחַנִי דּוֹרְשִׁי: וּמִמְעוֹן קָדְשׁוֹ חָבַשׁ כְּאֵבִי. אָדוֹן מִמַּעַיְנֵי הַיְשׁוּעָה הִשְׁאִיבִי:", "<b><b><small>חזן:</small> <b>לִמְדַּנִי</b> לָנוּחַ בְּשַׁבָּת מֵהַדְאִיבִי. לְהַאֲכִילִי נַחֲלַת יַעֲקֹב אָבִי:</b></b>", "<b><b><small>חו\"ק:</small> <b>יִמְלוֹךְ</b> יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל אֵל נָא:</b></b>", "<b>כֶּרֶם</b> חֶמֶד נֶטַע שַׁעֲשׁוּעִים. בְּלֻסָּה וּמְכֻסְכֶּסֶת שִׁנֵּי רְשָׁעִים. וְנִגְלֵיתָ לְחַלְּצָהּ מִבֵּין פּוֹשְׁעִים. בְּחֵיל אֲלָפִים רְבָבוֹת תִּשְׁעִים. וּבְצֶדֶק נִפְקַד לְתֵשַׁע וְתִשְׁעִים. הוּעֲמָסָה מַשָּׂא פְרָדִים תִּשְׁעִים. פִּנִּיתָ לְפָנֶיהָ מְלָכִים וְשׁוֹעִים. שֻׁלְחָה קְצִירֶיהָ וְעָלוּ מוֹשִׁיעִים. וּלְחֶלְקָהּ נָטְלָה שִׁבְעָה מִשִּׁבְעִים. שֶׁעִשּׂוּר נְכָסִים לַבָּנוֹת קְבוּעִים. וּבִישִׁימוֹן דֶּרֶךְ הָלְכוּ אַרְבָּעִים. מַעֲדַנֵּי מֶלֶךְ אוֹכְלִים וּשְׂבֵעִים. קְדֻשָּׁתוֹ מְתַנִּים וְרֶנֶן מַבִּיעִים:", "<b><b><small>חו\"ק:</small> <b>חַי</b> וְקַיָם נוֹרָא וּמָרוֹם וְקָדוֹשׁ:</b></b>", "<b>יָרַדְתָּ</b> לְהַצִּיל עַמֶּךָ. לְהוֹדִיעָם אֹרַח נוֹעֲמֶךָ. לְמַשֻׁאוֹת תָּרִים פְּעָמֶיךָ. לְהַכְנִיעַ רוֹדִים בְּזַעֲמֶךָ: וּכְהָתֵם הֲמוֹן שׁוֹדְדִים. כָּלוּ שָׂרִים וּגְדוּדִים. וְהִגִּיעָה עֵת דוֹדִים. צָמְחָה יְשׁוּעָה לִידִידִים: סוֹד כְּיָצָא בְּהַנְוָיָה. צֵאת עֲגוּמִים לָרְוָיָה. נָחֲצוּ צִירִים לִשְׁבִיָּה. שְׁנֵי תָּאֳמֵי צְבִיָּה: פְּרוֹס כֵּרָה שֶׁל מֶלֶךְ. אִרְעָהוּ לְשַׂר פֶּלֶךְ. כָּל הַבָּא לְמֶלֶךְ. אֶשְׁכָּר לְפָנָיו מְהַלֵּךְ: בְּשַׁעַר בַּת כַּסְלוּחַ. נִצָּבִים מַלְאֲכֵי שִׁלּוּחַ. נִסְתַּכְּלוּ קוֹטְפֵי מַלּוּחַ. בְּאֵין קוֹמֶץ וְקִלּוּחַ: רַהַב לֵבָב גִּנָּה. לְלִגְיוֹנָיו קָפַץ וּמִנָּה. יִכָּנֵס הַבָּא בְּמָנָה. וְאֵלֶּה לְבַד בָּאַחֲרוֹנָה: שָׁאַל פֶּתֶן חֵרֵשׁ. מִי נִדְרָשׁ וְהַדּוֹרֵשׁ. הֵשִׁיבוּהוּ הָפַךְ מִשּׁוֹרֶשׁ. כָּלָה גָּרֵשׁ יְגָרֵשׁ: מָרַד זֵד בְּעִקּוּלוֹ. מַה לִּי וּלְקוֹלוֹ. וְלֹא הִרְצַנִּי בְּשִׁקְלוֹ. כְּנִשְׁעָן עַל מַקְלוֹ: וְאָז צָפָה בָּאֱלִילִים. הֲיֵשׁ יָדָיו גְּלִילִים. צָגוּ עָלָיו בִּפְלִילִים. אֵין פְּנוֹת בַּחֲלָלִים: אֱוִיל מוּכָן לַעֲבָרוֹת. מַה לְכֹּהֵן בִּקְבָרוֹת. הֲלֹא בְּתֵכֶל הַדִּבְּרוֹת. נוֹדַע בַּעַל גְּבוּרוֹת: לוֹבֵשׁ צֶדֶק נֶאְזָר. לְהָשִׁיב גְּמוּל לְאַכְזָר. הָפַךְ דֶּרֶךְ אִישׁ וָזָר. עֲמָלוֹ בְרֹאשׁוֹ חָזָר:", "<b><b><small>חזן:</small> <b>חֲנָמַל</b> בָּרָד וּרְשָׁפִים. זִלְעֵף בַּעֲלֵי כְשָׁפִים. קָרְסוּ כָּרְעוּ כְשׁוּפִים. עֲפַר אֶרֶץ שׁוֹאֲפִים:</b></b>", "<b>אֵל</b> נָא לְעוֹלָם תֻּעֲרָץ. וּלְעוֹלָם תֻּקְדָּשׁ. וּלְעוֹלְמֵי עוֹלָמִים תִּמְלוֹךְ וְתִתְנַשֵׂא. הָאֵל מֶלֶךְ נוֹרָא מָרוֹם וְקָדוֹשׁ. כִּי אַתָּה הוּא מֶלֶךְ מַלְכֵי הַמְּלָכִים. מַלְכוּתוֹ נֶצַח. נוֹרְאוֹתָיו שִׂיחוּ. סַפְּרוּ עֻזּוֹ. פָּאֲרוּהוּ צְבָאָיו. קַדְשׁוּהוּ רוֹמְמוּהוּ. רוֹן שִׁיר וָשֶׁבַח. תּוֹקֶף תְּהִלוֹת תִּפְאַרְתּוֹ:", "<b><b><small>חו\"ק:</small> <b>יוֹצְאֵי</b> חִפָּזוֹן. סִפְּקָם מָזוֹן. לְשׂוֹבַע וְלֹא לְרָזוֹן. קָדוֹשׁ:</b></b>", "<b>אֲמָנָה</b> גְדוֹלָה הָיְתָה בָעָם. בְּלִי לְהִתְלוֹנֵן זֹאת הַפַּעַם. גּוֹעָה לוֹמַר מַה נִטְעָם: <b><small>יוצאי:</small></b>", "<b><b>דֶּרֶךְ שְׁלֹשָׁה נֵלֵךְ בַּמִּדְבָּר. הִגִּיד מֵאָז מַנְהִיג וְדַבָּר. וְלֹא כִחַד מֵהֶם דָּבָר. <b><small>יוצאי:</small></b> </b></b>", "<b><b>זְרִיזִים חָשׁוּ לְהַקְדִּישׁ קְרוּאָיו. חָסוּ בְּמַטְרִיף כָּל בְּרוּאָיו. טוֹב אֵין מַחְסוֹר לִירֵאָיו. <b><small>יוצאי:</small></b> </b></b>", "<b><b>יָחִיד שְׁמָרָהּ לְמִדָּה שְׂרוּעָה. כְּלוּלוֹתַיִךְ אֶזְכּוֹר חֶסֶד לְפָרְעָה. לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לֹא זְרוּעָה. <b><small>יוצאי:</small></b> </b></b>", "<b><b>מְקוֹם צִפְעוֹנִים נָחָשׁ שָׂרָף וְעַקְרָב. נָסְעוּ קְדוֹשִׁים לַשֶׁמֶשׁ וְשָׁרָב. שָׂב וְעוֹלֵל וּמִקְנֶה רָב. <b><small>יוצאי:</small></b> </b></b>", "<b><b>עֲדָרִים הִשְׂכִּילוּ מַדָּע לְהַחֲכִּימָם. פִּסַּת מִשְׁאָרוֹת נָשְׂאוּ בְּהַשְׁכִּימָם. צְרוּרוֹת בְּשִׂמְלוֹתָם עַל שִׁכְמָם. <b><small>יוצאי:</small></b> </b></b>", "<b><b>קִטּוּף הָעִסָּה בַּחֲרָרָה קְמוּצָה. רְצוּפָה בְּרָאשֵׁיהֶם שֶׁלֹּא חֻמָּצָה. שֶׁמֶשׁ שֶׁזָפַתָּהּ וַאֲכָלוּהָ מַצָּה. <b><small>יוצאי:</small></b> </b></b>", "<b><b>תּוּפִינֵי שִׁשִּׁים וְאַחַת בְּמִשְׁטָר. טָעֲמוּ וְאָרְחוּ בְּשִׁיּוּר הַמְּנֻטָּר. עַד לֶחֶם מִשָׁמַיִם הוּמְטָר. <b><small>יוצאי:</small></b></b></b>", "<b>וּבְכֵן</b> וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>אָז</b> רוֹב נִסִּים הִפְלֵאתָ בַּלַּיְלָה. בְּרֹאשׁ אַשְׁמוֹרֶת זֶה הַלַּיְלָה. גֵּר צֶדֶק נִצַּחְתּוֹ כְּנֶחֱלַק לוֹ לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>דַּנְתָּ</b> מֶלֶךְ גְּרָר בַּחֲלוֹם הַלַּיְלָה. הִפְחַדְתָּ אֲרַמִּי בְּאֶמֶשׁ לַיְלָה. וַיָשַׂר יִשְׂרָאֵל לְמַלְאָךְ וַיּוּכַל לוֹ לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>זֶרַע</b> בְּכוֹרֵי פַּתְרוֹס מָחַצְתָּ בַּחֲצִי הַלַּיְלָה. חֵילָם לֹא מָצְאוּ בְּקוּמָם בַּלַּיְלָה. טִיסַת נְגִיד חֲרוֹשֶׁת סִלִּיתָ בְּכוֹכְבֵי לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>יָעַץ</b> מְחָרֵף לְנוֹפֵף אִוּוּי הוֹבַשְׁתָּ פְּגָרָיו בַּלַּיְלָה. כָּרַע בֵּל וּמַצָּבוֹ בְּאִישׁוֹן לַיְלָה. לְאִישׁ חֲמוּדוֹת נִגְלָה רָז חֲזוֹת לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>מִשְׁתַּכֵּר</b> בִּכְלֵי קֹדֶשׁ נֶהֱרַג בּוֹ בַּלַּיְלָה. נוֹשַׁע מִבּוֹר אֲרָיוֹת פּוֹתֵר בִּעֲתוּתֵי לַיְלָה. שִׂנְאָה נָטַר אֲגָגִי וְכָתַב סְפָרִים בַּלַּיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>עוֹרַרְתָּ</b> נִצְחֲךָ עָלָיו בְּנֶדֶד שְׁנַת לַיְלָה. פּוּרָה תִדְרוֹךְ לְשׁוֹמֵר מַה מִלַּיְלָה. צָרַח כַּשּׁוֹמֵר וְשָׂח אָתָא בֹקֶר וְגַם לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>קָרֵב</b> יוֹם אֲשֶׁר הוּא לֹא יוֹם וְלֹא לַיְלָה. רָם הוֹדַע כִּי לְךָ הַיּוֹם אַף לְךָ הַלַּיְלָה. שׁוֹמְרִים הַפְקֵד לְעִירְךָ כָּל הַיּוֹם וְכָל הַלַּיְלָה. תָּאִיר כְּאוֹר יוֹם חֶשְׁכַת לַיְלָה. וַיְהִי בַּחֲצִי הַלַּיְלָה:", "<b>וּבְכֵן</b> כָּל מַחֲמֶצֶת לֹא תֹאכֵלוּ:", "<b>אָבֹא</b> בְחִיל לְהִתְיַצְּבָה. בְּמַעֲמַד פְּנֵי תֵיבָה. גַּשְׁתִּי לְרוֹמֵם וּלְשַׂגְּבָה. מֵרְשׁוּת דָּגוּל מֵרְבָבָה: הִלּוּל קוֹנִי אַקְשִׁיבָה. וּבְחֵקֶר דָּתוֹ אֶתְיַשְּׁבָה. זֹאת לָדַעַת אֲחַשְּׁבָה. מִטַּעַם חַכְמֵי יְשִׁיבָה: טוֹעֵן עוֹלָם אַמְלִיכָה. יְהָבִי עָלָיו אַשְׁלִיכָה. כְּרָשׁ לְפָנָיו אֶתְהַלְּכָה. לִפְתּוֹחַ בִּדְבַר הֲלָכָה: מִלַּת פִּי גְּדוּשָׁה. נוֹצֵר חֶסֶד אַקְדִּישָׁה. סַלְסֵל בְּדֵעָה חֲדָשָׁה. מֵרְשׁוּת עֵדָה הַקְּדוֹשָׁה: פְּנֵי יְשָׁרִים דּוֹבֵר. צִחֲצוּחַ אֲמָרִים אֲגַבֵּר. קִדַמְתִּי לִטּוֹל בְּסֵבֶר. רְשׁוּת מֵרַב וְחָבֵר: שַׁדַּי חֵילִי תְּאַמֵּץ. תַּעְדִּיף קָט וְקוֹמֶץ. לְבָאֵר בְּלִי שֶׁמֶץ. הִלְכוֹת בִּעוּר חָמֵץ:", "<b>אֱלֹהֵי</b> הָרוּחוֹת לְכָל בָּשָׂר. חוֹק לְעַמּוֹ מָסָר. וְהִזְהִירָם בִּכְתָב מוּסָר. לִבְדּוֹק חָמֵץ אוֹר לְאַרְבָּעָה עָשָׂר: בְּשָׁעָה שֶׁאֵין בְּנֵי אָדָם מְצוּיִים בְּשׁוּקָא. אוֹר הַנֵּר יָפֶה לִבְדִיקָה. אֵין בּוֹדְקִין לֹא לְאוֹר הַחַמָּה וְלֹא לְאוֹר הַלְּבָנָה וְלֹא לְאוֹר הָאֲבוּקָה. וְצָרִיךְ לְבָרֵךְ עַל בִּעוּר חָמֵץ כְּחֻקָּה: גָּמַר מְנַטְּרֵהּ עַד דְּבַתְרָא. וּמִיַד צָרִיךְ לְבַטֵל הַשְׁאָר בַּאֲמִירָה. וְלֵימָא הָכִי כָּל חֲמִירָא דְּאִיכָּא בַּהֲדָא דִירָה. דְּלָא חֲמִתֵּיהּ וּדְלָא בִעַרְתֵּיהּ לִבָּטֵל וְלֶהֱוֵי כְּעַפְרָא: דְּאִי מִשְׁתַּכַּח לְאַחַר אוֹתָהּ שָׁעָה. אֵינוֹ חַיָּב בְּבַל יֵרָאֶה וּבְבַל יִמָּצֵא לְפוֹשְׁעָה. וְהָרוֹצֶה אַחַר בְּדִיקָתוֹ לֶאֱכוֹל חָמֵץ וּלְשָׂבְעָה. מַה שֶׁמְּשַׁיֵּר יַנִּיחֶנּוּ בְּצִנְעָה: הֵיכָא דְבָדַק בְּחוֹרֵי בֵיתָא. וְהִנִיחַ אַרְבַּע אוֹ חָמֵשׁ רִפְתָּא. וְאַשְׁכַּח דְּחָדָא מִנַּיְהוּ פַּחֲתָא. לִבְדּוֹק מֵרֵישָׁא שֶׁמָּא חוּלְדָא לְקָחַתָּהּ: וְכֵן תָּנוּ רַבָּנָן בְּפִרְקִין. דְּחוֹרֵי בֵיתָא וּנְקִיקִין. עִילָאֵי וְתַתָּאֵי אֵינָן נִבְדָּקִין. וְאֶמְצָעִים זְקוּקִין: זִהֲרוּ גַּג הַיָּצִיעַ וְגַג מִגְדָּלִין. וְרֶפֶת בָּקָר וּמַתְבֵּן וְלוּלִין. וְאוֹצְרוֹת יַיִן וְשֶׁמֶן הַנְעוּלִין. לִבְדּוֹק חָמֵץ בְּלִי עוֹלִין: חוֹר שֶׁבֵּין אָדָם לַחֲבֵרוֹ. זֶה וְזֶה בּוֹדֵק עַד שֶׁמַּגִיעַ וּמְבַטֵּל שְׁאָרוֹ. וְכֵן בֵּין יְהוּדִי וְעוֹבֵד כּוֹכָבִים חַיָּב לְבַעֲרוֹ. פְּלֵימוֹ מֵקַל שֶׁמָּא יֹאמַר הָעוֹבֵד כּוֹכָבִים כְּשָׁפוֹ וַחֲבָרוֹ: טָעֲנוּ הַמְפָרֵשׁ וְהַיּוֹצֵא בִשְׁיָרָא. וְאֵין דַּעְתּוֹ קוֹדֶם פֶּסַח לְחָזְרָה. תּוֹךְ שְׁלֹשִׁים יוֹם בָּעֵי לְבָעֵר חֲמִירָא. לִפְנֵי שְׁלֹשִׁים יוֹם אֵין זָקוּק לְבַעֲרָה: יִשְׂרָאֵל דְּחָמֵץ אִתְפַּקֵּד לֵיהּ. וְלֵיתֵיהּ לְמָרֵיהּ לְמִשְׁקְלֵיהּ נַטְרֵיהּ עַד אַרְבַּע דְּחָזֵי לְאָכְלֵיהּ. שְׁלִים אַרְבַּע וְלֹא אָתָא לְנָכְרִי מְזַבִּין לֵיהּ: כְּשֶׁנָפְלָה מַפּוֹלֶת עַל חָמֵץ בְּעַרְבֵי פְּסָחִים. וְכֶלֶב אֵין יָכוֹל לְחַפֵּשׂ אַחֲרָיו בְּטוּחִים. הֲרֵי הוּא כִּמְבוּעָר לְרֵעִים פִּקְחִים. וְכַמָּה חֲפִישַׂת הַכֶּלֶב שְׁלֹשָׁה טְפָחִים: לִמְּדוּ בֵּי מִלְחֵי וּבֵי קִירֵי נְקוּבִים. וּבֵי תְמָרִים וְצִיבִים. לִבְדוֹק אוֹתָם חַיָּבִים. וְחָצֵר פְּטוּרָה מִפְּנֵי הָעוֹרְבִים: מוֹצֵא חָמֵץ בַּפֶּסַח בְּתוֹךְ בֵּיתוֹ. כּוֹפֶה עָלָיו כֶּלִי בְּלִי רְאוֹתוֹ. וְאִם שֶׁל הֶקְדֵּשׁ הוּא אֵין צָרִיךְ לְכַסּוֹתוֹ. לְפִי שֶׁבְּדֵלִין מֵאוֹתוֹ: נָפֵי וּפַתִּילֵי וְיוֹרָה. דְּאִשְׁתַּמֵּשׁ בְּהוּ חַמִּין חֲמִירָא. צָרִיךְ לְגַעֲלִינְהוּ וְיַנִּיחַ בְּגוֹ רַבָּא זְעֵירָא. וּלְרַבָּא לֶעֱבַד גְּדַנְפָא וּלְרַתְחֵיהּ בְּנוּרָא: סַכִּינֵי דְּאִשְׁתַּמֵּשׁ בְּהוּ חֲמִירָא לַאֲרוּחִין. אִם אֶפְשַׁר לַעֲשׂוֹתָן חֲדָשִׁים הֵם מְשֻׁבָּחִין. וְאִי לָא מַגְעִילָן בְּרוֹתְחִין. וּבִכְלִי רִאשׁוֹן הֵם מְצוּחֲצָחִין. וְעֵץ פָּרוּר מַגְעִילָן בְּרוֹתְחִין: עִנְּדוּ אַגָּנֵי וּקְצִיעֵי דְקוּנְיָא וּפַחֲרָא. אַף עַל גַּב דְּמַפְלִיט לְהוּ שַׁפִּיר לְאִשְׁתַּמּוּשֵׁי בְהוּ אֲסִירָא. וְאַף עַל גַּב דִּרְוִיחָן וְאִכָּא לְמֵימָר דְּשַׁלִּיט בְּהוּ אַוִּירָא. אֲפִילוּ הָכִי קַיְמָא אִסּוּרָא: פְּחַר קְדֵרוֹת אֵין צָרִיךְ לְפַלְחָא. אֲבָל מַשְׁהֵי לֵיהּ עַד בָּתַר פִּסְחָא. וּקְעָרוֹת מֻתָּרוֹת כִּי שָׁקִיל מִדּוּדָא עֲלַיְהוּ לְאַנָּחָא. וּבוּרְמֵי דִּגְלָלָא שַׁרְיָן בַּהֲדָחָה: צָעֵי דְמַשְׁהֵי בְּהוּ חֲמִירָא בִּשְׁאָר יוֹמֵי. כְּבֵית שְׂאוֹר שֶׁחִמּוּצוֹ קָשֶׁה דָּמֵי. וְאִי אַקְרָאֵי אוֹתִיבֵיהּ וְלֹא אִשְׁתָּהֵי עִמֵּיהּ. לְאִשְׁתַּמּוּשֵׁי בְּהוּ שַׁפִּיר דָּמֵי: קִטּוּף בְּיַיִן וְשֶׁמֶן עֲבִידִין. מִלְמֵילַשׁ בְּהוּ לֵילֵי קַמָּאֵי קַפְּדִין. וְאַמְהָן דְּלָא טְבִילָן וְעַבְדִּין. דְלָא לְמֵילַשׁ בְּהוּ הוּא הַדִּין: רְקִיקֵי מַצּוֹת עוֹשִׂין זֵכֶר לְעִגּוּן. וְלִשְׁמָן צָרִיךְ לְשָׁמְרָן מֵחִמּוּץ כְּהָגוּן. וְחֵרֵשׁ שׁוֹטֶה וְקָטָן אֵין לָשִׁין דִּלְמָא יִשְׁגּוּן. אַף עַל גַּב דְאַפְיֵה יִשְׂרָאֵל בַּר דֵּעָה לָא יְנַהֲגוּן: שָׁנוּ שֶׁאֵין לָשִׁין בְּבַת אַחַת לְמַעְלָה מֵחֲמֵשֶׁת רְבָעִים קֶמַח וְכֵן לְחַלָּה. וְהֵן בֵּיצִים כְּמִנְיַן חַלָּה. וְהָעוֹמֶר מוּכַח לָהּ. וְהָאִשָׁה לֹא תָלוּשׁ אֶלָא בְּמַיִם שֶׁלָּנוּ הַלַּיְלָה. תְּמִימִים שָׁנוּ בְּמִשְׁנָה הַמְּהֻלָּלָה. מֵי תַּשְׁמִישׁוֹ שֶׁל נַחְתּוֹם יִשָּׁפֵכוּ. מִפְּנֵי שֶׁמַּחֲמִיצִין סֶלָה. וְאַמְרִינָן שָׁדֵי לְהוּ בְּמָקוֹם מוּדְרָן דְּלָא לֵיתֵי בְּהוּ לִידֵי תַקָּלָה. תַּמוּ הִלְכוֹת בִּעוּר וְהַגְעָלָה:", "<b>יַיִן</b> כִּי יִתְאַדָּם. לְמִצְוָה הוּא מֻקְדָּם. לָצֵאת בּוֹ חוֹבַת יְדֵי אָדָם. אִם אַיִן קוּנְדִיטוּן וּמְבֻשָּׁל נֶגְדָּם: וְאַרְבַּע כּוֹסוֹת הַלָּלוּ. צָרִיךְ שֶׁיְהֵא בָהֵן כְּדֵי רְבִיעִית בְּלִי יָקֵלוּ. אֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים אֵלּוּ כָּאֵלּוּ. וּמְחַלְּקִין לְתִינוֹקוֹת קְלָיוֹת וֶאֱגוֹזִין כְּדֵי שֶׁיִּשְׁאָלוּ: סָחוּ שֶׁהַנָּשִׁים צְרִיכוֹת לְאַמְּצָה. בְּכָל מִילֵי דְפִּסְחָא בְּלִי שִׁמְצָה. אַף עַל גַּב דְמִצְוַת עֲשֵׂה שֶׁהַזְמַן גְּרָמָא בָּם לֹא נִמְצָא. שֶׁכָּל שֶׁיֶּשְׁנוֹ בְּבַל תֹּאכַל חָמֵץ יֶשְׁנוֹ בְּקוּם אֱכוֹל מַצָּה: פֵּרְשׁוּ בְשָׂפָה נְדִיבָה. מַצָּה וְיַיִן צָרִיךְ הֲסֵבָּה. מָרוֹר אֵין בּוֹ כֵּן חוֹבָה. וּמִבָּעֵי לֵיהּ לְכַסְכּוּסֵי טוּבָא: הֲסֵבַּת יָמִין הֲסֵבָּהּ אֵינָהּ. וְלֹא עוֹד אֶלָּא שֶׁמָּא יַקְּדִים קָנֶה לְוֵשֶׁט וְיָבֹא לִידֵי סַכָּנָה. פְּרַקְדָּן לָא מִן חוּשְׁבָּנָא. וְאִשָּׁה אֵינָהּ צְרִיכָה וְאִם חֲשׁוּבָה הִיא נְדוֹנָה: קַמֵּי אָב מֵיסַב הַבֵּן בְּדִיצָה. תַּלְמִיד בִּפְנֵי רַבּוֹ אֵינוֹ רָאוּי לְפָרְצָה. אֲבָל בְּשׁוּלְיָא דְנַגְרֵי צָרִיךְ לְהָסֵב בִּמְרוּצָה. וְהַשַּׁמָּשׁ שֶׁאָכַל כְּזַיִת מַצָּה כְּשֶׁהוּא מֵסֵב יָצָא: טָעֲנוּ לַחֲטוֹף מַצָּה בְּלֵילֵי פְסָחִים. כְּדֵי שֶׁלֹּא יִישְׁנוּ הַפְּרָחִים. וְחַיָּבִין בְּרֶגֶל לִהְיוֹת שְׂמֵחִים. בַּמִּקְדָּשׁ בְּבָשָׂר וְהַשְׁתָּא בְּיֵין רִקּוּחִים: נָשִׁים חַיָּבוֹת לִשְׂמוֹחַ וּלְהַרְנִין. בְּבָבֶל בְּבִגְדֵי צִּבְעוֹנִין. בְּאֶרֶץ יִשְׂרָאֵל בְּבִגְדֵי פִשְׁתָּן הַמְּלֻבָּנִין. וְהָאֲנָשִׁים בְּיַיִן מִתְעַדְּנִין: בְּעֶרֶב הַפֶּסַח סָמוּךְ לְמִנְחַת רִאשׁוֹן. לֹא יֹאכַל אָדָם עַד הָאִישׁוֹן. וּבְבֹאוֹ מִבֵּית רַחֲשׁוֹן. מוֹזְגִין לוֹ כּוֹס רִאשׁוֹן: רִאשׁוֹן מְבָרֵךְ עַל הַיַּיִן וְאַחַר כַּךְ קִדּוּשׁ וּזְמָן וְאֵינוֹ אוֹמֵר נֵס עֲדַיִן. שֶׁצָרִיךְ לְאָמְרוֹ בָּאֲגָדָה וְרָאוּי לְכָפְלוֹ אַיִן. וְשָׁתֵי וּמָשֵׁי יָדֵיהּ וְאֵינוֹ מְבָרֵךְ עַל נְטִילַת יָדָיִם: שָׁקִיל גַּרְגִּירָא אוֹ כַרְפְּסָא אוֹ כֻּסְבַּרְתָּא אוֹ חַסָא וְיִטְבּוֹל בַּחֲרוֹסֶת וִיבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה. וְכַד אָכִיל יֶחֱצֶה אַחַת מִשָׁלֹשׁ מַצוֹת וְאֵין בְּרָכָה עִמָּהּ. מַחֲצָה בִקְעָרָה וּמַחֲצָה בְשֻׁלְחָן לְהָשִׂימָה: מוֹשֵׁךְ מֵהַקְּעָרָה שְׁנֵי תַבְשִׁילֵי דְּאִנּוּן בִּשְׂרָא וְכַוְרָא צְלִילֵי. אִי נַמֵּי גַּרְמָא וּבִשּׁוּלֵי. וּמַגְבִּיהַּ קְעָרָה וְלֵימָא הָא לַחְמָא עַנְיָא כֻּלֵהּ: וּמוֹזְגִין לוֹ כּוֹס שֵׁנִי מֵאַרְבַּעַת הָאֵל. וְכַאן הַבֵּן מֵאָבִיו שׁוֹאֵל. מַה נִּשְׁתַּנָּה מִלֵּילוֹת זֶה לֵיל. וְגוֹמֵר הָאֲגָדָה עַד גָּאַל יִשְׂרָאֵל: אַחַר דְשָׁתֵי מָשֵׁי יָדֵיהּ. וּמְבָרֵךְ עַל נְטִילַת יָדָיִם לְחוֹדֵיהּ. וְשָׁרֵי הַמּוֹצִיא עַל הַשְּׁלֵמָה דְּעִלַּוֵּי תַּרְתֵּי דִידֵיהּ. וְלֹא אָכִיל מִנֵּיהּ אֲכַתֵּי מִדֵּי: לוֹקֵחַ פְּרוּסָה וּמְבָרֵךְ לֶאֱכוֹל מַצָּה בְּמֶלֶל. וּבַהֲדֵי דְהַהִיא דְהַמּוֹצִיא אוֹכֵל וְכוֹלֵל. וּמְבָרֵךְ בַּחֲזֶרֶת לֶאֱכוֹל מָרוֹר וְטוֹבֵל וּבוֹלֵל. וְהָדָר אָכִיל מַצָּה וּמָרוֹר בְּלֹא בְּרָכָה. וְכוֹרְכָן בְּבַת אַחַת כְּהִלֵּל: חָלִיף לְכַמָּה בָתֵּי וְעָבִיד כִּי הַאי גַּוְנָא עַד הָכָא. וְאַחַר כַּךְ עוֹשִׂין סְעוּדָתָן כָּל צָרְכָּהּ. וְכַזַיִת מַצָּה בָּאַחֲרוֹנָה צְרִיכִין לְכָּרְכָה. וְנוֹטְלִין וְלֹא מְבָרְכִין שֶׁמַּיִם אַחֲרוֹנִים חוֹבָה וְאֵין טְעוּנִין בְּרָכָה: זוֹכֵר בַּשְׁלִישִׁי בִּרְכַת מְזוֹנוֹ. וְלִשְׁאָר הַבָּתִּים תְּחִלָּה וְטוֹעֵם הַכּוֹס עַד מִשֶּׁלּוֹ אֵינוֹ. וּבָרְבִיעִי הַלֵּל מִצְרִי לְתַנּוֹ. בַּל יִטְעוֹם כְּלוּם בְּאִישׁוּנוֹ: קִמְעָא לִשְׁתּוֹת מַיִם יְכַנֵּס. אִם חוֹלֶה הוּא אוֹ אִסְטְנֵס. וּבָעֵי לְמִשְׁתֵּי חַמְרָא מִשּׁוּם אוֹנֵס. לוֹמַר בַּחֲמִישִׁי הַלֵּל הַגָּדוֹל יִשְׁתַּנֵּס:", "<b>חֲסַל</b> סִדּוּר פֶּסַח כְּהִלְכָתוֹ. כְּכָל מִשְׁפָּטוֹ וְחֻקָּתוֹ. כַּאֲשֶׁר זָכִינוּ לְסַדֵּר אוֹתוֹ. כֵּן נִזְכֶּה לַעֲשׂוֹתוֹ. זָךְ שׁוֹכֵן מְעוֹנָה. קוֹמֵם קְהַל עֲדַת מִי מָנָה. בְּקָרוֹב נַהֵל נִטְעֵי כַנָּה. פְּדוּיִם לְצִיּוֹן בְּרִנָּה:", "<b>וּבְכֵן</b> וּלְךָ תַעֲלֶה קְדֻשָּׁה כִּי אַתָּה קְדוֹשׁ יִשְׂרָאֵל וּמוֹשִׁיעַ:", "<b>אֵין</b> עֲרוֹךְ אֵלֶיךָ לְהַגִּיד וּלְדַבֵּר. חֵקֶר פִּלְאֵי נִסֶּיךָ לְהָבִין וּלְסַבֵּר <small>(נ\"א וּלְסַפֵּר)</small> מַה יָקָר חַסְדְּךָ מֵכִין מִצְעֲדֵי גָבֶר. מְאֹד עָמְקוּ מַחְשְׁבוֹתֶיךָ נוֹתֵן תַּעֲצוּמוֹת וָעוֹז לְהִתְגַּבֵּר. וּבְנֵי אָדָם בְּצִלְךָ יֶחֱסָיוּן אֶרֶךְ הָאֵבֶר. הִרְבִּיתָ הַגּוֹי וְהִגְדַּלְתָּ הַשִּׂמְחָה לִבְנֵי עֵבֶר. בִּמְשׁוֹל רָשָׁע עַל עַם דַּל לִישׁוּעָתְךָ סוֹבֵר. וְנִתְאַזַרְתָּ בַּחֲנִינוֹתֶיךָ מְפֻזָּר וּמְפוֹרָד לְכַנֵּס וּלְחַבֵּר. וְעוֹרַרְתָּ אַהֲבַת יְשֵׁנֵי חֶבְרוֹן שׁוֹכְנֵי קָבֶר. וְדַנְתָּ דִינֵי קְנָסוֹת וַחֲבָלוֹת עַל חוֹבְרֵי חָבֶר. וְהִכְנַעְתָּם בְּדָם וּצְפַרְדְּעִים וְכִנִּים וְעָרוֹב וָדֶבֶר. וְשִׁבַּרְתָּ רָאשֵׁי תַנִּין עַל רִיב לֹא לוֹ מִתְעַבֵּר. כִּי לִפְנֵי כִשָׁלוֹן גּוֹבַהּ וְגָאוֹן לִפְנֵי שֶׁבֶר. וּמַה יָעוֹז צִיץ הַשָּׂדֶה וְיָמָיו כְּצֵל עוֹבֵר. לְגָבוֹהַּ עַל גָּבוֹהַּ מְפָרֵק הָרִים וּמְשַׁבֵּר. וְהוּא בַּעַל נְקָמוֹת אֱלֹהֵי הַמִּשְׁפָּט מֵישָׁרִים דּוֹבֵר. וּמַצְמִיחַ יֶשַׁע לְקֹוָיו וְעַמִּים תַּחְתֵּיהֶם יַדְבֵּר:", "<b>וְעָלֵינוּ</b> הִפְלִיא חֲסָדָיו וְנָשָׂא נֵס. וְנָקַם נִקְמָתֵנוּ מִכָּל בַּעֲלֵי אוֹנֵס. וְהִכְנִיעָם בְּזַעַם וְצָרָה בַּחוּרֵי אָוֶן וְחָנֵס. וּמִלּוּשׁ בָּצֵק עַד חֻמְצָתוֹ דָּנָם בְּאוֹנִים לְהִקָּנֵס. וְאֵזוֹר חֲלָצָיו חִזֵּק וְאִמֵּץ לְהִשְׁתַּנֵּס. בָּקַע יָם וַיַּעֲבִירֵם וּכְנֵד נוֹזְלִים כִּנֵס. וּבְאֶרֶץ לֹא זְרוּעָה אֹתָם כִּלְכֵּל וּפִרְנֵס. לָכֵן לָנוּ לְהוֹדוֹת עַל כָּל נֵס וָנֵס:", "<b>לָמָּה</b> פֶּסַח בָּא מִן הַצֹּאן. שֶׁפָּסַח וְחָמַל עַל קְרוּאֵי צֹאן. וּכְרוֹעֶה מְקַבֵּץ טְלָאִים מְשָׁכָם וּגְאָלָם מִבַּעֲלֵי לָצוֹן: וְלָמָּה לְקִיחָתוֹ קוֹדֶם לִשְׁחִיטָתוֹ יָמִים אַרְבָּעָה. וְנִתַּן לְמוּלִים. וְלַעֲרֵלִים נִפְסַל בְּהִיא הַשָּׁעָה. כְּדֵי שֶׁיִּהְיוּ בְּיָדָם מִצְוֹת מְצוּיוֹת לְהִשְׁתַּעֲשֵׁעָה. שֶׁכְּבָר בָּא עֵת דּוֹדִים וּזְמַן שְׁבוּעָה. וְהָיוּ מִתְבּוֹסְסִים בִּשְׁנֵי דָמִים שֶׁתַּצְמִיחַ יְשׁוּעָה: וְלָמָּה נְתִינַת דָּמוֹ עַל הַמַּשְׁקוֹף וּשְׁתֵּי הַמְּזוּזוֹת. שֶׁהֵן שָׁלֹשׁ מִזְבְּחוֹת בִּמְקוֹם רוֹאִים אוֹתָם לַחֲזוֹת. זֵכֶר שָׁלֹשׁ מִזְבְּחוֹת שֶׁל אַב הֲמוֹן נִרְמָזוֹת. שֶׁבְּדָן וּבֵית אֵל וְאֵלוֹן מוֹרֶה נֶחֱרָזוֹת:", "<b>וְלָמָּה</b> אֲכִילַת חָמֵץ לְשֵׁשׁ שָׁעוֹת. זֵכֶר לְחִפָּזוֹן שְׁכִינָה לְהַעֲבִיר גְּזֵרוֹת רָעוֹת. מְדַלֵּג עַל הֶהָרִים מְקַפֵּץ עַל הַגְּבָעוֹת: וְלָמָּה אֲכִילַת מַצָּה לֶחֶם עוֹנִי. שֶׁלֹּא הִסְפִּיק בָּצֵק לְהַחֲמִיץ עַד שֶׁגְּאָלָם מֵעוֹנִי: וְלָמָּה בְּמָרוֹר שֶׁתְּחִלָּתוֹ רַךְ וְסוֹפוֹ קָשֶׁה. שֶׁנִּמְרְרוּ תְּחִלָּה בְּפֶה רַךְ וְלִבְסוֹף בְּעוֹל קָשֶׁה: וְלָמָּה טִבּוּלוֹ בַּחֲרוֹסֶת. זֵכֶר לְטִיט שֶׁאִשָּׁה וּבַעְלָהּ דּוֹרֶסֶת: וְלָמָּה תַּבְלִין בְּתוֹכוֹ מֻגְבָּלִין כְּמוֹ מַלְבֵּן. זֵכֶר לְנִפּוּץ עַם לְקוֹשֵׁשׁ קַשׁ לַתֶּבֶן: וְלָמָּה שְׁנֵי מִינֵי בָשָׂר בְּצַד עוּגָה. אֶחָד זֵכֶר לַפֶּסַח וְאֶחָד זֵכֶר לַחֲגִיגָה: וְלָמָּה מַגְבִּיהִין קְעָרָה קוֹדֶם זְמַנָּהּ. כְּדֵי שֶׁיִּרְאֶה תִּינוֹק וְיִשְׁאַל מַה נִשְׁתַּנָּה: וְלָמָּה שְׁאָר יְרָקוֹת בָּאִין תְּחִלָּה. לִפְטוֹר חֲזֶרֶת שֶׁל מִצְוָה בְּרָכָה רְאוּיָה לָהּ. וְשֶׁאֵין לוֹמַר שְׁתֵּי בְּרָכוֹת כְּאַחַת שְׁתִיָּה אוֹ אֲכִילָה. וְאִי אֶפְשַׁר לֶאֱכוֹל וְלִשְׁתּוֹת כְּאַחַת בְּשֶׁכְּבָר כְּרֵסוֹ מִלָּא. וְכֵן בִּשְׁתֵּי מַצּוֹת פּוֹטְרִין מֵחַלָּה לְחַלָּה: עַל כִּי אֵין לְשַׁנּוֹת בִּשְׁתֵּי בְרָכוֹת. מְבָרֵךְ עַל זוֹ וְעַל זוֹ וְאֵינוֹ אוֹכֵל עַד שֶׁיִּגְמוֹר שְׁתֵּי בְרָכוֹת:", "<b>וְלָמָּה</b> אַרְבָּעָה כּוֹסוֹת מִצְוָתָן בְּזֶה הַלַּיְלָה. זֵכֶר לְאַרְבָּעָה גְּאֻלּוֹת שֶׁנִתְבַּשְׂרוּ בָהֶם עַם סְגֻלָּה. יְצִיאָה וְהַצָּלָה לְקִיחָה וּגְאֻלָּה. וּלְהוֹדוֹת בָּהֶם וְלִתֵּן בָּם תְּהִלָּה. לְחוֹבֵט אַרְבָּעָה כּוֹסוֹת שֶׁל יְפֵיפִיָּה עֶגְלָה. וּכְדֵי לְשַׁבֵּר אֻמּוֹת עֲמָמוֹת מְשֻׁקָּצוֹת בִּגְעִילָה. בְּאַרְבָּעָה כּוֹסוֹת הַכְּתוּבִים בָּם שֶׁהֵן כּוֹס הַתַּרְעֵלָה. וּכְנֶגְדָם לְהַשְׁקוֹתֵנוּ אַרְבָּעָה כּוֹסוֹת שֶׁל חֶמְלָה: וְלָמָּה מְסֻבִּין בְּמִטָּה כְבוּדָה וּכְלוּלָה. זֵכֶר לְחֵרוּת וְרִבּוּץ עַנְנֵּי כָבוֹד בַּחֲתוּלָה. שֶׁכֵּן דֶּרֶךְ בְּנֵי מְלָכִים לִנְהוֹג כָּבוֹד וּלְסַלְסְלָה. שֶׁעִטְּרָנוּ קְדוֹשׁ יַעֲקֹב עֲטֶרֶת מְלוּכָה וּתְהִלָּה. וּבֵרַר לְהוֹדִיעַ עַם מַרְעִיתוֹ לִהְיוֹת לוֹ לְעַם נַחֲלָה. כִּי לֵאלֹהִים מָגִנֵּי אֶרֶץ מְאֹד נַעֲלָה:", "<b>נַעֲלָה</b> בִקְדֻשָּׁתוֹ מָרוֹם וְקָדוֹשׁ. כִּי אֱלֹהִים קְדוֹשִׁים הוּא בְּכָל מִינֵי קְדֻשָּׁה. דַרְכּוֹ בִּקְדֻשָּׁה. וְהִלוּכוֹ בִּקְדֻשָּׁה. דִבּוּרוֹ בִּקְדֻשָּׁה. יְשִׁיבָתוֹ בִּקְדֻשָּׁה. חֲשִׂיפַת זְרוֹעוֹ בִּקְדֻשָּׁה. נָאֶה וְאַדִיר בִּקְדֻשָּׁה. הוּא קָדוֹשׁ וְעַמּוֹ קָדוֹשׁ. וְכָל מְשָׁרְתָיו קְדוֹשִׁים. אֵין כִּקְדֻשָּׁתוֹ וְאֵין דוֹמֶה לּוֹ. מְקֻדָּשׁ בִּקְרוֹבָיו. וְנוֹרָא עַל כָּל סְבִיבָיו. וְנַעֲרָץ בְּסוֹד קְדוֹשִׁים. נִשְּׂגָּב בְּרִבְבוֹת אֶרְאֶלִּים. אֵילֵי קוֹדֶשׁ. מְשׁוֹרְרִים וּמְהַלְּלִים בְּשִׁיר קוֹדֶשׁ. עִירִין וְקַדִּישִׁין. רוֹעֲשִׁים וּמַקְדִישִׁים. בְּקֹדֶשׁ הַקֳּדָשִׁים. עִתִּים חָשִׁים וְעִתִּים מְמַלְּלִים. וְלַבְּקָרִים מִתְחַדְּשִׁים. מַקִּיפִים כֵּס הַמֶּרְכָּבָה וּקְדֻשַּׁת הַשֵּׁם מְפָרְשִׁים. וְשִׁלּוּשׁ קְדֻשָּׁה לְקָדוֹשׁ וְנוֹרָא מַקְדִּישִׁים:", "<b><b><small> קדושה</small></b></b>", "<small><b><b><small>נַקְדִּישָׁךְ וְנַעֲרִיצָךְ כְּנֹעַם שִׂיחַ סוֹד שַׂרְפֵי קֹדֶשׁ. הַמְּשַׁלְּשִׁים לְךָ קְדֻשָּׁה. כַּכָּתוּב עַל יַד נְבִיאֶךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר: </small></b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>קָדוֹשׁ</b> קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: <small>חזן:</small> <b>אָז.</b> בְּקוֹל רַעַשׁ גָּדוֹל אַדִּיר וְחָזָק. מַשְׁמִיעִים קוֹל. מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>בָּרוּךְ</b> כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>חזן:</small> מִמְּקוֹמְךָ מַלְכֵּנוּ תוֹפִיעַ. וְתִמְלוֹךְ עָלֵינוּ <small> <small>(מְהֵרָה)</small> </small> כִּי מְחַכִּים אֲנַחְנוּ לָךְ. מָתַי תִּמְלֹךְ בְּצִיּוֹן. בְּקָרוֹב בְּיָמֵינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן. תִּתְגַּדֵּל וְתִתְקַדֵּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵצַח נְצָחִים. וְעֵינֵינוּ תִרְאֶינָה מַלְכוּתֶךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּךָ. עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>יִמְלֹךְ</b> יְהֹוָה לְעוֹלָם. אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר. הַלְלוּיָהּ:</b></b></small><b><b> </b></b>", "<b>אַתָּה קָדוֹשׁ</b>, וְשִׁמְךָ קָדוֹשׁ, וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. כִּי אֵל מֶלֶךְ גָדוֹל וְקָדוֹשׁ אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה, הָאֵל הַקָּדוֹשׁ:", "<b>יִשְׂמַח מֹשֶׁה</b> בְּמַתְּנַת חֶלְקוֹ, כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּוֹ. כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ, בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לוּחוֹת אֲבָנִים הוֹרִיד בְּיָדוֹ, וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת, וְכֵן כָּתוּב בְּתוֹרָתֶךָ:", "<b>וְשָׁמְרוּ</b> בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְהֹוָה אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:", "<b>ולֹא</b> נְתַתּוֹ יְהֹוָה אֱלֹהֵינוּ לְגוֹיֵי הָאֲרָצוֹת, וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים, גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים, כִּי לְעַמְּךָ יִשְׂרָאֵל נְתַתּוֹ בְּאַהֲבָה, לְזֶרַע יַעֲקֹב אֲשֶׁר בָּם בָּחָרְתָּ:", "<b>יִשְׂמְחוּ</b> בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עוֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּוֹ וְקִדַּשְׁתּוֹ. חֶמְדַת יָמִים אוֹתוֹ קָרָאתָ. זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<b>אֱלֹהֵינוּ</b> וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךְ, וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶאֱמֶת, וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבָּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ. בָּרוּךְ אַתָּה יְהֹוָה, מְקַדֵּשׁ הַשַּׁבָּת:", "<b>רְצֵה</b> יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל, וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<b>וְתֶחֱזֶינָה</b> עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. בָּרוּךְ אַתָּה יְהֹוָה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:", "<b>מוֹדִים</b> אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדֹר וָדֹר. נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶיךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם. הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְּרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b><b><small> מודים דרבנן<small><b><small>בחזרת הש\"ץ</small></b> כשהוא אומר מודים, אומרים הקהל:</small> </small></b></b>", "<small><b><b><small>מוֹדִים אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׁר, יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמֹר חֻקֶּיךָ וְלַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְךָ בְלֵבָב שָׁלֵם, עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת.</small></b></b></small>", "<b>וְעַל</b> כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָמִיד לְעוֹלָם וָעֶד.", "<b>וְכֹל</b> הַחַיִּים יוֹדוּךָ סֶּלָה: וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל, בֶּאֱמֶת, לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<b><b>ברכת כהנים</b></b>", "<b>שִׂים שָׁלוֹם</b> טוֹבָה וּבְרָכָה, חַיִּים, חֵן וָחֶסֶד, וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד <small>(יַחַד)</small> בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים, וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים, וְחַיִּים וְשָׁלוֹם. <small>(וְכָל טוּב)</small> וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרֹב עֹז וְשָׁלוֹם.", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה, הַמְּבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>אֱלֹהַי.</b> נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וְאַחֲרֵי מִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַקָּמִים וְהַחוֹשְׁבִים עָלַי לְרָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:", "<b><b><small>יש אומרים כאן תפילה זו:</small></b></b>", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי. שֶׁלֹּא תַעֲלֶה קִנְאַת אָדָם עָלַי וְלֹא קִנְאָתִי עַל אֲחֵרִים. וְשֶׁלֹּא אֶכְעוֹס הַיֹּום וְשֶׁלֹּא אַכְעִיסֶךָ. וְתַצִּילֵנִי מִיֵּצֶר הָרָע. וְתֵן בְּלִבִּי הַכְנָעָה וַעֲנָוָה. מַלְכֵּנוּ וֵאלֹהֵינוּ אֱלֹהַּ כָּל בָּשָׂר. יַחֵד שִׁמְךָ בְּעוֹלָמֶךָ בְּנֵה עִירֶךָ יַסֵּד בֵּיתֶךָ וְשַׁכְלֵל הֵיכָלֶךָ. וְקַבֵּץ קִבּוּץ גָּלֻיּוֹת וּפְדֵה צֹאנֶךָ וְשַׂמַּח עֲדָתֶךָ: <b>עֲשֵׂה</b> לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי:", "<b><b><small>נוהגים לומר כאן פסוק המתחיל וגומר באוֹת שבה מתחיל וגומר שמו הפרטי</small></b></b>", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>עֹשֶׂה שָׁלוֹם</b> בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b>וְעָרְבָה</b> לַיהֹוָה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b><b><small>קדיש שלם</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>תִּתְקַבֵּל</b> צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא, וְאִמְרוּ אָמֵן:", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small>שיר של יום</small></b></b>", "<b><b><small><b>הַיּוֹם</b> יוֹם שַׁבָּת קֹדֶשׁ שֶׁבּו הָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ:</small></b></b>", "<b>מִזְמוֹר שִׁיר</b> לְיוֹם הַשַּׁבָּת: טוֹב לְהֹדוֹת לַיהֹוָה וּלְזַמֵּר לְשִׁמְךָ עֶלְיוֹן: לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ וֶאֱמוּנָתְךָ בַּלֵּילוֹת: עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל עֲלֵי הִגָּיוֹן בְּכִנּוֹר: כִּי שִׂמַּחְתַּנִי יְהֹוָה בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשֶׂיךָ יְהֹוָה מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ: אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת: בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרוֹם לְעֹלָם יְהֹוָה: כִּי הִנֵּה אֹיְבֶיךָ יְהֹוָה כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה: שְׁתוּלִים בְּבֵית יְהֹוָה בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ: עוֹד יְנוּבוּן בְּשֵׂיבָה דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר יְהֹוָה צוּרִי וְלֹא עַוְלָתָה בּוֹ:", "<b><b><small>קדיש יתום</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:"]}, "rh1": {"ref": "The Koren Rosh HaShana Mahzor; Ashkenaz, First Day, Leader's Repetition for Shaharit", "he": "חזרת הש\"ץ לשחרית, יום א' של ראש השנה", "nusach": "מחזור קורן, נוסח אשכנז", "version": "Hebrew Edition; Koren Publishers Jerusalem, 2019", "source": "https://korenpub.co.il/en/products/the-koren-sacks-rosh-hashana-mahzorhardcoverstandardashkenaz", "url": "https://www.sefaria.org/The_Koren_Rosh_HaShana_Mahzor%3B_Ashkenaz%2C_First_Day%2C_Leader's_Repetition_for_Shaharit", "segs": ["", "אֲדֹנָי, שְׂפָתַי תִּפְתָּח, וּפִי יַגִּיד תְּהִלָּתֶֽךָ׃", "<b>אבות</b>", "בָּרוּךְ אַתָּה יהוה, אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ<br>אֱלֹהֵי אַבְרָהָם, אֱלֹהֵי יִצְחָק, וֵאלֹהֵי יַעֲקֹב<br>הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, אֵל עֶלְיוֹן<br>גּוֹמֵל חֲסָדִים טוֹבִים, וְקֹנֵה הַכֹּל<br>וְזוֹכֵר חַסְדֵי אָבוֹת<br>וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַֽעַן שְׁמוֹ בְּאַהֲבָה.", "", "מִסּוֹד חֲכָמִים וּנְבוֹנִים<br>וּמִלֶּֽמֶד דַּֽעַת מְבִינִים<br>אֶפְתְּחָה פִּי בִּתְפִלָּה וּבְתַחֲנוּנִים<br>לְחַלּוֹת וּלְחַנֵּן פְּנֵי מֶֽלֶךְ מַלְכֵי הַמְּלָכִים וַאֲדוֹנֵי הָאֲדוֹנִים.", "יָרֵֽאתִי בִּפְצוֹתִי שִֽׂיחַ לְהַשְׁחִיל / קוּמִי לְחַלּוֹת פְּנֵי נוֹרָא וְדָחִיל<br>וְקָטֹֽנְתִּי מַֽעַשׂ לָכֵן אַזְחִיל / תְּבוּנָה חָסַֽרְתִּי וְאֵיךְ אוֹחִיל<br>יוֹצְרִי הֲבִינֵֽנִי מוֹרָשָׁה לְהַנְחִיל / אַיְּלֵֽנִי וְאַמְּצֵֽנִי מֵרִפְיוֹן וְחִיל<br>לַחֲשִׁי יֵרָצֶה כְּמַנְטִיף וּמַשְׁחִיל / בִּטּוּיִי יֻמְתַּק כְּצוּף נָחִיל<br>רָצוּי בְּיֹֽשֶׁר וְלֹא כְּמַכְחִיל / מְשַׁלְּחַי לְהַמְצִיא כֹּֽפֶר וּלְהַמְחִיל<br>שַׁאֲגִי יֶעֱרַב וְלֹא כְּמַשְׁחִיל / הֵעָתֵר לְנִגָּשִׁים וְנֶחְשָׁבִים כְּזָחִיל<br>חַנּוּן כְּהַבְטִיחֲךָ לִבְנִקְרַת מְחִיל / זַעֲקִי קְשֹׁב בְּעֵת אַתְחִיל<br>קְרָבַי יֶחְמְרוּ בְּחָקְרְךָ חַלּוֹחִיל / וּמֵאֵימַת הַדִּין נַפְשִׁי תַבְחִיל<br>אִם כִּגְמוּל הַלֵּב יָחִיל / מְקוֹרֵי עַפְעַפַּי אַזִּיל כְּמַזְחִיל<br>צְדָקָה אֲקַוֶּה מִמְּךָ וְאוֹחִיל / יֹֽשֶׁר הוֹרַי זָכְרָה לְהַאֲחִיל<br>חַם לִבִּי בַּהֲגִיגִי יַגְחִיל / יִסְתָּעֵר בְּקִרְבִּי בְּעֵת אָת חִיל.", "", "", "אָת חִיל יוֹם פְּקֻדָּה / בְּאֵימָיו כָּל לְחוּם לְשָׂקְדָה<br>גָּשִׁים בּוֹ בֶּֽרֶךְ לִקּֽוֹדָה / דֵּעָם לְיַשֵּׁר כְּעַל מוֹקְדָה.", "הַיּוֹצֵר יַֽחַד כֶּֽסֶל נִשְׁפָּט / וְשֽׁוֹעַ וָדַל בְּפִלּוּס יֻשְׁפָּט<br>זֵֽכֶר לֹא יַעֲשֶׂה מִשְׁפָּט / חִין עֶרְכּוֹ יֻזְכַּר בַּמִּשְׁפָּט.", "טֶֽרֶם כָּל מִפְעָל חָצַב / יָזַם בְּמַחֲשֶֽׁבֶת צוּר חֻצַּב<br>כְּאָחוֹר וָקֶֽדֶם בַּתָּֽוֶךְ נֶחְצַב / לְיַהֵב עָלָיו כָּל הַמַּחְצָב.", "מְנָתוֹ כְּהַיּוֹם כֹּֽחַ דֻּשָּֽׁנָה / נֵֽצֶר לְהַחֲנִיט לְתִשְׁעִים שָׁנָה<br>סֻיְּמָה אוֹת הֱיוֹת לְשׁוֹשַׁנָּה / עֲבֹר לְפָנָיו בְּרֹאשׁ הַשָּׁנָה.", "פֻּלְּצוּ פְרָחֶֽיהָ בְּחֹק יוֹם / צִיגָתָם פְּנֵי כֵס אָיֹם<br>קוֹל דִּבְבָם יַרְחִֽישׁוּ כְּהַיּוֹם / רוֹגְשִׁים לְהָרִֽיעַ לִמְצֹא פִדְיוֹם.", "שְׁעוּנִים עָלֶֽיהָ בָּהּ לְהִפָּקְדָה / שׁוֹאֲגִים בְּלַֽהַק דְּלָתוֹת לְשָׁקְדָה<br>תְּמוּכִים בְּדֶֽשֶׁן שֶׂה עֲקֵדָה / תֶּֽשֶׁר אֲשֶׁר בּוֹ נִפְקָֽדָה.", "", "נַעֲלָה בַדִּין עֲלוֹת בִּתְרוּעָה / גֵּיא עִם דָּרֶֽיהָ לְרוֹעֲעָה<br>בַּשּׁוֹפָר (בְּזִכְרוֹן שׁוֹפָר) אֲפַתֶּֽנּוּ, וּבְבֶֽרֶךְ כְּרִיעָה<br>בְּמָגִנַּת רֵעִים בְּגַנּוֹ אֶתְרוֹעֲעָה.", "", "זָכְרֵֽנוּ לְחַיִּים, מֶֽלֶךְ חָפֵץ בַּחַיִּים<br>וְכָתְבֵֽנוּ בְּסֵֽפֶר הַחַיִּים, לְמַעַנְךָ אֱלֹהִים חַיִּים.<br>מֶֽלֶךְ עוֹזֵר וּמוֹשִֽׁיעַ וּמָגֵן.<br>בָּרוּךְ אַתָּה יהוה, מָגֵן אַבְרָהָם.", "<b>גבורות</b>", "אַתָּה גִּבּוֹר לְעוֹלָם, אֲדֹנָי<br>מְחַיֵּה מֵתִים אַתָּה, רַב לְהוֹשִֽׁיעַ", "<i>בארץ ישראל:</i>", "מוֹרִיד הַטָּל", "מְכַלְכֵּל חַיִּים בְּחֶֽסֶד, מְחַיֵּה מֵתִים בְּרַחֲמִים רַבִּים<br>סוֹמֵךְ נוֹפְלִים, וְרוֹפֵא חוֹלִים, וּמַתִּיר אֲסוּרִים<br>וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר.<br>מִי כָמֽוֹךָ, בַּֽעַל גְּבוּרוֹת, וּמִי דּֽוֹמֶה לָּךְ<br>מֶֽלֶךְ, מֵמִית וּמְחַיֶּה וּמַצְמִֽיחַ יְשׁוּעָה.", "", "תַּאֲלַת זוּ כְּחָפֵץ לְהַתְעִיל / שֽׁוּעַ עֲרֹךְ לִמְּדָם לְהוֹעִיל<br>רוֹן הַרְרֵי קֶֽדֶם הַמּוֹעִיל / קְרֹא בְגָרוֹן מוֹקֵשׁ לְהַגְעִיל.", "צִדְקָם לְהַקְפּוֹת בְּנִיב שַׁוְעָה / פָּעֳלָם בְּקֶֽרֶב שָׁנִים לְשַׁמְּעָה<br>עֵת רָצוֹן וְיוֹם יְשׁוּעָה / סְבִיכַת קֶֽרֶן וּבְרִית שְׁבוּעָה.", "נוֹבְבִים בְּגִישַׁת חוֹתָמוֹת תִּשְׁעָה / מִסְפַּר שָׁתוֹת וְחוֹתְמֵיהֶן תִּשְׁעָה<br>לְמִנְיַן פִּלּוּל שֵׁמוֹת תִּשְׁעָה / כְּחִנְּנָה עֲקָרָה יָלְדָה שִׁבְעָה.", "יַאֲמִֽירוּ עֹז מַלְכִיּוֹת עֶֽשֶׂר / טְבוּעוֹת לְשֵׁם בֻּחַן עֶֽשֶׂר<br>חֹק זִכְרוֹנוֹת וְקוֹלוֹת עֶֽשֶׂר / זֵֽכֶר מְבָרֵךְ גְּבִירוֹ בְּעֶֽשֶׂר.", "וְיִֽפֶן בַּאֲהוּב אֲתוּי נַהֲרַֽיִם / הֶעָקוּד בְּהַר מוֹר אֲחוֹרַֽיִם<br>דִּשְׁנוֹ יֵֽרֶא לָחֹן שִׁירַֽיִם / גָּשִׁים עָדָיו בֹּֽקֶר וְצָהֳרָֽיִם.", "בְּזֶה פֶּֽרֶק חִנֵּן עֲתִירָה / בְּעַד אֲסוּרָה עַד הֻתָּֽרָה<br>אֶנְקַת אָסִיר אָז כְּהֻכְתָּֽרָה / אֵלַי לְהֵעָתֵר כְּמוֹ נֶעְתָּֽרָה.", "", "מֶֽלֶךְ עֶלְיוֹן וְנוֹרָא / מִשְׁפָּטֵֽנוּ יוֹצִיא כָאוֹרָה<br>אֲיַחֲלֶֽנּוּ כֶּֽתֶר לְעַטְּרָה / בְּטַלְלֵי תֶֽחִי בְּחַסְדּוֹ אֶתְפָּאֲרָה.", "", "מִי כָמֽוֹךָ אַב הָרַחֲמִים, זוֹכֵר יְצוּרָיו לְחַיִּים בְּרַחֲמִים.<br>וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים.<br>בָּרוּךְ אַתָּה יהוה, מְחַיֵּה הַמֵּתִים.", "", "אֶֽבֶן חוּג מְצוּק נְשִׁיָּה / תְּהוֹם רַבָּה צוּל שְׁאִיָּה<br>בְּפִנַּת רֹאשׁ יְסוֹד שְׁלִישִׁיָּה / שֻׁתְּתוּ שְׁעוֹן בָּהּ לִשְׁעִיָּה.", "גִּבְעַת שֹֽׁרֶשׁ מְאוּסַת בּוֹנִים / רֻבְּעָה הַיּוֹם מֵאַרְבַּע אֲבָנִים<br>דְּמָעוֹת מְבַכָּה עַל בָּנִים / קָשְׁבָה, מִנְעִי אֵם הַבָּנִים.", "הָאַדְמוֹן, כְּבָט שֶׁלֹּא חָֽלָה / צָבָה לְקַחְתָּהּ לוֹ, וְנִתְבַּהֲלָה<br>וּפִלְּלָה רַבִּים בְּעַד הַתּוֹחֵלָה / פְּדוֹתָהּ מִזֵּד, וְלֹא חֻלָּֽלָה.", "זָכַר לָהּ יֹֽשֶׁר אֳרָחוֹת / עֻבָּר לְהָמִיר בְּבֶֽטֶן אָחוֹת<br>חִשְּׁבָהּ הַיּוֹם זִכְרָהּ לְהֵאָחוֹת / סִלּוּף דִּינָה בִּיהוֹסֵף לְהַנְחוֹת.", "טֶֽבַע כִּכְלִי יוֹצֵר הֶעֱבִיר / נִסֵּי חֲיָלִים לְהַעֲצִים וּלְהַגְבִּיר<br>יָהּ כְּסָכַת אֶנְקַת גְּבִיר / מַטּוֹת שְׁנַֽיִם מֶֽנָּה הִסְבִּיר.", "כַּעֲקֶֽרֶת בַּֽיִת בְּתֶֽחֶל נֻכָּֽרָה / כְּבִכּוּר רֵאשִׁית בְּתֶֽכֶל בֻּכָּֽרָה<br>לְבַדֶּֽיהָ תַעֲמֹד בְּיוֹם זְכִירָה / לְהִזָּכֵר לָֽמוֹ כְּמוֹ נִזְכָּֽרָה.", "", "יִמְלֹךְ יהוה לְעוֹלָם<br>אֱלֹהַֽיִךְ צִיּוֹן לְדֹר וָדֹר, הַלְלוּיָהּ:", "וְאַתָּה קָדוֹשׁ, יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל:", "", "אֵל נָא.<br>אַתָּה הוּא אֱלֹהֵֽינוּ בַּשָּׁמַֽיִם וּבָאָֽרֶץ.<br>גִּבּוֹר וְנַעֲרָץ דָּגוּל מֵרְבָבָה.<br>הוּא שָׂח וַיֶּֽהִי וְצִוָּה וְנִבְרָֽאוּ.<br>זִכְרוֹ לָנֶֽצַח חַי עוֹלָמִים.<br>טְהוֹר עֵינַֽיִם יוֹשֵׁב סֵֽתֶר.<br>כִּתְרוֹ יְשׁוּעָה לְבוּשׁוֹ צְדָקָה.<br>מַעֲטֵֽהוּ קִנְאָה נֶאְפָּד נְקָמָה.<br>סִתְרוֹ יֹֽשֶׁר עֲצָתוֹ אֱמוּנָה.<br>פְּעֻלָּתוֹ אֱמֶת צַדִּיק וְיָשָׁר.<br>קָרוֹב לְקוֹרְאָיו בֶּאֱמֶת רָם וּמִתְנַשֵּׂא.<br>שׁוֹכֵן שְׁחָקִים תּוֹלֶה אֶֽרֶץ עַל בְּלִימָה.", "", "חַי וְקַיָּם, נוֹרָא וּמָרוֹם וְקָדוֹשׁ.", "", "", "", "", "תָּעִיר וְתָרִֽיעַ, לְהַכְרִית כָּל מֵרִֽיעַ<br>וְתֻקְדַּשׁ בְּיוֹדְעֵי לְהָרִֽיעַ. קָדוֹשׁ.", "", "אַדֶּֽרֶת מַמְלָכָה / עַל מָה הֻשְׁלָֽכָה / וְעוֹד לֹא מָלְכָה<br>לַבֵּל הִמְלִֽיכָה / וְאַחֲרָיו הָלְכָה / שֶׁלֹּא כַּהֲלָכָה<br>עָלֶֽיהָ הֻמְלְכָה / גְּבֶֽרֶת מַמְלָכָה / עַד תּוֹפִֽיעַ מְלוּכָה.", "זְבוּלִי חָרְכָה / מַתְמִימַי פָּרְכָה / וְנִתַּן לָהּ אַרְכָה<br>רָחֲבָה וְאָרְכָה / וְקֶֽשֶׁת דָּרְכָה / וְעֹל הֶאֱרִֽיכָה<br>בִּעֲתָה בְּרַכָּה / וְהִנֵּה דְרוּכָה / וְעַד עַתָּה מוֹלְכָה.", "יְסוֹדוֹת עֲרֵמָה / עֵרָה וְהֶחֱרִֽימָה / וְעַד יְסוֹד עָרְמָה<br>רֹאשׁ הֵרִֽימָה / וְסוֹד הֶעֱרִֽימָה / וְיָדָהּ רָֽמָה<br>בָּעֲרָה מֵעָרְמָה / וְעַד שַֽׁחַק רוּמָה / וְתֶאְפֹּד מְלוּכָה.", "יְרִיעוֹתַי גִּדְּדָה / אָהֳלִי שִׁדְּדָה / וְחָרְשָׁה וְשִׂדְּדָה<br>קְצִינוּת רָפְדָה / וּמַלְכוּת אָפְדָה / וְזֹאת הִקְפִּֽידָה<br>יָזְמָה וּמָרְדָה / עֲבֹד לַזָּר חָרְדָה / וְחִלְּלָה מְלוּכָה.", "לָחֲצָה בְּנֵי מֶֽלֶךְ / וּפָֽצָה לְעֵין מֶֽלֶךְ / מִי לִי בְּדוֹק מֶֽלֶךְ<br>יָהֲרָה בְּכֵס מֶֽלֶךְ / זוּלָתִי אֵין מֶֽלֶךְ / אֲנִי וְאַפְסִי מֶֽלֶךְ<br>רָם עַל כָּל מֶֽלֶךְ / תַּגְעִילֶֽנָּה מִמֶּֽלֶךְ / וּלְךָ תָּשִׁיב מְלוּכָה.", "", "תָּעִיר וְתָרִֽיעַ, לְהַכְרִית כָּל מֵרִֽיעַ<br>וְתֻקְדַּשׁ בְּיוֹדְעֵי לְהָרִֽיעַ. קָדוֹשׁ.", "", "", "וּבְכֵן, וַיהוה פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר<br>צֶאֱצָאֶֽיהָ כֵּן פְּקֹד לְטוֹב הַיּוֹם. קָדוֹשׁ.", "", "אֵם אֲשֶׁר בְּצֶֽדֶק נִתְיַשְּׁנָה / בְּמוֹ נִתְיַאֲשָׁה בְּתֶֽכֶל דֻּשָּֽׁנָה<br>גּוֹחָהּ, פְּקָדָהּ, בְּרֹאשׁ הַשָּׁנָה.", "דִּבְּבָה, הַיּוֹם אֲנִי נִדּוֹנָה / הִנְנִי עֲגוּמָה כִּכְלוֹת עֶדְנָה<br>וַתָּחְתַּם בְּצֶֽדֶק לְבַל הֱיוֹת עֲגוּנָה.", "זֹאת כְּהִתְבַּשְּׂרָה הֻשְׁקָֽדָה / חַלּוֹת פְּנֵי צַח שָׁקְדָה<br>טֶֽרֶם קָרְאָה מִיָּד נִפְקָֽדָה.", "יִצֲחַק כָּל שֹׁמֵֽעַ זֹאת, שָׂמֵֽחָה / כִּי גַלְמוּדָה לְלֹא עֵת צָמֵֽחָה<br>לָהּ הַכֹּל שִׁמְּעוּ, אֵם הַבָּנִים שְׂמֵחָה:", "מָצְאָה הַשְׁקֵט אַחֲרֵי בְלוֹתָהּ / נִתְחַדְּשָׁה כַנֶּֽשֶׁר בִּנְוֹתָהּ<br>שָֽׂשׂוּ שָׂרוֹת לְלַוּוֹתָהּ.", "עִלְזִי וְשִֽׂישִׂי עֲבוּרָהּ נִקְרָא / פָּצוּ עָדֶֽיהָ, רָנִּי עֲקָרָה:<br>צָמְקוּ שְׁדֵיהֶן וְעוֹד בָּם יָקְרָה.", "קְשַׁת רֽוּחַ אֲשֶׁר הָעָקְרָה / רֻפְּאָה לְקֵץ תִּשְׁעִים, כְּנִתְבַּקְּרָה<br>שִׁלְּחָה פֹארוֹת וְלֹא שִׁקֵּֽרָה.", "תֵּֽפֶן בַּנְּצָרִים אֲשֶׁר חוֹלְלוּ כְּהַיּוֹם / וְשָׁלֹשׁ עֲקָרוֹת שֶׁהֻפְקְדוּ בְּזֶה יוֹם<br>תַּצְדִּיק בְּצִדְקָתָם מְיַחֲלֶֽיךָ, אָיֹם.", "", "צֶאֱצָאֶֽיהָ כֵּן פְּקֹד לְטוֹב הַיּוֹם. קָדוֹשׁ.", "", "מֶֽלֶךְ מְמַלֵּט מֵרָעָה, לְיוֹדְעֵי תְרוּעָה. הָאֵל קָדוֹשׁ.", "", "מֶֽלֶךְ זְכֹר אֲחוּז קֶֽרֶן, לְתוֹקְעֵי לְךָ הַיּוֹם בְּקֶֽרֶן. נוֹרָא וְקָדוֹשׁ.", "", "אַאְפִּיד נֵֽזֶר אָיוֹם / בְּשִׁלּוּשׁ קְדֻשָּׁה בַּיּוֹם.<br>גִּבּוֹרֵי כֹֽחַ גְּדֻלָּה / דַּהֲרֽוּהוּ בְּבֵית דְּגִילָה.", "הוֹגֵי הֶֽגֶה הֲמֻלָּה / וַתְּקֽוּהוּ בְּהַלֵּל וּמִלָּה.<br>זוֹכֵר לָעַד זְכֻיּוֹת / חַדְּשֽׁוּהוּ זֶֽמֶר חַיּוֹת.", "טוֹב עוֹמֵס טֹֽרַח / יַחֲדֽוּהוּ בְּחִדּוּשׁ יָֽרַח.<br>כּוֹבֵשׁ כָּל כְּעָסִים / לְבַל אַף לְהָשִׂים.", "מְשָׁרְתֵי בְּחִיל מוֹרָא / נָכְחָם הַלְלוּ נוֹרָא.<br>שַׂרְפֵי סְבִיב סְעָרָה / עֱנוּ לְמַעֲבִיר עֶבְרָה.", "פְּלִיאִים פִּצְחוּ פֶה / צַלְצְלוּ הַכֹּל צוֹפֶה.<br>קְהִלּוֹת עַם קְדוֹשִׁים / רוֹמְמֽוּהוּ רִבְבוֹת רוֹעֲשִׁים.", "שֵֽׁמַע קוֹל שׁוֹפָר / תַּאֲזִין, וְאַשְׁמָה תוּפָר.<br>תְּשַׁלֵּשׁ שׁוֹפָרוֹת בְּהַר הַקֹּֽדֶשׁ / וַאֲשַׁלֵּשׁ קְדֻשָּׁה בַּקֹּֽדֶשׁ.", "מֶֽלֶךְ זְכוֹר אֲחוּז קֶֽרֶן, לְתוֹקְעֵי לְךָ הַיּוֹם בְּקֶֽרֶן. נוֹרָא וְקָדוֹשׁ.", "", "", "", "וּבְכֵן, וַיהוה פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר", "", "צֶאֱצָאֶֽיהָ כֵּן פְּקֹד לְטוֹב הַיּוֹם. קָדוֹשׁ.", "", "אֵם אֲשֶׁר בְּצֶֽדֶק נִתְיַשְּׁנָה / בְּמוֹ נִתְיַאֲשָׁה בְּתֶֽכֶל דֻּשָּֽׁנָה<br>גּוֹחָהּ, פְּקָדָהּ, בְּרֹאשׁ הַשָּׁנָה.", "דִּבְּבָה, הַיּוֹם אֲנִי נִדּוֹנָה / הִנְנִי עֲגוּמָה כִּכְלוֹת עֶדְנָה<br>וַתָּחְתַּם בְּצֶֽדֶק לְבַל הֱיוֹת עֲגוּנָה.", "זֹאת כְּהִתְבַּשְּׂרָה הֻשְׁקָֽדָה / חַלּוֹת פְּנֵי צַח שָׁקְדָה<br>טֶֽרֶם קָרְאָה מִיָּד נִפְקָֽדָה.", "יִצֲחַק כָּל שֹׁמֵֽעַ זֹאת, שָׂמֵֽחָה / כִּי גַלְמוּדָה לְלֹא עֵת צָמֵֽחָה<br>לָהּ הַכֹּל שִׁמְּעוּ, אֵם הַבָּנִים שְׂמֵחָה.", "מָצְאָה הַשְׁקֵט אַחֲרֵי בְלוֹתָהּ / נִתְחַדְּשָׁה כַנֶּֽשֶׁר בִּנְווֹתָהּ<br>שָֽׂשׂוּ שָׂרוֹת לְלַוּוֹתָהּ.", "עִלְזִי וְשִֽׂישִׂי עֲבוּרָהּ נִקְרָא / פָּצוּ עָדֶֽיהָ, רָנִּי עֲקָרָה<br>צָמְקוּ שְׁדֵיהֶן וְעוֹד בָּם יָקְרָה.", "קְשַׁת רֽוּחַ אֲשֶׁר הָעָקְרָה / רֻפְּאָה לְקֵץ תִּשְׁעִים, כְּנִתְבַּקְּרָה<br>שִׁלְּחָה פֹארוֹת וְלֹא שִׁקֵּֽרָה.", "תֵּֽפֶן בַּנְּצָרִים אֲשֶׁר חוֹלְלוּ כְּהַיּוֹם / וְשָׁלֹשׁ עֲקָרוֹת שֶׁהֻפְקְדוּ בְּזֶה יוֹם<br>תַּצְדִּיק בְּצִדְקָתָם מְיַחֲלֶֽיךָ, אָיוֹם.", "", "צֶאֱצָאֶֽיהָ כֵּן פְּקֹד לְטוֹב הַיּוֹם. קָדוֹשׁ.", "", "שְׁמוֹ מְפָאֲרִים עֲדַת חֶבְלוֹ<br>וְנַעֲרָץ בְּאֶרְאֶלֵּי קֹֽדֶשׁ הִלּוּלוֹ<br>וּבְהֵיכָלוֹ כָּבוֹד אֹמֵר כֻּלּוֹ / קָדוֹשׁ.", "שׁוֹמְרֵי מִצְוֹתָיו עוֹד יְשׁוּבוּן לְבִצָּרוֹן<br>נִדְבָּרִים יְרֵאָיו בְּהַכְשֵׁר וְיִתָּרוֹן<br>וַיַּקְשֵׁב יהוה וַיִּשְׁמָע, וַיִּכָּתֵב סֵֽפֶר זִכָּרוֹן: / קָדוֹשׁ.", "שַׁפְּרוּ מַעֲשֵׂיכֶם, וּבְרִית לֹא תוּפַר<br>נַאֲקַתְכֶם יַאֲזִין, שְׁחָקִים שִׁפַּר<br>וְתִיטַב לַיהוה מִשּׁוֹר פָּר: / קָדוֹשׁ.", "שִׁבְטֵי מְקֹרָאֲךָ עַלֵּה וְהַמְשֵׁל<br>נְטִישׁוֹת צָרִים בַּהֲתִזְּךָ לְנַשֵּׁל<br>כִּי לַיהוה הַמְּלוּכָה, וּמֹשֵׁל: / קָדוֹשׁ.", "שְׁבוּתֵֽנוּ מִמֶּרְחָק, עֲלוֹת לְהַר קָדְשׁוֹ<br>וּנְפָאֲרֶנּוּ תָמִיד בִּדְבִיר מִקְדָּשׁוֹ<br>כִּי־זָכַר אֶת־דְּבַר קָדְשׁוֹ: / קָדוֹשׁ.", "כָּל־יֹשְׁבֵי תֵבֵל וְשֹֽׁכְנֵי אָֽרֶץ:<br>יֹאמְרוּ תָמִיד, הִגְדִּיל יהוה לַעֲשׂוֹת בָּאָֽרֶץ<br>וְהָיָה יהוה לְמֶֽלֶךְ עַל־כָּל־הָאָֽרֶץ: / קָדוֹשׁ.", "", "<i>ש״ץ:</i> אֶֽדֶר וָהוֹד אֶתֵּן בְּצִבְיוֹן / שֶֽׁוַע אֶעֱרֹךְ בְּנִיב וְהִגָּיוֹן<br><i>קהל:</i> אֶקְרָא לֵאלֹהִים עֶלְיוֹן:", "<i>ש״ץ:</i> בַּיּוֹם הַנִּבְחָר מִשְּׁמֵי עֶֽרֶץ / מֵישָׁרִים לִשְׁפֹּט, קְדֻשָּׁתוֹ לְהַעֲרֵץ<br><i>קהל:</i> יהוה מָלָךְ תָּגֵל הָאָֽרֶץ:", "<i>ש״ץ:</i> גַּאֲוָתוֹ גָּדְלָה עוֹלָם מֵהָכִיל / עֱזוּזוֹ לְסַפֵּר כֹּֽחַ מִי יָכִיל<br><i>קהל:</i> מֶֽלֶךְ כָּל־הָאָֽרֶץ אֱלֹהִים, זַמְּרוּ מַשְׂכִּיל:", "שְׁמוֹ מְפָאֲרִים עֲדַת חֶבְלוֹ / וְנַעֲרָץ בְּאֶרְאֶלֵּי קֹֽדֶשׁ הִלּוּלוֹ<br>וּבְהֵיכָלוֹ כָּבוֹד אֹמֵר כֻּלּוֹ / קָדוֹשׁ.", "<i>ש״ץ:</i> דֵּֽעַ יָשִֽׂימוּ כָּל בְּרִיּוֹתָיו / וְיֵדְעוּ כִּי גָדְלוּ גְּבוּרוֹתָיו<br><i>קהל:</i> זֵֽכֶר עָשָׂה לְנִפְלְאֹתָיו:", "<i>ש״ץ:</i> הִצִּיב וְיָרָה אֶֽבֶן פִּנָּתוֹ / נַחֲלִיאֵל עֲבוּר לְשַׁעֲשֵֽׁעַ בְּאֻמָּתוֹ<br><i>קהל:</i> זָכַר לְעוֹלָם בְּרִיתוֹ:", "<i>ש״ץ:</i> וְרָשַׁם בְּחֹק דָּת הֶגְיוֹנַי / בְּכָל שָׁנָה וְשָׁנָה לִזְכֹּר זִכְרוֹנָי<br><i>קהל:</i> לְזִכָּרוֹן בְּהֵיכַל יהוה:", "שׁוֹמְרֵי מִצְוֹתָיו עוֹד יְשׁוּבוּן לְבִצָּרוֹן / נִדְבָּרִים יְרֵאָיו בְּהַכְשֵׁר וְיִתָּרוֹן<br>וַיַּקְשֵׁב יהוה וַיִּשְׁמָע, וַיִּכָּתֵב סֵֽפֶר זִכָּרוֹן: / קָדוֹשׁ.", "<i>ש״ץ:</i> זֶֽבַח קֹֽדֶשׁ כְּהָכְשַׁר אָז בְּעֵינָיו / רִגֵּל תְּמוּרָתוֹ אַֽיִל לְהַקְרִיב לְפָנָיו<br><i>קהל:</i> אַחַר נֶאֱחַז בַּסְּבַךְ בְּקַרְנָיו:", "<i>ש״ץ:</i> חִכֵּם חֲנִיטָיו לִתְקֹֽעַ בְּזֶה חֹֽדֶשׁ / יוֹם זֶה אִם יִקָּרֶה בְּשַׁבַּת קֹֽדֶשׁ<br><i>קהל:</i> זִכְרוֹן תְּרוּעָה מִקְרָא־קֹֽדֶשׁ:", "<i>ש״ץ:</i> טִבְעוֹ אִם בְּחוֹל יְבוֹאֲכֶם / צַוּוּ לִתְקֹֽעַ בְּכָל גְּבוּלְכֶם<br><i>קהל:</i> יוֹם תְּרוּעָה יִהְיֶה לָכֶם:", "שַׁפְּרוּ מַעֲשֵׂיכֶם, וּבְרִית לֹא תוּפַר / נַאֲקַתְכֶם יַאֲזִין, שְׁחָקִים שִׁפַּר<br>וְתִיטַב לַיהוה מִשּׁוֹר פָּר: / קָדוֹשׁ.", "<i>ש״ץ:</i> יָרוּם צוּר יִשְׁעִי בְּפִי כָּל אֻמִּים / חֲשֹׂף זְרוֹעֲךָ לְהוֹשִֽׁיעַ מִמִּתְקוֹמְמִים<br><i>קהל:</i> מַלְכוּתְךָ מַלְכוּת כָּל־עֹלָמִים:", "<i>ש״ץ:</i> כְּהִגָּלוֹתְךָ לְעֵין כֹּל שִׁכְנְךָ לְהִוָּעֵד / קְהִלּוֹת וּרְבָבוֹת בְּפִֽימוֹ לְהָעֵד<br><i>קהל:</i> יהוה יִמְלֹךְ לְעֹלָם וָעֶד:", "<i>ש״ץ:</i> לְךָ יָאֲתָה כָּבוֹד וָעֹז הֲגוּיִים / חֶֽלֶד וְשׁוֹכְנֶֽיהָ וְכָל הָאִיִּים<br><i>קהל:</i> מִי לֹא יִרָאֲךָ מֶֽלֶךְ הַגּוֹיִם:", "שִׁבְטֵי מְקֹרָאֲךָ עַלֵּה וְהַמְשֵׁל / נְטִישׁוֹת צָרִים בַּהֲתִזְּךָ לְנַשֵּׁל<br>כִּי לַיהוה הַמְּלוּכָה, וּמֹשֵׁל: / קָדוֹשׁ.", "<i>ש״ץ:</i> מוֹטֹת צָרִים שַׁבֵּר וְהַכְחִידֵם / זְרוּיֶֽיךָ קַבֵּץ וְחִנָּם תִּפְדֵּם<br><i>קהל:</i> זְכֹר עֲדָתְךָ קָנִֽיתָ קֶּֽדֶם:", "<i>ש״ץ:</i> נְדִיבֵי עַמִּים יְנֻחֲמוּ בְּכִפְלַֽיִם / קָמֵיהֶם עַל פָּנֵֽימוֹ גַּלֵּה שׁוּלָֽיִם<br><i>קהל:</i> זְכֹר יהוה לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלִָֽם:", "<i>ש״ץ:</i> סִלּוּל מְסִלָּתֵֽנוּ יַשֵּׁר לִצְעֹד / וּבֵן יַקִּירְךָ קַרְסֹל לֹא יִמְעֹד<br><i>קהל:</i> כְּנַֽמְתָּ, זָכֹר אֶזְכְּרֶֽנּוּ עוֹד:", "שְׁבוּתֵֽנוּ מִמֶּרְחָק, עֲלוֹת לְהַר קָדְשׁוֹ / וּנְפָאֲרֶנּוּ תָמִיד בִּדְבִיר מִקְדָּשׁוֹ<br>כִּי־זָכַר אֶת־דְּבַר קָדְשׁוֹ: / קָדוֹשׁ.", "<i>ש״ץ:</i> קִרְיַת מָשׂוֹשׂ, הֵיכָל וְאוּלָם / מִזְבֵּֽחַ יָשִׁיב, וּכְלֵי שָׁרֵת כֻּלָּם<br><i>קהל:</i> יהוה יִמְלֹךְ לְעֹלָם:", "<i>ש״ץ:</i> שָׁמַֽיִם וָאָֽרֶץ יְרַנְּנוּ לִשְׁמוֹ / יְעָרוֹת יִמְחֲאוּ כַף לְהַנְעִימוֹ<br><i>קהל:</i> כִּי־פָקַד יהוה אֶת־עַמּוֹ:", "<i>ש״ץ:</i> תֹּֽקֶף אֶרְאֶלִּים וְכוֹכְבֵי צְפָר / תְּהִלּוֹת יְתַנּוּ שֶֽׁבַח לְהַשְׁפַּר<br><i>קהל:</i> הַלְלֽוּהוּ בְּתֵֽקַע שׁוֹפָר:", "כָּל־יֹשְׁבֵי תֵבֵל וְשֹֽׁכְנֵי אָֽרֶץ: / יֹאמְרוּ תָמִיד, הִגְדִּיל יהוה לַעֲשׂוֹת בָּאָֽרֶץ<br>וְהָיָה יהוה לְמֶֽלֶךְ עַל־כָּל־הָאָֽרֶץ: / קָדוֹשׁ.", "", "יִשְׁפֹּט תֵּבֵל בְּצֶֽדֶק, וּלְאֻמִּים בְּמֵישָׁרִים / הָאֵל קָדוֹשׁ.", "וְהוּא בְאֶחָד וּמִי יְשִׁיבֶֽנּוּ, וְנַפְשׁוֹ אִוְּתָה וַיָּֽעַשׂ: / נוֹרָא וְקָדוֹשׁ.", "", "אֶתֵּן לְפֹעֲלִי צֶֽדֶק / בַּיּוֹם הַנִּבְחָר מַֽעַשׂ לְהִבָּדֵק.<br>גַּאֲוָתוֹ מְאֹד גָּדְלָה / דֶּֽרֶךְ עַנְוָתוֹ לְפִי הַגְּדֻלָּה.<br>הוּא אֲדוֹן הָעוֹלָם / וּמִי הִקְשָׁה אֵלָיו וַיִּשְׁלָם.<br>זוֹכֵר הוֹלֵךְ בַּתֹּם / חוֹנֵן וְעֹשֵׂה דִּין יָתוֹם.<br>טָהוֹר מָרוֹם וְנִשָּׂא / יָפֶה בְעִתּוֹ הַכֹּל עָשָׂה.<br>כַּבִּיר לֹא יִמְאַס / לְנִבְזֶה בְעֵינָיו, נִמְאָס.<br>מְפֹאָר רֹכֵב עֲרָבוֹת / נֹֽגַהּ נֶגְדּוֹ, וְאֵשׁ לֶהָבוֹת.<br>סוֹעֵף בַּחֲרָבוֹת שְׁנוּנוֹת / עֲבוּר יְתוֹמִים וְאַלְמָנוֹת.<br>פֹּֽעַל אָדָם יְשַׁלֵּם / צָר פֶּה וּמֵשִׂים אִלֵּם.<br>קֹנֵה הַכֹּל בְּרַחֲמִים / רָם וּמַשְׁפִּיל רָמִים.<br>שׁוֹפֵט יְצוּרָיו בַּחֲנִינָה / תְּמִים פֹּֽעַל, אֵל אֱמוּנָה.<br>שׁוֹפְטֵי אֶֽרֶץ כַּתֹּֽהוּ / מִפַּחְדּוֹ יִבָּהֲלוּ וְיִתְמָֽהוּ.<br>עוֹשֵׂה מִשְׁפַּט עַמּוֹ / וּתְחִלָּה מְקַדְּמָם מִפְּנֵי זַעְמוֹ.<br>נְדִיבִים בְּדִקְדּוּקָם יָחִֽילוּ / בַּאֲשֶׁר מִשְׁפָּטוֹ פָּעָֽלוּ.<br>רוֹאֶה כָּל תַּעֲלוּמוֹת / יוֹשֵׁב בְּגָבְהֵי מְרוֹמוֹת.<br>צוֹפֶה כָּל נוֹלָדוֹת / חוֹפֵשׂ כָּל הָעֲתִידוֹת.<br>קֹרֵא הַדֹּרוֹת מֵרֹאשׁ / חִקְרֵי לֵב לָתוּר וְלִדְרוֹשׁ.<br>זוֹכֵר בְּרִית רִאשׁוֹנִים / קַיֵּם שְׁבוּעָה לָאַחֲרוֹנִים.", "", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "אַדִּירֵי אֲיֻמָּה יַאְדִּֽירוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>בְּרוּאֵי בָרָק יְבָרְכוּ בְקוֹל. יהוה מָלָךְ.<br>גִּבּוֹרֵי גֹֽבַהּ יַגְבִּירוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "דּוֹהֲרֵי דוֹלְקִים יְדוֹבְבוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>הֲמוֹנֵי הֲמֻלָּה יְהַלְלוּ בְקוֹל. יהוה מָלָךְ.<br>וַחֲיָלִים וְחַיּוֹת יְוַעֲדוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "זוֹכְרֵי זְמִירוֹת יְזַמְּרוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>חַכְמֵי חִידוֹת יְחַסְּנוּ בְקוֹל. יהוה מָלָךְ.<br>טַפְסְרֵי טְפוּחִים יְטַכְּסוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "יוֹרְשֵׁי יְקָרָה יַיְשִֽׁירוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>כַּבִּֽירֵי כֹֽח יַכְתִּֽירוּ בְקוֹל. יהוה מָלָךְ.<br>לְבוּשֵׁי לֶהָבוֹת יְלַבְּבוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "מַנְעִימֵי מֶֽלֶל יְמַלְּלוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>נוֹצְצֵי נֹֽגַהּ יְנַצְּחוּ בְקוֹל. יהוה מָלָךְ.<br>שְׂרָפִים סוֹבְבִים יְסַלְסְלוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "עוֹרְכֵי עֹז יַעֲנוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>פְּחוּדֵי פִלְאֲךָ יִפְצְחוּ בְקוֹל. יהוה מָלָךְ.<br>צִבְאוֹת צֹאנְךָ יְצַלְצְלוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "קְהִלּוֹת קֹֽדֶשׁ יַקְדִּֽישׁוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>רִבְבוֹת רְבָבָה יְרַנְּנוּ בְקוֹל. יהוה מָלָךְ.<br>שְׁבִיבֵי שַׁלְהָבוֹת יְשַׁנְּנוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "תּוֹמְכֵי תְהִלּוֹת יַתְמִֽידוּ בְקוֹל. יהוה מֶֽלֶךְ.<br>תּוֹקְפֵי תִפְאַרְתְּךָ יַתְמִֽימוּ בְקוֹל. יהוה מָלָךְ.<br>תְּמִימֵי תְעוּדָה יְתַנּוּ בְקוֹל. יהוה יִמְלֹךְ.", "יהוה מֶֽלֶךְ, יהוה מָלָךְ, יהוה יִמְלֹךְ לְעֹלָם וָעֶד.", "", "וּבְכֵן לְךָ הַכֹּל יַכְתִּֽירוּ.", "לְאֵל עוֹרֵךְ דִּין לְבוֹחֵן לְבָבוֹת בְּיוֹם דִּין.<br>לְגוֹלֶה עֲמֻקּוֹת בַּדִּין לְדוֹבֵר מֵישָׁרִים בְּיוֹם דִּין.<br>לְהוֹגֶה דֵעוֹת בַּדִּין לְוָתִיק וְעוֹשֶׂה חֶֽסֶד בְּיוֹם דִּין.<br>לְזוֹכֵר בְּרִיתוֹ בַּדִּין לְחוֹמֵל מַעֲשָׂיו בְּיוֹם דִּין.<br>לְטַהֵר חוֹסָיו בַּדִּין לְיוֹדֵֽעַ מַחֲשָׁבוֹת בְּיוֹם דִּין לְכוֹבֵשׁ כַּעְסוֹ בַּדִּין לְלוֹבֵשׁ צְדָקוֹת בְּיוֹם דִּין.<br>לְמוֹחֵל עֲוֹנוֹת בַּדִּין לְנוֹרָא תְהִלּוֹת בְּיוֹם דִּין.<br>לְסוֹלֵֽחַ לַעֲמוּסָיו בַּדִּין לְעוֹנֶה לְקוֹרְאָיו בְּיוֹם דִּין.<br>לְפוֹעֵל רַחֲמָיו בַּדִּין לְצוֹפֶה נִסְתָּרוֹת בְּיוֹם דִּין.<br>לְקוֹנֶה עֲבָדָיו בַּדִּין לְרַחֵם עַמּוֹ בְּיוֹם דִּין.<br>לְשׁוֹמֵר אֹהֲבָיו בַּדִּין לְתוֹמֵךְ תְּמִימָיו בְּיוֹם דִּין.", "", "", "וּבְכֵן לְךָ תַעֲלֶה קְדֻשָּׁה, כִּי אַתָּה אֱלֹהֵֽינוּ מֶֽלֶךְ.", "", "<b>קדושה</b>", "", "<i>קהל ושליח ציבור:</i>", "נְקַדֵּשׁ אֶת שִׁמְךָ בָּעוֹלָם, כְּשֵׁם שֶׁמַּקְדִּישִׁים אוֹתוֹ בִּשְׁמֵי מָרוֹם<br>כַּכָּתוּב עַל יַד נְבִיאֶֽךָ: וְקָרָא זֶה אֶל־זֶה וְאָמַר", "<i>קהל ושליח ציבור:</i>", "קָדוֹשׁ, קָדוֹשׁ, קָדוֹשׁ, יהוה צְבָאוֹת, מְלֹא כָל־הָאָֽרֶץ כְּבוֹדוֹ׃<br>אָז בְּקוֹל רַֽעַשׁ גָּדוֹל אַדִּיר וְחָזָק, מַשְׁמִיעִים קוֹל<br>מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים, לְעֻמָּתָם בָּרוּךְ יֹאמֵֽרוּ", "<i>קהל ושליח ציבור:</i>", "בָּרוּךְ כְּבוֹד־יהוה מִמְּקוֹמוֹ׃<br>מִמְּקוֹמְךָ מַלְכֵּֽנוּ תוֹפִֽיעַ וְתִמְלֹךְ עָלֵֽינוּ, כִּי מְחַכִּים אֲנַֽחְנוּ לָךְ<br>מָתַי תִּמְלֹךְ בְּצִיּוֹן, בְּקָרוֹב בְּיָמֵֽינוּ לְעוֹלָם וָעֶד תִּשְׁכֹּן<br>תִּתְגַּדַּל וְתִתְקַדַּשׁ בְּתוֹךְ יְרוּשָׁלַֽיִם עִירְךָ, לְדוֹר וָדוֹר וּלְנֵֽצַח נְצָחִים.<br>וְעֵינֵֽינוּ תִרְאֶֽינָה מַלְכוּתֶֽךָ<br>כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּֽךָ עַל יְדֵי דָוִד מְשִֽׁיחַ צִדְקֶֽךָ.", "<i>קהל ושליח ציבור:</i>", "יִמְלֹךְ יהוה לְעוֹלָם, אֱלֹהַֽיִךְ צִיּוֹן לְדֹר וָדֹר, הַלְלוּיָהּ׃", "", "לְדוֹר וָדוֹר נַגִּיד גָּדְלֶֽךָ, וּלְנֵֽצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ<br>וְשִׁבְחֲךָ אֱלֹהֵֽינוּ מִפִּֽינוּ לֹא יָמוּשׁ לְעוֹלָם וָעֶד<br>כִּי אֵל מֶֽלֶךְ גָּדוֹל וְקָדוֹשׁ אָֽתָּה.", "וּבְכֵן תֵּן פַּחְדְּךָ יהוה אֱלֹהֵֽינוּ עַל כָּל מַעֲשֶֽׂיךָ<br>וְאֵימָתְךָ עַל כָּל מַה שֶּׁבָּרָֽאתָ<br>וְיִירָאֽוּךָ כָּל הַמַּעֲשִׂים, וְיִשְׁתַּחֲווּ לְפָנֶֽיךָ כָּל הַבְּרוּאִים<br>וְיֵעָשׂוּ כֻלָּם אֲגֻדָּה אֶחָת לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם<br>כְּמוֹ שֶׁיָּדַֽעְנוּ יהוה אֱלֹהֵֽינוּ שֶׁהַשָּׁלְטָן לְפָנֶֽיךָ<br>עֹז בְּיָדְךָ וּגְבוּרָה בִּימִינֶֽךָ<br>וְשִׁמְךָ נוֹרָא עַל כָּל מַה שֶּׁבָּרָֽאתָ.", "וּבְכֵן תֵּן כָּבוֹד יהוה לְעַמֶּֽךָ<br>תְּהִלָּה לִירֵאֶֽיךָ, וְתִקְוָה טוֹבָה לְדוֹרְשֶֽׁיךָ<br>וּפִתְחוֹן פֶּה לַמְיַחֲלִים לָךְ<br>שִׂמְחָה לְאַרְצֶֽךָ, וְשָׂשׂוֹן לְעִירֶֽךָ<br>וּצְמִיחַת קֶֽרֶן לְדָוִד עַבְדֶּֽךָ, וַעֲרִיכַת נֵר לְבֶן יִשַׁי מְשִׁיחֶֽךָ<br>בִּמְהֵרָה בְיָמֵֽינוּ.", "וּבְכֵן צַדִּיקִים יִרְאוּ וְיִשְׂמָֽחוּ, וִישָׁרִים יַעֲלֹֽזוּ<br>וַחֲסִידִים בְּרִנָּה יָגִֽילוּ, וְעוֹלָֽתָה תִּקְפָּץ פִּֽיהָ<br>וְכָל הָרִשְׁעָה כֻּלָּהּ כְּעָשָׁן תִּכְלֶה, כִּי תַעֲבִיר מֶמְשֶֽׁלֶת זָדוֹן מִן הָאָֽרֶץ.", "וְתִמְלֹךְ אַתָּה יהוה לְבַדֶּֽךָ עַל כָּל מַעֲשֶֽׂיךָ<br>בְּהַר צִיּוֹן מִשְׁכַּן כְּבוֹדֶֽךָ, וּבִירוּשָׁלַֽיִם עִיר קָדְשֶֽׁךָ<br>כַּכָּתוּב בְּדִבְרֵי קָדְשֶֽׁךָ<br>יִמְלֹךְ יהוה לְעוֹלָם, אֱלֹהַֽיִךְ צִיּוֹן לְדֹר וָדֹר, הַלְלוּיָהּ:", "קָדוֹשׁ אַתָּה וְנוֹרָא שְׁמֶֽךָ, וְאֵין אֱלֽוֹהַּ מִבַּלְעָדֶֽיךָ<br>כַּכָּתוּב, וַיִּגְבַּהּ יהוה צְבָאוֹת בַּמִּשְׁפָּט<br>וְהָאֵל הַקָּדוֹשׁ נִקְדַּשׁ בִּצְדָקָה:<br>בָּרוּךְ אַתָּה יהוה, הַמֶּֽלֶךְ הַקָּדוֹשׁ.", "<b>קדושת היום</b>", "אַתָּה בְחַרְתָּֽנוּ מִכָּל הָעַמִּים<br>אָהַֽבְתָּ אוֹתָֽנוּ וְרָצִֽיתָ בָּֽנוּ, וְרוֹמַמְתָּֽנוּ מִכָּל הַלְּשׁוֹנוֹת<br>וְקִדַּשְׁתָּֽנוּ בְּמִצְוֹתֶֽיךָ, וְקֵרַבְתָּֽנוּ מַלְכֵּֽנוּ לַעֲבוֹדָתֶֽךָ<br>וְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עָלֵֽינוּ קָרָֽאתָ.", "", "וַתִּתֶּן לָֽנוּ יהוה אֱלֹהֵֽינוּ בְּאַהֲבָה<br>אֶת יוֹם (הַשַּׁבָּת הַזֶּה וְאֶת יוֹם) הַזִּכָּרוֹן הַזֶּה<br>יוֹם (זִכְרוֹן) תְּרוּעָה (בְּאַהֲבָה) מִקְרָא קֹֽדֶשׁ, זֵֽכֶר לִיצִיאַת מִצְרָֽיִם.", "אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ<br>יַעֲלֶה וְיָבוֹא וְיַגִּֽיעַ, וְיֵרָאֶה וְיֵרָצֶה וְיִשָּׁמַע<br>וְיִפָּקֵד וְיִזָּכֵר זִכְרוֹנֵֽנוּ וּפִקְדוֹנֵֽנוּ וְזִכְרוֹן אֲבוֹתֵֽינוּ<br>וְזִכְרוֹן מָשִֽׁיחַ בֶּן דָּוִד עַבְדֶּֽךָ, וְזִכְרוֹן יְרוּשָׁלַֽיִם עִיר קָדְשֶֽׁךָ<br>וְזִכְרוֹן כָּל עַמְּךָ בֵּית יִשְׂרָאֵל, לְפָנֶֽיךָ<br>לִפְלֵיטָה לְטוֹבָה, לְחֵן וּלְחֶֽסֶד וּלְרַחֲמִים, לְחַיִּים וּלְשָׁלוֹם<br>בְּיוֹם הַזִּכָּרוֹן הַזֶּה.<br>זָכְרֵֽנוּ יהוה אֱלֹהֵֽינוּ בּוֹ לְטוֹבָה, וּפָקְדֵֽנוּ בוֹ לִבְרָכָה<br>וְהוֹשִׁיעֵֽנוּ בוֹ לְחַיִּים.<br>וּבִדְבַר יְשׁוּעָה וְרַחֲמִים חוּס וְחָנֵּֽנוּ, וְרַחֵם עָלֵֽינוּ וְהוֹשִׁיעֵֽנוּ<br>כִּי אֵלֶֽיךָ עֵינֵֽינוּ, כִּי אֵל מֶֽלֶךְ חַנּוּן וְרַחוּם אָֽתָּה.", "", "אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ<br>מְלֹךְ עַל כָּל הָעוֹלָם כֻּלּוֹ בִּכְבוֹדֶֽךָ<br>וְהִנָּשֵׂא עַל כָּל הָאָֽרֶץ בִּיקָרֶֽךָ<br>וְהוֹפַע בַּהֲדַר גְּאוֹן עֻזֶּֽךָ עַל כָּל יוֹשְׁבֵי תֵבֵל אַרְצֶֽךָ.<br>וְיֵדַע כָּל פָּעוּל כִּי אַתָּה פְעַלְתּוֹ, וְיָבִין כָּל יָצוּר כִּי אַתָּה יְצַרְתּוֹ<br>וְיֹאמַר כֹּל אֲשֶׁר נְשָׁמָה בְּאַפּוֹ<br>יהוה אֱלֹהֵי יִשְׂרָאֵל מֶֽלֶךְ וּמַלְכוּתוֹ בַּכֹּל מָשָֽׁלָה.<br>(אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ, רְצֵה בִמְנוּחָתֵֽנוּ)<br>קַדְּשֵֽׁנוּ בְּמִצְוֹתֶֽיךָ וְתֵן חֶלְקֵֽנוּ בְּתוֹרָתֶֽךָ<br>שַׂבְּעֵֽנוּ מִטּוּבֶֽךָ וְשַׂמְּחֵֽנוּ בִּישׁוּעָתֶֽךָ<br>(וְהַנְחִילֵֽנוּ יהוה אֱלֹהֵֽינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבַּת קָדְשֶֽׁךָ<br>וְיָנֽוּחוּ בוֹ יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶֽךָ)<br>וְטַהֵר לִבֵּֽנוּ לְעָבְדְּךָ בֶּאֱמֶת<br>כִּי אַתָּה אֱלֹהִים אֱמֶת, וּדְבָרְךָ אֱמֶת וְקַיָּם לָעַד.<br>בָּרוּךְ אַתָּה יהוה, מֶֽלֶךְ עַל כָּל הָאָֽרֶץ<br>מְקַדֵּשׁ (הַשַּׁבָּת וְ) יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן.", "<b>עבודה</b>", "רְצֵה יהוה אֱלֹהֵֽינוּ בְּעַמְּךָ יִשְׂרָאֵל וּבִתְפִלָּתָם<br>וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶֽךָ<br>וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן<br>וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּֽךָ.<br>וְתֶחֱזֶֽינָה עֵינֵֽינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים.<br>בָּרוּךְ אַתָּה יהוה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן.", "<b>הודאה</b>", "", "מוֹדִים אֲנַֽחְנוּ לָךְ<br>שָׁאַתָּה הוּא יהוה אֱלֹהֵֽינוּ<br>וֵאלֹהֵי אֲבוֹתֵֽינוּ לְעוֹלָם וָעֶד.<br>צוּר חַיֵּֽינוּ, מָגֵן יִשְׁעֵֽנוּ<br>אַתָּה הוּא לְדוֹר וָדוֹר.<br>נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶֽךָ<br>עַל חַיֵּֽינוּ הַמְּסוּרִים בְּיָדֶֽךָ<br>וְעַל נִשְׁמוֹתֵֽינוּ הַפְּקוּדוֹת לָךְ<br>וְעַל נִסֶּֽיךָ שֶׁבְּכָל יוֹם עִמָּֽנוּ<br>וְעַל נִפְלְאוֹתֶֽיךָ וְטוֹבוֹתֶֽיךָ<br>שֶׁבְּכָל עֵת, עֶֽרֶב וָבֹֽקֶר וְצָהֳרָֽיִם.<br>הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶֽיךָ וְהַמְרַחֵם, כִּי לֹא תַֽמּוּ חֲסָדֶֽיךָ<br>מֵעוֹלָם קִוִּֽינוּ לָךְ.", "", "מוֹדִים אֲנַֽחְנוּ לָךְ<br>שָׁאַתָּה הוּא יהוה אֱלֹהֵֽינוּ<br>וֵאלֹהֵי אֲבוֹתֵֽינוּ<br>אֱלֹהֵי כָל בָּשָׂר<br>יוֹצְרֵֽנוּ, יוֹצֵר בְּרֵאשִׁית.<br>בְּרָכוֹת וְהוֹדָאוֹת<br>לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ<br>עַל שֶׁהֶחֱיִיתָֽנוּ וְקִיַּמְתָּֽנוּ.<br>כֵּן תְּחַיֵּֽנוּ וּתְקַיְּמֵֽנוּ<br>וְתֶאֱסֹף גָּלֻיּוֹתֵֽינוּ<br>לְחַצְרוֹת קָדְשֶֽׁךָ<br>לִשְׁמֹר חֻקֶּֽיךָ וְלַעֲשׂוֹת רְצוֹנֶֽךָ וּלְעָבְדְּךָ בְּלֵבָב שָׁלֵם<br>עַל שֶׁאֲנַֽחְנוּ מוֹדִים לָךְ.<br>בָּרוּךְ אֵל הַהוֹדָאוֹת.", "וְעַל כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם שִׁמְךָ מַלְכֵּֽנוּ תָּמִיד לְעוֹלָם וָעֶד.", "", "וּכְתֹב לְחַיִּים טוֹבִים כָּל בְּנֵי בְרִיתֶֽךָ.", "", "וְכֹל הַחַיִּים יוֹדֽוּךָ סֶּֽלָה, וִיהַלְלוּ אֶת שִׁמְךָ בֶּאֱמֶת<br>הָאֵל יְשׁוּעָתֵֽנוּ וְעֶזְרָתֵֽנוּ סֶֽלָה.<br>בָּרוּךְ אַתָּה יהוה<br>הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת.", "", "אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ, בָּרְכֵֽנוּ בַּבְּרָכָה הַמְשֻׁלֶּֽשֶׁת בַּתּוֹרָה הַכְּתוּבָה עַל יְדֵי מֹשֶׁה עַבְדֶּֽךָ, הָאֲמוּרָה מִפִּי אַהֲרֹן וּבָנָיו כֹּהֲנִים עַם קְדוֹשֶֽׁיךָ, כָּאָמוּר", "יְבָרֶכְךָ יהוה וְיִשְׁמְרֶֽךָ׃ <i>קהל:</i> כֵּן יְהִי רָצוֹן<br>יָאֵר יהוה פָּנָיו אֵלֶֽיךָ וִיחֻנֶּֽךָּ׃ <i>קהל:</i> כֵּן יְהִי רָצוֹן<br>יִשָּׂא יהוה פָּנָיו אֵלֶֽיךָ וְיָשֵׂם לְךָ שָׁלוֹם׃ <i>קהל:</i> כֵּן יְהִי רָצוֹן", "<b>שלום</b>", "שִׂים שָׁלוֹם טוֹבָה וּבְרָכָה, חֵן וָחֶֽסֶד וְרַחֲמִים<br>עָלֵֽינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּֽךָ.<br>בָּרְכֵֽנוּ אָבִֽינוּ כֻּלָּֽנוּ כְּאֶחָד בְּאוֹר פָּנֶֽיךָ<br>כִּי בְאוֹר פָּנֶֽיךָ נָתַֽתָּ לָּֽנוּ, יהוה אֱלֹהֵֽינוּ<br>תּוֹרַת חַיִּים וְאַהֲבַת חֶֽסֶד<br>וּצְדָקָה וּבְרָכָה וְרַחֲמִים וְחַיִּים וְשָׁלוֹם.<br>וְטוֹב בְּעֵינֶֽיךָ לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל<br>בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶֽךָ.", "", "בְּסֵֽפֶר חַיִּים, בְּרָכָה וְשָׁלוֹם, וּפַרְנָסָה טוֹבָה<br>נִזָּכֵר וְנִכָּתֵב לְפָנֶֽיךָ, אֲנַֽחְנוּ וְכָל עַמְּךָ בֵּית יִשְׂרָאֵל<br>לְחַיִּים טוֹבִים וּלְשָׁלוֹם.*", "בָּרוּךְ אַתָּה יהוה, הַמְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם.", "", "בָּרוּךְ אַתָּה יהוה, עוֹשֶׂה הַשָּׁלוֹם.", "", "יִהְיוּ לְרָצוֹן אִמְרֵי־פִי וְהֶגְיוֹן לִבִּי לְפָנֶֽיךָ, יהוה צוּרִי וְגֹאֲלִי׃"]}, "selichot2": {"ref": "Selichot Nusach Ashkenaz Lita, Second Day of the Ten Days of Penitence 4", "he": "סליחות, יום ב' של עשרת ימי תשובה", "nusach": "סליחות נוסח ליטא", "version": "Selichot Nusach Lita -- Wikisource", "source": "https://he.wikisource.org/wiki/%D7%A1%D7%9C%D7%99%D7%97%D7%95%D7%AA_%D7%9C%D7%99%D7%9E%D7%99_%D7%94%D7%AA%D7%A9%D7%95%D7%91%D7%94/%D7%9E%D7%A0%D7%94%D7%92_%D7%9C%D7%99%D7%98%D7%90", "url": "https://www.sefaria.org/Selichot_Nusach_Ashkenaz_Lita%2C_Second_Day_of_the_Ten_Days_of_Penitence_4", "segs": ["סא. <small>על פי א\"ב. חתום שלמה הבבלי.</small><br>", "אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ<br>", "<b>אַךְ בְּךָ מִקְוֵה יִשְֹרָאֵל יְהֹוָה.</b> אָחוֹר וָקֶדֶם עַם נוֹשַׁע בַּיהֹוָה. וּמַדוּעַ בּוֹשֵׁשׁ יוֹם זֶה כַּמָּה עִדָּנַי. לִישׁוּעָתְךָ קִוִּיתִי יְהֹוָה:<br>", "גַּרְתִּי וָאֵחַר מֶשֶׁךְ יְמֵי עִגּוּנַי גֵּיא גּוֹי נָבָל וְעַם גְּנַאי. וּמַדּוּעַ דַל כָּכָה כָּבוֹד וְלִי דִינַי. קַוֵּה אֶל־יְהֹוָה חֲזַק וְיַאֲמֵץ לִבֶּךָ וְקַוֵּה אֶל יְהֹוָה:<br>", "הֲלֹא אַתָּה מִקֶּדֶם חֶרֶב גַּאֲוָתֵנוּ. הִקְוִינוּךָ אַף אֹרַח מִשְׁפָּטֶיךָ תַּאֲוָתֵנוּ. וּמַדּוּעַ וְאֵין אִישׁ מְכַפֵּר עַל חוֹבוֹתֵינוּ. וּמִדַּאֲבוֹנֵינוּ אוֹמְרִים יָבְשׁוּ עַצְמוֹתֵינוּ אָבְדָה תִּקְוָתֵנוּ:<br>", "זָכַרְנוּ חֶשְׁבּוֹנוֹת מִקֶּדֶם וּמִדָּתָם קָצְרָה. זֶה פַּעֲמַיִם קָצְרָה וְעוֹד פָּצְרָה. וּמַדּוּעַ נֶחֱשַׁבְנוּ כִּבְהֵמָה וְנִטְמִינוּ מִשִּׁטַּת הַשּׁוּרָה. מִקְוֵה יִשְֹרָאֵל יְהֹוָה מוֹשִׁיעוֹ בְּעֵת צָרָה:<br>", "טוֹעֲנִים וּפוֹרְקִים בָּנִים הַכָּתוּב סִבְלָם. טְרוּדֵי חֶבְלָם וְחָרֵב בֵּית זְבוּלָם. וּמַדּוּעַ יַסְתִּיר הָאָב שְׁבִילָם הָאָמוּר בִּגְלָלָם וְיֵשׁ תִּקְוָה לְאַחֲרִיתֵךְ נְאֻם יְהֹוָה וְשָׁבוּ בָנִים לִגְבוּלָם:<br>", "כִּמְעַט נָטָיוּ רַגְלַי וְשֻׁפְּכוּ אֲשׁוּרִים. כִּי קִנֵּאתִי בַּהוֹלְלִים מְעַרְבְּבֵי מֵישָׁרִים. וּמַדּוּעַ לֹא־תִקְצַר וְתִשָּׁבֵר רָמַת הַקּוֹשְׁרִים. וְקֹויֵ יְהֹוָה יַחֲלִיפוּ כֹחַ יַעֲלוּ אֵבֶר כַּנְּשָׁרִים:<br>", "מָלֵא רֻדַּפְתִּי וְחָסְרָה שְׁנַת גְּאוּלַי. מְסוּרִים לְמַכִּים וּמוֹרְטִים וּלְתִקְוָה אוּלַי. וּמַדּוּעַ נִסְחֲפוּ אַבִּירַי וּמְתֵי שִׁיר אַיָּלַי. קַוֹּה קִוִּיתִי אֶל יְהֹוָה וַיֵּט אֵלַי:<br>", "סוּגֶיךָ שְֹרִיגֶיךָ בְּקָקוּם בּוֹקְקִים וְהִבְאִישׁוּ. סִירִים סוּרֶיךָ גָּבְשׁוּ וְלֹא עָבְשׁוּ. וּמַדּוּעַ עָתְקוּ גָּבְרוּ כִּמְדֻבָּר לֹא יֵבוֹשׁוּ. מִקְוֵה יִשְֹרָאֵל יְהֹוָה כָּל־עוֹזְבֶיךָ יֵבוֹשׁוּ:<br>", "פּוֹעֲלֵי שֶׁקֶר יִתְאַמְּרוּ אִוִּינוּ רָאִינוּ פָּשְׁטוּ אֱמֶת אוֹתוֹתֵינוּ שַֹמְנוּ הִתְוִינוּ. וּמַדּוּעַ צָלְחָה דַרְכָּם וְחַסְדְּךָ דִמִּינוּ נִדְוִינוּ. יְהֹוָה חָנֵּנוּ לְךָ קִוִּינוּ:<br>", "קִימַת סֻכַּת שְׁלשׁ עֶשְֹרֵה פֶרֶץ. קִצָּהּ רָחַק. מִקוֹרָהּ עָלָה הַפּוֹרֵץ. וּמַדּוּעַ רְשָׁעִים יִחְיוּ וְלֹא יִדְּמוּ קֶרֶץ. וְקֹוֵי יְהֹוָה הֵמָּה יִירְשׁוּ אָרֶץ:<br>", "שׁוֹסֵי נַחֲלַת חֶבֶל מֵחֶלְקְךָ לְגָרְשֵׁנוּ. שׁוּבִי שׁוּבִי הַשּׁוּלַמִּית בְּפִיהֶם לְהַפְרִישֵׁנוּ. וּמַדּוּעַ תִּתְנַשְּׂאוּ וְזֶה לָזֶה תִּנְאֲמוּ נַפְרִישֶׁנּוּ. טוֹב יְהֹוָה לְקֹוָיו לְנֶפֶשׁ תִּדְרְשֶׁנּוּ:<br>", "שַׁדַּי תְּשׁוּבַת מַדּוּעֵינוּ פִּינוּ נְמַלֵּא. לַיהֹוָה אֱלֹהֵינוּ חָטָאנוּ וַתִּקְרֶאנָה אוֹתָנוּ כָּאֵלֶּה. מִשְׁפָּטֶיךָ אֱמֶת וְאַתָּה מָרוֹם מִתְעַלֶּה. הַצְּדָקָה לְךָ וְלָנוּ הַבֹּשֶׁת נִגְלֶה:<br>", "הֵעַדְתָּ רַבּוֹת וַנֹּאמֶר לֹא נַקְשִׁיב. קוֹל טִיף נְבִיאֶיךָ בָּזִינוּ לְהַקְשִׁיב. יִגְדַּל כֹּחַ סֶלָה יְחִידִים מוֹשִׁיב. בִּתְשׁוּבָה שְׁלֵמָה אוֹתָנוּ לְהָשִׁיב:<br>", "מַדּוּעַ אָדֹם לִלְבוּשֶׁךָ תְּקָרֵב עוֹנָתוֹ. וְיֵז נִצְחָם עַל בִּגְדֵי עֲטִיָּתוֹ. נוֹדֶה סֶלָה יוֹם הַבָּא בְּשַׁעְתּוֹ. זֶה יְהֹוָה קִוִּינוּ לוֹ נָגִילָה וְנִשְֹמְחָה בִּישׁוּעָתוֹ:<br>", "<b>אֵל מֶֽלֶךְ.</b> יוֹשֵׁב עַל כִּסֵּא רַחֲמִים. מִתְנַהֵג בַּחֲסִידוּת. מוֹחֵל עֲו‍ֹנוֹת עַמּוֹ. מַעֲבִיר רִאשׁוֹן רִאשׁוֹן. מַרְבֶּה מְחִילָה לְחַטָּאִים וּסְלִיחָה לְפוֹשְׁעִים. עוֹשֶׂה צְדָקוֹת עִם כָּל בָּשָׂר וָרֽוּחַ. לֹא כְרָעָתָם תִּגְמוֹל: אֵל הוֹרֵיתָ לָנוּ לוֹמַר שְׁלשׁ עֶשְׂרֵה. וּזְכָר לָֽנוּ הַיּוֹם בְּרִית שְׁלשׁ עֶשְׂרֵה. כְּמוֹ שֶׁהוֹדַֽעְתָּ לֶעָנָו מִקֶּֽדֶם. כְּמוֹ שֶׁכָּתוּב וַיֵּרֶד יְהֹוָה בֶּֽעָנָן וַיִּתְיַצֵּב עִמּוֹ שָׁם וַיִּקְרָא בְשֵׁם יְהֹוָה:<br>", "<small>קהל וחזן:</small><br>", "וַיַּֽעֲבֹר יְהֹוָה עַל פָּנָיו וַיִּקְרָא:<br>", "יְהֹוָה יְהֹוָה אֵל רַחוּם וְחַנּוּן אֶֽרֶךְ אַפַּֽיִם וְרַב חֶֽסֶד וֶֽאֱמֶת: נֹצֵר חֶֽסֶד לָאֲלָפִים נֹשֵׂא עָו‍ֹן וָפֶֽשַׁע וְחַטָּאָה וְנַקֵּה: וְסָלַחְתָּ לַעֲו‍ֹנֵֽנוּ וּלְחַטָּאתֵֽנוּ וּנְחַלְתָּֽנוּ:<br>", "סְלַח לָֽנוּ אָבִֽינוּ כִּי חָטָֽאנוּ. מְחַל לָֽנוּ מַלְכֵּֽנוּ כִּי פָשָֽׁעְנוּ: כִּי אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב חֶֽסֶד לְכָל קֹרְאֶֽיךָ:<br>", "הוֹשִׁיעָה יְהוָה כִּי־גָמַר חָסִיד כִּי־פַסּוּ אֱמוּנִים מִבְּנֵי אָדָם: אָבַד חָסִיד מִן־הָאָרֶץ וְיָשָׁר בָּאָדָם אָיִן: רְאֵה כִּי־אֵין אִישׁ וְהִשְׁתּוֹמֵם כִּי אֵין מַפְגִּיעַ: אַתָּה־הוּא מַלְכֵּנוּ אֱלֹהִים צַוֵּה יְשׁוּעוֹת יַעֲקֹב׃ יַחֵל יִשְׂרָאֵל אֶל־יְהוָה מֵעַתָּה וְעַד־עוֹלָם׃<br>", "<b>כְּרַחֵם אָב</b> עַל בָּנִים כֵּן תְּרַחֵם יְהֹוָה עָלֵֽינוּ: לַיהֹוָה הַיְשׁוּעָה, עַל עַמְּךָ בִרְכָתֶֽךָ סֶּֽלָה: יְהֹוָה צְבָאוֹת עִמָּֽנוּ מִשְׂגָּב לָֽנוּ, אֱלֹהֵי יַעֲקֹב סֶֽלָה: יְהֹוָה צְבָאוֹת, אַשְׁרֵי אָדָם בֹּֽטֵֽחַ בָּךְ: יְהֹוָה הוֹשִֽׁיעָה, הַמֶּֽלֶךְ יַעֲנֵֽנוּ בְיוֹם קָרְאֵנוּ:<br>", "<small>קהל ואח\"כ חזן:</small><br>", "<b>סְלַח נָא</b> לַעֲו‍ֹן הָעָם הַזֶּה, כְּגֹֽדֶל חַסְדֶּֽךָ. וְכַאֲשֶׁר נָשָֽׂאתָה לָעָם הַזֶּה. מִמִּצְרַֽיִם וְעַד הֵֽנָּה. וְשָׁם נֶאֱמַר:<br>", "<small>הקהל אומרים:</small><br>", "<b>וַיֹּאמֶר יְהֹוָה סָלַֽחְתִּי כִּדְבָרֶֽךָ:</b><br>", "הַטֵּה אֱלֹהַי אָזְנְךָ וּשְׁמָע, פְּקַח עֵינֶֽיךָ וּרְאֵה שֹׁמְמֹתֵֽינוּ, וְהָעִיר אֲשֶׁר נִקְרָא שִׁמְךָ עָלֶֽיהָ כִּי לֹא עַל צִדְקֹתֵֽינוּ, אֲנַֽחְנוּ מַפִּילִים תַּחֲנוּנֵֽינוּ לְפָנֶֽיךָ, כִּי עַל רַחֲמֶֽיךָ הָרַבִּים: אֲדֹנָי שְׁמָֽעָה, אֲדֹנָי סְלָֽחָה, אֲדֹנָי הַקְשִֽׁיבָה וַעֲשֵׂה, אַל תְּאַחַר. לְמַעַנְךָ אֱלֹהַי, כִּי שִׁמְךָ נִקְרָא עַל עִירְךָ וְעַל עַמֶּֽךָ:<br>"]}, "esther": {"ref": "Siddur Ashkenaz, Festivals, Selichot, Fast of Esther", "he": "סליחות לתענית אסתר", "nusach": "סידור אשכנז (דעת)", "version": "Daat Siddur Ashkenaz", "source": "http://www.daat.ac.il/daat/sidurim/tohen3.htm", "url": "https://www.sefaria.org/Siddur_Ashkenaz%2C_Festivals%2C_Selichot%2C_Fast_of_Esther", "segs": ["סְלַח לָנוּ אָבִינוּ כִּי בְּרוֹב אִוַּלְתֵּנוּ שָׁגִינוּ מְחַל לָנוּ מַלְכֵּנוּ כִּי רַבּוּ עֲוֹנֵינוּ:", "אֵל אֶרֶךְ אַפַּיִם אַתָּה וּבַעַל הָרַחֲמִים נִקְרֵאתָ. וְדֶרֶךְ תְּשׁוּבָה הוֹרֵיתָ. גְּדֻלַּת רַחֲמֶיךָ וַחֲסָדֶיךָ תִּזְכֹּר הַיּוֹם וּבְכָל יוֹם לְזֶרַע יְדִידֶיךָ. תֵּפֶן אֵלֵינוּ בְּרַחֲמִים כִּי אַתָּה הוּא בַּעַל הָרַחֲמִים. בְּתַחֲנוּן וּבִתְפִלָּה פָּנֶיךָ נְקַדֵּם. כְּהוֹדַעְתָּ לֶעָנָיו מִקֶּדֶם. מֵחֲרוֹן אַפְּךָ שׁוּב כְּמוֹ בְּתוֹרָתְךָ כָּתוּב. וּבְצֵל כְּנָפֶיךָ נֶחֱסֶה וְנִתְלוֹנָן כְּיוֹם וַיֵּרֶד יְהֹוָה בֶּעָנָן. תַּעֲבֹר עַל פֶּשַׁע וְתִמְחֶה אָשָׁם. כְּיוֹם וַיִּתְיַצֵּב עִמּוֹ שָׁם. תַּאֲזִין שַׁוְעָתֵנוּ וְתַקְשִׁיב מֶנּוּ מַאֲמַר. כְּיוֹם וַיִּקְרָא בְשֵׁם יְהֹוָה וְשָׁם נֶאֱמַר:", "וַיַּעֲבֹר יְהֹוָה עַל פָּנָיו וַיִּקְרָא:", "יְהֹוָה, יְהֹוָה, אֵל, רַחוּם, וְחַנּוּן, אֶרֶךְ אַפַּיִם, וְרַב חֶסֶד, וֶאֱמֶת: נֹצֵר חֶסֶד לָאֲלָפִים, נֹשֵׂא עָוֹן, וָפֶשַׁע, וְחַטָּאָה, וְנַקֵּה: וְסָלַחְתָּ לַעֲוֹנֵנוּ וּלְחַטָּאתֵנוּ וּנְחַלְתָּנוּ: סְלַח לָנוּ אָבִינוּ כִּי חָטָאנוּ מְחַל לָנוּ מַלְכֵּנוּ כִּי פָשָׁעְנוּ: כִּי אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב חֶסֶד לְכָל קֹרְאֶיךָ:", "קַוֹּה קִוִּינוּ אֶל יְהֹוָה וַיֵּט אֵלֵינוּ וַיּשְׁמַע שַׁוְעָתֵנוּ: אַף אֹרַח מִשְׁפָּטֶיךָ יְהֹוָה קִוִּינוּךָ לְשִׁמְךָ וּלְזִכְרְךָ תַּאֲוַת נָפֶשׁ:", "כְּרַחֵם אָב עַל בָּנִים כֵּן תְּרַחֵם יְהֹוָה עָלֵינוּ: לַיהֹוָה הַיְשׁוּעָה עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה: יְהֹוָה צְבָאוֹת עִמָּנוּ מִשְׂגָּב לָנוּ אֱלֹהֵי יַעֲקֹב סֶלָה: יְהֹוָה צְבָאוֹת אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ: יְהֹוָה הוֹשִׁיעָה הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ:", "<small>חזן</small> –", "סְלַח נָא לַעֲוֹן הָעָם הַזֶּה כְּגֹדֶל חַסְדֶּךָ וְכַאֲשֶׁר נָשָׂאתָ לָעָם הַזֶּה מִמִּצְרַיִם וְעַד הֵנָּה וְשָׁם נֶאֱמַר:", "<small>קהל</small> –", "וַיֹּאמֶר יְהֹוָה סָלַחְתִּי כִּדְבָרֶךָ:", "הַטֵּה אֱלֹהַי אָזְנְךָ וּשְׁמָע פְּקַח עֵינֶיךָ וּרְאֵה שׁוֹמְמוֹתֵינוּ וְהָעִיר אֲשֶׁר נִקְרָא שִׁמְךָ עָלֶיהָ כִּי לֹא עַל צִדְקוֹתֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵינוּ לְפָנֶיךָ כִּי עַל רַחֲמֶיךָ הָרַבִּים: אֲדֹנָי שְׁמָעָה אֲדֹנָי סְלָחָה אֲדֹנָי הַקְשִׁיבָה וַעֲשֵׂה אַל תְּאַחַר לְמַעַנְךָ אֱלֹהַי כִּי שִׁמְךָ נִקְרָא עַל עִירְךָ וְעַל עַמֶּךָ:", "סליחה מיוסד ע\"פ א\"ב ובסוף חתום שם המחבר מנחם ברבי מכיר יחיה אמן ואמן:", "אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אָדָם בְּקוּם עָלֵינוּ חִיל אֲחָזַתְנוּ לִרְעוֹד. בְּהִסְתַּפְּחוֹ לְמַלְכוּת חָנֵף כִּמְעַט כָּשַׁלְנוּ לִמְעוֹד. גָּמְרוּ לְמָכְרֵנוּ כְּתֵל וְחָרִיץ בְּלִי מִסְעוֹד. אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי וְלֹא יִזָּכֵר שֵׁם יִשְׂרָאֵל עוֹד: דַּלּוּ עֵינַי לַמָּרוֹם קְרָאתִיךָ אוֹיְבַי לָקוֹב. הַכְרֵת שֵׁם וּשְׁאָר וּמְחֵה שֵׁם לִרְקוֹב. וְצָר צוֹרְרַי בְּנִכְלֵיהֶם אֲשֶׁר נִכְּלוּ לַעֲקוֹב. וַיֹּאמְרוּ לֹא יִרְאֶה יָהּ וְלֹא יָבִין אֱלֹהֵי יַעֲקֹב: זְרוּיִם עִנָּה וַיַּגֶּה וְלֹא מִלֵּב לְכַלּוֹתָם. חָבוּ לְפָנִים וְרִדָּם בַּהֲסָרַת טַבַּעַת לְהַחֲלוֹתָם. טוֹב דְּבָרוֹ הֵקִים לְעֵינֵי הַגּוֹיִם לְהַעֲלוֹתָם. בְּאֶרֶץ אוֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלּוֹתָם: יִדַּע רֶמֶז הַקּוֹרוֹת לְעַם מְעֻפָּר וּמְהֻדָּס. כְּתָב הַסְתֵּר אַסְתִּיר וּמָר דְּרוֹר מְפֻרְדָּס. לִשְׁבּוֹת הָמָן מִמָּחֳרָת הֲמִן הָעֵץ קֻנְדָּס. תַּחַת הַנַּעֲצוּץ יַעֲלֶה בְרוֹשׁ וְתַחַת הַסִּרְפָּד יַעֲלֶה הֲדָס: מַקְשִׁיב דְבַר שֶׁקֶר כָּתַב שִׂטְנָה וָעֶצֶב. נִתְעַטֵּף בְּבִגְדֵי שְׂרָד כְּטָעָה בְּמִנְיַן קֶצֶב. סָדַּר לְהִשְׁתַּמֵּשׁ בְּשׁוֹנִים כְּלֵי בֵּית הַמַּחֲצֵב. וַיָּבֹא גַם הַשָּׂטָן בְּתוֹכָם לְהִתְיַצֵּב: עַם הַנִּמְצָאִים בְּשׁוּשָׁן בְּאָכְלָם מִזֶּבַח עָכְרָם. פָּעַר פִּיו לְהַשְׂטִינָם וּלְהַסְגִּירָם בְּיַד נוֹתֵן מִכְרָם. צוּר הִסְכִּים לִכְתּוֹב אִגֶּרֶת לְאַבֵּד שִׂבְרָם. אָמַרְתִּי אַפְאֵיהֶם אַשְׁבִּיתָה מֵאֱנוֹשׁ זִכְרָם: קְדוֹשִׁים מַלְאֲכֵי הַשָׁרֵת מַר יִבְכָּיוּן בִּצְעָקָה. רַחוּם הַבֵּט לַבְּרִית וְאַל תָּפֵר לְהַרְחִיקָה. שָׁמְעָה מוֹרָשָׁה וַתִּלְבַּשׁ בִּגְדֵי אַלְמְנוּת וּמוּעָקָה. וַתָּשֶׂם יָדָהּ עַל רֹאשָׁהּ וַתֵּלֶךְ הָלוֹךְ וּזְעָקָה: תִּשְׁבִּי שָׂם אֵזוֹר שַׂק בְּמָתְנָיו תַּחְבֹּשֶׁת. מִהֵר וְהוֹדִיעַ יְשֵׁנֵי מַכְפֵּל אָבוֹת שְׁלֹשֶׁת. נָחַץ לְרוֹעֶה מַה לְּךָ נִרְדָּם לְהִתְעַשֵּׁת. קוּם קְרָא אֶל אֱלֹהֶיךָ אוּלַי יִתְעַשֵּׁת: חוֹתַם טִיט אֲשֶׁר נַעֲשָׂה לְבִלְשָׁן סִפֵּר. מִנִּינְוֵה לָמְדוּ לְאַחַר גְּזֵרָה כַּעַס לְהָפֵר. בֶּן קִישׁ הִקִּישׁ דַּלְתוֹת בֵּית הַסֵּפֶר. וַיְּכַס שַׂק וַיֵּשֶׁב עַל הָאֵפֶר: רִבֵּץ תִּינוֹקוֹת לְפָנָיו יָמִים שְׁלֹשָׁה צָמִים וּמֻכְפָּנִים. בְּקוֹל יַעֲקֹב לַחֲלוֹשׁ יְדֵי עַז פָּנִים. יָדָיו אֱמוּנָה לָאֵל הַצִּילֵנִי מֵעֶלְבּוֹנִים. פֶּן יָבוֹא וְהִכַּנִי אֵם עַל בָּנִים: מִזֶּה אֵלֶּה וּמִזֶּה אֵלֶּה בְּנֵי אֵיתָנַי וְרַבָּנַי. כֻּלָּם צָעֲקוּ וַתַּעַל שַׁוְעָתָם אֶל יְהֹוָה. יָהּ לְקוֹל רִנּוּן כְּבוֹא שָׁאַל לִפְנָי. וּמֶה קוֹל הַצֹּאן הַזֶּה בְּאָזְנָי: רוֹעֶה הֱשִׁיבוֹ הֵם קְטַנֵּי קֹדֶשׁ זֶרַע. יָהּ הַצֵּל לְקוּחִים לַמָּוֶת מֵאוֹיֵב הָרַע. חַנּוּן נִכְמְרוּ רַחֲמָיו וַיְּבַקֵּשׁ לִבְכּוֹת הַמְּאֹרָע. וַיְּהִי כִּקְרוֹא מֶלֶךְ יִשְׂרָאֵל אֶת הַסֵּפֶר וַיִּקְרָע: יְהוּדִי הוֹקִיעַ יְלָדָיו לְמַטָּה וַאֲבִיהֶם מִלְמַעְלָה. אִישׁ אִישׁ בְּשָׁלֹשׁ אַמּוֹת וְהָרְבִיעִית אַוֵּיר מְגֻלָּה. מִשְׁנֶה נָקָם חָזָה וְשָׂמַח וְשָׂח תְּהִלָּה. אוֹתִי הֵשִׁיב עַל כַּנִּי וְאוֹתוֹ תָלָה: וַתִּכְתּוֹב אֶסְתֵּר תּוֹקֶף לִקְרוֹת כִּבְהַלֵּל מְהוֹדִים. מִלְּמַעְלָה קִיְּמוּ מַה שֶּׁקִּבְּלוּ לְמַטָּה דּוֹדִים. נֵס יְנוֹסֵס לְפַרְסֵם כְּאָז פִּלְאוֹ מַסְהִידִים. בָּעֵת הַזֹּאת רֶוַח וְהַצָּלָה יַעֲמוֹד לַיְּהוּדִים:", "אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים מִתְנַהֵג בַּחֲסִידוּת, מוֹחֵל עֲוֹנוֹת עַמּוֹ מַעֲבִיר רִאשׁוֹן רִאשׁוֹן, מַרְבֶּה מְחִילָה לְחַטָּאִים וּסְלִיחָה לַפּוֹשְׁעִים, עֹשֶׂה צְדָקוֹת עִם כָּל בָּשָׂר וָרוּחַ, לֹא כְרָעָתָם תִּגְמוֹל, אֵל הוֹרֵיתָ לָּנוּ לוֹמַר שְׁלֹשׁ עֶשְׂרֵה, וּזְכָר לָנוּ הַיּוֹם בְּרִית שְׁלשׁ עֶשְׂרֵה, כְּהוֹדַעְתָּ לֶעָנָיו מִקֶּדֶם, כְּמוֹ שֶׁכָּתוּב וַיֵּרֶד יְהֹוָה בֶּעָנָן וַיִּתְיַצֵּב עִמּוֹ שָׁם, וַיִּקְרָא בְשֵׁם יְהֹוָה:", "וַיַּעֲבוֹר יְהֹוָה עַל פָּנָיו וַיִּקְרָא:", "יְהֹוָה יְהֹוָה אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת: נֹצֵר חֶסֶד לָאֲלָפִים נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה וְנַקֵּה: וְסָלַחְתָּ לַעֲוֹנֵנוּ וּלְחַטָּאתֵנוּ וּנְחַלְתָּנוּ: סְלַח לָנוּ אָבִינוּ כִּי חָטָאנוּ מְחַל לָנוּ מַלְכֵּנוּ כִּי פָשָׁעְנוּ: כִּי אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב חֶסֶד לְכָל קֹרְאֶיךָ:", "כִּי עִמְּךָ מְקוֹר חַיִּים בְּאוֹרְךָ נִרְאֶה אוֹר: בְּקָרְאֵנוּ עֲנֵנוּ אֱלֹהֵי יִשְׁעֵנוּ בַּצָּר הִרְחַבְתָּ לָנוּ חָנֵּנוּ וּשְׁמַע תְּפִלָּתֵנוּ: וְעַתָּה יִגְדַּל נָא כֹּחַ אֲדֹנָי כַּאֲשֶׁר דִּבַּרְתָּ לֵאמֹר:", "כְּרַחֵם אָב עַל בָּנִים כֵּן תְּרַחֵם יְהֹוָה עָלֵינוּ: לַיהֹוָה הַיְשׁוּעָה עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה: יְהֹוָה צְבָאוֹת עִמָּנוּ מִשְׂגָּב לָנוּ אֱלֹהֵי יַעֲקֹב סֶלָה: יְהֹוָה צְבָאוֹת אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ: יְהֹוָה הוֹשִׁיעָה הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ:", "סליחה מיוסד ע\"פ א\"ב ובסוף חתום שם המחבר שמעון בר יצחק:", "אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ", "אַתָּה הָאֵל עוֹשֵׂה פְלָאוֹת. בָּעַמִּים הוֹדַעְתָּ עוֹז נוֹרָאוֹת. גָאַלְתָּ בִּזְרוֹעַ עַמְּךָ מִתְּלָאוֹת. דִּכִּיתָ צָרֵיהֶם בְּמוֹתֵי תַחֲלוּאוֹת: הָאוֹיֵב בְּקוּמוֹ לְעוֹרֵר מְדָנִים. וְדִמָּה לְהַכְרִית פִּרְחֵי עֲדָנִים. זָמַם לִשְׁקוֹל לְגִנְזֵי אֲדוֹנִים. חֲלִיפֵי מְאַת כִּכְּרֵי אֲדָנִים: טְלָאֶיךָ הִזְהַרְתָּ שִׁקְלֵיהֶם לְהַקְדִּים. יָדַעְתָּ הָעֲתִידוֹת וְדָרַשְׁתָּ נִשְׁקָדִים. כִּבּוּי לְהַמְצִיא לְלַהַב יוֹקְדִים. לְקוּחִים לַמָּוֶת לְתֶחִי נִפְקָדִים: מַסֵּכָה צָרָה בְּעָבְדָם לְפָנִים. נִמְסְרוּ לְהָתֵז קְנוֹקְנוֹת וּגְפָנִים. סְבָבוּם מוֹקְשִׁים בְּכָל דְּפָנִים. עֵינֵיהֶם לְךָ תּוֹלִים וּבְסִתְרְךָ נִצְפָּנִים: פּוּר נֶהְפַּךְ בְּאוֹיְבִים לִשְׁלוֹט. צְלִיבָה הוּכַן אֲגָגִי לִקְלוֹט. קַלַּע וּבַלַּע פְּנֵי הַלּוֹט הַלּוֹט. רִיבֵי עָם בְּאַשְׁמַנִּים לַעֲלוֹט: שָׁלוֹם וֶאֱמֶת נִכְתַּב לְכָל צַד. תּוֹקֶף יֶשַׁע סֶלַע וּמְצַד. שׁוֹדֵד הֻשְׁדַּד וּבְרִשְׁתּוֹ נוֹצַד. מְלָשְׁנִי נִסְחַף נִצְמַת וְנִרְצַד: עָשׂוּ שְׂמָחוֹת וְלַדּוֹרוֹת קְבָעוּם. וּמִקְרָאוֹת שִׁלְּשׁוּם וְלֹא רִבְּעוּם. נִסְכְּמוּ מִמַּעַל וּלְמַטָּה טִבְּעוּם. בַּסֵּפֶר נֶחֱקַק עַל מַה קְבָעוּם: רָמָה יָדְךָ לִסְלוֹחַ לַפּוֹשְׁעִים. יְהוּדִי וַהֲדַסָּה הֵקַמְתָּ מוֹשִׁיעִים. צִדְקָתָם עוֹמֶדֶת לָעַד לְשַׁעֲשׁוּעִים. חֵקֶר כְּבוֹדָם לְהִזָּכֵר לְנוֹשָׁעִים: קַנֵּא לְשִׁמְךָ נוֹרָא וְנִקְדָּשׁ. חֲזֵה כַרְמְךָ נֶהֱרַס וְנִדָּשׁ. זְרוּיֵינוּ קַבֵּץ וְשִׁיר לְךָ יְחֻדָּשׁ. קַיְּמֵם וְהַחֲיֵם בְּבִנְיַן בֵּית הַמִּקְדָּשׁ: וְכַעֲשׂוֹתְךָ נוֹרָאוֹת בְּאוֹתָן הַיָּמִים. אִתָּנוּ הַפְלֵא תְּשׁוּעַת עוֹלָמִים. מְצוֹא לְפָנֶיךָ כֹּפֶר וְתַנְחוּמִים. אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים:", "אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים מִתְנַהֵג בַּחֲסִידוּת, מוֹחֵל עֲוֹנוֹת עַמּוֹ מַעֲבִיר רִאשׁוֹן רִאשׁוֹן, מַרְבֶּה מְחִילָה לְחַטָּאִים וּסְלִיחָה לַפּוֹשְׁעִים, עֹשֶׂה צְדָקוֹת עִם כָּל בָּשָׂר וָרוּחַ, לֹא כְרָעָתָם תִּגְמוֹל, אֵל הוֹרֵיתָ לָּנוּ לוֹמַר שְׁלֹשׁ עֶשְׂרֵה, וּזְכָר לָנוּ הַיּוֹם בְּרִית שְׁלשׁ עֶשְׂרֵה, כְּהוֹדַעְתָּ לֶעָנָיו מִקֶּדֶם, כְּמוֹ שֶׁכָּתוּב וַיֵּרֶד יְהֹוָה בֶּעָנָן וַיִּתְיַצֵּב עִמּוֹ שָׁם, וַיִּקְרָא בְשֵׁם יְהֹוָה:", "וַיַּעֲבוֹר יְהֹוָה עַל פָּנָיו וַיִּקְרָא:", "יְהֹוָה יְהֹוָה אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת: נֹצֵר חֶסֶד לָאֲלָפִים נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה וְנַקֵּה: וְסָלַחְתָּ לַעֲוֹנֵנוּ וּלְחַטָּאתֵנוּ וּנְחַלְתָּנוּ: סְלַח לָנוּ אָבִינוּ כִּי חָטָאנוּ מְחַל לָנוּ מַלְכֵּנוּ כִּי פָשָׁעְנוּ: כִּי אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב חֶסֶד לְכָל קֹרְאֶיךָ:", "פזמון מיוסד ע\"פ תשר\"ק ובסוף חתום שם המחבר משלם:", "בִּמְתֵי מִסְפָּר חִלִּינוּ פָנֶיךָ. לְשַׁוְעַת נְכֵאִים אַל תַּעְלֵם אָזְנֶךָ. הַקְשֵׁב תְּחִנָּתָם מִשְּׁמֵי מְעוֹנֶךָ. כְּבִימֵי מוֹר וַהֲדַס הוֹשַׁעְתָּ בָנֶיךָ: תְּהִלּוֹת יִשְׂרָאֵל אַתָּה יוֹשֵׁב. שַׁוְעָתָם מַאֲזִין וְרִנָּתָם קוֹשֵׁב. רִפְאוּת לְמַחַץ מַקְדִּים וּמְחַשֵּׁב. קְנוּיֶיךָ לְהֵיטִיב וְנָוֵיהֶם לְיַשֵּׁב.", "במתי: צָר וְאוֹיֵב הִלְטִישׁ עֵינָיו. פִּיהוּ פָעַר לִשְׁאוֹף עָנָיו. עִשֵּׁת בְּשֶׁלּוֹ לְהַשְׁמִיד קְהַל הֲמוֹנָיו. סֶגֶל לְאַבֵּד חָרַת בְּנִשְׁתְּוָנָיו.", "במתי: נוֹקֵם לְצָרִים וְנוֹטֵר לְאוֹיְבִים. מָדַדְתָּ מִדָּתָם כְּזָדוּ לַאֲהוּבִים. לוֹחֵם וְנִינָיו הוּתְלוּ מֻצְלָבִים. כְּבַחֲרוֹזֶת דָּגִים חוֹרְזוּ תְּחוּבִים.", "במתי: יוֹם אֲשֶׁר שִׂבְּרוּ צוֹרְרִים. טִבְחָה לָשִׁית בְּעַם נְצוּרִים. חֻלְּפָה הַדָּת וְנָפְלוּ פְגָרִים. זֻלְעֲפוּ זוֹעֲמוּ מוּבָסִים מֻגָרִים.", "במתי: וּבְכֵן יִתְעַלֶּה שִׁמְךָ וְיִתְנַשֵּׂא. הוֹדְךָ שְׁמֵי שָׁמַיִם כִּסָּה. דַּכִּים בְּרוֹמִמְךָ נְתוּנִים לִמְשִׁסָּה. גֵּיא וַאֲפָסֶיהָ תְּהִלָּתְךָ מְכַסָּה.", "במתי: בִּינָה הֲגִינֵנוּ עַתָּה וּרְאֵה בַצָּר. בְּאַפְּךָ קוּמָה עַל צוֹרֵר הַצָּר. אָדוֹן קְרָאנוּךָ מִן הַמֵּצָר. אָנָּא הוֹצִיאֵנוּ לַמֶּרְחָב וְחַלְּצֵנוּ מִצָּר.", "במתי: מְאֹד תַּרְבֶּה לָנוּ מְחִילָה. שְׁמַע תְּפִלָּה וְהַעֲבֵר תִּפְלָה. לוֹחֲצֵינוּ יַשְׁלִימוּ אִתָּנוּ וַעֲוֹנוֹתֵינוּ תַשְׁלִיךְ בִּמְצוּלָה. מִמֶּנּוּ רַחֲמֶיךָ לֹא תִכְלָא", "במתי:", "אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים מִתְנַהֵג בַּחֲסִידוּת, מוֹחֵל עֲוֹנוֹת עַמּוֹ מַעֲבִיר רִאשׁוֹן רִאשׁוֹן, מַרְבֶּה מְחִילָה לְחַטָּאִים וּסְלִיחָה לַפּוֹשְׁעִים, עֹשֶׂה צְדָקוֹת עִם כָּל בָּשָׂר וָרוּחַ, לֹא כְרָעָתָם תִּגְמוֹל, אֵל הוֹרֵיתָ לָּנוּ לוֹמַר שְׁלֹשׁ עֶשְׂרֵה, וּזְכָר לָנוּ הַיּוֹם בְּרִית שְׁלשׁ עֶשְׂרֵה, כְּהוֹדַעְתָּ לֶעָנָיו מִקֶּדֶם, כְּמוֹ שֶׁכָּתוּב וַיֵּרֶד יְהֹוָה בֶּעָנָן וַיִּתְיַצֵּב עִמּוֹ שָׁם, וַיִּקְרָא בְשֵׁם יְהֹוָה:", "וַיַּעֲבוֹר יְהֹוָה עַל פָּנָיו וַיִּקְרָא:", "יְהֹוָה יְהֹוָה אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת: נֹצֵר חֶסֶד לָאֲלָפִים נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה וְנַקֵּה: וְסָלַחְתָּ לַעֲוֹנֵנוּ וּלְחַטָּאתֵנוּ וּנְחַלְתָּנוּ: סְלַח לָנוּ אָבִינוּ כִּי חָטָאנוּ מְחַל לָנוּ מַלְכֵּנוּ כִּי פָשָׁעְנוּ: כִּי אַתָּה אֲדֹנָי טוֹב וְסַלָּח וְרַב חֶסֶד לְכָל קֹרְאֶיךָ:", "זְכוֹר רַחֲמֶיךָ יְהֹוָה וַחֲסָדֶיךָ כִּי מֵעוֹלָם הֵמָּה: זָכְרֵנוּ יְהֹוָה בִּרְצוֹן עַמֶּךָ פָקְדֵנוּ בִּישׁוּעָתֶךָ: זְכוֹר עֲדָתְךָ קָנִיתָ קֶדֶם גָּאַלְתָּ שֵׁבֶט נַחֲלָתֶךָ הַר צִיּוֹן זֶה שָׁכַנְתָּ בּוֹ: זְכוֹר יְהֹוָה חִבַּת יְרוּשָׁלָיִם אַהֲבַת צִיּוֹן אַל תִּשְׁכַּח לָנֶצַח: אַתָּה תָקוּם תְּרַחֵם צִיּוֹן כִּי עֵת לְחֶנְנָהּ כִּי בָא מוֹעֵד: זְכוֹר יְהֹוָה לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלָיִם הָאוֹמְרִים עָרוּ עָרוּ עַד הַיְּסוֹד בָּהּ: זְכוֹר לְאַבְרָהָם לְיִצְחָק וּלְיִשְׂרָאֵל עֲבָדֶיךָ אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ וַתְּדַבֵּר אֲלֵהֶם אַרְבֶּה אֶת זַרְעֲכֶם כְּכוֹכְבֵי הַשָּׁמַיִם וְכָל הָאָרֶץ הַזֹּאת אֲשֶׁר אָמַרְתִּי אֶתֵּן לְזַרְעֲכֶם וְנָחֲלוּ לְעוֹלָם: זְכוֹר לַעֲבָדֶיךָ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְאֶל רִשְׁעוֹ וְאֶל חַטָּאתוֹ:", "זְכוֹר לָנוּ בְּרִית אָבוֹת כַּאֲשֶׁר אָמַרְתָּ וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכּוֹר וְהָאָרֶץ אֶזְכּוֹר:", "זְכוֹר לָנוּ בְּרִית רִאשׁוֹנִים כַּאֲשֶׁר אָמַרְתָּ וְזָכַרְתִּי לָהֶם בְּרִית רִאשׁוֹנִים אֲשֶׁר הוֹצֵאתִי אוֹתָם מֵאֶרֶץ מִצְרַיִם לְעֵינֵי הַגּוֹיִם לִהְיוֹת לָהֶם לֵאלֹהִים אֲנִי יְהֹוָה: עֲשֵׂה עִמָּנוּ כְּמָה שֶׁהִבְטַחְתָּנוּ וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלּוֹתָם לְהָפֵר בְּרִיתִי אִתָּם כִּי אֲנִי יְהֹוָה אֱלֹהֵיהֶם: הָשֵׁב שְׁבוּתֵנוּ וְרַחֲמֵנוּ כְּמָה שֶׁכָּתוּב וְשָׁב יְהֹוָה אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחֲמֶךָ וְשָׁב וְקִבֶּצְךָ מִכָּל הָעַמִּים אֲשֶׁר הֱפִיצְךָ יְהֹוָה אֱלֹהֶיךָ שָׁמָּה: קַבֵּץ נִדָּחֵינוּ כְּמָה שֶׁכָּתוּב אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךָ יְהֹוָה אֱלֹהֶיךָ וּמִשָּׁם יִקָּחֶךָ: מְחֵה פְשָׁעֵינוּ כָּעָב וְכֶעָנָן כְּמָה שֶׁכָּתוּב מָחִיתִי כָעָב פְּשָׁעֶיךָ וְכֶעָנָן חַטֹּאתֶיךָ שׁוּבָה אֵלַי כִּי גְאַלְתִּיךָ: מְחֵה פְשָׁעֵינוּ לְמַעַנְךָ כַּאֲשֶׁר אָמַרְתָּ אָנֹכִי אָנֹכִי הוּא מוֹחֶה פְשָׁעֶיךָ לְמַעֲנִי וְחַטֹּאתֶיךָ לֹא אֶזְכּוֹר: הַלְבֵּן חֲטָאֵינוּ כַּשֶּׁלֶג וְכַצֶּמֶר כְּמָה שֶׁכָּתוּב. לְכוּ נָא וְנִוָּכְחָה יֹאמַר יְהֹוָה אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. אִם יַאְדִּימוּ כַתּוֹלָע כַּצֶּמֶר יִהְיוּ: זְרוֹק עָלֵינוּ מַיִם טְהוֹרִים וְטַהֲרֵנוּ כְּמָה שֶׁכָּתוּב. וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם: רַחֵם עָלֵינוּ וְאַל תַּשְׁחִיתֵנוּ כְּמָה שֶׁכָּתוּב. כִּי אֵל רַחוּם יְהֹוָה אֱלֹהֶיךָ לֹא יַרְפְּךָ וְלֹא יַשְׁחִיתֶךָ וְלֹא יִשְׁכַּח אֶת בְּרִית אֲבֹתֶיךָ אֲשֶׁר נִשְׁבַּע לָהֶם: מוֹל אֶת לְבָבֵנוּ לְאַהֲבָה אֶת שְׁמֶךָ כְּמָה שֶׁכָּתוּב וּמָל יְהֹוָה אֱלֹהֶיךָ אֶת לְבָבְךָ וְאֶת לְבַב זַרְעֶךָ לְאַהֲבָה אֶת יְהֹוָה אֱלֹהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ לְמַעַן חַיֶּיךָ: הִמָּצֵא לָנוּ בְּבַקָּשָׁתֵנוּ כְּמָה שֶׁכָּתוּב וּבִקַּשְׁתֶּם מִשָּׁם אֶת יְהֹוָה אֱלֹהֶיךָ וּמָצָאתָ כִּי תִדְרְשֶׁנוּ בְּכָל לְבָבְךָ וּבְכָל נַפְשֶׁךָ: תְּבִיאֵנוּ אֶל הַר קָדְשֶׁךָ וְשַׂמְּחֵנוּ בְּבֵית תְּפִלָּתֶךָ כְּמָה שֶׁכָּתוּב וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי עוֹלוֹתֵיהֶם וְזִבְחֵיהֶם לְרָצוֹן עַל מִזְבְּחִי כִּי בֵיתִי בֵּית תְּפִלָּה יִקָּרֵא לְכָל הָעַמִּים:", "שְׁמַע קוֹלֵנוּ יְהֹוָה אֱלֹהֵינוּ חוּס וְרַחֵם עָלֵינוּ וְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן אֶת תְּפִלָּתֵנוּ: הֲשִׁיבֵנוּ יְהֹוָה אֵלֶיךָ וְנָשׁוּבָה חַדֵּשׁ יָמֵינוּ כְּקֶדֶם: אֲמָרֵינוּ הַאֲזִינָה יְהֹוָה בִּינָה הֲגִיגֵנוּ: יִהְיוּ לְרָצוֹן אִמְרֵי פִינוּ וְהֶגְיוֹן לִבֵּנוּ לְפָנֶיךָ יְהֹוָה צוּרֵנוּ וְגוֹאֲלֵנוּ: אַל תַּשְׁלִיכֵנוּ מִלְּפָנֶיךָ וְרוּחַ קָדְשְׁךָ אַל תִּקַּח מִמֶּנּוּ: אַל תַּשְׁלִיכֵנוּ לְעֵת זִקְנָה כִּכְלוֹת כֹּחֵנוּ אַל תַּעַזְבֵנוּ: אַל תַּעַזְבֵנוּ יְהֹוָה אֱלֹהֵינוּ, אַל תִּרְחַק מִמֶּנוּ: עֲשֵׂה עִמָּנוּ אוֹת לְטוֹבָה, וְיִרְאוּ שׂוֹנְאֵינוּ וְיֵבוֹשׁוּ כִּי אַתָּה יְהֹוָה עֲזַרְתָּנוּ וְנִחַמְתָּנוּ: כִּי לְךָ יְהֹוָה הוֹחָלְנוּ, אַתָּה תַעֲנֶה אֲדֹנָי אֱלֹהֵינוּ:", "אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. תָּבֹא לְפָנֶיךָ תְּפִלָּתֵנוּ וְאַל תִּתְעַלַּם מִתְּחִנָּתֵנוּ שֶׁאֵין אָנוּ עַזֵּי פָנִים וּקְשֵׁי עֹרֶף לוֹמַר לְפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ צַדִּיקִים אֲנַחְנוּ וְלֹא חָטָאנוּ אֲבָל אֲנַחְנוּ וַאֲבוֹתֵינוּ חָטָאנוּ:", "אָשַׁמְנוּ. בָּגַדְנוּ. גָּזַלְנוּ. דִּבַּרְנוּ דֹּפִי: הֶעֱוִינוּ. וְהִרְשַׁעְנוּ. זַדְנוּ. חָמַסְנוּ. טָפַלְנוּ שֶׁקֶר: יָעַצְנוּ רָע. כִּזַּבְנוּ. לַצְנוּ. מָרַדְנוּ. נִאַצְנוּ. סָרַרְנוּ. עָוִינוּ. פָּשַׁעְנוּ. צָרַרְנוּ. קִשִּׁינוּ עֹרֶף: רָשַׁעְנוּ. שִׁחַתְנוּ. תִּעַבְנוּ. תָּעִינוּ. תִּעְתָּעְנוּ:", "סַרְנוּ מִמִּצְוֹתֶיךָ וּמִמִּשְׁפָּטֶיךָ הַטּוֹבִים וְלֹא שָׁוָה לָנוּ: וְאַתָּה צַדִּיק עַל כָּל הַבָּא עָלֵינוּ כִּי אֱמֶת עָשִׂיתָ וַאֲנַחְנוּ הִרְשָׁעְנוּ: הִרְשַׁעְנוּ וּפָשַׁעְנוּ לָכֵן לֹא נוֹשָׁעְנוּ וְתֵן בְּלִבֵּנוּ לַעֲזוֹב דֶּרֶךְ רֶשַׁע וְחִישׁ לָנוּ יֶשַׁע: כַּכָּתוּב עַל יַד נְבִיאֶךָ יַעֲזוֹב רָשָׁע דַּרְכּוֹ וְאִישׁ אָוֶן מַחְשְׁבוֹתָיו וְיָשׁוֹב אֶל יְהֹוָה וִירַחֲמֵהוּ וְאֶל אֱלֹהֵינוּ כִּי יַרְבֶּה לִסְלוֹחַ: מְשִׁיחַ צִדְקֶךָ אָמַר לְפָנֶיךָ. שְׁגִיאוֹת מִי יָבִין מִנִּסְתָּרוֹת נַקֵּנִי:נַקֵּנוּ יְהֹוָה אֱלֹהֵינוּ מִכָּל פְּשָׁעֵינוּ וְטַהֲרֵנוּ מִכָּל טֻמְאוֹתֵינוּ וּזְרוֹק עָלֵינוּ מַיִם טְהוֹרִים וְטַהֲרֵנוּ כַּכָּתוּב עַל יַד נְבִיאֶךָ וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם: עַמְּךָ וְנַחֲלָתְךָ רְעֵבֵי טוּבְךָ צְמֵאֵי חַסְדֶּךָ תְּאֵבֵי יִשְׁעֶךָ. יַכִּירוּ וְיֵדְעוּ כִּי לַיהֹוָה אֱלֹהֵינוּ הָרַחֲמִים וְהַסְּלִיחוֹת:", "אֵל רַחוּם שְׁמֶךָ. אֵל חַנּוּן שְׁמֶךָ. בָּנוּ נִקְרָא שְׁמֶךָ. יְהֹוָה עֲשֵׂה לְמַעַן שְׁמֶךָ: עֲשֵׂה לְמַעַן אֲמִתֶּךָ. עֲשֵׂה לְמַעַן בְּרִיתֶךָ. עֲשֵׂה לְמַעַן גָּדְלְךָ וְתִפְאַרְתֶּךָ. עֲשֵׂה לְמַעַן דָּתֶךָ. עֲשֵׂה לְמַעַן הוֹדֶךָ. עֲשֵׂה לְמַעַן וִעוּדֶךָ. עֲשֵׂה לְמַעַן זִכְרֶךָ. עֲשֵׂה לְמַעַן חַסְדֶּךָ. עֲשֵׂה לְמַעַן טוּבֶךָ. עֲשֵׂה לְמַעַן יִחוּדֶךָ. עֲשֵׂה לְמַעַן כְּבוֹדֶךָ. עֲשֵׂה לְמַעַן לִמּוּדֶךָ. עֲשֵׂה לְמַעַן מַלְכוּתֶךָ. עֲשֵׂה לְמַעַן נִצְחֶךָ. עֲשֵׂה לְמַעַן סוֹדֶךָ. עֲשֵׂה לְמַעַן עֻזֶּךָ. עֲשֵׂה לְמַעַן פְּאֵרֶךָ. עֲשֵׂה לְמַעַן צִדְקָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָׁתֶךָ. עֲשֵׂה לְמַעַן רַחֲמֶיךָ הָרַבִּים. עֲשֵׂה לְמַעַן שְׁכִינָתֶךָ. עֲשֵׂה לְמַעַן תְּהִלָּתֶךָ. עֲשֵׂה לְמַעַן אוֹהֲבֶיךָ שׁוֹכְנֵי עָפָר. עֲשֵׂה לְמַעַן אַבְרָהָם יִצְחָק וְיַעֲקֹב. עֲשֵׂה לְמַעַן מֹשֶׁה וְאַהֲרֹן. עֲשֵׂה לְמַעַן דָּוִד וּשְׁלֹמֹה. עֲשֵׂה לְמַעַן יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ. עֲשֵׂה לְמַעַן צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ. עֲשֵׂה לְמַעַן שִׁמְמוֹת הֵיכָלֶךָ. עֲשֵׂה לְמַעַן הֲרִיסוּת מִזְבְּחֶךָ. עֲשֵׂה לְמַעַן הֲרוּגִים עַל שֵׁם קָדְשֶׁךָ. עֲשֵׂה לְמַעַן טְבוּחִים עַל יִחוּדֶךָ. עֲשֵׂה לְמַעַן בָּאֵי בָאֵשׁ וּבַמַּיִם עַל קִדּוּשׁ שְׁמֶךָ. עֲשֵׂה לְמַעַן יוֹנְקֵי שָׁדַיִם שֶׁלֹּא חָטְאוּ. עֲשֵׂה לְמַעַן גְּמוּלֵי חָלָב שֶׁלֹּא פָּשְׁעוּ. עֲשֵׂה לְמַעַן תִּינוֹקוֹת שֶׁל בֵּית רַבָּן. עֲשֵׂה לְמַעַנְךָ אִם לֹא לְמַעֲנֵנוּ. עֲשֵׂה לְמַעַנְךָ וְהוֹשִׁיעֵנוּ:", "עֲנֵנוּ יְהֹוָה עֲנֵנוּ. עֲנֵנוּ אֱלֹהֵינוּ עֲנֵנוּ. עֲנֵנוּ אָבִינוּ עֲנֵנוּ. עֲנֵנוּ בּוֹרְאֵנוּ עֲנֵנוּ. עֲנֵנוּ גּוֹאֲלֵנוּ עֲנֵנוּ. עֲנֵנוּ דּוֹרְשֵׁנוּ עֲנֵנוּ. עֲנֵנוּ הָאֵל הַנֶּאֱמָן עֲנֵנוּ. עֲנֵנוּ וָתִיק וְחָסִיד עֲנֵנוּ. עֲנֵנוּ זַךְ וְיָשָׁר עֲנֵנוּ. עֲנֵנוּ חַי וְקַיָּם עֲנֵנוּ. עֲנֵנוּ טוֹב וּמֵטִיב עֲנֵנוּ. עֲנֵנוּ יוֹדֵעַ יֶצֶר עֲנֵנוּ. עֲנֵנוּ כּוֹבֵשׁ כְּעָסִים עֲנֵנוּ. עֲנֵנוּ לוֹבֵשׁ צְדָקוֹת עֲנֵנוּ. עֲנֵנוּ מֶלֶךְ מַלְכֵי הַמְּלָכִים עֲנֵנוּ. עֲנֵנוּ נוֹרָא וְנִשְׂגָּב עֲנֵנוּ. עֲנֵנוּ סוֹלֵחַ וּמוֹחֵל עֲנֵנוּ. עֲנֵנוּ עוֹנֶה בְּעֵת צָרָה עֲנֵנוּ. עֲנֵנוּ פּוֹדֶה וּמַצִּיל עֲנֵנוּ. עֲנֵנוּ צַדִּיק וְיָשָׁר עֲנֵנוּ. עֲנֵנוּ קָרוֹב לְקוֹרְאָיו עֲנֵנוּ. עֲנֵנוּ רַחוּם וְחַנוּן עֲנֵנוּ. עֲנֵנוּ שׁוֹמֵעַ אֶל אֶבְיוֹנִים עֲנֵנוּ. עֲנֵנוּ תּוֹמֵךְ תְּמִימִים עֲנֵנוּ. עֲנֵנוּ אֱלֹהֵי אֲבוֹתֵינוּ עֲנֵנוּ. עֲנֵנוּ אֱלֹהֵי אַבְרָהָם עֲנֵנוּ. עֲנֵנוּ פַּחַד יִצְחָק עֲנֵנוּ. עֲנֵנוּ אֲבִיר יַעֲקֹב עֲנֵנוּ. עֲנֵנוּ עֶזְרַת הַשְּׁבָטִים עֲנֵנוּ. עֲנֵנוּ מִשְׂגַּב אִמָּהוֹת עֲנֵנוּ. עֲנֵנוּ קָשֶׁה לִכְעוֹס עֲנֵנוּ. עֲנֵנוּ רַךְ לִרְצוֹת עֲנֵנוּ. עֲנֵנוּ עוֹנֶה בְּעֵת רָצוֹן עֲנֵנוּ. עֲנֵנוּ אֲבִי יְתוֹמִים עֲנֵנוּ. עֲנֵנוּ דַּיַּן אַלְמָנוֹת עֲנֵנוּ:", "מִי שֶׁעָנָה לְאַבְרָהָם אָבִינוּ בְּהַר הַמּוֹרִיָּה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְיִצְחָק בְּנוֹ כְּשֶׁנֶּעֱקַד עַל גַּבֵּי הַמִּזְבֵּחַ הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְיַעֲקֹב בְּבֵית אֵל הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְיוֹסֵף בְּבֵית הָאֲסוּרִים הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לַאֲבוֹתֵינוּ עַל יַם סוּף הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְמֹשֶׁה בְּחוֹרֵב הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְאַהֲרֹן בַּמַּחְתָּה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְפִינְחָס בְּקוּמוֹ מִתּוֹךְ הָעֵדָה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לִיהוֹשֻׁעַ בַּגִּלְגָּל הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לִשְׁמוּאֵל בַּמִּצְפָּה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְדָוִד וּשְׁלֹמֹה בְנוֹ בִּירוּשָׁלָיִם הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְאֵלִיָּהוּ בְּהַר הַכַּרְמֶל הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לֶאֱלִישָׁע בִּירִיחוֹ הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְיוֹנָה בִּמְעֵי הַדָּגָה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה בְּחָלְיוֹ הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לַחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה בְּתוֹךְ כִּבְשַׁן הָאֵשׁ הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְדָנִיאֵל בְּגוֹב הָאֲרָיוֹת הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְמָרְדְּכַי וְאֶסְתֵּר בְּשׁוּשַׁן הַבִּירָה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְעֶזְרָא בַּגּוֹלָה הוּא יַעֲנֵנוּ. מִי שֶׁעָנָה לְכָל הַצַּדִּיקִים וְהַחֲסִידִים וְהַתְּמִימִים וְהַיְּשָׁרִים הוּא יַעֲנֵנוּ:", "רַחֲמָנָא דְעָנֵי לַעֲנִיֵי עֲנֵינָא. רַחֲמָנָא דְעָנֵי לִתְבִירֵי לִבָּא עֲנֵינָן. רַחֲמָנָא דְעָנֵי לְמַכִּיכֵי רוּחָא עֲנֵינָן. רַחֲמָנָא עֲנֵינָן. רַחֲמָנָא חוּס. רַחֲמָנָא פְּרוֹק. רַחֲמָנָא שְׁזִיב. רַחֲמָנָא רְחַם עֲלָן. הַשְׁתָּא בַּעֲגָלָא וּבִזְמַן קָרִיב:"]}, "hachodesh": {"ref": "Siddur Sefard, Yotzerot, Parashat HaChodesh", "he": "יוצר לפרשת החודש", "nusach": "סידור ספרד (תורת אמת)", "version": "Torat Emet 357", "source": "http://www.toratemetfreeware.com/index.html?downloads", "url": "https://www.sefaria.org/Siddur_Sefard%2C_Yotzerot%2C_Parashat_HaChodesh", "segs": ["<b><b><big><b>יוצר לפרשת החודש</b></big></b></b>", "<b>אֲדֹנָי</b> שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי אַבְרָהָם. אֱלֹהֵי יִצְחָק. וֵאלֹהֵי יַעֲקֹב. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן. גּוֹמֵל חֲסָדִים טוֹבִים. קוֹנֵה הַכֹּל. וְזוֹכֵר חַסְדֵי אָבוֹת. וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה: מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן:", "<b>מִסּוֹד</b> חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בְּשִׁיר וּרְנָנִים. לְהוֹדוֹת וּלְהַלֵּל פְּנֵי שׁוֹכֵן מְעוֹנִים:", "<b>אֲתִיַת</b> עֵת דּוֹדִים כְּגָעָה. בְּאַחַת וָעֶשֶׂר פּוּט נֻגָּעָה. גִּישַׁת צְקוֹן מַכְפֵּל כְּפָגְעָה. דִּלֵּג פַּעַם וְזֹאת רָגְעָה: הִשְׁגִּיחַ עוֹפֶר מֵחֶרֶךְ אֲרֻבּוֹת. וְחִתֵּל אֶרֶךְ בְּתֵבֶס תַּעֲרוּבוֹת. זְמַן קָפַץ עֲשׂוֹת רַבּוֹת. חֲדָשִׁים וְגַם יְשָׁנִים לְהַרְבּוֹת: טָס וַיֵּדֶא וְעִדָּן שִׁנָּה. יָקֵץ כְּיָשֵׁן וְעָר כְּמִשֵּׁנָה:", "<b><b><small>חזן:</small> <b>כָּסַף</b> וְדָפַק בְּפִתְחֵי יְשֵׁנָה. לְחַפְּשָׁהּ בָּרִאשׁוֹן לְחָדְשֵׁי הַשָּׁנָה: <b>לִי</b> עוֹד תִּגְנוֹן. בְּפָסוֹחַ וְגָנוֹן: </b></b>", "<b><b><small>חזן:</small> <b>בְּגוֹנְנָךְ</b> לְבָנוֹן. בְּמָגִנַּת יִנּוֹן:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה. מָגֵן אַבְרָהָם: אַתָּה גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מַשִׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם:", "<b>מְכַלְכֵּל</b> חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה: וְנֶאֱמָן אַתָּה לְהַחֲיוֹת מֵתִים:", "<b>מְרִימֵי</b> עוֹל עֶגְלָה לְהַלְאוֹת. מִכְּאֵב הַגְתָּ לְהַרְאוֹת אוֹת. נְאָקָה הָחִישָׁה קֵץ הַפְּלָאוֹת. נִחֲצוּ לְמָאתַיִם וְעֶשֶׂר אַרְבַּע מֵאוֹת: שֶׂה הַמְּסֻבָּךְ לְעֵקֶד צוּר. סֻיַּם זִכְרוֹ בְּפֶקֶד נָצוּר. עֲמוּסִים כְּאָתָיוּ לְעֵת בִּצּוּר. עָדֵימוֹ לְשַׁי יְהֵא עָצוּר: פֶּלֶא עֲשׂוֹת נֶגֶד אָבוֹת. פָּץ מִבֶּעָשׂוֹר לְאָסְרוֹ בֶּעָבוֹת:", "<b><b><small>חזן:</small> <b>צְלִיחַת</b> יַרְדֵּן בּוֹ לְהַתְווֹת. צְפִיַּת שֶׂה לְבֵית אָבוֹת:</b></b>", "<b>לְךָ</b> עוֹד נַקְשִׁיבָה. מִמַּעַיְנֵי הַיְשׁוּעָה נִשְׁאֲבָה:", "<b><b><small>חזן:</small> <b>שְׂשׂוֹן</b> יִשְׁעֲךָ לָנוּ הָשִׁיבָה. וּבִתְחִיַּת גֶּשֶׁם נֵחָשֵׁבָה:</b></b>", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<b>קִיחַת</b> עֲלָיַת עֶקֶד. הִיא נִצְּבָה בְּפֶקֶד. תְּוִיכַת בִּתְרֵי שָׁקַד. רִשְׁפֵּי לוּד לְיַקֵּד: רַחַשׁ יְשֵׁנִים כְּעָרַב. דַּם תְּבוּסָה כְּעֵרַב. קֵץ חָשׁ וְקָרַב. לְעוֹרֵר בְּתַנִּין קְרָב: שֵׁמַע מִכְסַת פְּסָחִים. אֲשֶׁר כָּסוּ פְסוּחִים. הִיא צִמְּתָה כַּסְלוּחִים. לְהַצִּיתָם כְּקוֹצִים כְּסוּחִים: תְּרָפִים כְּדֵי לַמְעַט. מְנוּיֵי מְתֵי מְעַט:", "<b><b><small>חזן:</small> <b>תּוֹקֶף</b> הַדְרַת מֶלֶךְ מִלְהִמָּעֵט. הוּרְשַׁם לְהִמָּנוֹת בִּוְאִם יִמְעַט:</b></b>", "<b>הַחוֹדֶשׁ</b> הַזֶּה לָכֶם לִשְׁמוֹר. בְּסֶכֶם אֲסוּפֵי הַר מוֹר. וְאִתָּם אֵל יִגְמוֹר. שְׁלֹשֶׁת אוֹתוֹת בּוֹ לִשְׁמוֹר: דּוֹרֵשׁ זֶה חוֹדֶשׁ בְּחָדְשׁוֹ. לְאוֹת וּלְמוֹפֵת קִדְשׁוֹ:", "<b><b><small>חזן:</small> <b>יְדִידֵי</b> עַם קְדוֹשׁוֹ. הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ:</b></b>", "<b>הֲדוֹם</b> מִגֵּר נְזִיד עֶדֶשׁ. כְּהַיוֹם הַזֶּה יְחֻדַשׁ בַּגוֹדֶשׁ:", "<b><b><small>חזן:</small> <b>וְנוֹבִיל</b> שַׁי בַּקּוֹדֶשׁ. בָּרִאשׁוֹן בְּאֶחָד לַחוֹדֶשׁ:</b></b>", "<b><b><small>חו\"ק:</small> <b>יִמְלוֹךְ</b> יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ: וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל אֵל נָא:</b></b>", "<b>רַבּוֹת</b> עָשִׂיתָ וְחָשַּׁבְתָּ וְסָפַרְתָּ. מִפְעֲלוֹתֶיךָ פְּעוֹל בְּסַהַר סָפַרְתָּ. לְאוֹתוֹת וּלְמוֹעֲדִים חֶבְלוֹ שִׁפַּרְתָּ. לִתְקוּפוֹת וּמַחֲזוֹרוֹת קִצּוֹ צָפַרְתָּ. לְאַלְפַּיִם וְאַרְבַּע מֵאוֹת וְאַרְבָּעִים וּשְׁמוֹנָה זְמַנוֹ בֵּאַרְתָּ. וּבִתְשַׁע מֵאוֹת עִבּוּרִים עָדָיו עִבַּרְתָּ. וְהַיּוֹם הוֹרֵיתָ לְעַם אֲשֶׁר בָּחַרְתָּ. לָכֵן עַל כָּל חֹדֶשׁ חָדְשׁוֹ הִגְבַּרְתָּ. סִפְרוֹ בִּקַּרְתָּ. קִצְבוֹ חָקַרְתָּ. נִזְלוֹ הֵקַרְתָּ. פִּלְאוֹ סָקַרְתָּ. מוֹעֲדוֹ יָקַרְתָּ. וּבוֹ יָקַרְתָּ וְנִתְיַקַּרְתָּ:", "<b><b><small>חו\"ק:</small> <b>חַי</b> וְקַיָם נוֹרָא וּמָרוֹם וְקָדוֹשׁ:</b></b>", "<b>אֲבִי</b> כָּל חוֹזֶה. חָל בּוֹ בַּמַּחֲזֶה. כְּנֶאֱמַר לוֹ חֲזֵה. תַּבְנִית הַחוֹדֶשׁ הַזֶּה: לְהָבִין קֶצֶב מוֹלַדְתּוֹ. מִתְּחִלָּתוֹ וְאֶרֶךְ מְלֵאָתוֹ. עַד תַּכְלִיתוֹ: עִמְּתוֹ לְהַרְאֵהוּ. וְלֹא הִכִּיר מַרְאֵהוּ. עַד בְּאֶצְבַּע הֶרְאָהוּ. אָז בָּן וְרָאָהוּ: זֹהַר לְשָׁעוֹת שֵׁשׁ. תָּאֳרוֹ לְהִתְאַשֵׁשׁ. פָּחוֹת מִשֵׁשׁ. כָּל עַיִן יְעַשֵׁשׁ: רוֹאָיו לְבַקֵּר. עֵדָיו לְחַקֵּר. מַאֲמִירָיו לְיַקֵּר. מְמִירָיו לְעַקֵּר: בְּמֶדֶד לוֹ שִׁעֵר. עָבְיוֹ אֵיךְ לְשַׁעֵר. עַד שְׁטִיפַת שֵׂעָר. יְקַבְּלוּ יוֹשְׁבֵי שָׁעַר: יִדְּעוֹ תְּבוּנָה. לְחַוּוֹת לְאוֹם נְכוֹנָה. לְהוֹרוֹת לְיוֹדְעֵי בִינָה. עֵרֶךְ לְבָנָה: רְגָלִים לְיַשֵּׁב. זְמַנִּים לְחַשֵּׁב. בְּעִבּוּר אֵיךְ לֵישֵׁב. וְסוֹד מַה לְהַקְשֵׁב: בְּפָנָיו צָגוּ אֵילֵי קוֹדֶשׁ. לְהָעִיד עֵדוּת חוֹדֶשׁ. וְאֵל נִתְעַטֵף בַּקּוֹדֶשׁ. כְּמַקְדִישֵׁי חוֹדֶשׁ: יָהּ בְּדָקָם לְעֵינוֹ. וְעֵדוּתָם דִּקְדֵּק בְּמַחֲנוֹ. וְהַכֹּל צָוְחוּ בִּמְעוֹנוֹ. מְקֻדָּשׁ הַחוֹדֶשׁ בִּזְמַנוֹ: קֵץ מוֹלַדְתּוֹ חָל לְהַקְצוֹת. בְּיוֹם רְבִיעִי בֶּחָצוֹת. וְעַד שְׁלֹשִׁים מְרוּצוֹת. לֹא נִכַּר בַּחוּצוֹת: לָאָה צִיר וּפָחַד. וְתָר מֵעֵת לְעֵת סְפוֹר אֶחָד. וְצוּר פָּץ לוֹ וַיִּחַדְּ. מֵעֶרֶב וְעַד עֶרֶב מְנוֹת אֶחָד: יַלְדוּת חֶרֶס וְסַהַר בּוֹ בַיּוֹם חֶשְׁבּוֹן מִצּוּ. וּבִתְחִלַּת בְּרִיָּתָם בְּחַלּוֹן אֶחָד נִמְצָאוּ:", "<b><b><small>חזן:</small> <b>רֵעִים</b> כְּנִתַּן לָמוֹ מַסּוֹרֶת אִמְּצוּ. לְחַשֵּׁב לְעַבֵּר וּלְקַדֵּשׁ סְפוֹרוֹת כְּמָצְאוּ:</b></b>", "<b>אֵל</b> נָא לְעוֹלָם תֻּעֲרָץ. וּלְעוֹלָם תֻּקְדָּשׁ. וּלְעוֹלְמֵי עוֹלָמִים תִּמְלוֹךְ וְתִתְנַשֵׂא. הָאֵל מֶלֶךְ נוֹרָא מָרוֹם וְקָדוֹשׁ. כִּי אַתָּה הוּא מֶלֶךְ מַלְכֵי הַמְּלָכִים. מַלְכוּתוֹ נֶצַח. נוֹרְאוֹתָיו שִׂיחוּ. סַפְּרוּ עֻזּוֹ. פָּאֲרוּהוּ צְבָאָיו. קַדְשׁוּהוּ רוֹמְמוּהוּ. רוֹן שִׁיר וָשֶׁבַח. תּוֹקֶף תְּהִלוֹת תִּפְאַרְתּוֹ:", "<b><b><small>חו\"ק:</small> <b>רִאשׁוֹן</b> הוּא לָכֶם. לִפְסוֹחַ עֲלֵיכֶם. לְהִתְקַדֵּשׁ בְּתוֹכְכֶם. קָדוֹשׁ:</b></b>", "<b><b><small>חו\"ק:</small> <b>לָכֶם</b> הוּא רִאשׁוֹן. נְצוּרֵי כְאִישׁוֹן. לְהַעֲרִיץ לְאֵל אַחֲרוֹן וְרִאשׁוֹן. קָדוֹשׁ:</b></b>", "<b>אָדוֹן</b> מִקֶּדֶם תִּכְּנוֹ רֹאשׁ. בִּינוֹ לֹא גָל בְּסֵפֶר תּוֹלְדוֹת רֹאשׁ. גִּלָהוּ תְּחִלָה לָכֶם לִדְרוֹשׁ: דּוֹרַשׁ לְהַשְׁווֹת בּוֹ גִּיהַּ וְאִישׁוֹן. הוּפְלָא מִכָּל עַם וְלָשׁוֹן. וְלֹא הוּמְסַר לְאָדָם הָרִאשׁוֹן: זְמַן עֶדְנָה בּוֹ בֻשָּׂרָה. חָנוּט לְקִצּוֹ עָקוּד לְמוֹסֵרָה. טַפֶּיהָ בְּכֵן בּוֹ בֻּשְּׂרוּ בְשׂוֹרָה: יֶרַח אֲשֶׁר לֹא פִּעֲנַח לָרִאשׁוֹנִים. כָּמוּס לִצְפוֹן חֲדָשִׁים וְגַם יְשָׁנִים. לְרֹאשׁ הוּשָׂם לְאַרְבָּעָה רָאשֵׁי שָׁנִים: מוֹעֲדִים מַזְמִין לְנִדְגָּלִים. נוֹעֲדִים בּוֹ עֵינֵימוֹ צִירֵי רוֹגְלִים. סָפוּר הוּא לִמְלָכִים וְלִרְגָלִים: עִבּוּר מְעַבְּרִים לְשָׁמְרוֹ בְּמוֹעֲדוֹ. פֶּרַח וְאָבִיב תְּקוּפָה בָּם לְוַעֲדוֹ. צִיּוּן שְׁלָשְׁתָּם יְצָרְפוּ לְסַעֲדוֹ: קֻדַּשׁ בְּרֹאשׁוֹ וּשְׁלִישׁוֹ חֶצְיוֹ וְרֻבּוֹ לִשְׁמוֹר. לְקַדֵּשׁ לָקַחַת לְחֶגֶּג לִקְצוֹר וְלִגְמוֹר. רֻשַׁם בְּכָל דוֹר. שָׁמוּר הוּא לְרוֹכֵב עַל חֲמוֹר: שְׁמִירַת שְׁלִישׁוֹ בַּיַּרְדֵּן עָמְדָה. שַׁלְהֶבֶת חֶצְיוֹ שְׁאוֹן פּוּל הִשְׁמִידָה. תְּשׁוּעַת קְצִירוֹ יְמִינִי הֶעֱמִידָה: לָכֶם הוּא רִאשׁוֹן. נְצוּרֵי כְאִישׁוֹן. לְהַעֲרִיץ לְאֵל אַחֲרוֹן וְרִאשׁוֹן. קָדוֹשׁ:", "<b>וּבְכֵן</b> וּלְךָ תַעֲלֶה קְדֻשָּׁה כִּי אַתָּה קְדוֹשׁ יִשְׂרָאֵל וּמוֹשִׁיעַ:", "<b>הוּא</b> נִקְרָא רֹאשׁ וְרִאשׁוֹן. וְנוֹאֲמוֹ נִקְרָא רֹאשׁ וְרִאשׁוֹן. וּמוֹעֲדוֹ נִקְרָא רֹאשׁ וְרִאשׁוֹן. וְאִוּוּיוֹ נִקְרָא רֹאשׁ וְרִאשׁוֹן. וְנוֹחֲלָיו נִקְרְאוּ רֹאשׁ וְרִאשׁוֹן. וְאוֹיְבָם נִקְרָא רֹאשׁ וְרִאשׁוֹן. וְאוֹהֲבָם נִקְרָא רֹאשׁ וְרִאשׁוֹן. וְגוֹאֲלָם נִקְרָא רֹאשׁ וְרִאשׁוֹן. הִנֵּה הָעֵת יָבֹא בְּרֹאשׁ וְרִאשׁוֹן. בְּקֵץ אֲשֶׁר הוּא רֹאשׁ וְרִאשׁוֹן. לַעֲבוֹר בְּרֹאשׁ וְרִאשׁוֹן. לְכוֹנֵן נָכוֹן בְּרֹאשׁ וְרִאשׁוֹן. וְאִתּוֹ נוֹצַר בְּרוּחַ רֹאשׁ וְרִאשׁוֹן. לְקַעֲקֵעַ שְׂרִידֵי עֲמָלֵק רֹאשׁ וְרִאשׁוֹן. לְעוֹרֵר צוּרִים הַחֲצוּבִים בְּרֹאשׁ וְרִאשׁוֹן. לִפְעוֹל חֲדָשׁוֹת בְּרֹאשׁ וְרִאשׁוֹן. לְרַצּוֹת חִדּוּשׁ תְּשׁוּרַת רֹאשׁ וְרִאשׁוֹן. לְהוֹבִיל בּוֹ שַׁי לְרֹאשׁ וְרִאשׁוֹן:", "<b>וְעוֹד</b> בַּל יֻזְכְּרוּ רִאשׁוֹנִים. כִּי יְחֻדְּשׁוּ חֲדָשִׁים וְגַם יְשָׁנִים. פְּלָאִים מִפְּלָאִים מְשֻׁנִּים. וְיָקִיצוּ כָּל יְשֵׁנִים. מְהַלְּלִים וּמְשׁוֹרְרִים שִׁירִים מִשִּׁירִים מְשַׁנְּנִים: וְלֹא יֹאמְרוּ עוֹד אֲשֶׁר הֶעֱלָה בְּנָבִיא. כִּי אִם חַי יְהֹוָה אֲשֶׁר הֶעֱלָה וַאֲשֶׁר הֵבִיא. וְאָז אֵל יִשְׁאַג כְּלָבִיא. לַעֲרוֹךְ קְרָבִי. חֲדָשׁוֹת לְהָבִיא. בְּיַד אִישׁ נָבִיא. מִשֵׁבֶט לֵוִי. לְהָשִׁיב לְבָבִי. לְחַדֵּשׁ קְרָבִי: וְיַצְמִיחַ צֶמַח נָקוּב שִׁבְעָה. וְאִתּוֹ יְהוּ רוֹעִים שִׁבְעָה. וִיחֻדְּשׁוּ לְאוֹם דְּבָרִים שִׁבְעָה. וְיִתְכַּסֶּה מֵהֶם שָׁבֻעִים שִׁבְעָה:", "<b>וְיָשׁוּב</b> וְיִגָלֶה לְעַם קְדוֹשִׁים. אֲשֶׁר עִמּוֹ יְהוּ מְקֻדָּשִׁים. וְלֹא לְעֶדְרֵי צֹאן קָדָשִׁים. עַד קֵץ שִׁשָּׁה חֳדָשִׁים. עַד בֹּא רִאשׁוֹן לְרָאשֵׁי חֳדָשִׁים. וְאָז יֵרָאֶה לַעֲדַת קְדוֹשִׁים. הַנִּשְׁאָרִים מֵעוֹל קְדֵשִׁים. וְיַרְאֶה לָמוֹ אוֹתוֹת חֲדָשִׁים. לְחַדֵּשׁ שָׁמַיִם הַחֲדָשִׁים. לִמְשׁוֹחַ קוֹדֶשׁ קָדָשִׁים. לִפְתּוֹחַ דֶלֶת לִקְדוֹשִׁים. בְּשַׁבָּתוֹת וּבֶחֳדָשִׁים: וְאָז יְצַוֶּה חִדּוּשׁ עֲבוֹדַת חוֹדֶשׁ. מַה לְהַעֲלוֹת בְּרֹאשׁ כָּל חוֹדֶשׁ. וַעֲבוֹדַת רִאשׁוֹן כָּל חוֹדֶשׁ. הִיא תַקְדִים תְּחִלָה לְכָל חוֹדֶשׁ: כִּי כְּמוֹ הָיָה רֹאשׁ לְכָל חוֹדֶשׁ. כֵּן יִהְיֶה רֹאשׁ לְכָל חוֹדֶשׁ:", "<b>וְתֵעָשֶׂה</b> בּוֹ חֲדָשָׁה. לִבְרֹאת אֶרֶץ חֲדָשָׁה. לְהִנָּתֵן דֵּעָה חֲדָשָׁה. לִכְרוֹת בְּרִית חֲדָשָׁה. לְהִבָּרְאוֹת בְּרִיָּה חֲדָשָׁה. לְהִתְחַדֵּשׁ רוּחַ חֲדָשָׁה. לְהוֹבִיל בּוֹ שַׁי מִנְחָה חֲדָשָׁה: וְחַמָּה וּלְבָנָה תִּתְחַדָּשׁ. וְאוֹרָם שִׁבְעָתַיִם יְחֻדָּשׁ. שְׁתַּיִם בַּשָׁנָה יִתְחַדָּשׁ. וִיצַמְצֵם שְׁכִינָתוֹ בְּתוֹךְ שַׁעַר הֶחָדָשׁ. וְיִקָּרֵא לוֹ שֵׁם חָדָשׁ. כְּשֵׁם הָעִיר מִיּוֹם הַמְּקֻדָּשׁ. וְיִנָּתֵן לָעָם לֵב חָדָשׁ. לְשׁוֹרֵר בְּפִיהֶם שִׁיר חָדָשׁ. שִׁיר מְפוֹאָר וּמְחֻדָּשׁ. עַל כָּל שִׁיר מְהֻלָּל וּמְקֻדָּשׁ:", "<b>כִּי</b> שִׁירֵי אֶרְאֶלִים. אֲשֶׁר שִׁיר וְתִשְׁבָּחוֹת מְהַלְּלִים. לִפְנֵי שִׁיר זֶה לֹא חָלִים: וְנִצּוּחַ אֵלִים. אֲשֶׁר קוֹל הֲמוּלָה צוֹהֲלִים. לִפְנֵי שִׁיר זֶה לֹא מְמַלְּלִים: וְרֶנֶן גַּלְגַּלִים. אֲשֶׁר אִם הוּרְשׁוּ כָּל גּוֹלְלִים. לִפְנֵי שִׁיר זֶה לֹא כוֹלְלִים: וְאֵימַת כְּרוּבִים. אֲשֶׁר הֵם צָגִים כְּמוֹ רוֹבִים. לִפְנֵי שִׁיר זֶה לֹא מַרְבִּים: וְהַדְרַת אוֹפַנִּים. אֲשֶׁר הֵם מְרֻבְּעֵי פָנִים. לִפְנֵי שִׁיר זֶה לֹא סוֹפְנִים: וַהֲמוֹן גְּדוּדִים. אֲשֶׁר הֵם הוֹד אֵל מַגִּידִים. לִפְנֵי שִׁיר זֶה לֹא נֶאֱגָדִים: וְסוֹד עִירִין. אֲשֶׁר כְּעֵין קָלָל בּוֹעֲרִים. לִפְנֵי שִׁיר זֶה לֹא מְפָאֲרִים:", "<b>וְרֶגֶשׁ</b> קַדִּישִׁין. אֲשֶׁר לַבְּקָרִים מִתְחַדְּשִׁים. לִפְנֵי שִׁיר זֶה לֹא מַקְדִּישִׁים: וְנַהַם שִׁנְאֲנִּים. אֲשֶׁר טַעֲמָם לֹא מְשַׁנִּים. לִפְנֵי שִׁיר זֶה לֹא מְשַׁנְּנִים: וּפַחַד שְׂרָפִים. אֲשֶׁר בְּרֶגַע כֹּל שׂוֹרְפִים. לִפְנֵי שִׁיר זֶה לֹא רוֹפְפִים: כִּי כָל מַחֲנוֹת מְשָׁרְתִים קְדוֹשִׁים. מְשָׁרְתָיו יְהוּ מַקְדִּישִׁים: וְגַם הֲמוֹן צְבָא מַלְאָכִים. מַנְעִימָיו יְהוּ מַמְלִיכִים: וּמְרוּצוֹת חֵיל זִקִּים. כֹּחָם יְהוּ מְחַזְּקִים. וְזִיו מִשְׁלַחַת בְּרָקִים. פְּנֵיהֶם יְהוּ מַבְרִיקִים. וְחוּצָה לָמוֹ הֹוִים. מִתְעַלְּסִים בָּאֳהָבִים: וְעַד מְחִיצָתָם לֹא בָאִים. בְּאִשָׁם נִלְהָבִים. וּבְגַחַלְתָּם נִכְוִים. וּבְפָאֲרָם הֵם נֶאֱלָמִים: וְעֵת כִּי יַתְחִילוּ יָחִישׁוּ. וְעֵת כִּי יַתְכִּילוּ יָחִילוּ. וְעֵת כִּי יִגְמוֹרוּ יַעֲרִיצוּ. וְעֵת כִּי יָחִישׁוּ <small>(נ\"א יֶחֱשׁוּ)</small> יַקְדִּישׁוּ. וְעֵת כִּי יִשְׁתּוֹקוּ יְשַׁלֵּשׁוּ קְדֻשָּׁה מְשֻׁלֶּשֶׁת:", "<b><b><small> קדושה</small></b></b>", "<small><b><b><small>נַקְדִּישָׁךְ וְנַעֲרִיצָךְ כְּנֹעַם שִׂיחַ סוֹד שַׂרְפֵי קֹדֶשׁ. הַמְּשַׁלְּשִׁים לְךָ קְדֻשָּׁה. כַּכָּתוּב עַל יַד נְבִיאֶךָ. וְקָרָא זֶה אֶל זֶה וְאָמַר: </small></b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>קָדוֹשׁ</b> קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: <small>חזן:</small> <b>אָז.</b> בְּקוֹל רַעַשׁ גָּדוֹל אַדִּיר וְחָזָק. מַשְׁמִיעִים קוֹל. מִתְנַשְּׂאִים לְעֻמַּת שְׂרָפִים. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>בָּרוּךְ</b> כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>חזן:</small> מִמְּקוֹמְךָ מַלְכֵּנוּ תוֹפִיעַ. וְתִמְלוֹךְ עָלֵינוּ <small> <small>(מְהֵרָה)</small> </small> כִּי מְחַכִּים אֲנַחְנוּ לָךְ. מָתַי תִּמְלֹךְ בְּצִיּוֹן. בְּקָרוֹב בְּיָמֵינוּ לְעוֹלָם וָעֶד תִּשְׁכּוֹן. תִּתְגַּדֵּל וְתִתְקַדֵּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר וּלְנֵצַח נְצָחִים. וְעֵינֵינוּ תִרְאֶינָה מַלְכוּתֶךָ כַּדָּבָר הָאָמוּר בְּשִׁירֵי עֻזֶּךָ. עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ: </b></b></small>", "<small><b><b><small>קו\"ח:</small> <b>יִמְלֹךְ</b> יְהֹוָה לְעוֹלָם. אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר. הַלְלוּיָהּ:</b></b></small><b><b> </b></b>", "<b>אַתָּה קָדוֹשׁ</b>, וְשִׁמְךָ קָדוֹשׁ, וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. כִּי אֵל מֶלֶךְ גָדוֹל וְקָדוֹשׁ אָתָּה. בָּרוּךְ אַתָּה יְהֹוָה, הָאֵל הַקָּדוֹשׁ:", "<b>יִשְׂמַח מֹשֶׁה</b> בְּמַתְּנַת חֶלְקוֹ, כִּי עֶבֶד נֶאֱמָן קָרָאתָ לּוֹ. כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ, בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי. וּשְׁנֵי לוּחוֹת אֲבָנִים הוֹרִיד בְּיָדוֹ, וְכָתוּב בָּהֶם שְׁמִירַת שַׁבָּת, וְכֵן כָּתוּב בְּתוֹרָתֶךָ:", "<b>וְשָׁמְרוּ</b> בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְהֹוָה אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ:", "<b>ולֹא</b> נְתַתּוֹ יְהֹוָה אֱלֹהֵינוּ לְגוֹיֵי הָאֲרָצוֹת, וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים, גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים, כִּי לְעַמְּךָ יִשְׂרָאֵל נְתַתּוֹ בְּאַהֲבָה, לְזֶרַע יַעֲקֹב אֲשֶׁר בָּם בָּחָרְתָּ:", "<b>יִשְׂמְחוּ</b> בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עוֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ. וּבַשְּׁבִיעִי רָצִיתָ בּוֹ וְקִדַּשְׁתּוֹ. חֶמְדַת יָמִים אוֹתוֹ קָרָאתָ. זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<b>אֱלֹהֵינוּ</b> וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךְ, וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶאֱמֶת, וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבָּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ. בָּרוּךְ אַתָּה יְהֹוָה, מְקַדֵּשׁ הַשַּׁבָּת:", "<b>רְצֵה</b> יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל, וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<b><b><small> <small><b><small>בראש חודש</small></b> אומרים כאן \"יעלה ויבא\":</small></small></b></b>", "<small><b><b><small> אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, יַעֲלֶה וְיָבֹא, וְיַגִּיעַ וְיֵרָאֶה וְיֵרָצֶה, וְיִשָּׁמַע וְיִפָּקֵד וְיִזָּכֵר, זִכְרוֹנֵנוּ וּפִקְדוֹנֵנו וְזִכְרוֹן אֲבוֹתֵינוּ, וְזִכְרוֹן מָשִׁיחַ בֶּן דָּוִד עַבְדָּךְ, וְזִכְרוֹן יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ, וְזִכְרוֹן כָּל עַמְּךָ בֵּית יִשְׂרָאֵל לְפָנֶיךָ, לִפְלֵטָה, לְטוֹבָה, לְחֵן וּלְחֶסֶד וּלְרַחֲמִים לְחַיִּים טוֹבִים וּלְשָׁלוֹם בְּיוֹם:</small></b></b></small>", "<small><b><b><small><b>רֹאשׁ הַחֹדֶשׁ</b> הַזֶּה. זָכְרֵנוּ יְהֹוָה אֱלֹהֵינוּ בּוֹ לְטוֹבָה, וּפָּקְדֵנוּ בוֹ לִבְרָכָה, וְהוֹשִׁיעֵנוּ בוֹ לְחַיִּים טוֹבִים, וּבִּדְבַר יְשׁוּעָה וְרַחֲמִים. חוּס וְחָנֵּנוּ, וְרַחֵם עָלֵינוּ וְהוֹשִׁיעֵנוּ, כִּי אֵלֶיךָ עֵינֵינוּ, כִּי אֵל מֶלֶךְ חַנּוּן וְרַחוּם אָתָּה:</small></b></b></small>", "<b>וְתֶחֱזֶינָה</b> עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. בָּרוּךְ אַתָּה יְהֹוָה, הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:", "<b>מוֹדִים</b> אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדֹר וָדֹר. נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶיךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם. הַטּוֹב, כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְּרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b><b><small> מודים דרבנן<small><b><small>בחזרת הש\"ץ</small></b> כשהוא אומר מודים, אומרים הקהל:</small> </small></b></b>", "<small><b><b><small>מוֹדִים אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׁר, יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמֹר חֻקֶּיךָ וְלַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְךָ בְלֵבָב שָׁלֵם, עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת.</small></b></b></small>", "<b>וְעַל</b> כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָמִיד לְעוֹלָם וָעֶד.", "<b>וְכֹל</b> הַחַיִּים יוֹדוּךָ סֶּלָה: וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל, בֶּאֱמֶת, לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<b><b>ברכת כהנים</b></b>", "<b>שִׂים שָׁלוֹם</b> טוֹבָה וּבְרָכָה, חַיִּים, חֵן וָחֶסֶד, וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד <small>(יַחַד)</small> בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים, וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים, וְחַיִּים וְשָׁלוֹם. <small>(וְכָל טוּב)</small> וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרֹב עֹז וְשָׁלוֹם.", "<b>בָּרוּךְ</b> אַתָּה יְהֹוָה, הַמְּבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>אֱלֹהַי.</b> נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וְאַחֲרֵי מִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַקָּמִים וְהַחוֹשְׁבִים עָלַי לְרָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:", "<b><b><small>יש אומרים כאן תפילה זו:</small></b></b>", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי. שֶׁלֹּא תַעֲלֶה קִנְאַת אָדָם עָלַי וְלֹא קִנְאָתִי עַל אֲחֵרִים. וְשֶׁלֹּא אֶכְעוֹס הַיֹּום וְשֶׁלֹּא אַכְעִיסֶךָ. וְתַצִּילֵנִי מִיֵּצֶר הָרָע. וְתֵן בְּלִבִּי הַכְנָעָה וַעֲנָוָה. מַלְכֵּנוּ וֵאלֹהֵינוּ אֱלֹהַּ כָּל בָּשָׂר. יַחֵד שִׁמְךָ בְּעוֹלָמֶךָ בְּנֵה עִירֶךָ יַסֵּד בֵּיתֶךָ וְשַׁכְלֵל הֵיכָלֶךָ. וְקַבֵּץ קִבּוּץ גָּלֻיּוֹת וּפְדֵה צֹאנֶךָ וְשַׂמַּח עֲדָתֶךָ: <b>עֲשֵׂה</b> לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הושִׁיעָה יְמִינְךָ וַעֲנֵנִי:", "<b><b><small>נוהגים לומר כאן פסוק המתחיל וגומר באוֹת שבה מתחיל וגומר שמו הפרטי</small></b></b>", "<b>יִהְיוּ לְרָצוֹן</b> אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>עֹשֶׂה שָׁלוֹם</b> בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:", "<b>יְהִי</b> רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ: וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b>וְעָרְבָה</b> לַיהֹוָה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם. כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:", "<b><b><small><b>בראש חודש</b> אומרים כאן הלל...</small></b></b>", "<b><b><small>קדיש שלם</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>תִּתְקַבֵּל</b> צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא, וְאִמְרוּ אָמֵן:", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small>שיר של יום</small></b></b>", "<b><b><small><b>הַיּוֹם</b> יוֹם שַׁבָּת קֹדֶשׁ שֶׁבּו הָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ:</small></b></b>", "<b>מִזְמוֹר שִׁיר</b> לְיוֹם הַשַּׁבָּת: טוֹב לְהֹדוֹת לַיהֹוָה וּלְזַמֵּר לְשִׁמְךָ עֶלְיוֹן: לְהַגִּיד בַּבֹּקֶר חַסְדֶּךָ וֶאֱמוּנָתְךָ בַּלֵּילוֹת: עֲלֵי עָשׂוֹר וַעֲלֵי נָבֶל עֲלֵי הִגָּיוֹן בְּכִנּוֹר: כִּי שִׂמַּחְתַּנִי יְהֹוָה בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן: מַה גָּדְלוּ מַעֲשֶׂיךָ יְהֹוָה מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ: אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת: בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן לְהִשָּׁמְדָם עֲדֵי עַד: וְאַתָּה מָרוֹם לְעֹלָם יְהֹוָה: כִּי הִנֵּה אֹיְבֶיךָ יְהֹוָה כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן: וַתָּרֶם כִּרְאֵים קַרְנִי בַּלֹּתִי בְּשֶׁמֶן רַעֲנָן: וַתַּבֵּט עֵינִי בְּשׁוּרָי בַּקָּמִים עָלַי מְרֵעִים תִּשְׁמַעְנָה אָזְנָי: צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה: שְׁתוּלִים בְּבֵית יְהֹוָה בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ: עוֹד יְנוּבוּן בְּשֵׂיבָה דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ: לְהַגִּיד כִּי יָשָׁר יְהֹוָה צוּרִי וְלֹא עַוְלָתָה בּוֹ:", "<b><b><small>קדיש יתום</small></b></b>", "<b><b><small><b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b>", "<b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:", "<b><b><small><small>בראש חדש אחר שיר של יום אומרים ברכי נפשי</small></small></b></b>", "<small><b>בָּרֲכִי</b> נַפְשִׁי אֶת יְהֹוָה יְהֹוָה אֱלֹהַי גָּדַלְתָּ מְּאֹד הוֹד וְהָדָר לָבָשְׁתָּ: עֹטֶה אוֹר כַּשַּׂלְמָה נוֹטֶה שָׁמַיִם כַּיְרִיעָה: הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו הַשָּׂם עָבִים רְכוּבוֹ הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ: עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט: יָסַד אֶרֶץ עַל מְכוֹנֶיהָ בַּל תִּמּוֹט עוֹלָם וָעֶד: תְּהוֹם כַּלְּבוּשׁ כִּסִּיתוֹ עַל הָרִים יַעַמְדוּ מָיִם: מִן גַּעֲרָתְךָ יְנוּסוּן מִן קוֹל רַעַמְךָ יֵחָפֵזוּן: יַעֲלוּ הָרִים יֵרְדוּ בְקָעוֹת אֶל מְקוֹם זֶה יָסַדְתָּ לָהֶם: גְּבוּל שַׂמְתָּ בַּל יַעֲבֹרוּן בַּל יְשׁוּבוּן לְכַסּוֹת הָאָרֶץ: הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים בֵּין הָרִים יְהַלֵּכוּן: יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם: עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן מִבֵּין עֳפָאיִם יִתְּנוּ קוֹל: מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו מִפְּרִי מַעֲשֶׂיךָ תִּשְׂבַּע הָאָרֶץ: מַצְמִיחַ חָצִיר לַבְּהֵמָה וְעֵשֶׂב לַעֲבֹדַת הָאָדָם לְהוֹצִיא לֶחֶם מִן הָאָרֶץ: וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ לְהַצְהִיל פָּנִים מִשָּׁמֶן וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד: יִשְׂבְּעוּ עֲצֵי יְהֹוָה אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע: אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ: הָרִים הַגְּבֹהִים לַיְּעֵלִים סְלָעִים מַחְסֶה לַשְׁפַנִּים: עָשָׂה יָרֵחַ לְמוֹעֲדִים שֶׁמֶשׁ יָדַע מְבוֹאוֹ: תָּשֶׁת חֹשֶׁךְ וִיהִי לָיְלָה בּוֹ תִרְמֹשׂ כָּל חַיְתוֹ יָעַר: הַכְּפִירִים שֹׁאֲגִים לַטָּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם: תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן וְאֶל מְעוֹנֹתָם יִרְבָּצוּן: יֵצֵא אָדָם לְפָעֳלוֹ וְלַעֲבֹדָתוֹ עֲדֵי עָרֶב: מָה רַבּוּ מַעֲשֶׂיךָ יְהֹוָה כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךָ: זֶה הַיָּם גָּדוֹל וּרְחַב יָדָיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדֹלוֹת: שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ: כֻּלָּם אֵלֶיךָ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ: תִּתֵּן לָהֶם יִלְקֹטוּן תִּפְתַּח יָדְךָ יִשְׂבְּעוּן טוֹב: תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן תֹּסֵף רוּחָם יִגְוָעוּן וְאֶל עֲפָרָם יְשׁוּבוּן: תְּשַׁלַּח רוּחֲךָ יִבָּרֵאוּן וּתְחַדֵּשׁ פְּנֵי אֲדָמָה: יְהִי כְבוֹד יְהֹוָה לְעוֹלָם יִשְׂמַח יְהֹוָה בְּמַעֲשָׂיו: הַמַּבִּיט לָאָרֶץ וַתִּרְעָד יִגַּע בֶּהָרִים וְיֶעֱשָׁנוּ: אָשִׁירָה לַיהֹוָה בְּחַיָּי אֲזַמְּרָה לֵאלֹהַי בְּעוֹדִי: יֶעֱרַב עָלָיו שִׂיחִי אָנֹכִי אֶשְׂמַח בַּיהוָה: יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם בָּרֲכִי נַפְשִׁי אֶת יְהֹוָה הַלְלוּיָהּ:</small>", "<small><b><b><small>קדיש יתום</small></b></b></small>", "<small><b><b><small> <b>יִתְגַּדַּל</b> וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵה, וְיַצְמַח פֻּרְקָנֵה, וִיקָרֵב מְשִׁיחֵהּ. בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן. <b>יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ.</b> וְיִשְׁתַּבַּח. וְיִתְפָּאַר. וְיִתְרוֹמַם. וְיִתְנַשֵּׂא. וְיִתְהַדָּר. וְיִתְעַלֶּה. וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא, בְּרִיךְ הוּא. לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן: </small></b></b></small>", "<small><b>יְהֵא</b> שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: <b>עֹשֶׂה</b> שָׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן:</b></b></small><b><b>"]}, "yotzer_or": {"ref": "Siddur Ashkenaz, Weekday, Shacharit, Blessings of the Shema, First Blessing before Shema", "he": "ברכת יוצר אור, שחרית של חול", "nusach": "סידור אשכנז (מצודה)", "version": "The Metsudah siddur, 1981", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002211687", "url": "https://www.sefaria.org/Siddur_Ashkenaz%2C_Weekday%2C_Shacharit%2C_Blessings_of_the_Shema%2C_First_Blessing_before_Shema", "segs": ["<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם יוֹצֵר אוֹר וּבוֹרֵא חֽשֶׁךְ עֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת־הַכֹּל:", "<b>הַמֵּאִיר לָאָֽרֶץ</b> וְלַדָּרִים עָלֶֽיהָ בְּרַחֲמִים וּבְטוּבוֹ מְחַדֵּשׁ בְּכָל־יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית: מָה־רַבּוּ מַעֲשֶׂיךָ | יְהֹוָה כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְ֒אָה הָאָרֶץ קִנְיָנֶֽךָ: הַמֶּֽלֶךְ הַמְ֒רוֹמָם לְבַדּוֹ מֵאָז. הַמְ֒שֻׁבָּח וְהַמְ֒פֹאָר וְהַמִּתְנַשֵּׂא מִימוֹת עוֹלָם: אֱלֹהֵי עוֹלָם בְּרַחֲמֶֽיךָ הָרַבִּים רַחֵם עָלֵֽינוּ אֲדוֹן עֻזֵּֽנוּ צוּר מִשְׂגַּבֵּֽנוּ מָגֵן יִשְׁעֵֽנוּ מִשְׂגָּב בַּעֲדֵֽנוּ: אֵל בָּרוּךְ גְּדוֹל דֵּעָה הֵכִין וּפָעַל זָהֳרֵי חַמָּה: טוֹב יָצַר כָּבוֹד לִשְׁמוֹ מְאוֹרוֹת נָתַן סְבִיבוֹת עֻזּוֹ: פִּנּוֹת צְבָאָיו קְדוֹשִׁים רוֹמְ֒מֵי שַׁדַּי תָּמִיד מְסַפְּרִים כְּבוֹד־אֵל וּקְדֻשָּׁתוֹ: תִּתְבָּרַךְ יְהֹוָה אֱלֹהֵֽינוּ עַל־שֶֽׁבַח מַעֲשֵׂה יָדֶֽיךָ וְעַל־מְאֽוֹרֵי אוֹר שֶׁעָשִֽׂיתָ יְפָאֲרֽוּךָ סֶּֽלָה:", "<b>תִּתְבָּרַךְ צוּרֵֽנוּ </b> מַלְכֵּֽנוּ וְגוֹאֲלֵֽנוּ בּוֹרֵא קְדוֹשִׁים. יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּֽנוּ יוֹצֵר מְשָׁרְ֒תִים. וַאֲשֶׁר מְשָׁרְ֒תָיו כֻּלָּם עוֹמְ֒דִים בְּרוּם עוֹלָם וּמַשְׁמִיעִים בְּיִרְאָה יַֽחַד בְּקוֹל דִּבְרֵי אֱלֹהִים חַיִּים וּמֶֽלֶךְ עוֹלָם. כֻּלָּם אֲהוּבִים. כֻּלָּם בְּרוּרִים. כֻּלָּם גִּבּוֹרִים. וְכֻלָּם עוֹשִׂים בְּאֵימָה וּבְיִרְאָה רְצוֹן קוֹנָם. וְכֻלָּם פּוֹתְ֒חִים אֶת־פִּיהֶם בִּקְדֻשָּׁה וּבְטָהֳרָה. בְּשִׁירָה וּבְזִמְרָה. וּמְבָרְ֒כִים וּמְשַׁבְּ֒חִים וּמְפָאֲרִים וּמַעֲרִיצִים וּמַקְדִּישִׁים וּמַמְלִיכִים:", "<b>אֶת שֵׁם</b> הָאֵל הַמֶּֽלֶךְ הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא קָדוֹשׁ הוּא. וְכֻלָּם מְקַבְּ֒לִים עֲלֵיהֶם עֹל מַלְכוּת שָׁמַֽיִם זֶה מִזֶּה. וְנוֹתְ֒נִים רְשׁוּת זֶה לָזֶה לְהַקְדִּישׁ לְיוֹצְ֒רָם בְּנַֽחַת רֽוּחַ. בְּשָׂפָה בְרוּרָה וּבִנְעִימָה. קְדֻשָּׁה כֻּלָּם כְּאֶחָד עוֹנִים וְאוֹמְ֒רִים בְּיִרְאָה:", "<b>קָדוֹשׁ קָדוֹשׁ, קָדוֹשׁ יְהֹוָה צְבָאוֹת. מְלֹא כָל־הָאָֽרֶץ כְּבוֹדוֹ:</b>", "וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּֽדֶשׁ בְּרַֽעַשׁ גָּדוֹל מִתְנַשְּׂ֒אִים לְעֻמַּת שְׂרָפִים לְעֻמָּתָם מְשַׁבְּ֒חִים וְאוֹמְ֒רִים:", "<b>בָּרוּךְ כְּבוֹד־יְהֹוָה מִמְּ֒קוֹמוֹ:</b>", "<b>לְאֵל</b> בָּרוּךְ נְעִימוֹת יִתֵּֽנוּ. לְמֶֽלֶךְ אֵל חַי וְקַיָּם זְמִרוֹת יֹאמֵֽרוּ וְתִשְׁבָּחוֹת יַשְׁמִֽיעוּ. כִּי הוּא לְבַדּוֹ פּוֹעֵל גְּבוּרוֹת. עוֹשֶׂה חֲדָשׁוֹת. בַּֽעַל מִלְחָמוֹת. זוֹרֵֽעַ צְדָקוֹת. מַצְמִֽיחַ יְשׁוּעוֹת. בּוֹרֵא רְפוּאוֹת. נוֹרָא תְהִלּוֹת. אֲדוֹן הַנִּפְלָאוֹת: הַמְ֒חַדֵּשׁ בְּטוּבוֹ בְּכָל־יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית: כָּאָמוּר לְעֹשֵׂה אוֹרִים גְּדֹלִים כִּי לְעוֹלָם חַסְדּֽוֹ: אוֹר חָדָשׁ עַל־צִיּוֹן תָּאִיר וְנִזְכֶּה כֻלָּֽנוּ מְהֵרָה לְאוֹרוֹ: בָּרוּךְ אַתָּה יְהֹוָה יוֹצֵר הַמְּ֒אוֹרוֹת:"]}, "rh1_musaf": {"ref": "Machzor Rosh Hashanah Sefard, Musaf, First Day of Rosh Hashana, Reader's Repetition", "he": "חזרת הש\"ץ למוסף, יום א' של ראש השנה", "nusach": "מחזור ראש השנה (נוסח ספרד)", "version": "Machzor Rosh Hashanah", "source": "https://www.sefaria.org", "url": "https://www.sefaria.org/Machzor_Rosh_Hashanah_Sefard%2C_Musaf%2C_First_Day_of_Rosh_Hashana%2C_Reader's_Repetition", "segs": ["<b>כִּי שֵׁם יְהֹוָה אֶקְרָא הָבוּ גוֹדֶל לֵאלֹהֵינוּ:</b>", "<small>פותחין הארון</small>", "<b>אֲדֹנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:</b>", "<b>בָּרוּךְ </b>אַתָּה יְהֹוָה, אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי אַבְרָהָם, אֱלֹהֵי יִצְחָק, וֵאלֹהֵי יַעֲקֹב, הָאֵל, הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, אֵל עֶלְיוֹן גּוֹמֵל חֲסָדִים טוֹבִים, וְקוֹנֵה הַכֹּל, וְזוֹכֵר חַסְדֵּי אָבוֹת, וּמֵבִיא גוֹאֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמוֹ בְּאַהֲבָה:", "<b>מִסּוֹד </b>חֲכָמִים וּנְבוֹנִים. וּמִלֶּמֶד דַּעַת מְבִינִים. אֶפְתְּחָה פִּי בִּתְפִלָּה וּבְתַחֲנוּנִים. לְחַלּוֹת וּלְחַנֵּן פְּנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים וַאֲדוֹנֵי הָאֲדוֹנִים:", "<small>סוגרין הארון</small>", "<small>מיוסד ע\"פ א\"ב</small>", "<b>אֻפַּד </b>מֵאָז לְשֶׁפֶט הַיּוֹם. בְּחֹן מַעֲשֵׂה כָּל יוֹם. גִּישַׁת יְקוּמִים פְּנֵי אָיֹם. דִּינָם בּוֹ לְפַלֵּס לְפִדְיוֹם: הָרִאשׁוֹן אָדָם בּוֹ נוֹצָר. וְצֻוָּה חֹק וְלֹא נָצָר. זֶה מֵלִיץ כְּהִרְחִיב בַּצָּר. חֲקָקוֹ לַמִּשְׁפָּט וְלַדּוֹרוֹת הֻנְצָר: טִיעַת חוֹצֵב גְּבָעוֹת וְצוּרִים. יֻלְּדוּ בוֹ מֵרֹאשׁ צֻרִים. כְּיוֹשְׁבֵי נְטָעִים הֵמָּה הַיּוֹצְרִים. לְלַמֵּד בּוֹ צֶדֶק לַעֲצוּרִים: מְיֻחָס שְׁמוֹ בְּשֵׁם אֵיתָנִים. נֵס לְהִתְנוֹסֵס עֶלְיוֹנִים וְתַחְתּוֹנִים. סְפָרִים נִפְתָּחִים וּמַעֲשִׂים מְתַנִּים. עוֹבְרִים לְפָנֶיךָ וְחֶשְׁבּוֹן נוֹתְנִים: פָּקִיד הוּכַן לְתִקּוּן מוֹעֲדֶיךָ. צֹאן לְהַעֲבִיר בַּשֵּׁבֶט עָדֶיךָ: <small>חזן </small>קֶרֶן בְּמָשְׁכָם (<small>בשבת </small>בְּזָכְרָם) הַיּוֹם עֵדֶיךָ. רַחוּם זְכֹר שְׁבוּעַת עֲבָדֶיךָ:", "<b>נַעֲלֶה </b>(<small>בשבת </small>זִכְרוֹן) שׁוֹפָר עִם תַּחֲנוּן. שַׁדַּי לְפַתּוֹתְךָ בָם בְּחִנּוּן: <small>חזן </small>תָּשִׁיב לִנְדָן בְּרַק הַשָּׁנוּן. תַּחֲזֵק מָגֵן לְגוֹנְנִי בְגִנּוּן:", "<b>זָכְרֵנוּ </b>לְחַיִּים מֶלֶךְ חָפֵץ בַּחַיִּים וְכָתְבֵנוּ בְּסֵפֶר הַחַיִּים לְמַעַנְךָ אֱלֹהִים חַיִּים:", "<b>מֶלֶךְ </b>עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן: בָּרוּךְ אַתָּה יְהֹוָה מָגֵן אַבְרָהָם:", "<b>אַתָּה </b>גִבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֶּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ: מוֹרִיד הַטָּל:", "<b>מְכַלְכֵּל </b>חַיִּים בְּחֶסֶד מְחַיֵּה מֵתִים בְּרַחֲמִים רַבִּים סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. מִי כָמוֹךָ בַּעַל גְּבוּרוֹת וּמִי דוֹמֶה לָּךְ מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה:", "<small>מיוסד ע\"פ תשר\"ק</small>", "<b>תֵּפֶן </b>בְּמָכוֹן לְכֵס שֶׁבֶת. שְׁעֹן וּמוּסָר כְּעָלוּ בְּמַחֲשֶׁבֶת. רָם תְּהִי אָזְנְךָ קַשֶּׁבֶת. קוֹל שׁוֹפָר שְׁעוֹת מִנּוֹשָׁבֶת: צָרַת אֹמֶר לֹא יָדוֹן. פַּעֲמַיִם לֹא תָקוּם לַאֲבַדּוֹן. עוֹלָם אֲשֶׁר בְּאַרְבָּעָה נִדּוֹן. סְמֹךְ בְּחַסְדְּךָ וּבַאֲמִתְּךָ אָדוֹן: נוֹעָדִים בְּיוֹם קְרָב וְנִלְחָמִים. מוּל אֶבֶן נֶגֶף מִתְלַחֲמִים. לִבּוּב תְּרוּעָתָם שְׁעֵה מִמְּרוֹמִים. כִּסֵּא דִין לְהָמִיר בְּשֶׁל רַחֲמִים: יָחִיד אֲשֶׁר בְּעֵקֶד נִשְׁפָּט. טְלָאָיו בּוֹ יְחֻנְּנוּ מִלְּהִשָּׁפֵט. חָלִילָה לְךָ אֱלֹהֵי הַמִּשְׁפָּט. זְכֹר לֹא יַעֲשֶׂה מִשְׁפָּט: וְאִם כְּאָדָם עָבְרוּ בְרִית. הָאֵל כָּאֵל הַבֵּט לַבְּרִית: <small>חזן </small><b>דִּבְּרוֹת, אֵלֶּה דִבְרֵי הַבְּרִית. גַּלֵּה בְּזִכְרוֹן שִׁלּוּשׁ בְּרִית:</b>", "<b>עוֹלָם </b>בְּבַקְּרָךְ בְּרֹאשׁ הַשָּׁנָה. בְּהַכְרָעַת צֶדֶק תַּכְרִיעַ שָׁנָה: <small>חזן </small>אֲסוּמָה טְלוּלָה גְּשׁוּמָה אִם שְׁחוּנָה. אֲטוּמִים לְהַחֲיוֹת בְּטַלְלֵי שֵׁנָה:", "<b>מִי כָמוֹךָ אַב הָרַחֲמִים, זוֹכֵר יְצוּרָיו לְחַיִּים בְּרַחֲמִים:</b>", "<b>וְנֶאֱמָן </b>אַתָּה לְהַחֲיוֹת מֵתִים: בָּרוּךְ אַתָּה יְהֹוָה מְחַיֶּה הַמֵּתִים:", "<small>מיוסד ע\"פ א\"ת ב\"ש (וכ' ול' כפול)</small>", "<b>אַף </b>אֹרַח מִשְׁפָּטֶיךָ יְהֹוָה קִוִּינוּךָ. תַּאֲוַת לֵב בַּצַּר פְּקַדְנוּךָ. בָּרֵי לֵבָב מֵאֶתְמוֹל קִדַּמְנוּךָ. שׁוֹפַר תְּרוּעָה טֶרֶם שִׁמַּעֲנוּךָ: גְּזֵרָה חַקְתָּ מִיצִירַת בְּרֵאשִׁית. רֹאשׁ דְּבָרְךָ תְּשׁוּבָה לְהָשִׁית. דִּין טֶרֶם הוּעֲרָךְ מֵרֵאשִׁית. קָדְמָה לְמַלֵּט שׁוֹבָבִים מֵחֲרִישִׁית: הַיּוֹצֵר יַחַד שְׁנֵי לְבָבֵיהֶם. צוֹפֶה וּמַבִּיט סַרְעַף קְרָבֵיהֶם. וְאִם אָוֶן נִרְאָה בְּמַחֲבוֹאֵיהֶם. פָּקוֹד תִּפְקֹד לָמוֹ קְרוֹבֵיהֶם: זֵכֶר הֲסָרַת שֶׁכֶם מִסֵּבֶל. עֶבֶד כְּהֻחְפַּשׁ מֵעִנּוּי כֶּבֶל. חֲנִיטָיו אִם תֻּעְתָּעוּ בְּתֶבֶל. שִׂיחוֹ יְחוֹנְנֵם לְחַיֵּי הָבֶל: טְמִינַת לֵב וּנְקִימַת קֵץ. נִדָּחִים לֶאֱסֹף בּוֹ בְקֵץ. יוֹם מוּכָן עִתִּים לְהָקֵץ. מִיָּמִים יָמִימָה וּמִקֵּץ לְקֵץ: כֶּסֶה לְהַקְפּוֹת חֹדֶשׁ לִקֹּב. כְּסוּחִים בְּלַהֲטוֹ לְהַבְהַב לִרְקֹב: <small>חזן </small><b>לְהָסִיר מִכְשׁוֹל מִלֵּב הֶעָקוֹב. לְהִזָּכֵר לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:</b>", "יִמְלֹךְ יְהֹוָה לְעֹלָם אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר הַלְלוּיָהּ:", "וְאַתָּה קָדוֹשׁ יוֹשֵׁב תְּהִלּוֹת יִשְׂרָאֵל, אֵל נָא:", "<small>חו\"ק </small><b>אֵל </b>אֱמוּנָה בְּעָרְכְּךָ דִין. אִם תְּמַצֶּה עֹמֶק הַדִּין. מִי יִצְדַּק לְפָנֶיךָ בַּדִּין. קָדוֹשׁ:", "<small>חו\"ק </small><b>אִם </b>לֹא לְמַעֲנוֹ יַעַשׂ. וְיָסִיר מֶנּוּ חֲרוֹן אַף וָכַעַס. אֵין לְבַקֵּר וְלִמְצֹא מַעַשׂ. קָדוֹשׁ:", "<small>כוונת הפייטן להזכיר מאדם הראשון עד יאשיהו, שכל אחד ואחד לא עמד זכאי בדין, ומזה יבינו כל יצורי ארץ, אם בצדיקים דקדק הקב\"ה כך, ברשעים עאכ\"ו. ושם המחבר כפול בראשי החרוזות <b>אלעזר בירבי קליר:</b></small>", "<b>אֹמֶץ </b>אַדִּירֵי כָּל חֵפֶץ. בְּהִתְבַּקְּרָם בַּדִּין חֻיְּבוּ לְנַפֵּץ. כְּלֹא נִמְצָא בָהֶם חֵפֶץ: אָדָם יְצִיר עָפָר מֵאֲדָמָה. לְאֵילֵי מָרוֹם אוֹתוֹ דִּמָּה. לֹא בָן וְלַהֶבֶל דָּמָה: לַעֲבֹד וְלִשְׁמֹר גַּן הִפְרִישׁוֹ. וְעָבַר עַל צִוּוּיוֹ וַיְגָרְשׁוֹ. וְיוֹם זֶה לְיֹשֶׁר דְּרָשׁוֹ: לְעֵת הֵאִיר אֶזְרָח מִמַּאֲפָל. עוֹלָם הָיָה תֹהוּ וּמְאֻפָּל. עֶשְׂרִים דּוֹר בָּזוּי וְשָׁפָל: עִקְשִׁים בְּאֹרַח מִישׁוֹר מַסְלוּל יִדַּע. וְעַל נָאֳמוֹ בַּמָּה אֵדַע. נִדּוֹן בְּקַו יָדֹעַ תֵּדַע: עוֹבְרִים בְּעֵמֶק הַבָּכָא לְהִבָּדֵק. אִם כְּפָעֳלָם בְּרִיב יְדַקְדֵּק. לִפְנֵי שׁוֹפֵט מִי יִצְטַדֵּק: זָךְ הַמַּשְׁלִים בְּעֵקֶד נֶפֶשׁ. בְּזֹקֶן לֹא מָצָא נֹפֶשׁ. וַתִּכְהֶיןָ עֵינָיו בַּעֲשַׁן טִפֵּשׁ: זַרְעוֹ רִגֵּל בְּאָהֳלֵי תוֹרָה. וְעַל אָמְרוֹ דַּרְכִּי נִסְתָּרָה. נִכְסָה מֶנּוּ פּוֹרָת בִּסְתִירָה. רָשָׁע אֲשֶׁר בְּמַחְבָּא יְחַתֵּר. צֶדֶק לְפָנָיו יְהַלֵּךְ וִינַתֵּר. אוּלַי בְּיוֹם אַף יִסָּתֵר: רֵעִים שְׁנֵים עָשָׂר כְּהִבְדִּיק. בְּרִיב אוֹתָם לֹא הִצְדִּיק. עַל מִכְרָם בַּכֶּסֶף צַדִּיק: בְּנֵי בְלִי שֵׁם בְּמָכְרָם עֲמוּסִים. בַּזּוֹנָה וּבַיַּיִן וּבְשׁוֹד חֲמָסִים. אֵיךְ בַּדִּין יִהְיוּ נֶעֱמָסִים: בְּהִתְיַצְּבוֹ לָרִיב בְּעָמְדוֹ לָדִין. עַל זֹאת אוֹתָם יָדִין. לְמַעַן יֵדְעוּן שַׁדּוּן בַּדִּין: יֶרֶד אֲשֶׁר הוֹרִיד אֲמָרִים. וְהִדְרִיר בְּכוֹר שׁוֹר מֵחֲמוֹרִים. וְנֶעֱנַשׁ בְּשִׁמְעוּ נָא הַמּוֹרִים: יַעַן אֲשֶׁר נוֹקַשׁ בְּעֶשֶׂר. נֶחֶרְתוּ בוֹ מִיתוֹת עֶשֶׂר. וּכְגָע גְּבוּל כֻּבַּל בְּאֹסֶר: רָאשֶׁיהָ אֲשֶׁר בְּשֹׁחַד יִשְׁפֹּטוּ. אֵיךְ בְּקַו צֶדֶק יִשָּׁפֵטוּ. כִּי אִם כְּמוֹ שָׁפָטוּ: רוֹבִים עֲלֵי אֵשׁ זָרָה. פָּגְעָה בָם בְּאַף גְּזֵרָה. לְלַמֵּד בָּם פּוֹשְׁעֵי פְזוּרָה: בַּעַר חָמַד מִן הַחֵרֶם. וְנִלְכַּד הוּא וְכָל אֲשֶׁר לוֹ בַּחֵרֶם. מִגָּדִישׁ וְעַד קָמָה וָכָרֶם: בּוֹגֵד וְשׁוֹדֵד מַה מּוֹעִיל. הוֹן בְּעֶבְרָה לֹא יוֹעִיל. כִּי אִם לְחַלּוֹת פְּנֵי מְלַמֵּד לְהוֹעִיל: יָד שָׁלַח אֱחֹז בָּאָרוֹן. נַעֲשָׂה בוֹ מִשְׁפָּט וְחָרוֹן. מַה יַּעֲשׂוּ עוֹבְרֵי כִּבְנֵי מָרוֹן: יוֹדֵעַ נַגֵּן כְּפָץ בְּחָנֵנִי. נִבְחַן וְנָאַם חִנָּם חָנֵּנִי. וְאַל תָּבוֹא בַמִּשְׁפָּט לְדַיְּנֵנִי: קוֹרְאֵי בְגָרוֹן וְקוֹל שׁוֹפָר. אִם פִּשְׁעָם בַּדִּין יְסֻפָּר. בְּמַתְּנַת חִנָּם הַיּוֹם יְכֻפָּר: קָצִין כְּגָאָה לְקַטֵּר לַשֵּׁם. נֶגַע בְּמִצְחוֹ זָרַח לְהֵרָשֵׁם. וְנִשְׁפַּט בְּלֹא יָדַע וְאָשֵׁם: לְעֵת תָּמוּט רֶגֶל זֵדִים. אֲשֶׁר בָּאוּ לְהֵיכָל מְזִידִים. יִשָּׁפְטוּ בְּמַכְנִיעַ זֵדִים: לְעֵת יְבֻקָּרוּ פּוֹעֲלֵי שֶׁקֶר. לְהִשָּׁפֵט בְּוִכּוּחַ אַף וָחֵקֶר. יִסָּכֵר פִּי דוֹבְרֵי שָׁקֶר: יָשָׁר מִתְהַלֵּךְ לְפָנָיו בֶּאֱמֶת. אֵיךְ אַחֲרֵי הַדְּבָרִים וְהָאֱמֶת. חִשַּׁב פָּעֳלוֹ אֱלֹהִים אֱמֶת: יְדִיד אֲשֶׁר לְפָנָיו וְאַחֲרָיו. לֹא קָם כָּמוֹהוּ בִּבְחִירָיו. וְאַחֲרֵי כָל זֹאת דִּקְדַּק אַחֲרָיו: יָבִינוּ כָּל יְצוּרֵי אֶרֶץ. אִם כַּךְ בִּמְצוּקֵי אֶרֶץ. מַה יַּעֲשׂוּ רִשְׁעֵי אָרֶץ: רָאֹה יִרְאוּ יַעֲרֵי שִׂיחִים. אִם אֵשׁ אָחֲזָה בַלַּחִים. אָז יָנוּעוּ יְבֵשִׁים כְּסוּחִים: רְאֵה כִּי אֵין אִישׁ. לְהַפְגִּיעַ בְּעַד בְּנֵי אִישׁ. וְאַתָּה אֵל וְלֹא אִישׁ: <small>חזן </small><b>רָשׁוּם בִּכְתַב אֱמֶת אֲשַׁנְּנָה. מַעֲשֵׂה כָּל יְמוֹת הַשָּׁנָה. לְרַצּוֹתְךָ בַּשּׁוֹפָר</b> (<small>בשבת </small>בְּזִכְרוֹן שׁוֹפָר) <b>בְּזֶה רֹאשׁ הַשָּׁנָה:</b>", "<small>חו\"ק </small><b>אִם </b>לֹא לְמַעֲנוֹ יַעַשׂ. וְיָסִיר מֶנּוּ חֲרוֹן אַף וָכַעַס. אֵין לְבַקֵּר וְלִמְצֹא מַעַשׂ. קָדוֹשׁ.", "וּבְכֵן וַיְהִי בִּישֻׁרוּן מֶלֶךְ:", "<small>פותחין הארון</small>", "השיר הזה נוסד ע\"פ א\"ב משולש", "<b>מֶלֶךְ עֶלְיוֹן: </b>אֵל דָּר בַּמָּרוֹם. אַדִּיר בַּמָּרוֹם. אֹמֶץ יָדוֹ תָּרוּם. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>גִּבּוֹר לְהָקִים. גּוֹזֵר וּמֵקִים. גּוֹלֶה עֲמוּקִים. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>הַמְדַבֵּר בִּצְדָקָה. הַלּוֹבֵשׁ צְדָקָה. הַמַּאֲזִין צְעָקָה. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>זוֹכֵר צוּרִים. זַכּוֹת יְצוּרִים. זוֹעֵם צָרִים. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>טוֹב שׁוֹכֵן עַד. טוּבוֹ לָעַד. טִפַּח שְׁמֵי עַד. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>כַּשַּׂלְמָה עוֹטֶה אוֹר. כָּל מְאוֹרֵי אוֹר. כַּבִּיר וְנָאוֹר. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>מֶלֶךְ עוֹלָמִים. מְפַעֲנֵחַ נֶעְלָמִים. מֵשִׂיחַ אִלְּמִים. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>סוֹבֵל הַכֹּל. סָב וּמְבַלֶּה כֹּל. סוֹקֵר הַכֹּל. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>פְּאֵרוֹ עֹז. פֹּעַל יְמִינוֹ תָּעֹז. פּוֹדֶה וּמָעֹז. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>קְדוֹשָׁיו לַהַב. קוֹרֵא מֵי רַהַב. קָרוֹב לְקוֹרְאָיו בְּאַהַב. לַעֲדֵי עַד יִמְלֹךְ:", "<b>מֶלֶךְ עֶלְיוֹן: </b>שֵׁנָה אֵין לְפָנָיו. שֶׁקֶט בִּפְנִינָיו. שֶׁבַח טוֹב בְּמַצְפּוּנָיו. לַעֲדֵי עַד יִמְלֹךְ:", "<small>סוגרין הארון</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>בָּלָה וְרָד שַׁחַת. בִּשְׁאוֹל וּבְתַחַת. בְּלֵאוּת בְּלִי נַחַת. עַד מָתַי יִמְלֹךְ:</small>", "<small>מכאן עד מלך אביון תנומה וכו' הושמט ברוב המחזורים ע\"י הצנזורה</small>", "<small>[מֶלֶךְ אֶבְיוֹן. דָּוֶה כַדֶּבֶר. דּוֹבֵר וְעוֹבֵר. דּוֹמֶה לְעִוֵּר. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>וְחָפֵץ בְּרֶשַׁע. וְעוֹשֶׂה רֶשַׁע. וּמוּכָן לְפֶשַׁע. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>חוֹשֵׁב וְשׁוֹכֵחַ. חָשׁ וּמִשְׁתַּכֵּחַ חָב וּמִתְוַכֵּחַ. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>יָמָיו טְפָחוֹת. יוֹמוֹ לְמַפָּחוֹת. יְחוּם טִפּוּחוֹת. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>לְצַלְמָוֶת יֻשְׁפַּל. לְרֶגֶב יְאֻפַּל. לְאַשְׁמָן יְקֻפַּל. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>נָע לִרְגָעִים. נֶחְפָּז מִפְּגָעִים. נִבְהָל בְּשִׁגּוּעִים. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>עוֹבֵר וּמִתְעַבֵּר. עַפְעַפָּיו מְעַוֵּר. עֲפָרוֹ צוֹבֵר. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>צַחֲנָה תַּבְאִישֶׁנּוּ. צוֹאָה תַּלְבִּישֶׁנּוּ. צִיָּה תִירָשֶׁנּוּ. עַד מָתַי יִמְלֹךְ:</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>רִמָּה לוֹבֵשׁ. רָטֹב וְיָבֵשׁ. רָשׁוּף בַּמַּיִם וּבָאֵשׁ. עַד מָתַי יִמְלֹךְ:]</small>", "<small><b>מֶלֶךְ אֶבְיוֹן. </b>תְּנוּמָה תְּעוּפֶנּוּ. תַּרְדֵּמָה תְּעוֹפְפֶנּוּ. תֹּהוּ יְשׁוּפֶנּוּ. עַד מָתַי יִמְלֹךְ:</small>", "<small>וחוזרין ופותחין הארון</small>", "<b>אֲבָל מֶלֶךְ עֶלְיוֹן:</b> תָּקְפּוֹ לָעַד. תִּפְאַרְתּוֹ עֲדֵי עַד. תְּהִלָּתוֹ עוֹמֶדֶת לָעַד. לַעֲדֵי עַד יִמְלֹךְ:", "<b>וּבְכֵן וּלְךָ תַעֲלֶה קְדֻשָּׁה כִּי אַתָּה הוּא אֱלֹהֵינוּ מֶלֶךְ:</b>", "<b>וּנְתַנֶּה </b>תֹּקֶף קְדֻשַּׁת הַיּוֹם. כִּי הוּא נוֹרָא וְאָיֹם. וּבוֹ תִנָּשֵׂא מַלְכוּתֶךָ. וְיִכּוֹן בְּחֶסֶד כִּסְאֶךָ. וְתֵשֵׁב עָלָיו בֶּאֱמֶת: אֱמֶת כִּי אַתָּה הוּא דַיָּן וּמוֹכִיחַ וְיוֹדֵעַ וָעֵד. וְכוֹתֵב וְחוֹתֵם (וְסוֹפֵר וּמוֹנֶה). וְתִזְכֹּר כָּל הַנִּשְׁכָּחוֹת. וְתִפְתַּח אֶת סֵפֶר הַזִּכְרוֹנוֹת. וּמֵאֵלָיו יִקָּרֵא. וְחוֹתָם יַד כָּל אָדָם בּוֹ. וּבְשׁוֹפָר גָּדוֹל יִתָּקַע. וְקוֹל דְּמָמָה דַקָּה יִשָּׁמַע. וּמַלְאָכִים יֵחָפֵזוּן. וְחִיל וּרְעָדָה יֹאחֵזוּן. וְיֹאמְרוּ הִנֵּה יוֹם הַדִּין. לִפְקֹד עַל צְבָא מָרוֹם בַּדִּין. כִּי לֹא יִזְכּוּ בְעֵינֶיךָ בַּדִּין. וְכָל בָּאֵי עוֹלָם יַעַבְרוּן לְפָנֶיךָ כִּבְנֵי מָרוֹן: <small>חזן </small>כְּבַקָּרַת רוֹעֶה עֶדְרוֹ. מַעֲבִיר צֹאנוֹ תַּחַת שִׁבְטוֹ. כֵּן תַּעֲבִיר וְתִסְפֹּר וְתִמְנֶה וְתִפְקֹד נֶפֶשׁ כָּל חָי. וְתַחְתֹּךְ קִצְבָה לְכָל בְּרִיּוֹתֶיךָ. וְתִכְתֹּב אֶת גְּזַר דִּינָם:", "<b>בְּרֹאשׁ </b>הַשָּׁנָה יִכָּתֵבוּן. וּבְיוֹם צוֹם כִּפּוּר יֵחָתֵמוּן. כַּמָּה יַעַבְרוּן. וְכַמָּה יִבָּרֵאוּן. מִי יִחְיֶה. וּמִי יָמוּת. מִי בְקִצּוֹ. וּמִי לֹא בְקִצּוֹ. מִי בַמַּיִם. וּמִי בָאֵשׁ. מִי בַחֶרֶב. וּמִי בַחַיָּה. מִי בָרָעָב. וּמִי בַצָּמָא. מִי בָרַעַשׁ. וּמִי בַמַּגֵּפָה. מִי בַחֲנִיקָה וּמִי בַסְּקִילָה. מִי יָנוּחַ. וּמִי יָנוּעַ. מִי יִשָּׁקֵט וּמִי יִטָּרֵף. מִי יִשָּׁלֵו. וּמִי יִתְיַסָּר. מִי יֵעָנִי. וּמִי יֵעָשֵׁר. מִי יִשָּׁפֵל. וּמִי יָרוּם:", "<small> צום קול ממון </small>", "<big>וּתְשׁוּבָה וּתְפִלָּה וּצְדָקָה</big>", "מַעֲבִירִין אֶת רֹעַ הַגְּזֵרָה:", "<b>כִּי </b>כְּשִׁמְךָ כֵּן תְּהִלָּתֶךָ. קָשֶׁה לִכְעֹס וְנוֹחַ לִרְצוֹת. כִּי לֹא תַחְפֹּץ בְּמוֹת הַמֵּת. כִּי אִם בְּשׁוּבוֹ מִדַּרְכּוֹ וְחָיָה. וְעַד יוֹם מוֹתוֹ תְּחַכֶּה לּוֹ. אִם יָשׁוּב מִיַּד תְּקַבְּלוֹ: <small>חזן </small>אֱמֶת כִּי אַתָּה הוּא יוֹצְרָם. וְאַתָּה יוֹדֵעַ יִצְרָם. כִּי הֵם בָּשָׂר וָדָם: אָדָם יְסוֹדוֹ מֵעָפָר. וְסוֹפוֹ לֶעָפָר. בְּנַפְשׁוֹ יָבִיא לַחְמוֹ. מָשׁוּל כְּחֶרֶס הַנִּשְׁבָּר. כְּחָצִיר יָבֵשׁ. וּכְצִיץ נוֹבֵל. כְּצֵל עוֹבֵר. וּכְעָנָן כָּלָה. וּכְרוּחַ נוֹשָׁבֶת. וּכְאָבָק פּוֹרֵחַ. וְכַחֲלוֹם יָעוּף:", "<big>וְאַתָּה הוּא מֶלֶךְ אֵל חַי וְקַיָּם:</big>", "<b>אֵין </b>קִצְבָה לִשְׁנוֹתֶיךָ. וְאֵין קֵץ לְאֹרֶךְ יָמֶיךָ: וְאֵין לְשַׁעֵר מַרְכְּבוֹת כְּבוֹדֶךָ. וְאֵין לְפָרֵשׁ עֵלוּם שְׁמֶךָ. שִׁמְךָ נָאֶה לְךָ. וְאַתָּה נָאֶה לִשְׁמֶךָ. וּשְׁמֵנוּ קָרָאתָ בִּשְׁמֶךָ:", "<b>עֲשֵׂה </b>לְמַעַן שְׁמֶךָ. וְקַדֵּשׁ אֶת שִׁמְךָ עַל מַקְדִּישֵׁי שְׁמֶךָ. בַּעֲבוּר כְּבוֹד שִׁמְךָ הַנַּעֲרָץ וְהַנִּקְדָּשׁ. כְּסוֹד שִׂיחַ שַׂרְפֵי קֹדֶשׁ. הַמַּקְדִּישִׁים שִׁמְךָ בַּקֹּדֶשׁ. דָּרֵי מַעְלָה עִם דָּרֵי מַטָּה. קוֹרְאִים וּמְשַׁלְּשִׁים בְּשִׁלּוּשׁ קְדֻשָּׁה בַּקֹּדֶשׁ:", "<small>סוגרין הארון</small>", "<b>כֶּתֶר </b>יִתְּנוּ לְךָ יְהֹוָה אֱלֹהֵינוּ מַלְאָכִים הֲמוֹנֵי מַעְלָה עִם עַמְּךָ יִשְׂרָאֵל קְבוּצֵי מַטָּה. יַחַד כֻּלָּם קְדֻשָּׁה לְךָ יְשַׁלֵּשׁוּ: כַּדָּבָר הָאָמוּר עַל יַד נְבִיאֶךָ וְקָרָא זֶה אֶל זֶה וְאָמַר: <small>קהל </small>קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְהֹוָה צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ: כְּבוֹדוֹ מָלֵא עוֹלָם מְשָׁרְתָיו שׁוֹאֲלִים זֶה לָזֶה אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים:", "<small>מיוסד ע\"פ א\"ב ושם המחבר לבסוף אלעזר:</small>", "<b>וְחַיּוֹת </b>אֲשֶׁר הֵנָּה מְרֻבָּעוֹת כִּסֵּא. בְּמָאתַיִם וַחֲמִשִּׁים וָשֵׁשׁ מַכְנִיפוֹת כִּסֵּא. גּוֹעֲשׁוֹת בּוֹ בְּסוֹכְכָם פָּנִים בְּפָנִים לַכִּסֵּא. דְּמוּת רָקִיעַ בְּרֹאשָׁם נָטוּי לַכִּסֵּא. הוּא כְּעֵין הַקֶּרַח וּבוֹ שְׁבִיב כִּסֵּא. וּמִמַּעַל לָרָקִיעַ כְּמַרְאֵה דְמוּת כִּסֵּא. זָעוֹת בְּלִי לֵאוֹת מֵחִיל כִּסֵּא. <small>חזן </small><b>חָשׁוֹת בְּרָצוֹא וָשׁוֹב מֵרְעִישׁוֹת כִּסֵּא. טָסוֹת כַּבָּזָק וְלֹא מְזִיזוֹת הוֹד כִּסֵּא. יוֹדְעוֹת כִּי כָל מָקוֹם לֹא יָכִיל מְקוֹם כִּסֵּא:</b>", "<b>כַּף </b>רֶגֶל חֲמֵשׁ מֵאוֹת וַחֲמֵשׁ עֶשְׂרֵה יְשָׁרָה לַכִּסֵּא. לְעֵת תֵּרָשֶׁינָה לְפָאֵר קוֹפְצוֹת מִתַּחַת לַכִּסֵּא. מִתְעַלְּפוֹת מִפַּחַד רָם יוֹשֵׁב עַל כִּסֵּא. נִרְאוֹת נוֹשְׂאוֹת וְהֵם נְשׂוּאוֹת עִם כִּסֵּא. סְבוּלוֹת מִתַּחַת זְרוֹעוֹת עוֹלָם לַכִּסֵּא. עֲתִירַת זוֹ כְּתַעַל תְּרַפֶּינָה כְּנַף כִּסֵּא. פְּשָׁעִים אִם עָצְמוּ מַשִּׁיקוֹת כִּסֵּא. צוֹרֵר כִּי יַשְׂטִין יְפַרְשֵׁז עֲנַן כִּסֵּא. קוֹל שׁוֹפָר לְעֵת יַעַל מְאַחֵז פְּנֵי כִסֵּא. רַחֲמִים יָלִיץ בְּעַד רְשׁוּמִים בַּכִּסֵּא. שׁוֹפֵט אִם יִרְצֶה מִשֶּׁבֶת בְּאוּלָם הַכִּסֵּא. תַּבְנִית תָּם יִפֶן חֲקוּקָה בַכִּסֵּא. אַרְבַּע חַיּוֹת נוֹשְׂאוֹת וּמְנֻשָּׂאוֹת עִם כִּסֵּא. <small>חזן </small><b>לְבִלְתִּי לְנַבֵּל לְמַעֲנוֹ כִּסֵּא. עוֹד יִפְצֶה פֶה וְיַפְגִּיעַ כִּסֵּא. זְכֹר לְיוֹשְׁבֵי נְטָעִים אֲשֶׁר עִמְּךָ בַּכִּסֵּא:</b>", "<small>חזן </small><b>רַחֵם </b>מְצוּקִים אֲשֶׁר עֲלֵיהֶם שַׂמְתָּ הֲדוֹם וְכִסֵּא. וְאָז <b>יִ</b>תְרַעֵם <b>הַ</b>גַּלְגַּל <b>וְ</b>יִתְרַעֵשׁ <b>הַ</b>כִּסֵּא. וְאוֹפָן לְאוֹפָן וּכְרוּב לִכְרוּב וְחַיָּה לְחַיָּה לְעֻמַּת כִּסֵּא:", "<small>חזן </small><b>כְּבוֹדוֹ </b>מָלֵא עוֹלָם מְשָׁרְתָיו שׁוֹאֲלִים זֶה לָזֶה אַיֵּה*)<i> בתפלת מוסף בר\"ה ויו\"כ בשעה שמאריך החזן בקדושה בתיבת אַיֵּה מקום כבודו ישאל א' מג' דברים אלו, או עושר מופלג לעבודתו, או בנים צדיקים וחסידים וחכמים, או השגת רוח הקודש, ויאמר:<br>יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ שֶׁתִּתֶּן לִי הַיּוֹם מַתָּנָה טוֹבָה מֵאוֹצְרוֹת מַתְּנַת חִנָּם אַף עַל פִּי שֶׁאֵינִי כְדַאי כְּדִכְתִיב וְחַנּוֹתִי אֶת אֲשֶׁר אָחֹן.</i> מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ. לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים: <small>קו\"ח</small> בָּרוּךְ כְּבוֹד יְהֹוָה מִמְּקוֹמוֹ: <small>קהל </small>מִמְּקוֹמוֹ הוּא יִפֶן בְּרַחֲמָיו לְעַמּוֹ וְיָחֹן עַם הַמְיַחֲדִים שְׁמוֹ עֶרֶב וָבֹקֶר בְּכָל יוֹם תָּמִיד פַּעֲמַיִם בְּאַהֲבָה שְׁמַע אוֹמְרִים:", "<small>לפרנסה: </small>וְתִתֶּן לִי וּלְכָל בְּנֵי בֵיתִי וּלְכָל הַסְּמוּכִים עַל שֻׁלְחָנִי בַּיּוֹם הַזֶּה וּבְכָל יוֹם וָיוֹם מְזוֹנוֹתֵינוּ בְּכָבוֹד וּבְרֶוַח בִּזְכוּת שִׁמְךָ הַגָּדוֹל דִיקָרְנוּסָא (<small>ס\"א ניקוד כזה </small>דֵיקַרְנוּסָא) הַמְמֻנֶּה עַל הַפַּרְנָסָה. וְאַל תַּצְרִיכֵנוּ לִידֵי מַתְּנַת בָּשָׂר וָדָם כִּי אִם בְּשִׁמְךָ חָנֵּנוּ וּמֵאוֹצַר מַתְּנַת חִנָּם תְּכַלְכְּלֵנוּ וְתַשְׁפִּיעֵנוּ, אָמֵן אָמֵן אָמֵן סֶלָה סֶלָה סֶלָה:", "<small>על השגת רוה\"ק: </small>וְתִגְזֹר עָלַי <small>(פב\"פ) </small>גְּזֵרוֹת טוֹבוֹת מִלִּפְנֵי כִסֵּא כְבוֹדֶךָ וְתִתֶּן לִי לֵב מֵבִין וּלְהַשִּׂיג רוּחַ הַקֹּדֶשׁ:", "<small>על בנים צדיקים: </small>וְתִתֶּן לִי בָּנִים טוֹבִים וּכְשֵׁרִים וַהֲגוּנִים לַעֲסֹק בְּתוֹרָתֶךָ וּבְמִצְו‍ֹתֶיךָ:", "יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אָבִינוּ שֶׁבַּשָּׁמַיִם שֶׁתְּמַלֵּא שְׁאֵלָתִי וּבַקָּשָׁתִי הַיּוֹם הַזֶּה בְּשֵׁם יֻהָ <small>(והנקודות הם מ\"ו כמנין מילוי ע\"ב ו\"ד י' ו\"ו י' והב' אותיות י\"ה דאי\"ה) </small>וְתַמְשִׁיךְ לִי שֶׁפַע טוֹב מִן סוֹד הַכֶּתֶר הַנִּרְמָז בָּאוֹת א' אַיֵּה, לְאַבָּא וְאִמָּא סוֹד י\"ה שֶׁל אַיֵּה, וּמִשָּׁם לְדוּכְרָא וְנוּקְבָא, וּמִשָּׁם לְעַבְדְּךָ <small>(פב\"פ) </small>הָעוֹמֵד וּמְבַקֵּשׁ מִלִּפְנֵי כִסֵּא כְבוֹדֶךָ. וְאַל תְּשִׁיבֵנִי רֵיקָם מִלְּפָנֶיךָ, אָמֵן כֵּן יְהִי רָצוֹן:", "<small>ויכוין בכ\"ד שמות דכ\"ד ספרים:</small>", "<b>יֻפָ עֻנָ הֻתָ הֻתָ הֻדָ דֻיָ מֻיָ הֻדָ אֻמָ אֻתָ בֻנָ הֻםָ שֻׁםָ אֻתָ וֻוָ אֻתָ שֻׁהָ לֻבָ הֻהָ אֻבָ לֻהָ לֻךָ אֻרָ הֻםָ:</b>", "<small>מיוסד ע\"פ תשר\"ק ובסוף חתום שם המחבר <b>אלעזר:</b></small>", "<b>וְעַמְּךָ </b>תְלוּאִים בִּתְשׁוּבָה לְהִתְיַחֵד. שְׁנֵי לְבָבוֹת לְךָ כְּאַחַד לְאֶחָד. רַחֵץ בְּנִקְיוֹן כַּפַּיִם נְשׂוֹא לֵב אֶחָד. קוֹל שׁוֹפָר כָּפוּף כְּפֹף לֵב אֶחָד. צִיּוּן שׁוֹפָר פָּשׁוּט פְּשֹׁט לֵב אֶחָד: פּוּר יָמִים יֻצָּרוּ בָּם לָבוּר אֶחָד. עוֹבְרִים בּוֹ לְהַקְבִּיל פְּנֵי יוֹצֵר אֶחָד: <small>חזן </small>סְמוּכִים בְּצִדְקַת אָב הָיָה אֶחָד. נִשְׁעָנִים בַּסְּבַךְ יָחִיד וּמְיֻחָד. מֻבְטָחִים בְּתָם (<small>נ\"א </small>בְּתֹם) וּבְיֹשֶׁר אָב אֶחָד:", "<b>לְהִזָּכֵר </b>לָמוֹ עֲנָיַת קוֹל אֶחָד. כְּשִׁבְתּוֹ בַכִּסֵּא שְׁפֹט גּוֹי אֶחָד. יַעֲמִיד מֵלִיץ יֹשֶׁר מִנִּי אֶלֶף אֶחָד. טוֹבוֹת לְהַגִּיד בַּשְּׁבִיעִי בְּאֶחָד. חָשׁוּב גֵּר וְאֶזְרָח לְמִשְׁפָּט אֶחָד. זָךְ וָרַע מֵהַיּוֹם מוֹדַע דִּינָם לְאֶחָד. וַאֲשֶׁר מַעֲשָׂיו שְׁקוּלִים עַד עָשׂוֹר יוּאֲחָד. הוּא כְּחָפֵץ לְהַצְדִּיק עֲשֶׂרֶת יְמֵי תְשׁוּבָה יִחַד. דֶּלֶת פְּתוּחָה לַשָּׁבִים תֵּת צֳרִי לְכָל אֶחָד וְאֶחָד. גּוֹלֶה זְכוּת וָרֶשַׁע לְהַגִּישׁ אֶחָד בְּאֶחָד. בִּקּוּר חֶשְׁבּוֹן לִמְצֹא אֶחָד לְאֶחָד: <small>חזן </small>אִם יַשְׁקִיט וּמִי יַרְשִׁיעַ לַהֲשִׁיבֶנּוּ וְהוּא בְּאֶחָד. אֱמֶת חוֹתָמוֹ לְהוֹדִיעַ כִּי הוּא אֶחָד. לְעֵת תָּמוּט וּכְכַל יַד עַם אֶחָד:", "<b>עוֹד </b>יִזְכָּר לָמוֹ מִטַּת שְׁכֶם אֶחָד. זֹאת הַמַּתְמֶדֶת שְׁמַע פֶּה אֶחָד. רוֹגֶשֶׁת נֶשֶׁף וָשַׁחַר לְיַחֵד לְאֶחָד:", "<small>חזן </small><b>מִמְּקוֹמוֹ </b>הוּא יִפֶן בְּרַחֲמָיו לְעַמּוֹ וְיָחֹן עַם הַמְיַחֲדִים שְׁמוֹ עֶרֶב וָבֹקֶר בְּכָל יוֹם תָּמִיד פַּעֲמַיִם בְּאַהֲבָה שְׁמַע אוֹמְרִים: <small>קו\"ח </small>שְׁמַע יִשְׂרָאֵל יְהֹוָה אֱלֹהֵינוּ יְהֹוָה אֶחָד: <small>קהל </small>הוּא אֱלֹהֵינוּ הוּא אָבִינוּ הוּא מַלְכֵּנוּ הוּא מוֹשִׁיעֵנוּ. וְהוּא יוֹשִׁיעֵנוּ וְיִגְאָלֵנוּ שֵׁנִית. וְיַשְׁמִיעֵנוּ בְּרַחֲמָיו שֵׁנִית לְעֵינֵי כָּל חַי לֵאמֹר. הֵן גָּאַלְתִּי אֶתְכֶם אַחֲרִית כְּרֵאשִׁית לִהְיוֹת לָכֶם לֵאלֹהִים:", "<small>כתב הראב\"ן: אל ישיאך הפסקות של רבי אלעזר הקליר שתהא סבור כשאתה מגיע להפסקה והוא חוזר ומתחיל שהענין של מטה מופלג מענין של מעלה, דע לך כי סמוך ומחובר הוא, לפי שאמר למעלה שישראל רוגשים נשף ושחר בק\"ש לכן אמר ואתה הקב\"ה אזון קול מפאריך בכל איבריהם אלו ישראל שקורין ק\"ש שיש בה רמ\"ח תיבות כמנין איברים שבאדם, ותפס לו הלשון שמצא במדרש, שכך שמע מרבי עזריאל שהלשון הזה מצא במדרש צדיקים שבישראל מתיראים מיום הדין ומברכים ומיחדים ומקדשים להקב\"ה בכל איבריהם, ובמיתתן הקב\"ה מרביצן בכבוד גדול תחת עץ החיים ובקבריהם נותן להם מנוחה, ובכל ערב שבת ויו\"ט עומדים מקבריהם ומשבחים להקב\"ה שנאמר יעלזו חסידים בכבוד ירננו על משכבותם, ואחר הלשון הזה יסד הפיוט הזה, עכ\"ל.</small>", "<small>מיוסד מהקליר ע\"פ א\"ת ב\"ש:</small>", "<b>וְאַתָּה </b>אֱזֹן קוֹל מְפָאֲרֶיךָ בְּכָל אֵיבָרֵיהֶם, תֹּכֶן מִצְו‍ֹת מַעֲשֵׂיהֶם, בְּמָאתַיִם וְאַרְבָּעִים וּשְׁמוֹנָה אֵיבָרֵיהֶם. בְּזֶה חֹדֶשׁ תְּקֹעַ שְׁלֹשִׁים, כְּמוֹ שְׁלֹשִׁים בְּכַף רַגְלֵיהֶם. שַׁי מוּסְפֵי יוֹם עֲשָׂרָה, כְּמוֹ עֲשָׂרָה בְּקַרְסֻלֵּיהֶם. גָּשִׁים פְּנֵי תֵבָה שַׁחֲרִית שְׁתַּיִם, כְּמוֹ שְׁתַּיִם בְּשׁוֹקֵיהֶם. רְשׁוּמִים קְרוֹת בּוֹ חֲמִשָּׁה, כְּמוֹ חֲמִשָּׁה עַל בִּרְכֵּיהֶם: דְּרוּשִׁים תְּקֹעַ בַּכֶּסֶה בְּאֶחָד, כְּמוֹ אֶחָד בְּיַרְכוֹתֵיהֶם. קֶרֶן יִמְשְׁכוּ לְשַׁלֵּשׁ שְׁלֹשָׁה, כְּמוֹ שְׁלֹשָׁה בְּקוֹטָלֵיהֶם. הֵן מוּסְפֵי חֹדֶשׁ עַשְׁתֵּי עֶשְׂרֵה, כְּמוֹ עַשְׁתֵּי עֶשְׂרֵה צַלְעוֹתֵיהֶם. צְקוֹן לַחֲשָׁם בְּרָכוֹת תֵּשַׁע, כְּמוֹ תִּשְׁעָה שֶׁבִּזְרוֹעוֹתֵיהֶם. וּמַלְכֻיּוֹת וְזִכְרוֹנוֹת וְשׁוֹפָרוֹת שְׁלֹשִׁים, כְּמוֹ שְׁלֹשִׁים בְּפִסַּת יְדֵיהֶם. פִּלּוּל תְּמִידִים שְׁמוֹנֶה עֶשְׂרֵה, כְּמוֹ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁבְּשֶׁדְרוֹתֵיהֶם. זִבְחֵי תְמִידִים תְּקִיעוֹת תֵּשַׁע, כְּמוֹ תִּשְׁעָה שֶׁבְּרָאשֵׁיהֶם. עֲתִירוֹת שְׁתַּיִם שְׁחוֹחַ בָּם שְׁמוֹנָה, כְּמוֹ שְׁמוֹנָה שֶׁבְּצַוְּארֵיהֶם. חֹק דָּתָם סְפָרִים חֲמִשָּׁה, כְּמוֹ חֲמִשָּׁה שֶׁבְּנִקְבֵיהֶם. שָׂם הֲלִיכוֹת עוֹלָם שִׁשָּׁה, כְּמוֹ שִׁשָּׁה בִּלְבָבֵיהֶם. טוּחוֹת וָכֶסֶל וְשֶׂכְוִי וְסַרְעַף וּבֶטֶן וָקֶרֶב וְעֶשְׁתְּנוֹתֵיהֶם. נֶפֶשׁ רוּחַ נְשָׁמָה יְחִידָה חַיָּה, עוֹר וּבָשָׂר וְגִיד וְעַצְמוֹתֵיהֶם: <small>חזן </small>יִשְׂאוּ עַיִן וְיִכְרוּ אֹזֶן וְיִפְצוּ פֶה וְלָשׁוֹן וְנִיב שִׂפְתוֹתֵיהֶם. מִכַּף רֶגֶל וְעַד רֹאשׁ נִתְוַכְּחוּ פְּרֹט מַעֲשֵׂיהֶם. כִּתְקֹעַ שׁוֹפָר בְּקוֹל יַחְפְּרוּ שׂוֹטְנֵיהֶם, לְהַצְדִּיקָם בְּיוֹם דִּין שְׁמֹעַ שֵׁנִית מֵאֱלֹהֵיהֶם:", "<small>חזן </small><b>הוּא </b>אֱלֹהֵינוּ הוּא אָבִינוּ הוּא מַלְכֵּנוּ הוּא מוֹשִׁיעֵנוּ וְהוּא יוֹשִׁיעֵנוּ וְיִגְאָלֵנוּ שֵׁנִית. וְיַשְׁמִיעֵנוּ בְּרַחֲמָיו שֵׁנִית לְעֵינֵי כָּל חַי לֵאמֹר. הֵן גָּאַלְתִּי אֶתְכֶם אַחֲרִית כְּרֵאשִׁית לִהְיוֹת לָכֶם לֵאלֹהִים: <small>קו\"ח </small>אֲנִי יְהֹוָה אֱלֹהֵיכֶם: <small>קהל </small>אַדִּיר אַדִּירֵנוּ יְהֹוָה אֲדוֹנֵינוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ: וְהָיָה יְהֹוָה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד:", "<small>ראשי החרוזות מיוסדים ע\"פ תשר\"ק עד כ' ואמצע החרוזות ע\"פ א\"ב עד י':</small>", "<b>תְּהִלּוֹת </b>כְּבוֹדְךָ אָמְצָךְ מְלֹא כָל הָאָרֶץ. שִׁמְעֲךָ דִין מִשָּׁמַיִם בְּכֵן יָרְאָה וְשָׁקְטָה הָאָרֶץ. רַעַשׁ יוֹם מִשְׁפָּט גָּעֲשׁוּ תְּהוֹמוֹת הָאָרֶץ. קוֹל שׁוֹפָר חָזָק דִּבֶּר וַיִּקְרָא אָרֶץ. צְבִי לַצַּדִּיק בְּזֶמֶר הִשְׁמִיעַ מִכְּנַף הָאָרֶץ. פַּחַד וָפַחַת וָפַח וּפַלָּצוּת יַבְעִיתוּ אָרֶץ. עֵת תָּקוּם לַמִּשְׁפָּט זְעֹם כָּל אַפְסֵי אָרֶץ: <small>חזן </small>סֹלּוּ פַּנּוּ (<small>נ\"א </small>סוּרוּ מֶנִּי) דֶרֶךְ יְנוֹבְבוּ חֲרֵדִים מֵחֶרְדַּת הָאָרֶץ. נָאוֹר וְאַדִּיר טַעַם תָּשִׁיב לָאָרֶץ. מַה תִּירְאִי אֲדָמָה יָרִיעוּ תַּחְתִּיּוֹת אָרֶץ:", "<small>חזן </small><b>לְהִתְוַדַּע </b>וּלְהִגָּלוֹת. כִּי הוּא מֶלֶךְ עַל כָּל הָאָרֶץ. כְּמוֹ פֶאֱרוּהוּ מֵאָז בַּשַּׁחַק. יוּרְשׁוּ בְחוּנָיו לְפָאֲרוֹ בָאָרֶץ:", "<small>חזן </small><b>אַדִּיר </b>אַדִּירֵנוּ יְהֹוָה אֲדוֹנֵנוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ: וְהָיָה יְהֹוָה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד: <small>קו\"ח </small>וּבְדִבְרֵי קָדְשְׁךָ כָּתוּב לֵאמֹר: יִמְלֹךְ יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיּוֹן לְדֹר וָדֹר הַלְלוּיָהּ:", "<small>בק\"ק אומר החזן אתה קדוש וכו'</small>", "<b>לְדוֹר </b>וָדוֹר נַגִּיד גָּדְלֶךָ וּלְנֵצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ. וְשִׁבְחֲךָ אֱלֹהֵינוּ מִפִּינוּ לֹא יָמוּשׁ לְעוֹלָם וָעֶד. כִּי אֵל מֶלֶךְ גָּדוֹל וְקָדוֹשׁ אָתָּה:", "לְדוֹר וָדוֹר הַמְלִיכוּ לָאֵל כִּי הוּא לְבַדּוֹ מָרוֹם וְקָדוֹשׁ:", "<b>חֲמוֹל</b> עַל מַעֲשֶׂיךָ. וְתִשְׂמַח בְּמַעֲשֶׂיךָ. וְיֹאמְרוּ לְךָ חוֹסֶיךָ. בְּצַדֶּקְךָ עֲמוּסֶיךָ. תֻּקְדַּשׁ אָדוֹן עַל כָּל מַעֲשֶׂיךָ: כִּי מַקְדִּישֶׁיךָ בִּקְדֻשָּׁתְךָ (<small>נ\"א </small>כְּעֶרְכְּךָ) קִדַּשְׁתָּ. נָאֶה לְקָדוֹשׁ פְּאֵר מִקְּדוֹשִׁים:", "<b>וּבְכֵן </b>יִתְקַדֵּשׁ שִׁמְךָ יְהֹוָה אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ. וְעַל מַלְכוּת בֵּית דָּוִד מְשִׁיחֶךָ וְעַל מְכוֹנָךְ וְהֵיכָלָךְ:", "<small>צריך להפסיק בין תיבת איתן לתיבת אדונינו, כי אדונינו קאי על הש\"י:</small>", "<b>עוֹד </b>יִזְכֹּר לָנוּ אַהֲבַת אֵיתָן, אֲדוֹנֵינוּ. וּבַבֵּן הַנֶּעֱקַד יַשְׁבִּית מְדַיְּנֵנוּ. וּבִזְכוּת הַתָּם יוֹצִיא אָיוֹם (<small>נ\"א </small>הַיּוֹם) לְצֶדֶק דִּינֵנוּ. כִּי קָדוֹשׁ הַיּוֹם לַאֲדוֹנֵינוּ:", "<b>בְּאֵין </b>מֵלִיץ יֹשֶׁר מוּל מַגִּיד פֶּשַׁע. תַּגִּיד לְיַעֲקֹב דְּבַר חֹק וּמִשְׁפָּט. וְצַדְּקֵנוּ בַּמִּשְׁפָּט הַמֶּלֶךְ הַמִּשְׁפָּט:", "<small>מהר\"י סג\"ל היה אומר תיבת המשפט עם האוחז בנשימה אחת</small>", "<small>פותחין הארון</small>", "<small>מיוסד ע\"פ א\"ב</small>", "הָאוֹחֵז בְּיַד מִדַּת מִשְׁפָּט:", "וְכֹל מַאֲמִינִים שֶׁהוּא אֵל אֱמוּנָה:", "הַבּוֹחֵן וּבוֹדֵק גִּנְזֵי נִסְתָּרוֹת:", "וְכֹל מַאֲמִינִים שֶׁהוּא בּוֹחֵן כְּלָיוֹת:", "הַגּוֹאֵל מִמָּוֶת וּפוֹדֶה מִשַּׁחַת:", "וְכֹל מַאֲמִינִים שֶׁהוּא גּוֹאֵל חָזָק:", "הַדָּן יְחִידִי לְבָאֵי עוֹלָם:", "וְכֹל מַאֲמִינִים שֶׁהוּא דַּיָּן אֱמֶת:", "הֶהָגוּי בְּאֶהְיֶה אֲשֶׁר אֶהְיֶה:", "וְכֹל מַאֲמִינִים שֶׁהוּא הָיָה הֹוֶה וְיִהְיֶה:", "הַוַּדַּאי שְׁמוֹ כֵּן תְּהִלָּתוֹ:", "וְכֹל מַאֲמִינִים שֶׁהוּא וְאֵין בִּלְתּוֹ:", "הַזּוֹכֵר לְמַזְכִּירָיו טוֹבוֹת זִכְרוֹנוֹת:", "וְכֹל מַאֲמִינִים שֶׁהוּא זוֹכֵר הַבְּרִית:", "הַחוֹתֵךְ חַיִּים לְכָל חַי:", "וְכֹל מַאֲמִינִים שֶׁהוּא חַי וְקַיָּם:", "הַטּוֹב, וּמֵטִיב לָרָעִים וְלַטּוֹבִים:", "וְכֹל מַאֲמִינִים שֶׁהוּא טוֹב לַכֹּל:", "הַיּוֹדֵע יֵצֶר כָּל יְצוּרִים:", "וְכֹל מַאֲמִינִים שֶׁהוּא יוֹצְרָם בַּבָּטֶן:", "הַכֹּל יָכוֹל וְכוֹלְלָם (<small>נ\"א </small>יוּכַל וְכִלְּלָם) יָחַד:", "וְכֹל מַאֲמִינִים שֶׁהוּא כֹּל יָכוֹל:", "הַלָּן בְּסֵתֶר בְּצֵל, שַׁדַּי:", "וְכֹל מַאֲמִינִים שֶׁהוּא לְבַדּוֹ הוּא:", "הַמַּמְלִיךְ מְלָכִים וְלוֹ הַמְּלוּכָה:", "וְכֹל מַאֲמִינִים שֶׁהוּא מֶלֶךְ עוֹלָם:", "הַנּוֹהֵג בְּחַסְדּוֹ כָּל דּוֹר:", "וְכֹל מַאֲמִינִים שֶׁהוּא נוֹצֵר חֶסֶד:", "הַסּוֹבֵל, וּמַעְלִים עַיִן מִסּוֹרְרִים:", "וְכֹל מַאֲמִינִים שֶׁהוּא סוֹלֵחַ סֶלָה:", "הָעֶלְיוֹן, וְעֵינוֹ אֶל יְרֵאָיו:", "וְכֹל מַאֲמִינִים שֶׁהוּא עוֹנֶה לָחַשׁ:", "הַפּוֹתֵחַ שַׁעַר לְדוֹפְקֵי בִתְשׁוּבָה:", "וְכֹל מַאֲמִינִים שֶׁהוּא פְּתוּחָה יָדוֹ:", "הַצּוֹפֶה לָרָשָׁע וְחָפֵץ בְּהִצָּדְקוֹ:", "וְכֹל מַאֲמִינִים שֶׁהוּא צַדִּיק וְיָשָׁר:", "הַקְּצַר בְּזַעַם וּמַאֲרִיךְ אַף:", "וְכֹל מַאֲמִינִים שֶׁהוּא קָשֶׁה לִכְעֹס:", "הָרַחוּם וּמַקְדִּים רַחֲמִים לְרֹגֶז:", "וְכֹל מַאֲמִינִים שֶׁהוּא רַךְ לִרְצוֹת:", "הַשָּׁוֶה וּמַשְׁוֶה קָטֹן וְגָדוֹל:", "וְכֹל מַאֲמִינִים שֶׁהוּא שׁוֹפֵט צֶדֶק:", "הַתָּם וּמִתַּמֵּם עִם תְּמִימִים:", "וְכֹל מַאֲמִינִים שֶׁהוּא תָּמִים פָּעֳלוֹ:", "<b>תֻּשְׂגַּב </b>לְבַדְּךָ וְתִמְלֹךְ עַל כֹּל בְּיִחוּד: כַּכָּתוּב עַל יַד נְבִיאֶךָ וְהָיָה יְהֹוָה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד:", "<small>כשסיים \"האוחז ביד\" יאמר אנא בכח וכו' ואח\"כ יאמר זה:</small>", "<b>בְּשִׁמְךָ </b>שַׁדַּי יְהֹוָה צְבָאוֹת שֶׁתַּעֲשֶׂה שְׁאֵלָתִי וּבַקָּשָׁתִי. וְהָיָה יְהֹוָה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד:", "<b>וּבְכֵן </b>תֵּן פַּחְדְּךָ יְהֹוָה אֱלֹהֵינוּ, עַל כָּל מַעֲשֶׂיךָ, וְאֵימָתְךָ עַל כָּל מַה שֶּׁבָּרָאתָ, וְיִירָאוּךָ כָּל הַמַּעֲשִׂים, וְיִשְׁתַּחֲווּ לְפָנֶיךָ כָּל הַבְּרוּאִים. וְיֵעָשׂוּ כֻלָּם אֲגֻדָּה אֶחָת, לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם. כְּמוֹ שֶׁיָּדַעְנוּ יְהֹוָה אֱלֹהֵינוּ, שֶׁהַשָּׁלְטָן לְפָנֶיךָ, עוֹז בְּיָדְךָ, וּגְבוּרָה בִּימִינֶךָ. וְשִׁמְךָ נוֹרָא עַל כָּל מַה שֶּׁבָּרָאתָ:", "<b>וּבְכֵן </b>תֵּן כָּבוֹד יְהֹוָה לְעַמֶּךָ, תְּהִלָּה לִירֵאֶיךָ, וְתִקְוָה טוֹבָה לְדוֹרְשֶׁיךָ, וּפִתְחוֹן פֶּה לַמְיַחֲלִים לָךְ, שִׂמְחָה לְאַרְצֶךָ, וְשָׂשׂוֹן לְעִירֶךָ, וּצְמִיחַת קֶרֶן לְדָוִד עַבְדֶּךָ, וַעֲרִיכַת נֵר לְבֶן יִשַׁי מְשִׁיחֶךָ, בִּמְהֵרָה בְיָמֵינוּ:", "<b>וּבְכֵן </b>צַדִּיקִים יִרְאוּ וְיִשְׂמָחוּ, וִישָׁרִים יַעֲלֹזוּ, וַחֲסִידִים בְּרִנָּה יָגִילוּ, וְעוֹלָתָה תִּקְפָּץ פִּיהָ, וְכָל הָרִשְׁעָה כֻּלָּהּ כֶּעָשָׁן תִּכְלֶה, כִּי תַעֲבִיר מֶמְשֶׁלֶת זָדוֹן מִן הָאָרֶץ:", "<b>וְיֶאֱתָיוּ </b>כֹל לְעָבְדֶךָ. וִיבָרְכוּ שֵׁם כְּבוֹדֶךָ. וְיַגִּידוּ בָאִיִּים צִדְקֶךָ. וְיִדְרְשׁוּךָ עַמִּים לֹא יְדָעוּךָ. וִיהַלְלוּךָ כָּל אַפְסֵי אָרֶץ. וְיֹאמְרוּ תָמִיד יִגְדַּל יְהֹוָה. (וְיִזְבְּחוּ לְךָ אֶת זִבְחֵיהֶם.) וְיִזְנְחוּ אֶת עֲצַבֵּיהֶם. וְיַחְפְּרוּ עִם פְּסִילֵיהֶם. וְיַטּוּ שְׁכֶם אֶחָד לְעָבְדֶךָ. וְיִירָאוּךָ עִם שֶׁמֶשׁ מְבַקְשֵׁי פָנֶיךָ. וְיַכִּירוּ כֹּחַ מַלְכוּתֶךָ. וִילַמְּדוּ תוֹעִים בִּינָה. וִימַלְלוּ אֶת גְּבוּרָתֶךָ. וִינַשְּׂאוּךָ מִתְנַשֵּׂא לְכֹל לְרֹאשׁ. וִיסַלְּדוּ בְחִילָה פָּנֶיךָ. וִיעַטְּרוּךָ נֵזֶר תִּפְאָרָה. וְיִפְצְחוּ הָרִים רִנָּה. וְיִצְהֲלוּ אִיִּים בְּמָלְכֶךָ. וִיקַבְּלוּ עֹל מַלְכוּתְךָ עֲלֵיהֶם. וִירוֹמְמוּךָ בִּקְהַל עָם. וְיִשְׁמְעוּ רְחוֹקִים וְיָבוֹאוּ. וְיִתְּנוּ לְךָ כֶּתֶר מְלוּכָה:", "<b>וְתִמְלוֹךְ </b>אַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ מְהֵרָה לְבַדֶּךָ עַל כָּל מַעֲשֶׂיךָ, בְּהַר צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ. וּבִירוּשָׁלַיִם עִיר קָדְשֶׁךָ. כַּכָּתוּב בְּדִבְרֵי קָדְשֶׁךָ: יִמְלוֹךְ יְהֹוָה לְעוֹלָם אֱלֹהַיִךְ צִיּוֹן לְדוֹר וָדוֹר, הַלְלוּיָהּ:", "<b>קָדוֹשׁ </b>אַתָּה וְנוֹרָא שְׁמֶךָ, וְאֵין אֱלוֹהַּ מִבַּלְעָדֶיךָ, כַּכָּתוּב, וַיִּגְבַּהּ יְהֹוָה צְבָאוֹת בַּמִּשְׁפָּט, וְהָאֵל הַקָּדוֹשׁ נִקְדַּשׁ בִּצְדָקָה. בָּרוּךְ אַתָּה יְהֹוָה, הַמֶּלֶךְ הַקָּדוֹשׁ:", "<b>אַתָּה </b>בְחַרְתָּנוּ מִכָּל הָעַמִּים, אָהַבְתָּ אוֹתָנוּ וְרָצִיתָ בָּנוּ, וְרוֹמַמְתָּנוּ מִכָּל הַלְּשׁוֹנוֹת, וְקִדַּשְׁתָּנוּ בְּמִצְוֹתֶיךָ, וְקֵרַבְתָּנוּ מַלְכֵּנוּ לַעֲבוֹדָתֶךָ, וְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עָלֵינוּ קָרָאתָ:", "<b>וַתִּתֶּן </b>לָנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה אֶת יוֹם (<small>לשבת </small>הַשַּׁבָּת הַזֶּה וְאֶת יוֹם) הַזִּכָּרוֹן הַזֶּה, יוֹם (<small>לשבת </small>זִכְרוֹן) תְּרוּעָה (<small>לשבת </small>בְּאַהֲבָה) מִקְרָא קוֹדֶשׁ זֵכֶר לִיצִיאַת מִצְרָיִם:", "<b>תפלה לתקון קרי</b>", "<small>כשהחזן אומר \"ומפני חטאינו\" תאמר תחינה לתקון קרי ותכוין לשתף עצמך עם צער השכינה שהיא בגלות ונתמעט אורה בסוד מיעוט הירח, ואנחנו מאריכים הגלות בעונותינו מחמת חטא קרי, שאל\"כ היתה חוזרת בסוד אור החמה כמ\"ש אור הלבנה כאור החמה, לכן יאמר תפלת רבש\"ע וכו', והיא מס' עבודת הקודש והיא תפלה קדומה אך שהוא ז\"ל תיקן הלשון והוסיף נופך משלו:</small>", "<b>רִבּוֹנוֹ </b>שֶׁל עוֹלָם, בֹּשְׁנוּ מְאֹד וְנָמַס לִבֵּנוּ עַל אֲשֶׁר פָּגַמְנוּ בְּאוֹת בְּרִית קֹדֶשׁ בְּכַמָּה מִינֵי פְגָם, וּבִפְרָט בְּכַמָּה מִינֵי קֶרִי וְטִפּוֹת זֶרַע לְבַטָּלָה שֶׁיָּצְאוּ מִמֶּנִּי וּמִכָּל יִשְׂרָאֵל בִּכְלָל וּבִפְרָט שֶׁלֹּא בִּמְקוֹם מִצְוָה, בְּאֹנֶס וּבְרָצוֹן, בְּגִלְגּוּל זֶה וּבְגִלְגּוּלִים אֲחֵרִים. וְגַם הַנְּשָׁמוֹת הָעֲשׁוּקוּת בַּקְּלִפּוֹת הַנְּפוּצוֹת בְּאַרְבַּע כַּנְפוֹת הָאָרֶץ וּנְשָׁמוֹת עַרְטִילָאִיּוֹת הַנִּפְזָרוֹת בֵּין הַגּוֹיִם, וְעַל יְדֵי זֶה נִתְאָרְכָה גָּלוּתֵנוּ וְשָׁמַם בֵּית מִקְדָּשֵׁנוּ וְגָלָה יְקָרֵנוּ. וּבְכֵן בִּמְרִירוּת נֶפֶשׁ וַחֲרָטָה גְמוּרָה בָּאנוּ לְבַקֵּשׁ רַחֲמִים וּסְלִיחוֹת. וִיהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אַב הָרַחֲמִים שֶׁתְּרַחֵם עָלֵינוּ הָעֲנִיִּים וְהָאֶבְיוֹנִים מָרִים וְנֶאֱנָחִים. וְעַתָּה יִגְדַּל נָא כֹּחַ אֲדֹנָי וְתַפְלֵטְנָה הַקְּלִפּוֹת כָּל הַנִּיצוֹצוֹת הַקְּדוֹשִׁים וְטִפּוֹת קֶרִי וְזֶרַע לְבַטָּלָה שֶׁיָּצְאוּ מִמֶּנִּי וּמִכָּל יִשְׂרָאֵל בְּגִלְגּוּל זֶה וְגִלְגּוּלִים אֲחֵרִים וְתַחֲזֹר לְקַבְּצָם בִּקְדֻשָּׁה שֵׁנִית וְהָיוּ לִמְאוֹרוֹת בְּכֹחַ הַשֵּׁם הַקָּדוֹשׁ בי\"ט שֶׁיּוֹצֵא מִפָּסוּק בִּ'זְרוֹעוֹ יְ'קַבֵּץ טְ'לָאִים, וּפָסוּק כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ <small>(והוא גימטריא אהי\"ה) </small>וְשֵׁם הַקָּדוֹשׁ חב\"ו הַיּוֹצֵא מִפָּסוּק חַ'יִל בָּ'לַע וַ'יְקִאֶנּוּ מִבִּטְנוֹ יֹרִישֶׁנּוּ אֵל, וּתְקָרֵב פְּזוּרֵינוּ מִבֵּין הַגּוֹיִם וּנְפוּצוֹתֵינוּ כַּנֵּס מִיַּרְכְּתֵי הָאָרֶץ. וִיקֻיַּם בָּנוּ מִקְרָא שֶׁכָּתוּב וְשָׁב יְהֹוָה אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחֲמֶךָ וְשָׁב וְקִבֶּצְךָ מִכָּל הָעַמִּים אֲשֶׁר הֱפִיצְךָ יְהֹוָה אֱלֹהֶיךָ שָׁמָּה. וְתִגְאָלֵנוּ גְּאֻלַּת עוֹלָם. עֲשֵׂה לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. עֲשֵׂה לְמַעַן אַבְרָהָם יִצְחָק וְיַעֲקֹב משֶׁה וְאַהֲרֹן יוֹסֵף וְדָוִד הַחֲתוּמִים וְנֶאֱחָזִים בַּמִּדּוֹת הָעֶלְיוֹנוֹת הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד יְסוֹד וּמַלְכוּת. וּתְתַקֵּן אֲשֶׁר פָּגַמְנוּ וּתְיַחֵד אֲשֶׁר הִפְרַדְנוּ וּתְלַקֵּט אֲשֶׁר פִּזַּרְנוּ. וּבְרַחֲמֶיךָ הָרַבִּים תִּשְׁמְרֵנוּ מִכָּל רָע מֵעַתָּה וְעַד עוֹלָם. וְתַשְׁפִּיעַ עָלֵינוּ שֶׁפַע קְדֻשָּׁה וְטָהֳרָה לְעָבְדְךָ בֶּאֱמֶת אָנוּ וְזַרְעֵנוּ וְזֶרַע זַרְעֵנוּ. רַ'חוּם חַ'נּוּן שׁ'וֹמֵר תּ'וֹמֵךְ מַ'צִּיל יָ'שָׁר פּ'וֹדֶה <small>(יכוין בר\"ת שהיא </small>רח\"ש תמי\"ף <small>שם קדוש) </small>חוּס וְרַחֵם עָלֵינוּ וְקַבֵּל תְּפִלָּתֵנוּ כְּדִכְתִיב לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה וּכְתִיב כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְלֹא הִסְתִּיר פָּנָיו מִמֶּנּוּ וּבְשַׁוְּעוֹ אֵלָיו שָׁמֵעַ. יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגֹאֲלִי:", "<b>וּמִפְּנֵי </b>חֲטָאֵינוּ גָּלִינוּ מֵאַרְצֵנוּ, וְנִתְרַחַקְנוּ מֵעַל אַדְמָתֵנוּ, וְאֵין אֲנַחְנוּ יְכוֹלִים לַעֲשׂוֹת חוֹבוֹתֵינוּ בְּבֵית בְּחִירָתֶךָ, בַּבַּיִת הַגָּדוֹל וְהַקָּדוֹשׁ שֶׁנִּקְרָא שִׁמְךָ עָלָיו, מִפְּנֵי הַיָּד שֶׁנִּשְׁתַּלְּחָה בְּמִקְדָּשֶׁךָ. יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, מֶלֶךְ רַחֲמָן, שֶׁתָּשׁוּב וּתְרַחֵם עָלֵינוּ וְעַל מִקְדָּשְׁךָ בְּרַחֲמֶיךָ הָרַבִּים, וְתִבְנֵהוּ מְהֵרָה וּתְגַדֵּל כְּבוֹדוֹ, אָבִינוּ מַלְכֵּנוּ, גַלֵּה כְּבוֹד מַלְכוּתְךָ עָלֵינוּ מְהֵרָה, וְהוֹפַע וְהִנָּשֵׂא עָלֵינוּ לְעֵינֵי כָּל חָי. וְקָרֵב פְּזוּרֵינוּ מִבֵּין הַגּוֹיִם וּנְפוּצוֹתֵינוּ כַּנֵּס מִיַּרְכְּתֵי אָרֶץ. וַהֲבִיאֵנוּ לְצִיּוֹן עִירְךָ, בְּרִנָּה, וְלִירוּשָׁלַיִם בֵּית מִקְדָּשְׁךָ בְּשִׂמְחַת עוֹלָם. וְשָׁם נַעֲשֶׂה לְפָנֶיךָ אֶת קָרְבְּנוֹת חוֹבוֹתֵינוּ. תְּמִידִים כְּסִדְרָם וּמוּסָפִים כְּהִלְכָתָם. וְאֶת מוּסְפֵי יוֹם (<small>לשבת הַשַּׁבָּת הַזֶּה וְיוֹם) </small>הַזִּכָּרוֹן הַזֶּה נַעֲשֶׂה וְנַקְרִיב לְפָנֶיךָ בְּאַהֲבָה כְּמִצְוַת רְצוֹנֶךָ, כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ, עַל יְדֵי משֶׁה עַבְדֶּךָ, מִפִּי כְבוֹדֶךָ כָּאָמוּר:", "<small>לשבת </small><b>וּבְיוֹם </b>הַשַּׁבָּת, שְׁנֵי כְבָשִׂים בְּנֵי שָׁנָה תְּמִימִם, וּשְׁנֵי עֶשְׂרוֹנִים סוֹלֶת מִנְחָה בְּלוּלָה בַשֶּׁמֶן וְנִסְכּוֹ: עוֹלַת שַׁבַּת בְּשַׁבַּתּוֹ, עַל עוֹלַת הַתָּמִיד וְנִסְכָּהּ: (זֶה קָרְבַּן שַׁבָּת, וְקָרְבַּן הַיּוֹם כָּאָמוּר):", "<b>וּבַחוֹדֶשׁ </b>הַשְּׁבִיעִי בְּאֶחָד לַחוֹדֶשׁ, מִקְרָא קוֹדֶשׁ יִהְיֶה לָכֶם, כָּל מְלֶאכֶת עֲבוֹדָה לֹא תַעֲשׂוּ, יוֹם תְּרוּעָה יִהְיֶה לָכֶם. וַעֲשִׂיתֶם עוֹלָה לְרֵיחַ נִיחוֹחַ לַיהֹוָה, פַּר בֶּן בָּקָר אֶחָד, אַיִל אֶחָד, כְּבָשִׂים בְּנֵי שָׁנָה שִׁבְעָה תְּמִימִם:", "<b>וּמִנְחָתָם </b>וְנִסְכֵּיהֶם כִּמְדֻבָּר, שְׁלשָׁה עֶשְׂרוֹנִים לַפָּר, וּשְׁנֵי עֶשְׂרוֹנִים לָאָיִל, וְעִשָּׂרוֹן לַכֶּבֶשׂ, וְיַיִן כְּנִסְכּוֹ, וּשְׁנֵי שְׂעִירִים לְכַפֵּר, וּשְׁנֵי תְמִידִים כְּהִלְכָתָם: מִלְּבַד עוֹלַת הַחוֹדֶשׁ וּמִנְחָתָהּ, וְעוֹלַת הַתָּמִיד וּמִנְחָתָהּ, וְנִסְכֵּיהֶם כְּמִשְׁפָּטָם, לְרֵיחַ נִיחוֹחַ אִשֶּׁה לַיהֹוָה:", "<small>לשבת </small><b>יִשְׂמְחוּ </b>בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת וְקוֹרְאֵי עֹנֶג, עַם מְקַדְּשֵׁי שְׁבִיעִי, כֻּלָּם יִשְׂבְּעוּ וְיִתְעַנְּגוּ מִטּוּבֶךָ, וּבַשְּׁבִיעִי רָצִיתָ בוֹ וְקִדַּשְׁתּוֹ, חֶמְדַּת יָמִים אוֹתוֹ קָרָאתָ, זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית:", "<small>כשהחזן אומר עלינו לשבח אומר כל הצבור עמו בלחש מלה במלה. ויש להזהר מאד להפסיק לפני ואנחנו כורעים משהו בשתיקה. יש מקומות שבעלינו נופלים על פניהם החזן וכל הקהל, ויש מקומות שרק החזן נופל, ויש המחלקים בין חל בשבת לחל בחול, וכל מקום כמנהגו. החזן הנופל על פניו יזהר שלא לעקור את רגליו בנפילתו ובקימתו, ונוהגים להעמיד לפניו עוד עמוד למשך זמן התפלה ולסלקו בעת נפילתו על פניו בכדי שלא יצטרך לעקור רגליו. צריכים להזהר להפסיק בנייר או באיזה בגד בין הקרקע ובין הפנים בשעה שנופלים (ואין לשטוח עתון מודפס במקום נייר). ויש להזהר מאוד שאם התלכלכו בגדיו מהעפר והם חדשים ושחורים שלא ינערם מהאבק ויכשל בחלול יום טוב או בחלול שבת ויו\"ט. אחר שקם החזן מהכריעה יזהר לגמור בקול רם את תפילת עלינו ממקום שהפסיק עד אין עוד, כי זה מחזרת הש\"ץ.</small>", "<b>עָלֵינוּ </b>לְשַׁבֵּחַ לַאֲדוֹן הַכֹּל, לָתֵת גְּדֻלָּה לְיוֹצֵר בְּרֵאשִׁית, שֶׁלֹּא עָשָׂנוּ כְּגוֹיֵי הָאֲרָצוֹת, וְלֹא שָׂמָנוּ כְּמִשְׁפְּחוֹת הָאֲדָמָה, <small>סוגרין הארון </small>שֶׁלֹּא שָׂם חֶלְקֵנוּ כָּהֶם וְגוֹרָלֵנוּ כְּכָל הֲמוֹנָם. שֶׁהֵם מִשְׁתַּחֲוִים לְהֶבֶל וְלָרִיק וּמִתְפַּלְּלִים אֶל אֵל לֹא יוֹשִׁיעַ: <small>פותחין הארון </small>וַאֲנַחְנוּ כּוֹרְעִים וּמִשְׁתַּחֲוִים וּמוֹדִים לִפְנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים, הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהוּא נוֹטֶה שָׁמַיִם וְיוֹסֵד אָרֶץ, וּמוֹשַׁב יְקָרוֹ בַּשָּׁמַיִם מִמַּעַל, וּשְׁכִינַת עֻזּוֹ בְּגָבְהֵי מְרוֹמִים, הוּא אֱלֹהֵינוּ אֵין עוֹד. אֱמֶת מַלְכֵּנוּ, אֶפֶס זוּלָתוֹ, כַּכָּתוּב בְּתוֹרָתוֹ, וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ, כִּי יְהֹוָה הוּא הָאֱלֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת, אֵין עוֹד:", "<small>והש\"ץ חוזר בקול רם הוא אלהינו וכו'. ובשעה שהצבור אומרים הוא אלהינו וכו' אומר הש\"ץ אלו הפסוקים, וטוב לבטל גזירות רעות. וקבלה היא מן ר' אליעזר בעל הרוקח:</small>", "<b>אַתָּה </b>הָרְאֵתָ לָדַעַת כִּי יְהֹוָה הוּא הָאֱלֹהִים אֵין עוֹד מִלְּבַדּוֹ: וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶל לְבָבֶךָ כִּי יְהֹוָה הוּא הָאֱלֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת אֵין עוֹד: שְׁמַע יִשְׂרָאֵל יְהֹוָה אֱלֹהֵינוּ יְהֹוָה אֶחָד: הֵן לַיהֹוָה אֱלֹהֶיךָ הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם הָאָרֶץ וְכָל אֲשֶׁר בָּהּ: כִּי יְהֹוָה אֱלֹהֵיכֶם הוּא אֱלֹהֵי הָאֱלֹהִים וַאֲדֹנֵי הָאֲדֹנִים הָאֵל הַגָּדֹל הַגִּבֹּר וְהַנּוֹרָא אֲשֶׁר לֹא יִשָּׂא פָנִים וְלֹא יִקַּח שֹׁחַד: כִּי שֵׁם יְהֹוָה אֶקְרָא הָבוּ גֹדֶל לֵאלֹהֵינוּ: יְהִי שֵׁם יְהֹוָה מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם:", "<small>סוגרין הארון</small>", "<small>בזמן שהש\"ץ אומר עלינו יאמר הקהל מגדל עוז:</small>", "מִגְדַּל עֹז שֵׁם יְהֹוָה בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. רִבּוֹנוֹ שֶׁל עוֹלָם, מִיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ אֵין לָנוּ בַּמֶּה לְכַפֵּר, לֹא קָרְבָּן, וְלֹא בִגְדֵי כְהֻנָּה, וְלֹא מִנְחָה, וְלֹא זֶבַח, וְלֹא מִזְבֵּחַ, רַק שִׁמְךָ הַגָּדוֹל עוֹמֵד לָנוּ. יְהִי רָצוֹן שֶׁתְּהֵא שָׁעָה זוֹ עֵת רָצוֹן לִכָּנֵס תְּפִלָּתִי לַמָּרוֹם, כְּשֶׁאֲנִי מַזְכִּיר יְהֹוָה יְהֹוָה אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת. נֹצֵר חֶסֶד לָאֲלָפִים נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה וְנַקֵּה. <small>אנא בכח וכו'</small>", "<small>תחנה להש\"ץ קודם מלכויות זכרונות ושופרות:</small>", "<b>אֱלֹהֵינוּ </b>וֵאלֹהֵי אֲבוֹתֵינוּ, הֱיֵה עִם פִּיפִיּוֹת שְׁלוּחֵי עַמְּךָ בֵּית יִשְׂרָאֵל, הָעוֹמְדִים לְבַקֵּשׁ תְּפִלָּה וְתַחֲנוּנִים מִלְּפָנֶיךָ עַל עַמְּךָ בֵּית יִשְׂרָאֵל: הוֹרֵם מַה שֶּׁיֹּאמֵרוּ. הֲבִינֵם מַה שֶּׁיְּדַבֵּרוּ. הֲשִׁיבֵם מַה שֶּׁיִּשְׁאֲלוּ. יַדְּעֵם אֵיךְ יְפָאֵרוּ. בְּאוֹר פָּנֶיךָ יְהַלֵּכוּן. בֶּרֶךְ לְךָ יִכְרְעוּן. עַמְּךָ בְּפִיהֶם יְבָרֵכוּן. וּמִבִּרְכוֹת פִּיךָ כֻּלָּם יִתְבָּרְכוּן. עַמְּךָ לְפָנֶיךָ יַעֲבִירוּן, וְהֵם בַּתָּוֶךְ יַעֲבֹרוּן. עֵינֵי עַמְּךָ בָּם תְּלוּיוֹת. וְעֵינֵיהֶם לְךָ מְיַחֲלוֹת: גָּשִׁים מוּל אֲרוֹן הַקֹּדֶשׁ בְּאֵימָה. לְשַׁכֵּךְ כַּעַס וְחֵמָה. וְעַמְּךָ מַסְבִּיבִים אוֹתָם כַּחוֹמָה. וְאַתָּה מִן הַשָּׁמַיִם תַּשְׁגִּיחַ אוֹתָם לְרַחֵמָה: עַיִן נוֹשְׂאִים לְךָ לַשָּׁמַיִם. לֵב שׁוֹפְכִים נָכְחֲךָ כַּמַּיִם. וְאַתָּה תִשְׁמַע מִן הַשָּׁמָיִם: שֶׁלֹּא יִכָּשְׁלוּ בִלְשׁוֹנָם. וְלֹא יִנָּקְשׁוּ בְשִׁנּוּנָם. וְלֹא יֵבוֹשׁוּ בְּמַשְׁעֵנָם. וְלֹא יִכָּלְמוּ בָם שְׁאוֹנָם. וְאַל יֹאמַר פִּיהֶם דָּבָר שֶׁלֹּא כִרְצוֹנֶךָ. כִּי חֲנוּנֶיךָ יְהֹוָה אֱלֹהֵינוּ הֵמָּה חֲנוּנִים. וּמְרֻחֲמֶיךָ הֵמָּה מְרֻחָמִים. כְּמָה שֶׁיָּדַעְנוּ יְהֹוָה אֱלֹהֵינוּ אֵת אֲשֶׁר תָּחֹן יוּחָן, וְאֵת אֲשֶׁר תְּרַחֵם יְרֻחָם: כַּכָּתוּב בְּתוֹרָתֶךָ וַיֹּאמֶר אֲנִי אַעֲבִיר כָּל טוּבִי עַל פָּנֶיךָ, וְקָרָאתִי בְשֵׁם יְהֹוָה לְפָנֶיךָ, וְחַנֹּתִי אֶת אֲשֶׁר אָחֹן, וְרִחַמְתִּי אֶת אֲשֶׁר אֲרַחֵם: וְנֶאֱמַר אַל יֵבֹשׁוּ בִי קֹוֶיךָ אֲדֹנָי אֱלֹהִים צְבָאוֹת, אַל יִכָּלְמוּ בִי מְבַקְשֶׁיךָ אֱלֹהֵי יִשְׂרָאֵל:", "<small>אוחילה זו היא נטילת רשות לחזן על מה שרוצה לומר מלכויות זכרונות ושופרות. וכתב אבודרהם שאין ליחיד לאמרו שהרי אומר בו אשר בקהל עם אשירה עוזו:</small>", "<small>פותחין הארון</small>", "<b>אוֹחִילָה </b>לָאֵל. אֲחַלֶּה פָנָיו. אֶשְׁאֲלָה מִמֶּנּוּ מַעֲנֵה לָשׁוֹן: אֲשֶׁר בִּקְהַל עָם אָשִׁירָה עֻזּוֹ. אַבִּיעָה רְנָנוֹת בְּעַד מִפְעָלָיו: לְאָדָם מַעַרְכֵי לֵב. וּמֵיְהֹוָה מַעֲנֵה לָשׁוֹן: אֲדֹנָי שְׂפָתַי תִּפְתָּח. וּפִי יַגִּיד תְּהִלָּתֶךָ: יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְהֹוָה צוּרִי וְגוֹאֲלִי:", "<small>סוגרין הארון</small>", "<small>כשחל יום ראשון בשבת אומרים אהללה</small>", "<small>מיוסד ע\"פ א\"ב מרובע</small>", "<b>אַנְסִיכָה </b>מַלְכִּי. לְפָנָיו בְּהִתְהַלְּכִי. אָמְצוֹ בְּהַמְלִיכִי. יֶאֱזֹר עֹז וְיִמְלֹךְ: אֱלִיל בְּהַשְׁלִיכִי. לִפְנֵי בּוֹא יוֹם מַלְכִּי. אִישׁ מַלְאָכִי. יִשְׁלַח וְאָז יִמְלֹךְ: בְּבוֹאוֹ לַהֲלֹךְ. נְתוֹשׁ חָנֵף מִמְּלֹךְ. בֵּית גֵּאִים בְּלִי מְלֹךְ. יִסַּח לְבַל יִמְלֹךְ: בְּתוֹכִי יַהֲלֹךְ. בְּהוֹפִיעוֹ לִמְלֹךְ. בְּמַלְכוּתוֹ אֶמְלֹךְ. וְאָז יִמְלֹךְ: גְּבֶרֶת מַמְלָכוֹת. בְּמַגְּרוֹ מַמְלָכוֹת. גּוֹיִם וּמַמְלָכוֹת. יָהֹם וְהוּא יִמְלֹךְ: גִּלְיוֹן הֲלִיכוֹת, וְסֵפֶר תַּהֲלוּכוֹת. גַּל הַיּוֹם לְזַכּוֹת. חוֹכָיו לִמְלֹךְ: דּוֹרֶכֶת נְסִיכוּת. בְּחִנּוּן קוֹל בָּכוּת. דִּבְּרָה אֲנִי בְּמַלְכוּת. וּמִי יוּכַל לִמְלֹךְ: דַּכְּאֵי רוּחַ נְמִיכוּת. מְחַפְּשֵׂי בְּיוֹם דִּין זְכוּת. דָּשָׁה בְּעֹל מַלְכוּת. עַד צוּר יִמְלֹךְ: הִלּוּךְ מַהֲלַךְ. חֲמֵשׁ מֵאוֹת הִלַּךְ. הָדוּר עַד הָמְלַךְ. בְּעֻזּוֹ לִמְלֹךְ: הַבֵּל הַמֻּמְלָךְ. עַל מֶה מָלַךְ. הֲלֹא בְּמִי נִמְלַךְ. כִּי אָץ לִמְלֹךְ: וּמִלִּפְנֵי מְלֹךְ מֶלֶךְ. חַי מִלְּפָנִים מֶלֶךְ. וְעַד תִּכֻּל כָּל מֶלֶךְ. הוּא לְבַדּוֹ יִמְלֹךְ: וּמַה יָּעֹז מֹלֶךְ. בְּעֹז מִשְׁפַּט מֶלֶךְ. וְכַעֲבֹר סוּפָה בְּהֵלֶךְ. יַחֲלֹף מִמְּלֹךְ: זָךְ דִּין בְּעָרְכוֹ. יֹאחֵז דַּרְכּוֹ. זֵדִים בְּדָרְכוֹ. נָקָם יַעַט וְיִמְלֹךְ: זֵר זֵד בְּשַׁלְּכוֹ. יִתֵּן עֹז לְמַלְכּוֹ. זַכִּים בְּהַמְלִיכוֹ. עַל כֹּל יִמְלֹךְ: חַדְּשׁוֹ מְלוּכָה. כַּדָּת וְכַהֲלָכָה. חֹטֶר מַמְלָכָה. בְּמִישׁוֹר יִמְלֹךְ: חֹבֵשׁ אֲרוּכָה. וְאֶרֶךְ יוֹם מְבוּכָה. חֲתֻלָּה לְמַכָּה. יַעַל בְּעֵת יִמְלֹךְ: טֹרַח מַלְכֻיּוֹת. עוֹבְדֵי מַשְׂכִּיּוֹת. טִמְּאוּ חֶמֶד שְׂכִיּוֹת. בְּגַאֲוָה לִמְלֹךְ: טֹהַר זָכִיּוֹת. וְשַׁאַג קוֹל בְּכִיּוֹת. טֶבַע צוּל דָּכִיּוֹת. יִפֶן וּבָם יִמְלֹךְ: יַהַב מַשְׁלִיכִים. עָלָיו בְּנֵי מְלָכִים. יוֹם זֶה לוֹ מְחַכִּים. בּוֹא יָבוֹא לִמְלֹךְ: יַעַבְרוּ מִתְהַלְּכִים. לְפָנָיו כְּמַלְאָכִים. יַחַד מַמְלִיכִים. יְהֹוָה יִמְלֹךְ: כִּתִּים בְּכַתְּתוֹ. אִיִּים בְּהַכּוֹתוֹ. כֵּס מַמְלַכְתּוֹ. יִכּוֹן וְיִמְלֹךְ: כְּבוֹד מַלְכוּתוֹ. וְקִדּוּשׁ הֲלִיכָתוֹ. כְּגָמְרוֹ מְלַאכְתּוֹ. לְעֵין כֹּל יִמְלֹךְ: לְכָל גֹּבַהּ יַפִּיל. וְהַר וָגֶבַע יַשְׁפִּיל. לְכָל אֹם יַאְפִּיל. וּכְאוֹר זָרוּעַ יִמְלֹךְ: לִרְאִי יַקְפִּיל. וַחֲדָשִׁים יַכְפִּיל. לְיוֹם זֶה פּוּר הִפִּיל. מִצִּיּוֹן לִמְלֹךְ: מָטוּ גוֹיִם. הָמוּ גֵאִים. מָעֲדוּ מִתְגָּאִים. גֵּאֶה בְּבוֹאוֹ לִמְלֹךְ: מָלְכוּ דְגוּיִם. נֻטָּלוּ סְגוּיִם. מֶלֶךְ הַגּוֹיִם. עֵת אָתָא לִמְלֹךְ: נְדִיבֵי עַמִּים. יְאֻסָּפוּ מֵעַמִּים. נְשׂוֹא מְעוּטֵי עַמִּים. אֶל מְקוֹמָם יִמְלֹךְ: נִגּוּן נְעִימִים. לְמוּלָם מַנְעִימִים. נְשָׂאָם מֵעֲמָמִים. עֲלֵיהֶם לִמְלֹךְ: סִכּוּת אֱלִילִים. כִּיּוּן גִּלּוּלִים. סָחוֹב כְּמוֹ חֲלָלִים. יֻשְׁלָכוּ בְּלִי לִמְלֹךְ: סוֹד אֵל אֵלִים. הָבוּ בְּנֵי אֵלִים. שְׂאוּ זִמְרָה וְהִלּוּלִים. לְאָדוֹן כִּי יִמְלֹךְ: עִזּוּז יָד בְּהַשִּׂיאוֹ. לְהָרִים נְשִׂיאוֹ. עֲמוּסָיו בְּנָשְׂאוֹ. יָעֹז וְיִמְלֹךְ: עַל רוֹם מַשָּׂאוֹ. יָדֵהוּ בְּנָשְׂאוֹ. עַל הוֹד כִּסְאוֹ. יֵשֵׁב וְיִמְלֹךְ: פּוֹר תְּפוֹרֵר אֶרֶץ. בְּכִלָּיוֹן וָחֶרֶץ. פַּח בְּיוֹשְׁבֵי הָאָרֶץ. יַרְגִּיז וְיִמְלֹךְ: פַּחַד שׁוֹפְרוֹת עֶרֶץ. יְשַׁלְּשׁוּ וּבָם יִרֶץ. פְּאֵר מִכְּנַף הָאָרֶץ. יַעַל כִּי יִמְלֹךְ: צְבִי מֵהֲדוֹם יַעַל. וְאֶדֶר מִשַּׁעַל. צַהַל מִשְּׁמֵי מַעַל. יְרַנְּנוּ כִּי יִמְלֹךְ: צִבְאוֹת כָּל פֹּעַל. לְצַלְעָם יַרְטִי תַעַל. צְפִירַת פְּאֵר לְהַעַל. הֵן לְצֶדֶק יִמְלֹךְ: קְצִינִים אֲשֶׁר מָלְכוּ. אַדֶּרֶת יַשְׁלִיכוּ. קוֹל יְתַנּוּ וְיַמְלִיכוּ. לְאָדוֹן כִּי יִמְלֹךְ: קְרוּאִים יִמְלֹכוּ. וְאַחֲרָיו יַהֲלֹכוּ. קוֹמְמִיּוּת יֵלֵכוּ. וּבְרֹאשָׁם יִמְלֹךְ: רָז הַמֻּכְמָן. לְיוֹם זֶה מְזֻמָּן. רָשׁוּם לְמוֹעֵד וּזְמָן. וּבוֹ נוֹקֵם יִמְלֹךְ: רוֹעֶה נֶאֱמָן. בְּבוֹאוֹ מִתֵּימָן. רוּחַ יַסְעִיר בְּתֵימָן. בְּגִלְעָד יִמְלֹךְ: שִׁנְאַן עֲלִיּוֹת. וְסוֹד פְּלִיאִיּוֹת. שִׁיר מִתְּלוּלִיּוֹת. יִפְצְחוּ כִּי יִמְלֹךְ: שְׁאִיּוֹת תַּחְתִּיּוֹת. וְהוֹד אוֹתִיּוֹת. שְׁאוֹן הֲמוֹן בְּרִיּוֹת. יָרִיעוּ כִּי יִמְלֹךְ: תִּכּוֹן כֵּס כַּשֶּׁמֶשׁ. שְׁמוֹ לִפְנֵי שֶׁמֶשׁ. תָּאֳרוֹ כְּצֵאת הַשֶּׁמֶשׁ. בְּמָלְכוֹ יִמְלֹךְ: <small>חזן </small>תּוֹמֵךְ מִמִּזְרַח שֶׁמֶשׁ. וְעַד מְבוֹאַת שֶׁמֶשׁ. תַּמָּה בָּרָה כַּשֶּׁמֶשׁ. יְרוֹמֵם וְיִמְלֹךְ:", "לשבת", "<b>אֲהַלְלָה </b>אֱלֹהַי. אָשִׁירָה עֻזּוֹ. אֲסַפְּרָה כְבוֹדוֹ. אֲאַפְּדֶנּוּ מְלוּכָה: אֲשַׂגֵּב לְפוֹעֵל. אֲשֶׁר שָׂח וּפָעַל. אַנְוֵהוּ כִּי לוֹ יָאֲתָה מְלוּכָה: בְּעֻזּוֹ נֶצַח אֲשַׁנֵּן. כִּי צְבָאוֹ אָנִי. וְלִי נָאֶה שִׂיחַ. גֹּדֶל הַמְּלוּכָה: בְּקָהָל אֲבַשֵּׂר. בְּרָב עָם אֲדַבֵּר. לְמִי שְׂאֵת וְיֶתֶר עָז. וּלְמִי הַמְּלוּכָה: גּוֹשׁוּ גּוֹיִם. וּבוֹאוּ מַמְלָכוֹת. רְאוּ מַה נֶּהְדָּר. בְּמֵזַח הַמְּלוּכָה: גַּדְּלוּהוּ אִתִּי. וּנְרוֹמְמֶנְהוּ יָחַד. וְאַל תִּתְגָּאוּ. בְּנֵזֶר הַמְּלוּכָה: דְּרָכִים בְּעֵת נֶעֶשְׂתָה מְצוּלָה. הִתְבּוֹנְנוּ יַחַד. לְמִי נִזְרְקָה מְלוּכָה: דָּרַךְ סוּס בַּיָּם. כְּנֶגֶד שֵׁשׁ מֵאוֹת רֶכֶב. וּמַה יּוֹעִיל גֶּבֶר. עֹז בִּמְלוּכָה: הֶאֱזִינוּ רוֹזְנִים אָז וַיִּרְגָּזוּ. הִבִּיטוּ חֲתַת. וּמָאֲסוּ מְלוּכָה: הִגִּידוּ כֹחוֹ לְאֻמִּים וְדִבֵּרוּ. לָזֶה יִכָּתֵב שֵׁם הַמְּלוּכָה: וְנִלְחַם רֵאשִׁית גּוֹיִם וְאָבַד. כִּי נִשְׁבַּע חַי. בְּכִסֵּא מְלוּכָה: וְיֻלְעַג בְּכָל דּוֹר. כִּי לֹא לָמַד. מִי נִלְחַם בַּיָּם. וְעָטָה מְלוּכָה: זָד עַל אֲדוֹנָיו. עֶבֶד יוֹשֵׁב נֶגֶב. בְּזֹאת תִּרְגַּז אֶרֶץ. בִּשְׂאֵת עֶבֶד מְלוּכָה: זֶרַע בְּרוּכִים. הֶחֱרִימוּ אֲרוּרִים. כִּי נָתְנוּ קוֹל. לְאַדִּיר בִּמְלוּכָה: חֶשְׁבּוֹן וּבָשָׁן. עוֹרְרוּ מִלְחָמָה. בְּלִי לָתֵת דֶּרֶךְ. לְצִבְאוֹת מְלוּכָה: חֵילָם נִשְׁמַד. וְאַרְצָם חֻלָּקָה. וּמֵעַל זְרוֹעָם. נָפְלָה מְלוּכָה: טָפְשׁוּ בְּנֵי כְנָעַן. כִּי נָכְרִים הֵם. בְּאַדְמַת בְּנֵי שֵׁם. זֶרַע מְלוּכָה: טְבָחָם בִּן נוּן. עַד פִּנָּה אֶרֶץ. לִפְנֵי אֲרוֹן הַבְּרִית. אֲדוֹן הַמְּלוּכָה: יוֹשְׁבֵי חֲרוֹשֶׁת. אָז הִקְשָׁה לַחַץ. עֲזָרוּהוּ בְּלִי בֶצַע. אַפְסֵי מְלוּכָה: יָהּ נִלְחַם בָּם. צָבָא בְּלִי בֶצַע. כֵּן יֹאבְדוּ שְׁאָר. וְלָאֵל הַמְּלוּכָה: כְּאֶרֶז בַּלְּבָנוֹן. אַשּׁוּר גָּדַל. וְחֵרֵף אוֹרִיד. כַּבִּיר הַמְּלוּכָה: כְּלִיל אֵשׁ הֲמָמָם. בְּלֵיל שִׁמּוּרִים. וְאָז יָדְעוּ כֹל. כִּי לָאֵל הַמְּלוּכָה: לַשַּׁחַת כָּרַע בֵּל. כְּחָשְׁבוֹ עֲלוֹת לַשַּׁחַק. וְסָר מֶנּוּ לְבַב אֱנוֹשׁ. וְרָד מִמְּלוּכָה: לְכַנּוֹ הוּשַׁב. וְכֹחַ אֵל הִכִּיר. לְמֵרִים וּמַשְׁפִּיל. הִשְׁלִים מְלוּכָה: מֻגָּרָה צֹאן לַטֶּבַח. וְנִתְכְּנוּ עֲלִילוֹת. בִּלְבוּשׁ צָעִיר. רוֹדֵם הַמְּלוּכָה: מְכוּרֵי בְלֹא הוֹן. פְּדוּיֵי בְלֹא כֶסֶף. סֹלּוּ לְמַטֶּה כַמַּיִם. לֵב הַמְּלוּכָה: נִמְכְּרוּ יוֹנִים. לִבְנֵי יְוָנִים. וְרִחֲקוּם מֵעַל גְּבוּל מְלוּכָה: נֵאֲרוּ בְּרִית וָדָת. וְהִמְרִידוּ עָם בְּאֵל. וּמִגְּרוּם בְּלֹא כֹחַ. מְכַהֲנֵי מְלוּכָה: שָׂעִיר הֶחֱנִיף. לְהוֹרֵהוּ בְּצֵידוֹ. וַיִּירַשׁ בְּקוֹל בֶּכִי. חֶרֶב וּמְלוּכָה: <small>חזן </small>שֻׂגַּב חָלָק. הֱיוֹת גְּבִיר לְאֶחָיו. וְעוֹד תִּסֹּב. לִישֻׁרוּן מְלוּכָה:", "<b>עֲשֵׂה </b>לְךָ בְּצִיּוֹן. שֵׁם נוֹרָאוֹת. כְּאָז תַּצְלִיחֶנָּה. בְּכִסֵּא מְלוּכָה: עוֹרֵר וְהָקֵץ. מְשׂוֹשׂ כָּל הָאָרֶץ. וְכוֹנֵן כִּסְאֲךָ בְּקִרְיַת מְלוּכָה: פְּנֵי מְאוֹר לְבָנָה. וְחַמָּה תַּחְפִּיר. וְיֵבוֹשׁוּ עוֹבְדֵימוֹ. בִּשְׂאֵתְךָ מְלוּכָה: פָּאֵר עִיר יֹפִי. לְבָרָה כַחַמָּה. וְגַלֵּה לְנֶגְדֵּנוּ. כְּבוֹד מְלוּכָה: צִבְאוֹת גְּאוּלֵי צֹעַן. שׁוֹרְרוּ בְּלֵיל חַג. הוּא לַיְלָה נִשְׁמָר. לְסַחֵף מְלוּכָה: צָעֲדוּ בְּמֵי שַׁעַל. צָפוּ בְּרוּחַ שֵׂכֶל. אָנָה יֻנְטָעוּ. וִיקַבְּלוּ מְלוּכָה: קֻמְּטוּ שַׁעֲרֵי זְבוּל. בֵּית עוֹלָמִים. כִּי מִבֵּינֵימוֹ. שָׁבְתָה מְלוּכָה: קָדוֹשׁ יָבֹא בָם לְעוֹלָמִים. וְאָז יִשְׂאוּ רֹאשׁ. בְּחַדְּשׁוֹ מְלוּכָה: רָבְצָה עֲדִינָה. שָׁקְטָה מֵאַלְמוֹן. כִּי אָרַךְ לָהּ. קֵץ הַמְּלוּכָה: רִיבוּ מוֹשִׁיעִים. שְׂאוּ אֶדֶר מִתֵּימָן. וְשִׁיתוּ עַל אָדוֹן. הוֹד הַמְּלוּכָה: שָׁוְא שָׂנֵא אֵל. וְהוּא עַל לְשׁוֹנֵנוּ. בִּקֵּשׁ אֱמֶת וָאָיִן. וְרִחֲקָה מְלוּכָה: שַׁדַּי הָסֵר אָוֶן מִצְּבָאֶיךָ. וְיָרִיעוּ לְךָ תְּרוּעַת מְלוּכָה: תַּחְגֹּר גֵּאוּת. תִּתְאַזָּר עֹז. לְבַל יִשְׂתָּרֵר זָר בִּמְלוּכָה: תִּכּוֹן תֵּבֵל. כִּי יֻנְעַר רֶשַׁע. וְשָׂם צֶדֶק לְרַגְלָיו. וְיִצְנֹף מְלוּכָה: תִּקֹּם גּוֹיִם תּוֹכִיחַ לְאֻמִּים. תִּשְׁבֹּר מַטֵּה רֶשַׁע. מוֹשֵׁל הַמְּלוּכָה: <small>חזן </small>תַּחֲלִיף אֱלִילִים. תֻּשְׂגַּב לְבַדֶּךָ. תִּקָּרֵא נֶצַח. יָחִיד בִּמְלוּכָה:", "<b>וְעַל </b>כֵּן נְקַוֶּה לְּךָ יְהֹוָה אֱלֹהֵינוּ, לִרְאוֹת מְהֵרָה בְּתִפְאֶרֶת עֻזֶּךָ, לְהַעֲבִיר גִּלּוּלִים מִן הָאָרֶץ, וְהָאֱלִילִים כָּרוֹת יִכָּרֵתוּן, לְתַקֵּן עוֹלָם בְּמַלְכוּת שַׁדַּי. וְכָל בְּנֵי בָשָׂר יִקְרְאוּ בִשְׁמֶךָ, לְהַפְנוֹת אֵלֶיךָ כָּל רִשְׁעֵי אָרֶץ. יַכִּירוּ וְיֵדְעוּ כָּל יוֹשְׁבֵי תֵבֵל, כִּי לְךָ תִּכְרַע כָּל בֶּרֶךְ, תִּשָּׁבַע כָּל לָשׁוֹן. לְפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ יִכְרְעוּ וְיִפּוֹלוּ, וְלִכְבוֹד שִׁמְךָ יְקָר יִתֵּנוּ, וִיקַבְּלוּ כֻלָּם אֶת עוֹל מַלְכוּתֶךָ, וְתִמְלוֹךְ עֲלֵיהֶם מְהֵרָה לְעוֹלָם וָעֶד: כִּי הַמַּלְכוּת שֶׁלְּךָ הִיא, וּלְעוֹלְמֵי עַד תִּמְלֹךְ בְּכָבוֹד, כַּכָּתוּב בְּתוֹרָתֶךָ: יְהֹוָה יִמְלוֹךְ לְעוֹלָם וָעֶד: וְנֶאֱמַר, לֹא הִבִּיט אָוֶן בְּיַעֲקֹב, וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל, יְהֹוָה אֱלֹהָיו עִמּוֹ, וּתְרוּעַת מֶלֶךְ בּוֹ: וְנֶאֱמַר, וַיְהִי בִישֻׁרוּן מֶלֶךְ בְּהִתְאַסֵּף רָאשֵׁי עָם יַחַד שִׁבְטֵי יִשְׂרָאֵל:", "<b>וּבְדִבְרֵי </b>קָדְשְׁךָ כָּתוּב לֵאמֹר, כִּי לַיהֹוָה הַמְּלוּכָה וּמשֵׁל בַּגּוֹיִם: וְנֶאֱמַר, יְהֹוָה מָלָךְ גֵּאוּת לָבֵשׁ, לָבֵשׁ יְהֹוָה עוֹז הִתְאַזָּר, אַף תִּכּוֹן תֵּבֵל בַּל תִּמּוֹט: וְנֶאֱמַר, שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם וְיָבוֹא מֶלֶךְ הַכָּבוֹד: מִי זֶה מֶלֶךְ הַכָּבוֹד יְהֹוָה עִזּוּז וְגִבּוֹר יְהֹוָה גִּבּוֹר מִלְחָמָה: שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וּשְׂאוּ פִּתְחֵי עוֹלָם וְיָבוֹא מֶלֶךְ הַכָּבוֹד: מִי הוּא זֶה מֶלֶךְ הַכָּבוֹד יְהֹוָה צְבָאוֹת הוּא מֶלֶךְ הַכָּבוֹד סֶלָה:", "<b>וְעַל </b>יְדֵי עֲבָדֶיךָ הַנְּבִיאִים כָּתוּב לֵאמֹר, כֹּה אָמַר יְהֹוָה מֶלֶךְ יִשְׂרָאֵל וְגוֹאֲלוֹ יְהֹוָה צְבָאוֹת, אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן, וּמִבַּלְעָדַי אֵין אֱלֹהִים: וְנֶאֱמַר, וְעָלוּ מוֹשִׁעִים בְּהַר צִיּוֹן לִשְׁפּוֹט אֶת הַר עֵשָׂו וְהָיְתָה לַיהֹוָה הַמְּלוּכָה: וְנֶאֱמַר, וְהָיָה יְהֹוָה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד:", "<b>וּבְתוֹרָתְךָ </b>כָּתוּב לֵאמֹר שְׁמַע יִשְׂרָאֵל יְהֹוָה אֱלֹהֵינוּ יְהֹוָה אֶחָד:", "<b>אֱלֹהֵינוּ </b>וֵאלֹהֵי אֲבוֹתֵינוּ, מְלוֹךְ עַל כָּל הָעוֹלָם כֻּלּוֹ בִּכְבוֹדֶךָ, וְהִנָּשֵׂא עַל כָּל הָאָרֶץ בִּיקָרֶךָ, וְהוֹפַע בַּהֲדַר גְּאוֹן עֻזֶּךָ עַל כָּל יוֹשְׁבֵי תֵבֵל אַרְצֶךָ, וְיֵדַע כָּל פָּעוּל, כִּי אַתָּה פְעַלְתּוֹ, וְיָבִין כָּל יְצוּר, כִּי אַתָּה יְצַרְתּוֹ, וְיֹאמַר כֹּל אֲשֶׁר נְשָׁמָה בְאַפּוֹ, יְהֹוָה אֱלֹהֵי יִשְׂרָאֵל מֶלֶךְ, וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה: (<small>לשבת </small>אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, רְצֵה נָא בִמְנוּחָתֵנוּ) קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבֶךָ וְשַׂמְּחֵנוּ בִּישׁוּעָתֶךָ, (<small>לשבת </small>וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבַּת קָדְשֶׁךָ, וְיָנוּחוּ בוֹ כָּל יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ) וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶּאֱמֶת, כִּי אַתָּה אֱלֹהִים אֱמֶת, וּדְבָרְךָ אֱמֶת וְקַיָּם לָעַד. בָּרוּךְ אַתָּה יְהֹוָה, מֶלֶךְ עַל כָּל הָאָרֶץ, מְקַדֵּשׁ (<small>לשבת </small>הַשַּׁבָּת וְ)יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן:", "<small>ותוקעין <b>תשר\"ת תש\"ת תר\"ת </b>ואח\"כ אומרים זה גם בשבת אע\"פ שאין תוקעין:</small>", "<b>הַיּוֹם </b>הֲרַת עוֹלָם, הַיּוֹם יַעֲמִיד בַּמִּשְׁפָּט כָּל יְצוּרֵי עוֹלָמִים, אִם כְּבָנִים אִם כַּעֲבָדִים, אִם כְּבָנִים רַחֲמֵנוּ כְּרַחֵם אָב עַל בָּנִים, וְאִם כַּעֲבָדִים עֵינֵינוּ לְךָ תְלוּיוֹת עַד שֶׁתְּחָנֵּנוּ וְתוֹצִיא כָאוֹר מִשְׁפָּטֵנוּ, אָיוֹם קָדוֹשׁ:", "<small>כשחל בשבת אין אומרים זה:</small>", "<b>אֲרֶשֶׁת </b>שְׂפָתֵינוּ יֶעֱרַב לְפָנֶיךָ אֵל רָם וְנִשָּׂא. מֵבִין וּמַאֲזִין מַבִּיט וּמַקְשִׁיב לְקוֹל תְּקִיעָתֵנוּ, וּתְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן סֵדֶר מַלְכֻיּוֹתֵינוּ:", "<small>כשחל יום ראשון בשבת אומרים אפחד במעשי</small>", "<small>מיוסד ע\"פ תשר\"ק במרובע אחר מלת זכר</small>", "<b>זֵכֶר </b>תְּחִלַּת כָּל מַעַשׂ. אֲשֶׁר בְּכָל שָׁנָה נַעַשׂ. תּוֹחַלְתָּם לִמְאַס. יוֹצֵר בַּל יִזְכֹּר: תּוֹכַחַת מַעַשׂ. אִם יָצְאָה בְּכַעַס. תּוֹמֵךְ לְמַעֲנוֹ יַעַשׂ. וִיצוּרִים יִזְכֹּר: זֵכֶר שֶׁמִּבְּרֵאשִׁית. תְּבוּאַת רֵאשִׁית. שֹׁרֶשׁ בִּכּוּר רֵאשִׁית. יֵרֶא וְיִזְכֹּר: שֶׁצֶף חֲרִישִׁית. אִם חָר לְהָשִׁית. שׁוּבָה אֲשֶׁר הֵשִׁית. לַשּׁוֹבָבִים יִזְכֹּר: זֵכֶר רֹאשׁ עֲפָרוֹת. וְתוֹלָדוֹת סְפוּרוֹת. רִשּׁוּם סְפוּרוֹת. לְמִסְפַּר חוֹל יִזְכֹּר: רֹבַע מִסְפָּרוֹת. מְחַנְּנֵי לְכַפָּרוֹת. רֶגֶשׁ שׁוֹפָרוֹת. לְשַׁפְרְרָם יִזְכֹּר: זֵכֶר קְרִיאַת סֵפֶר. אֲשֶׁר גָּלְמִי שִׁפֵּר. קָצַב לוֹ בַּסֵּפֶר. בְּכָל דּוֹר וָדוֹר לִזְכֹּר: קֶצֶף אִם הֻחְרַט בַּסֵּפֶר. לְבִלְתִּי מְצֹא כֹפֶר. קִיּוּם זִכְרוֹן זֶה סֵפֶר. לְפָנָיו יִזְכֹּר: זֵכֶר צָפוּן מוֹרְדֵי אוֹר. תְּמִים דּוֹר כָּאוֹר. צִיָּה כְּחָר לֵאוֹר. קְנוּיָו יִזְכֹּר: צְפוּפִים פְּנֵי נָאוֹר. מִשְׁפָּטָם תֵּת לָאוֹר. צַחַן רֹעַ שְׂאוֹר. בְּרִיב בַּל יִזְכֹּר: זֵכֶר פְּעֻלַּת אֶזְרָח. הֵעַרְתָּ מִמִּזְרָח. פָּעֳלוֹ יִזְרָח. בְּקֶרֶב שָׁנִים יִזְכֹּר: פַּח אִם הֻטְרַח. פְּרָחָיו לִמְרַח. פִּלּוּלוֹ יִצְרַח. בַּעֲדָם יִזְכֹּר: זֵכֶר עֲקֵדַת מוֹרִיָּה. כְּהִיַּת רְאִיָּה. עֲדֵי עֵירֹם וְעֶרְיָה. סִבּוּכוֹ יִזְכֹּר: עֶצֶב טְרִיָּה. אִם כֹּאֲבָה פּוֹרִיָּה. עֲתָרוֹ לִרְאִיָּה. וְלִזְכוּת יִזְכֹּר: זֵכֶר סֻלָּם חָלָם. וְעָלָיו מְחוֹלְלָם. שָׂרֵי אַרְבַּע וְעֻלָּם. בּוֹ כְּמֵאָז יִזְכֹּר: שָׂרִיגָיו בְּמָעֳלָם. וְיֹאמַר לְגָעֳלָם. שִׂיחוֹ יוֹעִילָם. בְּרִית לִזְכֹּר: זֵכֶר נְקוּבֵי מַטּוֹת. שְׁבוּעוֹת מַטּוֹת. נְדִידוּת הַמִּטּוֹת. לְאַמְּצָם יִזְכֹּר: נוֹשְׂאֵי עֹל מוֹטוֹת. אִם פָּץ לְהַמְטוֹת. נֶפֶץ חֲדַר הַמִּטּוֹת. לְכִפּוּר יִזְכֹּר: זֵכֶר מְצוּקִים. יְסוֹד מוּצָקִים. מִפְעָלָם לְצוֹעֲקִים. בְּפוּט חָשׁ לִזְכֹּר: מִפִּי יוֹנְקִים. אֲשֶׁר בַּסּוּף נוֹאֲקִים. מַאֲמַר בְּרִית וְחֻקִּים. דְּבַר קָדְשׁוֹ יִזְכֹּר: זֵכֶר לִין כְּפָרִים. וְאִמְרֵי שְׁפָרִים. לִמְשַׁלְּמֵי פָרִים. בְּשָׂפָה יִזְכֹּר: לְעֵת בִּקּוּר סְפָרִים. סְתָרִים מְסַפְּרִים. לִשְׁנֵי עֳפָרִים. לְצֶדֶק יִזְכֹּר: זֵכֶר כְּבוֹד מִשְׁכַּן. מְקוֹם דּוֹד שָׁכַן. כְּרוּבִים בּוֹ שִׁכַּן. חֶסֶד נְעוּרִים יִזְכֹּר: כִּיּוֹר עִם כַּן. וְנֹעַם קוֹל דּוּכַן. כַּבִּיר בְּיוֹם מוּכָן. לַנְּבוֹנִים יִזְכֹּר: זֵכֶר יְלִיד נוּן. וּמִשְׁפְּטֵי אוּרִי אֶפְנוּן. יִזָּכְרוּ בְּרִנּוּן. פִּלְאָם לִזְכֹּר: יֹקֶשׁ בְּרַק הַשָּׁנוּן. אִם הֻשְׁלַף לְתַאֲנוּן. יַקְשִׁיב תַּחֲנוּן. חֲנוּנָיו לִזְכֹּר: זֵכֶר טַעַם שׁוֹפְטִים. וְאוֹת קְצִיר חִטִּים. טֶפֶשׁ שׁוֹטִים. יְחַתֵּל מִלִּזְכֹּר: טֹרַח אַרְבָּעָה שְׁפָטִים. אִם נֶעֶנְשׁוּ נִשְׁפָּטִים. טֶבַע מִשְׁפָּטִים. אֲשֶׁר שָׂם יִזְכֹּר: זֵכֶר חֲצוֹת לַיְלָה. וְתוֹדוֹת מִשְׁפְּטֵי לַיְלָה. חֹשֶׁךְ בְּאִישׁוֹן לַיְלָה. נִגּוּנוֹ לָמוֹ יִזְכֹּר: חֵקֶר מִפְקַד לַיְלָה. יַגִּיהַּ בְּלַהַב לַיְלָה. חֹק הֶגֶה יוֹמָם וָלַיְלָה. לְגִיהָם יִזְכֹּר: זֵכֶר זֶה זְבוּל. אֲשֶׁר בְּבִצְעִי חָבוּל. זְדוֹנוֹת סָבוּל. עוֹד בַּל יִזְכֹּר: זַעַם כַּמַּבּוּל. אִם יָצְאָה לְחִבּוּל. זִכְרוֹן יֶרַח בּוּל. לְחֶמְלָה יִזְכֹּר: זֵכֶר וֶכַח כָּל פֹּעַל. בְּקַו וָפֶלֶס יַעַל. וְאִם בְּמֶרֶד וְאִם בְּמַעַל. רַב חֶסֶד יִזְכֹּר: וְאִם טוֹב וְאִם רַע. אֲשֶׁר בּוֹ יֶאֱרַע. וֶסְתּוֹ יִפָּרַע. בְּסַאסְאָה מִלִּזְכֹּר: זֵכֶר הַחַיִּים. עַד כַּמָּה הֵם חַיִּים. הֵן לַמָּוֶת אִם לְחַיִּים. חַי חַי יִזְכֹּר: הֲמוֹן שְׁאוֹן בְּרוּאִים. יַעַבְרוּ לְפָנָיו כִּמְרִיאִים. הֲלֹא כְּמוֹ רְאוּיִים. לְכָל אֶחָד יִזְכֹּר: זֵכֶר דַּלּוּת וָעֹשֶׁר. בַּצֹּרֶת וָחֹשֶׁר. דֹּפִי וְגַם יֹשֶׁר. בַּדִּין הוּא יִזְכֹּר: דְּבַר גָּלוּי וָסֵתֶר. בִּנְיָנוֹת וְסוֹתֵר. דֵּי חָסֵר וְיָתֵר. לְקֶצֶב יִזְכֹּר: זֵכֶר גְּנוּנִים לְיַשֵּׁב. בַּמִּדְבָּר וְיוֹשֵׁב. גֶּשֶׁם וָרוּחַ לְנַשֵּׁב. מֵהַיּוֹם יִזְכֹּר: גָּרוֹן לְהַקְשֵׁב. מֵעַם שְׁמוֹ חוֹשֵׁב. גָּלֻיּוֹת לְהָשֵׁב. בְּיוֹם תֵּקַע יִזְכֹּר: זֵכֶר בַּהַל וְחֵמָה. קְרָב וּמִלְחָמָה. בִּקּוּעַ חוֹמָה. לְחוֹמַת יָם יִזְכֹּר: בָּאָדָם וּבַבְּהֵמָה. אִם הֻקְנַס מְהוּמָה. בִּצּוּר קוֹל הוֹמָה. לַאֲדָמָה יִזְכֹּר: זֵכֶר אֱמוּנָה וָשֶׁקֶר. אִזּוּן שִׂיחַ וָסֶקֶר. אוֹת פְּקֻדַּת בֹּקֶר. לִרְגָעִים יִזְכֹּר: <small>חזן </small>אִם לְזוֹל אִם לְיֹקֶר. אִם לָטַעַת אִם לְעַקֵּר. אֱנוֹשׁ בְּדִקְדּוּק וָחֵקֶר. לַמִּשְׁפָּט יִזְכֹּר:", "לשבת", "<b>אֶפְחַד </b>בְּמַעֲשַׂי. אֶדְאַג בְּכָל עֵת. אִירָא בְּיוֹם דִּין. בְּבוֹאִי לְזִכָּרוֹן: אֶדְרוֹשׁ לְחַנּוּן. אֲחַלֶּה לְרַחוּם. אֲחַנֵּן לְחַק לִי. יוֹם לְזִכָּרוֹן: בְּבוֹאִי לְמִשְׁפָּט. בְּמִי אֶשָּׁעֵן. וּמִי יְחַפֵּשׂ לִי. צֶדֶק לְזִכָּרוֹן: בְּאָבוֹת בָּטַחְתִּי. וּפָעֳלָם אָכַלְתִּי. וְהֵם הָיוּ לִי. קֶדֶם לְזִכָּרוֹן: גָּבְרָה זְרוֹעִי. כְּשָׂח מְחֵנִי נָא. לְבַל יִמַּח מֶנִּי. שֵׁם וְזִכָּרוֹן: גֶּבֶר אִם יַעֲמֹד לְפָנָיו הֲיוֹעִיל. בְּעֵת יְבַקֵּשׁ מֶנִּי. זְכוּת וְזִכָּרוֹן: דַּצְתִּי בְּלוֹבֵשׁ אֵפוֹד. וְחֹשֶׁן הַמִּשְׁפָּט. אֲשֶׁר בָּם הוּחַק. שְׁמִי לְזִכָּרוֹן: דִּלֵּג בַּמַּחְתָּה. עַד יֵעָצֵר נֶגֶף. בְּגֶשֶׁת זָר מְכַהֵן. יָקוּד לְזִכָּרוֹן: הַבִּיטָה אֵל בְּעָמְדִי לְפָנֶיךָ. אֵין בְּקִרְבִּי אֱנוֹשׁ. תָּוִי לְזִכָּרוֹן: הֲיֵשׁ מִי יְפַלֵּל. וְיָשִׁיב חֵמָה. וְיוּחַק לַדּוֹרוֹת. שְׁמוֹ לְזִכָּרוֹן: וּמִי שׂוֹנֵא בֶצַע יְדַבֵּר עֲנוּ בִי. וְיַעַן וְיֹאמַר, עֵד אָדוֹן לְזִכָּרוֹן: וּבִטְלֵה חָלָב. יְכַפֵּר בַּעֲדֵנוּ. כְּנֶגֶד שְׁנֵי עֳפָרִים. יַעַל לְזִכָּרוֹן: זַעַף יֵרֶא וְיֹאמַר תְּהִי יָדְךָ בִי. אֲשֶׁר כְּלֵב אֱלֹהָיו הוּא לְזִכָּרוֹן: זָעַק וְהֵשִׁיב חֶרֶב אֶל נְדָנָהּ. וְהוּשַׁת לוֹ כַּשֶּׁמֶשׁ כֵּס לְזִכָּרוֹן: חִכִּיתִי בְּעֵת עֶצֶר. לְפוֹתֵחַ וּמַמְטִיר. כְּמֵשִׁיב רוּחַ לַיֶּלֶד אָבוּד מִזִּכָּרוֹן: חַי לִרְאוֹת בְּרִית בְּדַבְּרוֹ קִנֵּאתִי. כִּי עָזְבוּ עָם בְּרִית וְזִכָּרוֹן: טֶרֶם הָיָה לִי מְכַפֵּר פָּנִים. מִנְחָה הוֹלֶכֶת כַּשֹּׁחַד לְזִכָּרוֹן: טֶרֶף נֵרְדְּ וְסַמִּים. לְמֵסַב חֲדָרָיו. דָּם וְחֵלֶב לְנִיחוֹחַ. וְלֶחֶם הַפָּנִים לְזִכָּרוֹן: יֻצַּגְתִּי עַל גֶּחָלַי רֵיקָה. כִּי לֹא אַלְמָן. שַׁתִּי לְזִכָּרוֹן: יָהּ אֶבְטַח בָּךְ וְלֹא בִנְדִיבִים. כִּי הֵם בַּקֶּבֶר. וְלָנֶצַח שִׁמְךָ לְזִכָּרוֹן: כָּל אֵלֶּה סְמָכוּנִי וְרַחֲמֶיךָ בִּקַּשְׁתִּי. לוּלֵי הֵם תַּמְתִּי וְאֵינִי לְזִכָּרוֹן: כִּי הֵם בִּזְרוֹעַ. עָדֶיךָ לֹא בָאוּ. רוֹמְמוּתֶךָ בְּפִיהֶם. שָׂמוּ לְזִכָּרוֹן: לְיוֹם זֶה נִכְמָס. סֶכֶם חִשְּׁבוֹנוֹת. תְּחִלָּה לְיָמִים. וְרֹאשׁ לְזִכָּרוֹן: לְהִקָּרֵא בוֹ כְּתָב עֵט וְשָׁמִיר. גָּלוּי וּבָאֵר. וְיָדוּעַ לְזִכָּרוֹן: מָוֶת וְחַיִּים. שָׁלוֹם וּמִלְחָמוֹת. צַחְצָחוֹת וָשֹׂבַע. בָּאִים לְזִכָּרוֹן: מַעַלְלֵי גֶבֶר. וּמִסְפַּר צְעָדָיו. נִשְׁכְּחוּ מֵאֱנוֹשׁ. וְלָאֵל לְזִכָּרוֹן: נִסְתְּרָה דַרְכִּי. מִי יוּכַל שִׂיחַ. לַשָּׁוְא נִכְתַּב לִי. חֵטְא לְזִכָּרוֹן: נֶגֶד פְּנֵי גֶבֶר. מַעֲשָׂיו יוֹכִיחוּ. וְיַעֲנֶה בוֹ כַּחֲשׁוֹ. עֵד לְזִכָּרוֹן: שִׂיחוּ מְזִמּוֹת אֵל. יַחַד כָּל בְּנֵי אִישׁ. עוֹבְרֵי תַּחַת שֵׁבֶט. כַּצֹּאן לְזִכָּרוֹן: <small>חזן </small>סוֹגֵר דֶּלֶת. בְּעַד תְּמִימִים בְּזַעַם. עַד בּוֹא קִצָּם. צֵאת לְזִכָּרוֹן:", "<b>עֲשֵׂה </b>פֶלֶא לְחַיִּים. לְבַל יִהְיוּ כַמֵּתִים. הֲיֵשׁ אֲמִתֶּךָ. בַּקֶּבֶר לְזִכָּרוֹן: עוֹרַרְתָּ אָז בְּפֹעַל. עוֹרְרֵנוּ בְּלֹא פֹעַל. הֲלֹא לְנִפְלְאוֹתֶיךָ. תַּעַשׂ לְזִכָּרוֹן: פְּנֵה אֱלֹהִים. בְּיוֹשְׁבֵי גַנִּים. מַקְשִׁיב לְנִדְבָּרֵימוֹ. בְּדָת לְזִכָּרוֹן: פָּעֳלָם לְפָנֶיךָ. וּשְׂכָרָם אִתָּךְ. אוֹכְלֵי לֶחֶם הָעֲצָבִים. בַּסֵּפֶר לְזִכָּרוֹן: צָצוּ שֻׁעָלִים. מְחַבְּלִים כְּרָמִים. לְהַכְרִית מִגֶּפֶן. שֹׁרֶשׁ וְזִכָּרוֹן: צְרָרוּם בְּפֶרֶךְ. נָאֲקוּ וְנוֹשָׁעוּ. בְּכוֹשֶׁר הַרְרֵי קֶדֶם. הוּחַק לְזִכָּרוֹן: קֶדֶם בַּנְתָּ לַדּוֹרוֹת. אֵין בָּהֶם חֵפֶץ. חִלַּפְתָּם וְאִבַּדְתָּם. מִהְיוֹת לְזִכָּרוֹן: קַחְתָּ דוֹר מֵאָלֶף. אֲמָרֶיךָ הִנְחַלְתָּם. לְמַעֲנָם בְּכָל דּוֹר. חַקְתָּ לְזִכָּרוֹן: רָם חָשַׁק מְאֹד. בְּכַלַּת נְעוּרִים. הֲרוּגֶיהָ וַעֲנִיֶּיהָ. תַּתָּה לְזִכָּרוֹן: רָצָה אַחֲרֶיךָ. בְּגֵיא צִיָּה וְצַלְמָוֶת. אַהֲבַת כְּלוּלוֹתֶיהָ. תַּעַשׂ לְזִכָּרוֹן: שִׁחֲתוּ עַם זוּ. שְׂאֵת שִׁמְצָה בְּקָמֵיהֶם. שֵׁם פֶּסֶל וְלֹא אֵל. שָׁתוּ לְזִכָּרוֹן: שֻׁכְּלוּ כִּמְעַט רֶגַע. לוּלֵי קָם בַּפֶּרֶץ. מְעוֹרֵר שְׁבוּעָה. וּבְרִית לְזִכָּרוֹן: תִּעַבְתָּ מֵאָז. עֲדַת כָּל לְאֻמִּים. חֲשַׁקְתָּנוּ מֵהֶם. עֵדוּת לְזִכָּרוֹן: תְּמוּר כֶּסֶף נִמְאָס. דּוֹר נִשְׁכַּח קַחְתָּ. קְנֵנוּ שֵׁנִית. כִּי שֻׁכַּחְנוּ מִזִּכָּרוֹן: תָּר אִישׁ תָּם. בְּמִי זַרְעוֹ יְכֻנֶּה. שִׂכֵּל יָדָיו. לְאוֹת וְזִכָּרוֹן: <small>חזן </small>תְּרַפֵּק מְשׁוּל אֶפְרַיִם. בְּשַׁעֲשׁוּעַ יֶלֶד וּבֵן יַקִּיר הֲלֹא בְּכוֹרִי הוּא. חַקְתָּ לְזִכָּרוֹן: <small>אתה זוכר וכו'</small>", "<b>אַתָּה </b>זוֹכֵר מַעֲשֵׂה עוֹלָם וּפוֹקֵד כָּל יְצוּרֵי קֶדֶם. לְפָנֶיךָ נִגְלוּ כָּל תַּעֲלוּמוֹת וַהֲמוֹן נִסְתָּרוֹת שֶׁמִּבְּרֵאשִׁית. כִּי אֵין שִׁכְחָה לִפְנֵי כִסֵּא כְבוֹדֶךָ וְאֵין נִסְתָּר מִנֶּגֶד עֵינֶיךָ: אַתָּה זוֹכֵר אֶת כָּל הַמִּפְעָל. וְגַם כָּל הַיְצוּר לֹא נִכְחַד מִמֶּךָּ: הַכֹּל גָּלוּי וְיָדוּעַ לְפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ, צוֹפֶה וּמַבִּיט עַד סוֹף כָּל הַדּוֹרוֹת. כִּי תָבִיא חוֹק זִכָּרוֹן לְהִפָּקֵד כָּל רוּחַ וָנָפֶשׁ. לְהִזָּכֵר מַעֲשִׂים רַבִּים וַהֲמוֹן בְּרִיּוֹת לְאֵין תַּכְלִית: מֵרֵאשִׁית כָּזֹאת הוֹדָעְתָּ, וּמִלְּפָנִים אוֹתָהּ גִּלִיתָ. זֶה הַיּוֹם תְּחִלַּת מַעֲשֶׂיךָ, זִכָּרוֹן לְיוֹם רִאשׁוֹן. כִּי חוֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב: וְעַל הַמְּדִינוֹת בּוֹ יֵאָמֵר אֵיזוֹ לַחֶרֶב, וְאֵיזוֹ לַשָּׁלוֹם, אֵיזוֹ לָרָעָב, וְאֵיזוֹ לָשּׂבַע, וּבְרִיּוֹת בּוֹ יִפָּקֵדוּ לְהַזְכִּירָם לְחַיִּים וְלַמָּוֶת. מִי לֹא נִפְקַד כְּהַיּוֹם הַזֶּה. כִּי זֵכֶר כָּל הַיְצוּר לְפָנֶיךָ בָּא. מַעֲשֵׂה אִישׁ וּפְקֻדָּתוֹ וַעֲלִילוֹת מִצְעֲדֵי גָבֶר. מַחְשְׁבוֹת אָדָם וְתַחְבּוּלוֹתָיו וְיִצְרֵי מַעַלְלֵי אִישׁ: אַשְׁרֵי אִישׁ שֶׁלֹּא יִשְׁכָּחֶךָּ, וּבֶן אָדָם יִתְאַמֶּץ בָּךְ, כִּי דוֹרְשֶׁיךָ, לְעוֹלָם לֹא יִכָּשֵׁלוּ, וְלֹא יִכָּלְמוּ לָנֶצַח כָּל הַחוֹסִים בָּךְ: כִּי זֵכֶר כָּל הַמַּעֲשִׂים לְפָנֶיךָ בָּא וְאַתָּה דוֹרֵשׁ מַעֲשֵׂה כֻּלָּם: וְגַם אֶת נֹחַ בְּאַהֲבָה זָכַרְתָּ. וַתִּפְקְדֵהוּ בִּדְבַר יְשׁוּעָה וְרַחֲמִים, בַּהֲבִיאֲךָ אֶת מֵי הַמַּבּוּל לְשַׁחֵת כָּל בָּשָׂר מִפְּנֵי רוֹעַ מַעַלְלֵיהֶם. עַל כֵּן זִכְרוֹנוֹ בָּא לְפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ, לְהַרְבּוֹת זַרְעוֹ כְּעַפְרוֹת תֵּבֵל וְצֶאֱצָאָיו כְּחוֹל הַיָּם. כַּכָּתוּב בְּתוֹרָתֶךָ, וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ, וְאֵת כָּל הַחַיָּה, וְאֶת כָּל הַבְּהֵמָה, אֲשֶׁר אִתּוֹ בַּתֵּבָה, וַיַּעֲבֵר אֱלֹהִים רוּחַ עַל הָאָרֶץ וַיָּשֹׁכּוּ הַמָּיִם: וְנֶאֱמַר, וַיִּשְׁמַע אֱלֹהִים אֶת נַאֲקָתָם, וַיִּזְכּוֹר אֱלֹהִים אֶת בְּרִיתוֹ, אֶת אַבְרָהָם אֶת יִצְחָק וְאֶת יַעֲקֹב: וְנֶאֱמַר, וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב, וְאַף אֶת בְּרִיתִי יִצְחָק, וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכּוֹר, וְהָאָרֶץ אֶזְכּוֹר:", "<b>וּבְדִבְרֵי </b>קָדְשְׁךָ כָּתוּב לֵאמֹר, זֵכֶר עָשָׂה לְנִפְלְאֹתָיו, חַנּוּן וְרַחוּם יְהֹוָה: וְנֶאֱמַר, טֶרֶף נָתַן לִירֵאָיו, יִזְכֹּר לְעוֹלָם בְּרִיתוֹ: וְנֶאֱמַר, וַיִּזְכֹּר לָהֶם בְּרִיתוֹ, וַיִּנָּחֵם כְּרֹב חֲסָדָיו:", "<b>וְעַל </b>יְדֵי עֲבָדֶיךָ הַנְּבִיאִים כָּתוּב לֵאמֹר, הָלוֹךְ וְקָרָאתָ בְאָזְנֵי יְרוּשָׁלַיִם לֵאמֹר, כֹּה אָמַר יְהֹוָה זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ, אַהֲבַת כְּלוּלוֹתָיִךְ, לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר, בְּאֶרֶץ לֹא זְרוּעָה: וְנֶאֱמַר, וְזָכַרְתִּי אֲנִי אֶת בְּרִיתִי אוֹתָךְ בִּימֵי נְעוּרָיִךְ, וַהֲקִימוֹתִי לָךְ בְּרִית עוֹלָם: וְנֶאֱמַר הֲבֵן יַקִּיר לִי אֶפְרַיִם, אִם יֶלֶד שַׁעֲשׁוּעִים, כִּי מִדֵּי דַבְּרִי בּוֹ זָכוֹר אֶזְכְּרֶנּוּ עוֹד, עַל כֵּן הָמוּ מֵעַי לוֹ, רַחֵם אֲרַחֲמֶנּוּ נְאֻם יְהֹוָה:", "<b>אֱלֹהֵינוּ </b>וֵאלֹהֵי אֲבוֹתֵינוּ, זָכְרֵנוּ בְּזִכָּרוֹן טוֹב לְפָנֶיךָ, וּפָקְדֵנוּ בִּפְקֻדַּת יְשׁוּעָה וְרַחֲמִים מִשְּׁמֵי שְׁמֵי קֶדֶם, וּזְכָר לָנוּ יְהֹוָה אֱלֹהֵינוּ אֶת הַבְּרִית וְאֶת הַחֶסֶד וְאֶת הַשְּׁבוּעָה אֲשֶׁר נִשְׁבַּעְתָּ לְאַבְרָהָם אָבִינוּ בְּהַר הַמֹּרִיָּה. וְתֵרָאֶה לְפָנֶיךָ עֲקֵדָה שֶׁעָקַד אַבְרָהָם אָבִינוּ אֶת יִצְחָק בְּנוֹ עַל גַּבֵּי הַמִּזְבֵּחַ, וְכָבַשׁ רַחֲמָיו לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם, כֵּן יִכְבְּשׁוּ רַחֲמֶיךָ אֶת כַּעַסְךָ מֵעָלֵינוּ, וּבְטוּבְךָ הַגָּדוֹל יָשׁוּב חֲרוֹן אַפְּךָ מֵעַמְּךָ וּמֵעִירְךָ וּמֵאַרְצְךָ וּמִנַּחֲלָתֶךָ. וְקַיֶּם לָנוּ יְהֹוָה אֱלֹהֵינוּ אֶת הַדָּבָר שֶׁהִבְטַחְתָּנוּ בְּתוֹרָתֶךָ עַל יְדֵי משֶׁה עַבְדֶּךָ מִפִּי כְבוֹדֶךָ כָּאָמוּר: וְזָכַרְתִּי לָהֶם בְּרִית רִאשֹׁנִים אֲשֶׁר הוֹצֵאתִי אֹתָם מֵאֶרֶץ מִצְרַיִם לְעֵינֵי הַגּוֹיִם לִהְיוֹת לָהֶם לֵאלֹהִים, אֲנִי יְהֹוָה: כִּי זוֹכֵר כָּל הַנִּשְׁכָּחוֹת אַתָּה הוּא מֵעוֹלָם, וְאֵין שִׁכְחָה לִפְנֵי כִסֵּא כְבוֹדֶךָ, וַעֲקֵדַת יִצְחָק, לְזַרְעוֹ (שֶׁל יַעֲקֹב) הַיּוֹם בְּרַחֲמִים תִּזְכֹּר. בָּרוּךְ אַתָּה יְהֹוָה, זוֹכֵר הַבְּרִית:", "<small>ותוקעין <b>תשר\"ת תש\"ת תר\"ת </b>ואח\"כ אומרים זה גם בשבת אע\"פ שאין תוקעין:</small>", "<b>הַיּוֹם </b>הֲרַת עוֹלָם, הַיּוֹם יַעֲמִיד בַּמִּשְׁפָּט כָּל יְצוּרֵי עוֹלָמִים, אִם כְּבָנִים אִם כַּעֲבָדִים, אִם כְּבָנִים רַחֲמֵנוּ כְּרַחֵם אָב עַל בָּנִים, וְאִם כַּעֲבָדִים עֵינֵינוּ לְךָ תְלוּיוֹת עַד שֶׁתְּחָנֵּנוּ וְתוֹצִיא כָאוֹר מִשְׁפָּטֵנוּ, אָיוֹם קָדוֹשׁ:", "<small>כשחל בשבת אין אומרים זה:</small>", "<b>אֲרֶשֶׁת </b>שְׂפָתֵינוּ יֶעֱרַב לְפָנֶיךָ אֵל רָם וְנִשָּׂא. מֵבִין וּמַאֲזִין מַבִּיט וּמַקְשִׁיב לְקוֹל תְּקִיעָתֵנוּ, וּתְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן סֵדֶר זִכְרוֹנוֹתֵינוּ:", "<small>כשחל יום ראשון בשבת אומרים אנוסה לעזרה</small>", "<small>מיוסד ע\"פ א\"ב מרובע</small>", "<b>אֶשָּׂא </b>דֵעִי בְּצֶדֶק. תֵּת לְפוֹעֲלִי צֶדֶק. אֶשְׁאֲלָה מִשְׁפְּטֵי צֶדֶק. קוֹל לְהָרִים כַּשּׁוֹפָר. אֵין קוֹרֵא בְצֶדֶק. רוֹדֵף צֶדֶק צֶדֶק. אֶקְרָא שִׁמְעָה צֶדֶק. בְּקוֹל בָּלוּל בַּשּׁוֹפָר: בַּנְתִּי בְּמַדָּעִי. לְמֵרָחוֹק שְׂאֵת דֵּעִי. בִּטּוּי תְּרוּעָה בְּיַדְּעִי. בְּקוֹל מַתַּן שׁוֹפָר: בּוֹ בַּהֲרִיעִי. אֲרַצֶּה לִּי רוֹעִי. בְּאָמְצוֹ זְרוֹעִי. בְּקוֹל כֹּחַ שׁוֹפָר: גַּשְׁתִּי בְּיוֹם דִּין. לְהִתְוַכֵּחַ בַּדִּין. גּוֹלֶה עֹמֶק הַדִּין. בְּקוֹל קִפְאוֹן שׁוֹפָר: גְּזֵרַת דָּת וָדִין. אִם חֻיַּבְתִּי בַּדִּין. גְּרוֹנִי יְעַכֵּב מוֹרַע דִּין. בְּקוֹל עִם שׁוֹפָר: דְּרֹשׁ וְהַעַל רְטִיָּה. לִפְנֵי טְרִיָּה. דַּעַת לִטְרוּיָה. קוֹל חוֹבֵשׁ שׁוֹפָר: דָּחוּי לִכְרוּיָה. בְּעַד נָכְרִיָּה. דְּרוֹר לְכָל בְּרִיָּה. בְּקוֹל הַעֲבָרַת שׁוֹפָר: הֻכְשַׁל בְּנַאֲפוּף. בְּזָרַת גִּפּוּף. הֻצַּג בְּרִיב צָפוּף. בְּקוֹל חֶרְדַּת שׁוֹפָר: הֻעֲנַשׁ בְּאַפּוּף. וְשָׁב הֱיוֹת חָפוּף. הוֹעִילוּ לֵב כָּפוּף. בְּקוֹל כְּפִיפַת שׁוֹפָר: וְאִם שׁוֹד יַעַלְזוֹ. וּבַדִּין יְלִיזוֹ. וְצֶדֶק יָרוּץ לְאָחֳזוֹ. בְּקוֹל חִיל שׁוֹפָר: וּכְמוֹ מַכְנִיס בְּזוֹ. וּמוֹצִיא בְזוֹ. וְכֵן מֶנּוּ יְגִיזוֹ. בְּקוֹל רוּחַ שׁוֹפָר: זֶה מִכָּל קוֹלוֹת. אֲשֶׁר בְּמַקְהֵלוֹת. זִקֵּק לִקְהִלּוֹת. קוֹל תֵּקַע שׁוֹפָר: זוֹמְמֵי עֲקַלְקַלּוֹת. מְחֻיְּבֵי סְקִילוֹת. זָעוּ בְּגִדּוּעַ מַקְלוֹת. בְּקוֹל שֵׁמַע שׁוֹפָר: חַי מִכָּל שָׁנָה. יוֹם זֶה שִׁנָּה. חָקוּק לְשׁוֹשַׁנָּה. לְקוֹל חֵרוּת שׁוֹפָר: חִבָּתוֹ מְשֻׁנָּה. שְׁנִיָּה מֵרִאשׁוֹנָה. חֵטְא כָּל הַשָּׁנָה. דְּחוֹת בְּקוֹל שׁוֹפָר: טֶבַע בְּרָכוֹת תֵּשַׁע. מוּל שׁוֹפְרוֹת תֵּשַׁע. טָהוֹר מֵהֶם יִשַׁע. בְּקוֹל דַּת שׁוֹפָר: טֶנֶף צְחוּנֵי רֶשַׁע. בְּשׁוּבָם מִפֶּשַׁע. טְרִיָּתָם תְּשַׁעֲשַׁע. בְּקוֹל שֶׁוַע שׁוֹפָר: יוּטַב מִשּׁוֹר פָּר. וּמֵאַיִל הַמְשֻׁפָּר. יוֹם הַמְסֻפָּר. לְקוֹל חִדּוּשׁ שׁוֹפָר: יֹקֶשׁ יוּפָר. וְסוֹטֵן יֻחְפָּר. יֹשֶׁר לֵב יֻשְׁפָּר. בְּקוֹל שִׁפּוּר שׁוֹפָר: כָּעֵת הֵם תּוֹקְעִים. גֵּיא מַבְקִיעִים. כְּרַכִּים מַשְׁקִיעִים. בְּקוֹל שְׁאוֹן שׁוֹפָר: כָּל הֲמוֹן מְרֵעִים. בְּחִיל מִתְרוֹעֲעִים. כַּאֲשֶׁר הֵם מַתְרִיעִים. קוֹל יָרִיעַ בַּשּׁוֹפָר: לְקוֹלוֹ כְּיֻקְשַׁב. יֻבְעַת כָּל מוֹשָׁב. לְאֻמִּים בְּסַעַר יֻנְשַׁב. בְּקוֹל סַעֲרַת שׁוֹפָר: לְיוֹדְעָיו יוּשַׁב. לְאוֹת טוֹב יִתְחַשֵּׁב. לְעֵת יִתְיַשֵּׁב. בְּקוֹל טַעַם שׁוֹפָר: מוֹאֲסָיו לְהַבְקִיעַ. בּוֹגְדָיו לְקַעֲקֵעַ. מוֹרְדָיו לְהַשְׁקִיעַ. בְּקוֹל חִזּוּק שׁוֹפָר: מַאֲרִיךְ בְּהִתָּקֵעַ. מְקַצֵּר בְּהִבָּקֵעַ. מֵרִיעַ וְתוֹקֵעַ. בְּקוֹל שִׁלּוּשׁ שׁוֹפָר: נוֹתֵן אֵימוֹת. מַחְפִּיז אֻמּוֹת. נוּסוּ נוֹאֲמוֹת. מִקּוֹל בּוּךְ שׁוֹפָר: נוֹתֵץ חוֹמוֹת. מַשְׁבִּית מִלְחָמוֹת. נוֹהֵם כַּהֲמוֹת. קוֹל שַׁאַג שׁוֹפָר: סוֹדוֹ כְּגִלָּה. בְּסִין לִסְגֻלָּה. סֻיַּם מְגִלָּה. בְּקוֹל הִלּוּךְ שׁוֹפָר: סוֹד יוֹם גְּאֻלָּה. בְּחָשְׂפוֹ לִדְגוּלָה. שָׂשׂוֹן וְגִילָה. קוֹל יַשְׁמִיעַ שׁוֹפָר: עָשׂוֹר דּוֹחֶה. עֹנֶג מַדְחֶה. עֲבֵרוֹת מַמְחֶה. בְּקוֹל צֶרַח שׁוֹפָר: עֲווֹנוֹת מוֹחֶה. עַבְדוּת מְאַחֶה. עֲבוֹדוֹת מַנְחֶה. קוֹל חִצוּר שׁוֹפָר: פַּגֵּר וְהַסְעִיר. גְּדֻלַּת שֵׂעִיר. פְּשָׁעָיו תָּעִיר. בְּקוֹל קוֹלוֹת שׁוֹפָר: פִּתְחֵי הָעִיר. תַּשְׁקִיעַ וְתַבְעִיר. פַּחַד רַב וְצָעִיר. מִקּוֹל הֶמְיַת שׁוֹפָר: צִיּוּן רֶמֶז אוֹת. שׁוֹפָרוֹת שְׁלֹשׁ מֵאוֹת. צְוָחָה בְּמִדְיָן דְּאוֹת. בְּקוֹל שִׁתּוּף שׁוֹפָר: צִפְצְפוּ צְבָאוֹת. כְּשָׁרוּ פְּלָאוֹת. צוּר כְּעָשׂ נִפְלָאוֹת. בְּקוֹל עָרֵב שׁוֹפָר: קוֹל חֲלוּשָׁה. בְּאַרְקָא חֻלָּשָׁה. קוֹלוֹת מַתַּן שְׁלֹשָׁה. קוֹלוֹת כְּנִתְּנוּ בַּשּׁוֹפָר: קֶרֶן מְשֻׁלָּשָׁה. הַיּוֹם לְזֵכֶר אֲשַׁלֵּשָׁה. קְרֹא עוֹד שְׁלֹשָׁה. בְּקוֹל עִתּוּד שׁוֹפָר: רָחַשְׁתִּי לַעֲלִיּוֹת. וְעֵינַי תְּלוּיוֹת. רְאוֹת כִּנּוּס גָּלֻיּוֹת. בְּקוֹל גֹּדֶל שׁוֹפָר: רְבִיעִית חַיּוֹת. לִיקוֹד לִהְיוֹת. רֶשֶׁף שַׁלְהֵבִיּוֹת. בְּקוֹל לַהַב שׁוֹפָר: שֵׁנָה תְּעוֹרֵר. לְשַׁלֵּם גְּמוּל לְצוֹרֵר. שְׁאוֹנוֹ תְּפוֹרֵר. בְּקוֹל גְּבוּרוֹת שׁוֹפָר: שׁוֹשָׁן תַּדְרֵר. גְּאֻלָּה תְּבָרֵר. שׁוֹכְנִים תְּזוֹרֵר. בְּקוֹל הַעֲרַת שׁוֹפָר: תְּיַשֵּׁר מֵחֶרְמוֹן. לְרוֹעֵעַ אַדְמוֹן. תַּשְׁלֵג בְּצַלְמוֹן. בְּקוֹל הֲמוֹן שׁוֹפָר: <small>חזן </small>תִּצְעַד כְּבִישִׁימוֹן. בְּמַתַּן אָמוֹן. תַּשְׁמִיעַ בְּאַרְמוֹן. קוֹל קוֹרֵא כַּשּׁוֹפָר:", "לשבת", "<b>אָנוּסָה </b>לְעֶזְרָה. אֶמְצָא נֶגְדִּי. אֵל קָרוֹב לִי. בְּעֵת קָרְאִי בְקוֹל: אֲשֶׁר בַּעֲדַת אֵל. בְּקִרְבִּי נִצָּב. וּפֹה בְּמִקְדָּשׁ מְעָט. אֲצַפְצֵף לוֹ בְּקוֹל: בַּקְרֵנִי דָּרְשֵׁנִי. שֶׂה פְזוּרָה אָנִי. נִגְזַזְתִּי וְנֶאֱלַמְתִּי. בְּלִי לְהָרִים קוֹל: בֶּאֱמֹר גּוֹזְזַי. נִדָּחָה הִיא. שׁוֹמְרָהּ וְצִלָּהּ. לֹא יִשְׁאַג בְּקוֹל: גַּלְתִּי שִׂיחַ בְּחֻקָּיו. וְחִכִּי עָרֵב. וְהִטָּה אֹזֶן וְשָׂח. הַשְׁמִיעִנִי אֶת קוֹלֵךְ קוֹל: גָּז וּבָרַח מֶנִּי. כְּעֹפֶר עַל הָרֵי בָתֶר. בְּבַקְשׁוֹ דָּת וָאוֹת. בְּמִשְׁכְּנוֹתַי וְאֵין קוֹל: דִּלֵּג מִבֶּתֶר לְבֶתֶר. הֲשִׁיבֵהוּ אֵלַי. אוּלַי יִשָּׂא פָנֶיךָ. עֵקֶב שָׁמְעֲךָ בְּקוֹל: דְּרוֹשׁ טוֹבָה לָמוֹ. וּרְאֵה שֵׂה מוֹרִיָּה. אֵלֶם פִּיהוּ יְהִי צֶדֶק. לְלֹא שָׁמְעָה בְקוֹל: הָסֵר מֵחָלָק. יָדַיִם שְׂעִירוֹת. הוֹגֶה בְּתַחֲנוּנִים. כִּי לְךָ הַקּוֹל: הוֹשַׁע אֲשֶׁר לֹא תִשָּׁכַח עֵדוּת. וּמִפִּי זַרְעוֹ. לֹא יָסוּף קוֹל: וְחוֹזַי וּמְלִיצַי. הֵם בְּנֵי אִמִּי. וְאָז נִחֲרוּ בִי. לְמַעַן אֶשְׁמַע קוֹל: וְעַל מִשְׁמַרְתָּם. יַעַמְדוּ וְיִזְעָקוּ. וְגַל לָהֶם סוֹד. וְהוּא יַעֲנֵם בְּקוֹל: זֶה חָמַק מֶנִּי. אֲסוֹבֵב וַאֲבַקְשֶׁנּוּ. בְּכָל מָקוֹם הוּא. אָנָה אֶשָּׂא קוֹל: זֵכֶר דּוֹדִי לְמַטָּה. אַדִּיר בַּמָּרוֹם. מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. לְמַעְלָה קוֹרְאִים בְּקוֹל: חֲיָלֵי מַיִם. אֲשֶׁר בָּם שְׁבִילוֹ. דִּבְּרוּ תְּמוּנָה לֹא רָאִינוּ. זוּלָתִי קוֹל: חִפַּשְׂתִּי יְשִׁימוֹן הֲיֵשׁ. וְאָמַר אָיִן. קֶדֶם תִּתּוֹ עֹז. בִּעֲתַנִי בְּקוֹל: טָהוֹר דִּלֵּג הָרִים וְעָבַר. וּמִמְּעוֹן הַר מוֹר. אָז נָתַן קוֹל: טִמֵּאתִי יְדִידוּת שִׁכְנוֹ וְעָלָה. לְיוֹם כֶּסֶא יָבוֹא. בְּאָזְנַי קוֹל: יָקַרְתִּי בְּעֵינָיו. וְנִלְוָה לִי בַּשֶּׁבִי. עִמּוֹ אָנֹכִי. אָז הִבְטִיחַנִי בְּקוֹל: יָרַד לְשִׁנְעָר. וְשָׂם כֵּס בְּעֵילָם. הִשְׁמִיעַ כָּאֲרִי. וּכְנָחָשׁ קוֹל: כִּלָּה מֶנִּי דֹּב. כְּהִתְרַפָּה מִמְּלֶאכֶת. חַק בַּמִּכְתָּב. וַיַּעֲבֵר קוֹל: כָּבַשׁ לִי. אַרְבָּעָה רָאשֵׁי נָמֵר. וְגַם אֲנִי בְּהוֹדָיוֹת סֶלָה. אַשְׁמִיעַ לוֹ בְּקוֹל: לְחַיַּת קָנֶה. אָז מָכַר אָרֶץ. מִי לִי בַשָּׁמָיִם. אָז הֵרִימָה קּוֹל. לֵאלֹהֵי יִשְׁעִי. מִשִּׁנֵּי בַרְזֶל שִׁוַּעְתִּי. וּמֵרֶגֶל עָב טִיט. הִצְרַחְתִּי בְּקוֹל: מִדַּת קִצִּי. לֹא הוֹדִיעַנִי. מָתַי בְּאַרְצִי. תּוֹר יַשְׁמִיעַ קוֹל: מִיּוֹדְעֵי סֵפֶר. חָתַם קִצִּי. לְבַל דַּעַת צוֹפַי. עֵת יִשְׂאוּ קוֹל: נָא הַבֵּט. וּרְאֵה עָנְיִי וּמְרוּדִי. אֵין לִי מַכִּיר. לְמִי אֶשָּׂא קוֹל: נֶצַח אֲקַוֶּה. כִּי לֹא יִפֹּל דָּבָר. מִמַּקְשִׁיבֵי דְמָמָה וָקוֹל: שׂוֹשׂ יָשִׂישׂ. לִבִּי בְּקִרְבִּי. בְּשָׁמְעִי דוֹדִי דוֹפֵק. עַל פְּתָחַי קוֹל: <small>חזן</small><b>סֶלָה יְשִׂימֵנִי. כַּחוֹתָם עַל לֵב. כְּאָז תַּחַת הַתַּפּוּחַ. עוֹרְרַנִי בְּקוֹל:</b>", "<b>עִלִּיתַנִי </b>אֵל עַל כָּל בָּנוֹת. כִּי בַעֲבוּרִי בְּחוֹרֵב תַּתָּה קּוֹל: עַל כָּל אֱלֹהִים מְאֹד נִתְעַלֵּיתָ. נֶצַח תִּתְעַלֶּה. בִּתְרוּעַת קוֹל: פָּעָה מִמִּדְבָּר. צִפּוֹר מִמִּצְרַיִם. וְיוֹנָה הִשְׁמִיעָה. מֵאַשּׁוּר קוֹל: פְּקֹד צִפּוֹר בַּיִת. דְּרוֹשׁ יוֹנַת אֵלֶם. תְּקַע לָמוֹ בַּשּׁוֹפָר. וּשְׁרֹק לָמוֹ בְּקוֹל: צֹר חֻקִּים מֶנִּי. לְבַל יָעוּפוּ כַּנֶּשֶׁר. לְבַל יִכָּנְפוּ. מַשְׁמִיעֵי קוֹל: צְרוּפָה אֶלְמַד. וְעֵינַי לְמוֹרַי. כְּאָז צִיר מְדַבֵּר. וְאֵל מְשִׁיבוֹ בְּקוֹל: קָרֵב קֵץ. בָּא עֵת מִשְׁפָּט. קָם מֵלִיץ יוֹשֶׁר. לְהִתְחַנֵּן בְּקוֹל: קֻדַּשׁ חֹדֶשׁ. וְהוּכַן מוֹעֵד. וְאֶתְקַע בַּשּׁוֹפָר. וְיַעֲנֶה לִּי בְּקוֹל: רֶגֶשׁ מִקֶּבֶר. צְוָחָה מִסֶּלַע. בְּתֵת יְבֵשֵׁי עֶצֶם. מֵעָפָר קוֹל: רְאוּ נֵס בֶּהָרִים. וְקוֹל שׁוֹפָר בָּאָרֶץ. לְהַשְׁמִיעַ רֶנֶן. מִדְּמוּמֵי קוֹל: שֶׁגֶג לֵב הוּתַל. עוֹד בַּל יַטֶּנּוּ. בְּלִי לְהַכְבִּיד אֹזֶן. מִשְּׁמֹעַ קוֹל: שׁוֹבֵב לִי כְּקֶדֶם דַּת מוֹרָשָׁה. אֲשֶׁר בָּהּ עִלַּפְתַּנִי. בְּלַפִּידִים וָקוֹל: תְּבוּנָה הֵפִיק אִישׁ נָבוֹן דָּבָר. וְחַק נֹעַם זְמִירוֹת. בִּנְעִימוֹת קוֹל: תְּהִלָּה יְתַנּוּ. אָז לַכֹּל הִשְׁמִיעַ. לָאֵל מוֹשֵׁל בַּכֹּל. יַמְתִּיקוּ בְּקוֹל: תַּחַת בְּנֵי צִיּוֹן בְּנֵי יָוָן שָׁחוּ. הִבְרַקְתָּ חִצִּים. וַתְּהֻמֵּם בְּקוֹל: <small>חזן </small>תַּרְעֵם לְבוֹזְזַי. תִּתְקַע בַּשּׁוֹפָר. בְּסַעֲרוֹת תֵּימָן. אָז יֵלֵךְ קוֹל: <small>אתה נגלית וכו'</small>", "<b>אַתָּה </b>נִגְלֵיתָ בַּעֲנַן כְּבוֹדֶךָ עַל עַם קָדְשְׁךָ לְדַבֵּר עִמָּם. מִן הַשָּׁמַיִם הִשְׁמַעְתָּם קוֹלֶךָ, וְנִגְלֵיתָ עֲלֵיהֶם בְּעַרְפְּלֵּי טֹהַר. גַּם כָּל הָעוֹלָם כֻּלּוֹ חָל מִפָּנֶיךָ, וּבְרִיּוֹת בְּרֵאשִׁית חָרְדוּ מִמֶּךָּ, בְּהִגָּלוֹתְךָ מַלְכֵּנוּ עַל הַר סִינַי: לְלַמֵּד לְעַמְּךָ תּוֹרָה וּמִצְווֹת. וַתַּשְׁמִיעֵם אֶת הוֹד קוֹלֶךָ, וְדִבְּרוֹת קָדְשְׁךָ מִלַּהֲבוֹת אֵשׁ. בְּקוֹלוֹת וּבְרָקִים עֲלֵיהֶם נִגְלֵיתָ, וּבְקוֹל שׁוֹפָר עֲלֵיהֶם הוֹפָעְתָּ. כַּכָּתוּב בְּתוֹרָתֶךָ, וַיְהִי בַיּוֹם הַשְּׁלִישִׁי בִּהְיוֹת הַבֹּקֶר, וַיְהִי קוֹלוֹת וּבְרָקִים וְעָנָן כָּבֵד עַל הָהָר, וְקוֹל שׁוֹפָר חָזָק מְאֹד, וַיֶּחֱרַד כָּל הָעָם אֲשֶׁר בַּמַּחֲנֶה: וְנֶאֱמַר, וַיְהִי קוֹל הַשּׁוֹפָר הוֹלֵךְ וְחָזֵק מְאֹד, משֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל: וְנֶאֱמַר, וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת, וְאֶת הַלַּפִּידִם, וְאֵת קוֹל הַשּׁוֹפָר וְאֶת הָהָר עָשֵׁן, וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק:", "<b>וּבְדִבְרֵי </b>קָדְשְׁךָ כָּתוּב לֵאמֹר, עָלָה אֱלֹהִים בִּתְרוּעָה, יְהֹוָה בְּקוֹל שׁוֹפָר: וְנֶאֱמַר, בַּחֲצוֹצְרוֹת וְקוֹל שׁוֹפָר, הָרִיעוּ לִפְנֵי הַמֶּלֶךְ יְהֹוָה: וְנֶאֱמַר תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ: כִּי חוֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב:", "<b>וְנֶאֱמַר </b>הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ, הַלְלוּהוּ בִּרְקִיעַ עֻזּוֹ: הַלְלוּהוּ בִּגְבוּרוֹתָיו, הַלְלוּהוּ כְּרוֹב גֻּדְלוֹ: הַלְלוּהוּ בְּתֵקַע שׁוֹפָר, הַלְלוּהוּ בְּנֵבֶל וְכִנּוֹר: הַלְלוּהוּ בְּתֹף וּמָחוֹל, הַלְלוּהוּ בְּמִנִּים וְעֻגָּב: הַלְלוּהוּ בְּצִלְצְלֵי שָׁמַע, הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה: כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ, הַלְלוּיָהּ:", "<b>וְעַל </b>יְדֵי עֲבָדֶיךָ הַנְּבִיאִים כָּתוּב לֵאמֹר, כָּל ישְׁבֵי תֵבֵל וְשֹׁכְנֵי אָרֶץ, כִּנְשׂא נֵס הָרִים תִּרְאוּ וְכִתְקוֹעַ שׁוֹפָר תִּשְׁמָעוּ: וְנֶאֱמַר, וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל, וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר, וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם, וְהִשְׁתַּחֲווּ לַיהֹוָה בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלָיִם: וְנֶאֱמַר, וַיהֹוָה עֲלֵיהֶם יֵרָאֶה, וְיָצָא כַבָּרָק חִצּוֹ, וַאדֹנָי יֱהֹוִה בַּשּׁוֹפָר יִתְקָע, וְהָלַךְ בְּסַעֲרוֹת תֵּימָן: יְהֹוָה צְבָאוֹת יָגֵן עֲלֵיהֶם, כֵּן תָּגֵן עַל עַמְּךָ יִשְׂרָאֵל בִּשְׁלוֹמֶךָ:", "<b>אֱלֹהֵינוּ </b>וֵאלֹהֵי אֲבוֹתֵינוּ, תְּקַע בְּשׁוֹפָר גָּדוֹל לְחֵרוּתֵנוּ, וְשָׂא נֵס לְקַבֵּץ גָּלֻיּוֹתֵינוּ, וְקָרֵב פְּזוּרֵינוּ מִבֵּין הַגּוֹיִם, וּנְפוּצוֹתֵינוּ כַּנֵּס מִיַּרְכְּתֵי אָרֶץ. וַהֲבִיאֵנוּ לְצִיּוֹן עִירְךָ בְּרִנָּה וְלִירוּשָׁלַיִם בֵּית מִקְדָּשְׁךָ בְּשִׂמְחַת עוֹלָם, וְשָׁם נַעֲשֶׂה לְפָנֶיךָ אֶת קָרְבְּנוֹת חוֹבוֹתֵינוּ, כִּמְצֻוָּה עָלֵינוּ בְּתוֹרָתֶךָ, עַל יְדֵי משֶׁה עַבְדֶּךָ מִפִּי כְבוֹדֶךָ, כָּאָמוּר:", "<b>וּבְיוֹם </b>שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וּבְרָאשֵׁי חָדְשֵׁיכֶם, וּתְקַעְתֶּם בַּחֲצוֹצְרוֹת עַל עוֹלוֹתֵיכֶם וְעַל זִבְחֵי שַׁלְמֵיכֶם, וְהָיוּ לָכֶם לְזִכָּרוֹן לִפְנֵי אֱלֹהֵיכֶם, אֲנִי יְהֹוָה אֱלֹהֵיכֶם: כִּי אַתָּה שׁוֹמֵעַ קוֹל שׁוֹפָר, וּמַאֲזִין תְּרוּעָה וְאֵין דּוֹמֶה לָּךְ: בָּרוּךְ אַתָּה יְהֹוָה, שׁוֹמֵעַ קוֹל תְּרוּעַת עַמּוֹ יִשְׂרָאֵל בְּרַחֲמִים:", "<small>ותוקעין <b>תשר\"ת תש\"ת תר\"ת </b>ואח\"כ אומרים זה גם בשבת אע\"פ שאין תוקעין:</small>", "<b>הַיּוֹם </b>הֲרַת עוֹלָם, הַיּוֹם יַעֲמִיד בַּמִּשְׁפָּט כָּל יְצוּרֵי עוֹלָמִים, אִם כְּבָנִים אִם כַּעֲבָדִים, אִם כְּבָנִים רַחֲמֵנוּ כְּרַחֵם אָב עַל בָּנִים, וְאִם כַּעֲבָדִים עֵינֵינוּ לְךָ תְלוּיוֹת עַד שֶׁתְּחָנֵּנוּ וְתוֹצִיא כָאוֹר מִשְׁפָּטֵנוּ, אָיוֹם קָדוֹשׁ:", "<small>כשחל בשבת אין אומרים זה:</small>", "<b>אֲרֶשֶׁת </b>שְׂפָתֵינוּ יֶעֱרַב לְפָנֶיךָ אֵל רָם וְנִשָּׂא. מֵבִין וּמַאֲזִין מַבִּיט וּמַקְשִׁיב לְקוֹל תְּקִיעָתֵנוּ, וּתְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן סֵדֶר שׁוֹפְרוֹתֵינוּ:", "<b>רְצֵה </b>יְהֹוָה אֱלֹהֵינוּ, בְּעַמְּךָ יִשְׂרָאֵל וְלִתְפִלָּתָם שְׁעֵה. וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ וְאִשֵּׁי יִשְׂרָאֵל. וּתְפִלָּתָם מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:", "<small>כשהכהנים עולים לדוכן, אזי כשמגיע הש\"ץ לותחזינה אומרים הש\"ץ והקהל זה:</small>", "<b>וְתֵעָרֵב </b>לְפָנֶיךָ עֲתִירָתֵנוּ כְּעוֹלָה וּכְקָרְבָּן. אָנָּא רַחוּם בְּרַחֲמֶיךָ הָרַבִּים הָשֵׁב שְׁכִינָתְךָ לְצִיוֹן עִירֶךָ וְסֵדֶר הָעֲבוֹדָה לִירוּשָׁלָיִם: וְתֶחֱזֶינָה עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים. וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיּוֹת: <small>והש\"ץ מסיים </small>בָּרוּךְ אַתָּה יְהֹוָה שֶׁאוֹתְךָ לְבַדְּךָ בְּיִרְאָה נַעֲבֹד:", "<b>מוֹדִים </b>אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד, צוּרֵנוּ צוּר חַיֵּינוּ, מָגֵן יִשְׁעֵנוּ, אַתָּה הוּא לְדוֹר וָדוֹר נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ, עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶךָ, וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ, וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ, וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת, עֶרֶב וָבֹקֶר וְצָהֳרָיִם, הַטּוֹב כִּי לֹא כָלוּ רַחֲמֶיךָ, וְהַמְרַחֵם, כִּי לֹא תַמּוּ חֲסָדֶיךָ, כִּי מֵעוֹלָם קִוִּינוּ לָךְ:", "<b>מודים דרבנן</b>", "<b>מוֹדִים </b>אֲנַחְנוּ לָךְ, שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, אֱלֹהֵי כָל בָּשָׂר, יוֹצְרֵנוּ, יוֹצֵר בְּרֵאשִׁית, בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ, עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְּמֵנוּ, וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ, לִשְׁמוֹר חֻקֶּךָ, וְלַעֲשׂוֹת רְצוֹנֶךָ, וּלְעָבְדְּךָ בְּלֵבָב שָׁלֵם, עַל שֶׁאָנוּ מוֹדִים לָךְ, בָּרוּךְ אֵל הַהוֹדָאוֹת:", "<b>וְעַל </b>כֻּלָּם יִתְבָּרֵךְ וְיִתְרוֹמֵם וְיִתְנַשֵּׂא שִׁמְךָ מַלְכֵּנוּ תָּמִיד לְעוֹלָם וָעֶד:", "<b>אָבִינוּ </b>מַלְכֵּנוּ זְכֹר רַחֲמֶיךָ וּכְבוֹשׁ כַּעַסְךָ וְכַלֵּה דֶבֶר וְחֶרֶב וְרָעָב וּשְׁבִי וּמַשְׁחִית וְעָו‍ֹן וּמַגֵּפָה וּפֶגַע רַע וְכָל מַחֲלָה וְכָל תַּקָּלָה וְכָל קְטָטָה וְכָל מִינֵי פֻרְעָנֻיּוֹת וְכָל גְּזֵרָה רָעָה וְשִׂנְאַת חִנָּם מֵעָלֵינוּ וּמֵעַל כָּל בְּנֵי בְרִיתֶךָ:", "<b>וּכְתוֹב לְחַיִּים טוֹבִים כָּל בְּנֵי בְרִיתֶךָ:</b>", "<b>וְכֹל </b>הַחַיִּים יוֹדוּךָ סֶּלָה, וִיהַלְלוּ וִיבָרְכוּ אֶת שִׁמְךָ הַגָּדוֹל בֶּאֱמֶת לְעוֹלָם כִּי טוֹב, הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה, הָאֵל הַטּוֹב. בָּרוּךְ אַתָּה יְהֹוָה, הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:", "<small>לפני נשיאת כפים אומרים הכהנים והצבור בלחש:</small>", "<b>יְהִי </b>רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, שֶׁתְּהֵא הַבְּרָכָה הַזֹּאת (<small>לכהנים </small>שֶׁצִּוִּיתָנוּ) (<small>לקהל </small>שֶׁצִּוִּיתָ) לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל, בְּרָכָה שְׁלֵמָה, וְלֹא יִהְיֶה בָּהּ שׁוּם מִכְשׁוֹל וְעָוֹן, מֵעַתָּה וְעַד עוֹלָם:", "<small>(החזן בלחש) </small>אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, בָּרְכֵנוּ בַּבְּרָכָה הַמְשֻׁלֶּשֶׁת בַּתּוֹרָה הַכְּתוּבָה עַל יְדֵי משֶׁה עַבְדֶּךָ, הָאֲמוּרָה מִפִּי אַהֲרֹן וּבָנָיו:", "<small>(החזן אומר בקול רם)</small> <b>כֹּהֲנִים:</b> <small>(והקהל עונים) </small>עַם קְדוֹשֶׁךָ, כָּאָמוּר:", "<b>בָּרוּךְ </b>אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה:", "<big>יְבָרֶכְךָ.</big>", "יְבָרֶכְךָ יְהֹוָה מִצִיוֹן עוֹשֵׂה שָׁמַיִם וָאָרֶץ:", "בָּרְכִי נַפְשִׁי אֶת יְהֹוָה וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ:", "<big>יְהֹוָה.</big>", "יְהֹוָה אֲדוֹנֵינוּ, מָה אַדִיר שִׁמְךָ בְּכָל הָאָרֶץ:", "יְהֹוָה בּוֹקֶר תִּשְׁמַע קוֹלִי בּוֹקֶר אֶעֱרָךְ לְךָ וַאֲצַפֶּה:", "<big>וְיִשְׁמְרֶךָ.</big>", "שָׁמְרֵנִי אֵל כִּי חָסִיתִי בָךְ:", "שָׁמְרֵנִי כְּאִשׁוֹן בַּת עָיִן בְּצֵל כְּנָפֶיךָ תַּסְתִּירֵנִי:", "<small>הצבור אומרים רבש\"ע בשעה שהכהנים מזמרים בוישמרך ויחנך שלום אבל המקרא אפילו אינו ש\"ץ לא יאמר הרבש\"ע מפני הטירוף:</small>", "<small>מאן דחזי חלמא ולא ידע מאי חזי ליקום קמי כהני בעידן דפרסי ידייהו ולימא רבש\"ע ולסיים בהדי כהני דלעני צבורא אמן, ואי לא סיימו עדיין לימא אדיר וכו':</small>", "<b>רִבּוֹנוֹ </b>שֶׁל עוֹלָם, אֲנִי שֶׁלָּךְ וַחֲלוֹמוֹתַי שֶׁלָּךְ, חֲלוֹם חָלַמְתִּי וְאֵינִי יוֹדֵעַ מַה הוּא. יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי, שֶׁיִּהְיוּ כָּל חֲלוֹמוֹתַי עָלַי וְעַל כָּל יִשְׂרָאֵל לְטוֹבָה, בֵּין שֶׁחָלַמְתִּי עַל עַצְמִי וּבֵין שֶׁחָלַמְתִּי עַל אֲחֵרִים, וּבֵין שֶׁחָלְמוּ אֲחֵרִים עָלַי, אִם טוֹבִים הֵם חַזְּקֵם וְאַמְּצֵם, וְיִתְקַיְּמוּ בִי וּבָהֶם כַּחֲלוֹמוֹתָיו שֶׁל יוֹסֵף הַצַּדִּיק, וְאִם צְרִיכִים רְפוּאָה רְפָאֵם כְּחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה מֵחָלְיוֹ, וּכְמִרְיָם הַנְּבִיאָה מִצָּרַעְתָּהּ, וּכְנַעֲמָן מִצָּרַעְתּוֹ, וּכְמֵי מָרָה עַל יְדֵי משֶׁה רַבֵּנוּ, וּכְמֵי יְרִיחוֹ עַל יְדֵי אֱלִישָׁע. וּכְשֵׁם שֶׁהָפַכְתָּ אֶת קִלְלַת בִּלְעָם הָרָשָׁע מִקְּלָלָה לִבְרָכָה כֵּן תַּהֲפוֹךְ כָּל חֲלוֹמוֹתַי עָלַי וְעַל כָּל יִשְׂרָאֵל לְטוֹבָה וְתִשְׁמְרֵנִי וּתְחָנֵּנִי וְתִרְצֵנִי: אמן.", "<big>יָאֵר.</big>", "אֱלֹהִים יְחָנֵּנוּ וִיבָרְכֵנוּ. יָאֵר פָּנָיו אִתָּנוּ סֶלָה:", "הָאִירָה פָנֶיךָ עַל עַבְדֶךָ הוֹשִׁיעֵנוּ בְחַסְדֶךָ:", "<big>יְהֹוָה.</big>", "יְהֹוָה יְהֹוָה, אֵל רַחוּם וְחַנוּן. אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת:", "יְהֹוָה אַל בְּאַפְּךָ תוֹכִיחֵנִי וְאַל בַּחֲמָתְךָ תְיַסְרֵנִי:", "<big>פָּנָיו.</big>", "פְּנֵה אֵלַי וְחָנֵנִי, כִּי יָחִיד וְעָנִי אָנִי:", "פָּנָה אֶל תְּפִלַת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָתָם:", "<big>אֵלֶיךָ.</big>", "אֵלֶיךָ יְהֹוָה נַפְשִׁי אֶשָׂא:", "אֵלֶיךָ יְהֹוָה שִׁוַעְתִּי וּבַבּוֹקֶר תְּפִלָתִי תְקַדְמֶךָּ:", "<big>וִיחֻנֶךָּ.</big>", "הִנֵה כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם כְּעֵינֵי שִׁפְחָה אֶל יַד גְּבִרְתָּהּ, כֵּן עֵינֵינוּ אֶל יְהֹוָה אֱלֹהֵינוּ עַד שֶׁיְחָנֵנוּ:", "חָנֵנִי אֱלֹהִים כְּחַסְדֶךָ כְּרוֹב רַחֲמֶיךָ מְחֵה פְשָׁעָי. <small>רבונו של עולם:</small>", "<big>יִשָּׂא.</big>", "יִשָּׂא בְרָכָה מֵאֵת יְהֹוָה, וּצְדָקָה מֵאֱלֹהֵי יִשְׁעוֹ. וּמְצָא חֵן וְשֵׂכֶל טוֹב בְּעֵינֵי אֱלֹהִים וְאָדָם:", "נִשָּׂא לְבָבֵנוּ אֶל כַּפָּיִם אֶל אֵל בַּשָׁמָיִם:", "<big>יְהֹוָה.</big>", "יְהֹוָה חָנֵנוּ לְךָ קִוִינוּ, הֱיֵה זְרוֹעָם לַבְּקָרִים, אַף יְשׁוּעָתֵנוּ בְּעֵת צָרָה:", "יְהֹוָה אֱלֹהִים צְבָאוֹת שִׁמְעָה תְפִלָתִי הַאֲזִינָה אֱלֹהֵי יַעֲקֹב סֶלָה:", "<big>פָּנָיו.</big>", "אַל תַּסְתֵּר פָּנֶיךָ מִמֶּנִי בְּיוֹם צַר לִי, הַטֵה אֵלַי אָזְנְךָ, בְּיוֹם אֶקְרָא מַהֵר עֲנֵנִי:", "אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךָ:", "<big>אֵלֶיךָ.</big>", "אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי, הַיוֹשְׁבִי בַּשָׁמָיִם:", "אֵלֶיךָ אֶקְרָא בַּעֲטוֹף לִבִּי בְּצוּר יָרוּם מִמֶנִי תַנְחֵנִי:", "<big>וְיָשֵׂם.</big>", "וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל, וַאֲנִי אֲבָרְכֵם:", "שָׁם אַצְמִיחַ קֶרֶן לְדָוִד עָרַכְתִּי נֵר לִמְשִׁיחִי: שִׂימֵנִי כַּחוֹתָם עַל לִבֶּךָ כַּחוֹתָם עַל זְרוֹעֶךָ:", "<big>לְךָ.</big>", "לְךָ יְהֹוָה הַגְדֻלָה וְהַגְבוּרָה וְהַתִּפְאֶרֶת וְהַנֵצַח וְהַהוֹד, כִּי כֹל בַּשָׁמַיִם וּבָאָרֶץ, לְךָ יְהֹוָה הַמַּמְלָכָה וְהַמִּתְנַשֵׂא, לְכֹל לְרֹאשׁ:", "כִּי לְךָ יְהֹוָה הוֹחָלְתִּי אַתָּה תַעֲנֶה אֲדֹנָי אֱלֹהָי:", "<big>שָׁלוֹם.</big>", "שָׁלוֹם שָׁלוֹם לָרָחוֹק, וְלַקָּרוֹב אָמַר יְהֹוָה וּרְפָאתִיו:", "יְהֹוָה עוֹז לְעַמוֹ יִתֵּן יְהֹוָה יְבָרֵךְ אֶת עַמּוֹ בַּשָׁלוֹם:", "כתוב בשערי ציון שלא יאמר אצל שלום <b>רבונו של עולם </b>רק יאמר זה:", "<b>יְהִי </b>רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי, שֶׁתַּעֲשֶׂה לְמַעַן קְדֻשַּׁת חֲסָדֶיךָ וְגֹדֶל רַחֲמֶיךָ הַפְּשׁוּטִים וּלְמַעַן טָהֳרַת שִׁמְךָ הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, בֶּן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַיּוֹצְאִים מֵהַפְּסוּקִים שֶׁל בִּרְכַּת כֹּהֲנִים (אנקת\"ם פסת\"ם פספסי\"ם דיונסי\"ם) הָאֲמוּרָה מִפִּי אַהֲרֹן וּבָנָיו עַם קְדוֹשֶׁיךָ, שֶׁתִּהְיֶה קָרוֹב לִי בְּקָרְאִי לָךְ, וְתִשְׁמַע תְּפִלָּתִי נַאֲקָתִי וְאֶנְקָתִי תָּמִיד, כְּמוֹ שֶׁשָּׁמַעְתָּ אֶנְקַת יַעֲקֹב תְּמִימֶךָ הַנִּקְרָא אִישׁ תָּם, וְתִתֶּן לִי וּלְכָל נַפְשׁוֹת בֵּיתִי מְזוֹנוֹתֵינוּ וּפַרְנָסָתֵנוּ בְּרֶוַח וְלֹא בְצִמְצוּם, בְּהֶתֵּר וְלֹא בְאִסּוּר, בְּנַחַת וְלֹא בְצַעַר, מִתַּחַת יָדְךָ הָרְחָבָה, כְּשֵׁם שֶׁנָּתַתָּ פִּסַּת לֶחֶם לֶאֱכוֹל וּבֶגֶד לִלְבּוֹשׁ לְיַעֲקֹב אָבִינוּ הַנִּקְרָא אִישׁ תָּם, וְתִתְּנֵנוּ לְאַהֲבָה לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאֵינוּ, וְיִהְיוּ דְבָרַי נִשְׁמָעִים לַעֲבוֹדָתֶךָ, כְּשֵׁם שֶׁנָּתַתָּ אֶת יוֹסֵף צַדִּיקֶךָ בְּשָׁעָה שֶׁהִלְבִּישׁוֹ אָבִיו כְּתוֹנֶת פַּסִּים לְחֵן וּלְחֶסֶד וּלְרַחֲמִים בְּעֵינֶיךָ וּבְעֵינֵי כָל רוֹאָיו, וְתַעֲשֶׂה עִמִּי נִפְלָאוֹת וְנִסִּים וּלְטוֹבָה אוֹת, וְתַצְלִיחֵנִי בִּדְרָכַי, וְתֵן בְּלִבִּי בִּינָה לְהָבִין וּלְהַשְׂכִּיל וּלְקַיֵּם אֶת כָּל דִּבְרֵי תַלְמוּד תּוֹרָתֶךָ וְסוֹדוֹתֶיהָ, וְתַצִּילֵנִי מִשְּׁגִיאוֹת, וּתְטַהֵר רַעְיוֹנַי וְלִבִּי לַעֲבוֹדָתֶךָ וּלְיִרְאָתֶךָ וְתַאֲרִיךְ יָמַי (<small>נשוי אומר </small>וִימֵי אִשְׁתִּי וּבָנַי וּבְנוֹתַי) (<small>ואם יש לו אב ואם יאמר </small>וִימֵי אָבִי וְאִמִּי) בְּטוֹב וּבִנְעִימוֹת בְּרוֹב עוֹז וְשָׁלוֹם אָמֵן סֶלָה:", "<small>אחר נשיאת כפים אומר הקהל:</small>", "<b>אַדִּיר </b>בַּמָּרוֹם, שׁוֹכֵן בִּגְבוּרָה, אַתָּה שָׁלוֹם וְשִׁמְךָ שָׁלוֹם. יְהִי רָצוֹן שֶׁתָּשִׂים עָלֵינוּ וְעַל כָּל עַמְּךָ בֵּית יִשְׂרָאֵל חַיִּים וּבְרָכָה לְמִשְׁמֶרֶת שָׁלוֹם:", "<small>והכהנים אומרים:</small>", "<b>רִבּוֹנוֹ </b>שֶׁל עוֹלָם, עָשִׂינוּ מַה שֶּׁגָּזַרְתָּ עָלֵינוּ, אַף אַתָּה עֲשֵׂה עִמָּנוּ כְּמָה שֶׁהִבְטַחְתָּנוּ. הַשְּׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם, וּבָרֵךְ אֶת עַמְּךָ אֶת יִשְׂרָאֵל, וְאֵת הָאֲדָמָה אֲשֶׁר נָתַתָּה לָנוּ, כַּאֲשֶׁר נִשְׁבַּעְתָּ לַאֲבֹתֵינוּ אֶרֶץ זָבַת חָלָב וּדְבָשׁ:", "<b>שִׂים </b>שָׁלוֹם טוֹבָה וּבְרָכָה, חַיִּים חֵן וָחֶסֶד וְרַחֲמִים, עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ, כֻּלָּנוּ כְּאֶחָד יַחַד בְּאוֹר פָּנֶיךָ, כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ, יְהֹוָה אֱלֹהֵינוּ, תּוֹרַת חַיִּים וְאַהֲבַת חֶסֶד, וּצְדָקָה וּבְרָכָה וְרַחֲמִים וְחַיִּים וְשָׁלוֹם. וְטוֹב יִהְיֶה בְּעֵינֶיךָ לְבָרְכֵנוּ וּלְבָרֵךְ אֶת כָּל עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ, בְּרוֹב עוֹז וְשָׁלוֹם:", "<b>בְּסֵפֶר </b>חַיִּים בְּרָכָה וְשָׁלוֹם, וּפַרְנָסָה טוֹבָה, וּגְזֵרוֹת טוֹבוֹת, יְשׁוּעוֹת וְנֶחָמוֹת, נִזָּכֵר וְנִכָּתֵב לְפָנֶיךָ אֲנַחְנוּ וְכָל עַמְּךָ בֵּית יִשְׂרָאֵל לְחַיִּים טוֹבִים וּלְשָׁלוֹם:", "<b>וְנֶאֱמַר </b>כִּי בִי יִרְבּוּ יָמֶיךָ וְיוֹסִיפוּ לְךָ שְׁנוֹת חַיִּים: לְחַיִּים טוֹבִים תִּכְתְּבֵנוּ אֱלֹהִים חַיִּים כָּתְבֵנוּ בְּסֵפֶר הַחַיִּים. כַּכָּתוּב וְאַתֶּם הַדְּבֵקִים בַּיהֹוָה אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם:", "<small>פותחין הארון</small>", "<small>ז' היום נתקנו ע\"ש ז' תיבות בפסוק ואתם הדבקים בה' אלהיכם חיים כלכם היום</small>", "<b>הַיּוֹם תְּאַמְּצֵנוּ: </b>אמן", "<b>הַיּוֹם תְּבָרְכֵנוּ: </b>אמן", "<b>הַיּוֹם תְּגַדְּלֵנוּ: </b>אמן", "<b>הַיּוֹם תִּדְרְשֵׁנוּ לְטוֹבָה: </b>אמן", "<b>הַיּוֹם תִּשְׁמַע שַׁוְעָתֵנוּ: </b>אמן", "<b>הַיּוֹם תְּקַבֵּל בְּרַחֲמִים וּבְרָצוֹן אֶת תְּפִלָּתֵנוּ: </b>אמן", "<b>הַיּוֹם תִּתְמְכֵנוּ בִּימִין צִדְקֶךָ:</b> אמן", "<small>סוגרין הארון</small>", "<b>כְּהַיּוֹם </b>הַזֶּה תְּבִיאֵנוּ שָׂשִׂים וּשְׂמֵחִים בְּבִנְיַן שָׁלֵם. כַּכָּתוּב וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי עוֹלֹתֵיהֶם וְזִבְחֵיהֶם לְרָצוֹן עַל מִזְבְּחִי כִּי בֵיתִי בֵּית תְּפִלָּה יִקָּרֵא לְכָל הָעַמִּים: וְנֶאֱמַר וַיְצַוֵּנוּ יְהֹוָה לַעֲשׂוֹת אֶת כָּל הַחֻקִּים הָאֵלֶּה לְיִרְאָה אֶת יְהֹוָה אֱלֹהֵינוּ לְטוֹב לָנוּ כָּל הַיָּמִים לְחַיֹּתֵנוּ כְּהַיּוֹם הַזֶּה: וְנֶאֱמַר וּצְדָקָה תִּהְיֶה לָּנוּ כִּי נִשְׁמֹר לַעֲשׂוֹת אֶת כָּל הַמִּצְוָה הַזֹּאת לִפְנֵי יְהֹוָה אֱלֹהֵינוּ כַּאֲשֶׁר צִוָּנוּ. וּצְדָקָה וּבְרָכָה וְרַחֲמִים וְחַיִּים וְשָׁלוֹם יִהְיֶה לָּנוּ וּלְכָל יִשְׂרָאֵל עַד הָעוֹלָם:", "<small>והש\"ץ מסיים </small>בָּרוּךְ אַתָּה יְהֹוָה הַמְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:", "<small>אחר תשלום תפילת מוסף תוקעים בקדיש לפני תתקבל או לאחר הקדיש עד תשלום מאה קולות; אלו שתקעו בתפילת לחש תוקעים כעת עשרה קולות, ואלו שלא תקעו תוקעים כעת ארבעים קולות. ותוקעים את התשר\"ת בשתי נשימות. ועיין בשל\"ה גודל מעלת תקיעות אלו דתתקבל ולכן יזהר מאד בשמיעתם.</small>", "<b>יִתְגַּדַּל </b>וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא, בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ, וְיַצְמַח פּוּרְקָנֵהּ וִיקָרֵב (<small>נ\"א </small>קֵץ) מְשִׁיחֵהּ, בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשְׂרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב וְאִמְרוּ אָמֵן. יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. יִתְבָּרַךְ וְיִשְׁתַּבַּח, וְיִתְפָּאַר וְיִתְרוֹמַם וְיִתְנַשֵּׂא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְעֵלָּא וּלְעֵלָּא מִכָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא וְאִמְרוּ אָמֵן:", "<small>ותוקעין </small>תשר\"ת תש\"ת תר\"ת", "<b>תִּתְקַבֵּל </b>צְלוֹתְהוֹן וּבָעוּתְהוֹן דְכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא וְאִמְרוּ אָמֵן.", "<b>יְהֵא </b>שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן.", "<b>עֹשֶׂה </b>הַשָּׁלוֹם בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן."]}}, "entries": [{"id": "e00", "sec": "torah", "ref": "Rashi on Genesis 30:22:1", "label": "רש\"י בראשית ל:כב", "paytan": "הפייט", "kind": "line", "quotes": ["הָאַדְמוֹן כְּבָט שֶׁלֹּא חָלָה, צָבָה לְקַחְתָּהּ לוֹ וְנִתְבֶּהָלָה"], "rishonHtml": "<b>ויזכור אלהים את רחל.</b> זָכַר לָהּ שֶׁמָּסְרָה סִימָנֶיהָ לַאֲחוֹתָהּ וְשֶׁהָיְתָה מְצֵרָה שֶׁמָּא תַּעֲלֶה בְּגוֹרָלוֹ שֶׁל עֵשָׂו, שֶׁמָּא יְגָרְשֶׁנָּה יַעֲקֹב לְפִי שֶׁאֵין לָהּ בָּנִים, וְאַף עֵשָׂו הָרָשָׁע כָּךְ עָלָה בְּלִבּוֹ כְּשֶׁשָּׁמַע שֶׁאֵין לָהּ בָּנִים; הוּא שֶׁיִּסֵּד הַפַּיָּט <mark>הָאַדְמוֹן כְּבָט שֶׁלֹּא חָלָה, צָבָה לְקַחְתָּהּ לוֹ וְנִתְבֶּהָלָה</mark>:", "version": "Pentateuch with Rashi's commentary by M. Rosenbaum and A.M. Silbermann, 1929-1934", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001969084", "url": "https://www.sefaria.org/Rashi_on_Genesis_30:22:1", "lit": [{"src": "rh1", "seg": 38, "segHtml": "<mark>הָאַדְמוֹן, כְּבָט שֶׁלֹּא חָֽלָה</mark> / צָבָה לְקַחְתָּהּ לוֹ, וְנִתְבַּהֲלָה<br>וּפִלְּלָה רַבִּים בְּעַד הַתּוֹחֵלָה / פְּדוֹתָהּ מִזֵּד, וְלֹא חֻלָּֽלָה.", "note": null, "a": 36, "b": 41, "head": null}], "said": ["text", "חזרת הש\"ץ לשחרית, יום א' של ראש השנה"], "when": [["rh", "text", "חזרת הש\"ץ לשחרית, יום א'"]]}, {"id": "e01", "sec": "torah", "ref": "Rashi on Exodus 26:15:1", "label": "רש\"י שמות כו:טו", "paytan": "הבבלי", "kind": "line", "quotes": ["טָס מַטַּע מְזֹרָזִים קוֹרוֹת בָּתֵּינוּ אֲרָזִים"], "rishonHtml": "<b>ועשית את הקרשים.</b> הָיָה לוֹ לוֹמַר וְעָשִׂיתָ קְרָשִׁים, כְּמוֹ שֶׁנֶּאֱמַר בְּכָל דָּבָר וְדָבָר, מַהוּ הַקְּרָשִׁים? מֵאוֹתָן הָעוֹמְדִין וּמְיֻחָדִין לְכָךְ; יַעֲקֹב אָבִינוּ נָטַע אֲרָזִים בְּמִצְרַיִם, וּכְשֶׁמֵּת צִוָּה לְבָנָיו לְהַעֲלוֹתָם עִמָּהֶם כְּשֶׁיֵּצְאוּ מִמִּצְרַיִם, וְאָמַר לָהֶם שֶׁעָתִיד הַקָּבָּ\"ה לְצַוּוֹת אוֹתָן לַעֲשׂוֹת מִשְׁכָּן בַּמִּדְבָּר מֵעֲצֵי שִׁטִּים, רְאוּ שֶׁיִּהְיוּ מְזֻמָּנִים בְּיֶדְכֶם; הוּא שֶׁיִּסֵּד הַבַּבְלִי בַּפִּיּוּט שֶׁלּוֹ, \"<mark>טָס מַטַּע מְזֹרָזִים קוֹרוֹת בָּתֵּינוּ אֲרָזִים</mark>\", שֶׁנִּזְדָּרְזוּ לִהְיוֹת מוּכָנִים בְּיָדָם מִקֹּדֶם לָכֵן:", "version": "Pentateuch with Rashi's commentary by M. Rosenbaum and A.M. Silbermann, 1929-1934", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001969084", "url": "https://www.sefaria.org/Rashi_on_Exodus_26:15:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e06", "sec": "nach", "ref": "Rashi on II Kings 11:2:1", "label": "רש\"י מלכים ב יא:ב", "paytan": "רבי אליעזר", "kind": "line", "quotes": ["נִפֵּץ חֲדַר הַמִּטּוֹת, חָרְבַּן בֵּיתְךָ יְכַפֵּר עֲלֵיהֶם"], "rishonHtml": "<b>בַּחֲדַר הַמִּטּוֹת.</b> בַּעֲלִיַּת בֵּית קָדְשֵׁי הַקֳּדָשִׁים, כְּמָה שֶׁהוּא אוֹמֵר: וַיְהִי אִתָּהּ בֵּית ה' מִתְחַבֵּא וְגוֹ', עָלָיו אָמַר דָּוִד: כִּי יִצְפְּנֵנִי בְּסֻכֹּה יַסְתִּירֵנִי בְּסֵתֶר אָהֳלוֹ. וְקוֹרֵא אוֹתָהּ חֲדַר הַמִּטּוֹת, עַל שֵׁם: בֵּין שָׁדַי יָלִין. וְזֶהוּ שֶׁיִּסֵּד רַבִּי אֱלִיעֶזֶר: <mark>נִפֵּץ חֲדַר הַמִּטּוֹת, חָרְבַּן בֵּיתְךָ יְכַפֵּר עֲלֵיהֶם</mark>.", "version": "The Metsudah Tanach series, Lakewood, N.J", "source": "https://www.judaicaplace.com/search/brand/Metsudah-Publications/", "url": "https://www.sefaria.org/Rashi_on_II_Kings_11:2:1", "lit": [{"src": "rh1_musaf", "seg": 196, "segHtml": "<b>זֵכֶר </b>תְּחִלַּת כָּל מַעַשׂ. אֲשֶׁר בְּכָל שָׁנָה נַעַשׂ. תּוֹחַלְתָּם לִמְאַס. יוֹצֵר בַּל יִזְכֹּר: תּוֹכַחַת מַעַשׂ. אִם יָצְאָה בְּכַעַס. תּוֹמֵךְ לְמַעֲנוֹ יַעַשׂ. וִיצוּרִים יִזְכֹּר: זֵכֶר שֶׁמִּבְּרֵאשִׁית. תְּבוּאַת רֵאשִׁית. שֹׁרֶשׁ בִּכּוּר רֵאשִׁית. יֵרֶא וְיִזְכֹּר: שֶׁצֶף חֲרִישִׁית. אִם חָר לְהָשִׁית. שׁוּבָה אֲשֶׁר הֵשִׁית. לַשּׁוֹבָבִים יִזְכֹּר: זֵכֶר רֹאשׁ עֲפָרוֹת. וְתוֹלָדוֹת סְפוּרוֹת. רִשּׁוּם סְפוּרוֹת. לְמִסְפַּר חוֹל יִזְכֹּר: רֹבַע מִסְפָּרוֹת. מְחַנְּנֵי לְכַפָּרוֹת. רֶגֶשׁ שׁוֹפָרוֹת. לְשַׁפְרְרָם יִזְכֹּר: זֵכֶר קְרִיאַת סֵפֶר. אֲשֶׁר גָּלְמִי שִׁפֵּר. קָצַב לוֹ בַּסֵּפֶר. בְּכָל דּוֹר וָדוֹר לִזְכֹּר: קֶצֶף אִם הֻחְרַט בַּסֵּפֶר. לְבִלְתִּי מְצֹא כֹפֶר. קִיּוּם זִכְרוֹן זֶה סֵפֶר. לְפָנָיו יִזְכֹּר: זֵכֶר צָפוּן מוֹרְדֵי אוֹר. תְּמִים דּוֹר כָּאוֹר. צִיָּה כְּחָר לֵאוֹר. קְנוּיָו יִזְכֹּר: צְפוּפִים פְּנֵי נָאוֹר. מִשְׁפָּטָם תֵּת לָאוֹר. צַחַן רֹעַ שְׂאוֹר. בְּרִיב בַּל יִזְכֹּר: זֵכֶר פְּעֻלַּת אֶזְרָח. הֵעַרְתָּ מִמִּזְרָח. פָּעֳלוֹ יִזְרָח. בְּקֶרֶב שָׁנִים יִזְכֹּר: פַּח אִם הֻטְרַח. פְּרָחָיו לִמְרַח. פִּלּוּלוֹ יִצְרַח. בַּעֲדָם יִזְכֹּר: זֵכֶר עֲקֵדַת מוֹרִיָּה. כְּהִיַּת רְאִיָּה. עֲדֵי עֵירֹם וְעֶרְיָה. סִבּוּכוֹ יִזְכֹּר: עֶצֶב טְרִיָּה. אִם כֹּאֲבָה פּוֹרִיָּה. עֲתָרוֹ לִרְאִיָּה. וְלִזְכוּת יִזְכֹּר: זֵכֶר סֻלָּם חָלָם. וְעָלָיו מְחוֹלְלָם. שָׂרֵי אַרְבַּע וְעֻלָּם. בּוֹ כְּמֵאָז יִזְכֹּר: שָׂרִיגָיו בְּמָעֳלָם. וְיֹאמַר לְגָעֳלָם. שִׂיחוֹ יוֹעִילָם. בְּרִית לִזְכֹּר: זֵכֶר נְקוּבֵי מַטּוֹת. שְׁבוּעוֹת מַטּוֹת. נְדִידוּת הַמִּטּוֹת. לְאַמְּצָם יִזְכֹּר: נוֹשְׂאֵי עֹל מוֹטוֹת. אִם פָּץ לְהַמְטוֹת. <mark>נֶפֶץ חֲדַר הַמִּטּוֹת</mark>. לְכִפּוּר יִזְכֹּר: זֵכֶר מְצוּקִים. יְסוֹד מוּצָקִים. מִפְעָלָם לְצוֹעֲקִים. בְּפוּט חָשׁ לִזְכֹּר: מִפִּי יוֹנְקִים. אֲשֶׁר בַּסּוּף נוֹאֲקִים. מַאֲמַר בְּרִית וְחֻקִּים. דְּבַר קָדְשׁוֹ יִזְכֹּר: זֵכֶר לִין כְּפָרִים. וְאִמְרֵי שְׁפָרִים. לִמְשַׁלְּמֵי פָרִים. בְּשָׂפָה יִזְכֹּר: לְעֵת בִּקּוּר סְפָרִים. סְתָרִים מְסַפְּרִים. לִשְׁנֵי עֳפָרִים. לְצֶדֶק יִזְכֹּר: זֵכֶר כְּבוֹד מִשְׁכַּן. מְקוֹם דּוֹד שָׁכַן. כְּרוּבִים בּוֹ שִׁכַּן. חֶסֶד נְעוּרִים יִזְכֹּר: כִּיּוֹר עִם כַּן. וְנֹעַם קוֹל דּוּכַן. כַּבִּיר בְּיוֹם מוּכָן. לַנְּבוֹנִים יִזְכֹּר: זֵכֶר יְלִיד נוּן. וּמִשְׁפְּטֵי אוּרִי אֶפְנוּן. יִזָּכְרוּ בְּרִנּוּן. פִּלְאָם לִזְכֹּר: יֹקֶשׁ בְּרַק הַשָּׁנוּן. אִם הֻשְׁלַף לְתַאֲנוּן. יַקְשִׁיב תַּחֲנוּן. חֲנוּנָיו לִזְכֹּר: זֵכֶר טַעַם שׁוֹפְטִים. וְאוֹת קְצִיר חִטִּים. טֶפֶשׁ שׁוֹטִים. יְחַתֵּל מִלִּזְכֹּר: טֹרַח אַרְבָּעָה שְׁפָטִים. אִם נֶעֶנְשׁוּ נִשְׁפָּטִים. טֶבַע מִשְׁפָּטִים. אֲשֶׁר שָׂם יִזְכֹּר: זֵכֶר חֲצוֹת לַיְלָה. וְתוֹדוֹת מִשְׁפְּטֵי לַיְלָה. חֹשֶׁךְ בְּאִישׁוֹן לַיְלָה. נִגּוּנוֹ לָמוֹ יִזְכֹּר: חֵקֶר מִפְקַד לַיְלָה. יַגִּיהַּ בְּלַהַב לַיְלָה. חֹק הֶגֶה יוֹמָם וָלַיְלָה. לְגִיהָם יִזְכֹּר: זֵכֶר זֶה זְבוּל. אֲשֶׁר בְּבִצְעִי חָבוּל. זְדוֹנוֹת סָבוּל. עוֹד בַּל יִזְכֹּר: זַעַם כַּמַּבּוּל. אִם יָצְאָה לְחִבּוּל. זִכְרוֹן יֶרַח בּוּל. לְחֶמְלָה יִזְכֹּר: זֵכֶר וֶכַח כָּל פֹּעַל. בְּקַו וָפֶלֶס יַעַל. וְאִם בְּמֶרֶד וְאִם בְּמַעַל. רַב חֶסֶד יִזְכֹּר: וְאִם טוֹב וְאִם רַע. אֲשֶׁר בּוֹ יֶאֱרַע. וֶסְתּוֹ יִפָּרַע. בְּסַאסְאָה מִלִּזְכֹּר: זֵכֶר הַחַיִּים. עַד כַּמָּה הֵם חַיִּים. הֵן לַמָּוֶת אִם לְחַיִּים. חַי חַי יִזְכֹּר: הֲמוֹן שְׁאוֹן בְּרוּאִים. יַעַבְרוּ לְפָנָיו כִּמְרִיאִים. הֲלֹא כְּמוֹ רְאוּיִים. לְכָל אֶחָד יִזְכֹּר: זֵכֶר דַּלּוּת וָעֹשֶׁר. בַּצֹּרֶת וָחֹשֶׁר. דֹּפִי וְגַם יֹשֶׁר. בַּדִּין הוּא יִזְכֹּר: דְּבַר גָּלוּי וָסֵתֶר. בִּנְיָנוֹת וְסוֹתֵר. דֵּי חָסֵר וְיָתֵר. לְקֶצֶב יִזְכֹּר: זֵכֶר גְּנוּנִים לְיַשֵּׁב. בַּמִּדְבָּר וְיוֹשֵׁב. גֶּשֶׁם וָרוּחַ לְנַשֵּׁב. מֵהַיּוֹם יִזְכֹּר: גָּרוֹן לְהַקְשֵׁב. מֵעַם שְׁמוֹ חוֹשֵׁב. גָּלֻיּוֹת לְהָשֵׁב. בְּיוֹם תֵּקַע יִזְכֹּר: זֵכֶר בַּהַל וְחֵמָה. קְרָב וּמִלְחָמָה. בִּקּוּעַ חוֹמָה. לְחוֹמַת יָם יִזְכֹּר: בָּאָדָם וּבַבְּהֵמָה. אִם הֻקְנַס מְהוּמָה. בִּצּוּר קוֹל הוֹמָה. לַאֲדָמָה יִזְכֹּר: זֵכֶר אֱמוּנָה וָשֶׁקֶר. אִזּוּן שִׂיחַ וָסֶקֶר. אוֹת פְּקֻדַּת בֹּקֶר. לִרְגָעִים יִזְכֹּר: <small>חזן </small>אִם לְזוֹל אִם לְיֹקֶר. אִם לָטַעַת אִם לְעַקֵּר. אֱנוֹשׁ בְּדִקְדּוּק וָחֵקֶר. לַמִּשְׁפָּט יִזְכֹּר:", "note": "בנוסח המחזור: \"אם פץ להמטות נפץ חדר המטות לכפור יזכר\"", "a": 196, "b": 196, "head": 195}], "said": ["text", "חזרת הש\"ץ למוסף, יום א' של ראש השנה"], "when": [["rh", "text", "זכרונות, מוסף יום א'"]]}, {"id": "e04", "sec": "nach", "ref": "Rashi on Isaiah 6:3:1", "label": "רש\"י ישעיה ו:ג", "paytan": "", "kind": "line", "quotes": ["קְדוּשָׁה כֻּלָּם כְּאֶחָד עוֹנִים"], "rishonHtml": "<b>וְקָרָא זֶה אֶל זֶה.</b> נוֹטְלִין רְשׁוּת זֶה מִזֶּה, שֶׁלֹּא יַקְדִּים הָאֶחָד וְיַתְחִיל וְיִתְחַיֵּב שְׂרֵפָה, אֶלָּא אִם כֵּן פָּתְחוּ כֻּלָּם כְּאֶחָד; וְזֶהוּ שֶׁיִּסַּד בְּיוֹצֵר אוֹר: ׳<mark>קְדוּשָׁה כֻּלָּם כְּאֶחָד עוֹנִים</mark>׳. וּמִדְרַשׁ אַגָּדָה מַעֲשֵׂה מֶרְכָּבָה הוּא; וְכֵן תִּרְגֵּם יוֹנָתָן:", "version": "Sefaria vocalized edition", "source": "http://sefaria.org", "url": "https://www.sefaria.org/Rashi_on_Isaiah_6:3:1", "lit": [{"src": "yotzer_or", "seg": 3, "segHtml": "<b>אֶת שֵׁם</b> הָאֵל הַמֶּֽלֶךְ הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא קָדוֹשׁ הוּא. וְכֻלָּם מְקַבְּ֒לִים עֲלֵיהֶם עֹל מַלְכוּת שָׁמַֽיִם זֶה מִזֶּה. וְנוֹתְ֒נִים רְשׁוּת זֶה לָזֶה לְהַקְדִּישׁ לְיוֹצְ֒רָם בְּנַֽחַת רֽוּחַ. בְּשָׂפָה בְרוּרָה וּבִנְעִימָה. <mark>קְדֻשָּׁה כֻּלָּם כְּאֶחָד עוֹנִים</mark> וְאוֹמְ֒רִים בְּיִרְאָה:", "note": null, "a": 1, "b": 7, "head": null}], "said": ["rishon", "בְּיוֹצֵר אוֹר"], "when": [["everyday", "rishon", "ביוצר אור"]]}, {"id": "e05", "sec": "nach", "ref": "Rashi on Isaiah 24:22:3", "label": "רש\"י ישעיה כד:כב", "paytan": "הקלירי", "kind": "line", "quotes": ["לְרֹב יָמִים לְהִמָּנוֹת, לַחְשׁוֹב לָהֶם חֶשְׁבּוֹנוֹת"], "rishonHtml": "<b>וּמֵרֹב יָמִים יִפָּקֵדוּ.</b> עֲוֹנוֹת יָמִים רַבִּים יִפָּקְדוּ עֲלֵיהֶם, וְזֶהוּ שֶׁיִּסֵּד הַקָּלִירִי (בסלוק של יוצר דפרשת זכור): ״<mark>לְרֹב יָמִים לְהִמָּנוֹת, לַחְשׁוֹב לָהֶם חֶשְׁבּוֹנוֹת</mark>״:", "version": "Sefaria vocalized edition", "source": "http://sefaria.org", "url": "https://www.sefaria.org/Rashi_on_Isaiah_24:22:3", "lit": [{"src": "zachor", "seg": 31, "segHtml": "<b>זָכוֹר</b> אֵת אֲשֶׁר עָשָׂה לָךְ. אֲשֶׁר קָרְךָ וַיַּחֲשִׁילָךְ. וְהָיָה בְּהָנִיחַ יְהֹוָה אֱלֹהֶיךָ לָךְ. תִּמְחֶה זִכְרוֹ מִכָּל גְּבוּלָךְ. וְהֵם יָשִׁיבוּ וְיֹאמְרוּ לָךְ. וּמִשֶׁלָּךְ עוֹד יִתְּנוּ לָךְ. אָנָא הָקֵם אֶת דְּבַר מִלּוּלָךְ. עַד שָׁאַתָּה מְצַוֵּנוּ הִזָּכֵר לָךְ. אַתָּה זְכוֹר אֵת אֲשֶׁר עָשׂוּ לָךְ. זְכוֹר יְהֹוָה אֶת יוֹם זְבוּלָךְ. הַמִּתְגָּאִים וְנוֹאֲמִים פֹּה מַה לָךְ. הַשׁוֹלְחִים זְמוֹרוֹת בְּאַף לְחַלְּלָךְ. זְכוֹר כִּסֵּא כְּבוֹד גָּדְלָךְ. אֲשֶׁר מִגְּרוּ וְנִאֲצוּ לְמוּלָךְ. וְשִׁלְחוּ בָּאֵשׁ הֵיכָלָךְ. וַיַּשִּׁימוּ כָּל גְּבוּלָךְ. וְשִׁדְּדוּ וְנִתְּקוּ יְרִיעוֹת אָהֳלָךְ. אֲשֶׁר צִוִּיתָה לֹא יָבֹאוּ בַקָּהָל לָךְ. אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי בִּגְלָלָךְ. וְלֹא יִזָּכֵר שֵׁם הִלּוּלָךְ. עָלֶיךָ יַעֲזוֹב חֵילָךְ. וְיוֹתֵר מֵאֲשֶׁר עָשׂוּ לָנוּ עָשׂוּ לָךְ: אוֹתָנוּ בַּמִּדְבָּר נִלְחָמוּ. וְאוֹתְךָ בְּיִשׁוּב נִתְלָחֲמוּ. אוֹתָנוּ חוּץ לַמַּחֲנֶה הָמוּ. וְאוֹתְךָ בְּקֶרֶב הַמַּחֲנֶה נָהָמוּ. אוֹתָנוּ פְּלֵיטֵי עָנָן זָמָמוּ. וְאוֹתְךָ כַּפּוֹרֶת עָנָן גָּמָמוּ. אוֹתָנוּ לַחֲשׁוּלֵי עָב דִּמּוּ. וְאוֹתְךָ עֲלוֹת עַל בָּמֳתֵי עָב דָּמָמוּ. אוֹתָנוּ חוּץ מִמְּחִיצָה קָמוּ. וְאוֹתְךָ לִפְנַי וְלִפְנִים קִדְּמוּ. אוֹתָנוּ בְּרִחוּק מָקוֹם אִשְׁמוּ. וְאוֹתְךָ בְּקֶרֶב מְקוֹמְךָ שִׁמְּמוּ. אוֹתָנוּ חוּץ מִישִׁיבָתֵנוּ רָמוּ. וְאוֹתְךָ בִּמְכוֹן שִׁבְתְּךָ דַּמוּ. אוֹתָנוּ אוֹת בְּרִית מִשְׁאֵר הֵרִימוּ. וְאוֹתְךָ עֲשֶׂרֶת אַבִּירֵי בְרִית הֶחֱרִימוּ. אוֹתָנוּ בְהַנָחַת יְדֵי עָנָיו הֵרִימוּ. וְאוֹתְךָ תְּלוֹת יָד לְמוּלְךָ הֵרִימוּ. אוֹתָנוּ נִתְיַעֲצוּ וְסוֹד הֶעֱרִימוּ. וְאוֹתְךָ כְּרוּבֵי סוֹדְךָ לַחֲרָפוֹת הִגְרִימוּ: וְאַתָּה יְהֹוָה לְעוֹלָם תֵּשֵׁב. וְהוּא נֶגְדְּךָ בְּמַטָּה יוֹשֵׁב. תָּפוּשׂ מִדְבָּר וְכָל הַיִשׁוּב. אֲנִי וְאַפְסִי עוֹד בְּלֵב מִתְחַשֵׁב. אִם לֹא עַתָּה תָקוּם וְתַקְשֵׁב. בִּשְׁלֹשׁ עֶשְׂרֵה קִימוֹת נְקָמוֹת לְחַשֵּׁב. בְּפַחַד וָפַחַת וָפַח לִפְקוֹד עַל הַיּוֹשֵׁב. וְאִם אַיִן כַּגֵּר תֵּחָשֵׁב. וְכָל הַמּוֹנֶה וְסוֹפֵר וְחוֹשֵׁב. קֵץ הַפְּלָאוֹת לְהָבִין וּלְחַשֵׁב. נָשְׁתָה גְבוּרָתוֹ מִמְּחַשֵׁב. וְלֹא יִמְצָא מַעֲנֶה לְהָשֵׁב. וְיֶחֱשֶׁה דוּמִיָּה מֵהַקְשֵׁב. וּבֶאֱמוּנָה כְּסָלָיו יְיַשֵׁב. וְזֹאת עַל לִבּוֹ יָשֵׁב. וְיֹאמַר עַד יַשְׁקִיף וְיֵרֶא וְיַקְשֵׁב: וְנֶחֱשַׁבְתִּי כְּעֵד זוֹמֵם. כָּל הַיּוֹם מְדַמֵּם. וְנַפְשִׁי נִבְהֲלָה מְאֹד וּמִשְׁתּוֹמֵם. וְאַתָּה יְהֹוָה עַד מָתַי רוֹאֶה וְדוֹמֵם. זְכוֹר בֵּית מִקְדָּשְׁךָ הַשָׁמֵם. כָּל עוֹבֵר עָלָיו מִשְׁתּוֹמֵם. מָתַי תִּתְנַשֵׂא וְתִתְרוֹמֵם. וְזֶכֶר אֹמֶר פִּיךָ קוֹמֵם. בְּשָׁלֹשׁ עִתּוֹת עֲמָלֵק לְהָמֵם. בְּשָׁלֹשׁ מִיתוֹת זִכְרָם לְהַדְמֵם. בִּשְׁלֹשֶׁת יְמֵי אֲפֵלָה נָגְהָם לְהַעֲמֵם. בְּשִׁבְעָה יְמֵי עֶבְרָה לְהַרְשִׁימֵם. בַּעֲשֶׂרֶת מִינֵי שְׁמָד לְהַאֲשִׁימֵם: וּכְמוֹ מֵעֲשָׂרָה דְבָרִים עִכְּבוּ עָם מֵעֲנוֹת. וּמִשֶׁבַע מִצְוֹת הַמְּיֻשָׁנוֹת. כֵּן בְּעֶשֶׂר וָשֶׁבַע יֻשְׁכְּרוּ לְעַנּוֹת. וּבַת קוֹל תֵּצֵא מִמְּעוֹנוֹת. וּתְפוֹצֵץ בְּכָל הַמַּחֲנוֹת. זִכְרוֹן דְּבָרִים לְהַגִּיד וְלַעֲנוֹת. אַל תִּזְכְּרוּ רִאשׁוֹנוֹת. בִּינוּ נָא יְשׁוּעוֹת אַחֲרוֹנוֹת. וְהַזְכִּירוּ זֵכֶר רְנָנוֹת. עֲמָלֵק אֲשֶׁר בָּא וְעִוֵּת מַחֲנוֹת. וְהֵקַר אֶתְכֶם בִּפְנֵי בָנוֹת. וְיָצָא לוֹ שֵׁם בְּכָל הַמְּדִינוֹת. רְאוּ עַתָּה זֹאת לְתַנּוֹת. אֵיךְ נִמְחֶה בְּחֶתֶף בְּכָל פִּנּוֹת. וּצְבָא הַמָּרוֹם אֲשֶׁר בִּמְעוֹנוֹת. אֲשֶׁר הוּסְמַךְ עֲלֵיהֶם בְּמַשְׁעֵנוֹת. יִפְקוֹד עֲלֵיהֶם אֶת הָעֲוֹנוֹת. <mark>לְרוֹב יָמִים לְהִמָּנוֹת</mark>. לַחֲשׁוֹב לָהֶם חִשְׁבּוֹנוֹת. לְהַפִּילָם לְתוֹפֶת דֵּרְאוֹנוֹת. וַהֲמוֹן לְאֻמִּים וְכָל הַלְּשׁוֹנוֹת. עַל עוֹזֵר וְעָזוּר יִשְׂאוּ קִינוֹת. וְכָשַׁל עוֹזֵר וְנָפַל עָזוּר מְקוֹנְנוֹת: וְיֵדַע כָּל פָּעוּל כִּי לֹא שָׁכַחְתָּ. וְיָבִין כָּל יְצִיר כִּי שְׁמָם שִׁכַּחְתָּ. וְשֵׂעִיר וְשָׂרָיו אָז וִכַּחְתָּ. וַעֲמָלֵק וְטַפְסְרָיו הוֹכַחְתָּ. וְאִתָּם בַּמִּשְׁפָּט נִתְוַכַּחְתָּ. וְיֻזְכְּרוּ עַם אֲשֶׁר זָכַרְתָּ. כִּי לְטוֹבָה אוֹתָם זָכַרְתָּ. וּבְזִכְרוֹן טוֹב אִתָּם נִזְכַּרְתָּ:", "note": null, "a": 30, "b": 32, "head": null}], "said": ["editor", "בסלוק של יוצר דפרשת זכור"], "when": [["zachor", "text", "סלוק היוצר"]]}, {"id": "e02", "sec": "nach", "ref": "Rashi on Ezekiel 21:18:3", "label": "רש\"י יחזקאל כא:יח", "paytan": "הפייט", "kind": "line", "quotes": ["הַמּוֹאֶסֶת כָּל עֵץ הִדְקִיר הַמְּזַנֶּה"], "rishonHtml": "<b>לֹא יִהְיֶה.</b> עוֹד בְּנִי בָּעוֹלָם; וְכֵן תִּרְגֵּם יוֹנָתָן: ״לָא יִתְקַיְּמוּן״, אֲבָל שְׁאָר הַמִּקְרָא לֹא תִרְגֵּם כָּךְ; וְכֵן נִרְאֶה בְּעֵינַי. וְשָׁמַעְתִּי בּוֹ לְשׁוֹנוֹת רַבִּים, וְרָאִיתִי בְּסִפְרֵי פִּתְרוֹנוֹת, וְלֹא נִתְיַשְּׁבוּ לִי; וְהַפַּיָּט שֶׁיִּסֵּד בַּחֲנֻכָּה (בשבת ראשונה ביוצר): ״<mark>הַמּוֹאֶסֶת כָּל עֵץ הִדְקִיר הַמְּזַנֶּה</mark>״, מְסַיְּעֵנִי, שֶׁקָּרָא אֶת הַחֶרֶב מוֹאֶסֶת כָּל עֵץ (יחזקאל כא:טו). וְיוֹנָתָן כֵּן תִּרְגֵּם: ״אוֹ נָשִׂישׂ וְגוֹ׳״ (יחזקאל כא:טו) – ״עַל דַּחֲדִיאוּ שִׁבְטָא דְבֵית יְהוּדָה וּבִנְיָמִין לְשִׁבְטֵי דְיִשְׂרָאֵל, כַּד גְּלוֹ עַל דִּפְלָחוּ לְטָעֲוָותָא, וְתָבוּ אִינוּן לְמִטְעֵי בָּתַר צַלְמֵי אָעָא״; אַף הוּא מְפָרֵשׁ ״אוֹ נָשִׂישׂ״ לְשׁוֹן תְּמִיהָא:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Ezekiel_21:18:3", "lit": [], "said": ["rishon", "בַּחֲנֻכָּה (בשבת ראשונה ביוצר)"], "when": [["chanukah", "rishon", "בחנוכה (בשבת ראשונה ביוצר)"]]}, {"id": "e07", "sec": "nach", "ref": "Rashi on Ezekiel 42:20:1", "label": "רש\"י יחזקאל מב:כ", "paytan": "הקלירי", "kind": "line", "quotes": ["דָּוִד יִנְטֶה קַו שְׁלֹשֶׁת אַלְפֵי אַמּוֹת קְצוּבָה עַל שְׁלֹשֶׁת אַלְפֵי אַמּוֹת", "שְׁלֹשִׁים וְשִׁשָּׁה כְּמוֹ שֶׁהָיְתָה מִתְכַּפֶּלֶת"], "rishonHtml": "<b>לְאַרְבַּע רוּחוֹת מְדָדוֹ.</b> שְׁלֹשֶׁת אֲלָפִים עַל שְׁלֹשֶׁת אֲלָפִים אַמָּה, שֶׁהַקָּנֶה שֵׁשׁ אַמּוֹת (יחזקאל מ:ה); וְזֶהוּ שֶׁיִּסֵּד הַקְּלִירִי (בקדשתא דיום שני של סכות): ״<mark>דָּוִד יִנְטֶה קַו שְׁלֹשֶׁת אַלְפֵי אַמּוֹת קְצוּבָה עַל שְׁלֹשֶׁת אַלְפֵי אַמּוֹת</mark>״, וְהִיא שְׁלֹשִׁים וְשִׁשָּׁה כַּמִּדָּה הָרִאשׁוֹנָה – שֶׁהָיָה הַר הַבַּיִת חֲמֵשׁ מֵאוֹת אַמָּה עַל חֲמֵשׁ מֵאוֹת אַמָּה (מידות ב:א) – חֲלוֹק שְׁלֹשֶׁת אֲלָפִים עַל שְׁלֹשֶׁת אֲלָפִים לִרְצוּעוֹת שֶׁל חֲמֵשׁ מֵאוֹת אַמּוֹת שְׁתִי וָעֵרֶב, וְתִמְצָא שָׁם שְׁלֹשִׁים וְשִׁשָּׁה רְבָעִים שֶׁל חֲמֵשׁ מֵאוֹת עַל חֲמֵשׁ מֵאוֹת; וְעַל כֵּן אָמַר הַפַּיְּטָן (שם בקדשתא): ״<mark>שְׁלֹשִׁים וְשִׁשָּׁה כְּמוֹ שֶׁהָיְתָה מִתְכַּפֶּלֶת</mark>״, מָצָאתִי:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Ezekiel_42:20:1", "lit": [], "said": ["editor", "בקדשתא דיום שני של סכות"], "when": [["sukkos", "editor", "קדושתא דיום שני"]]}, {"id": "e08", "sec": "nach", "ref": "Rashi on Ezekiel 43:3:1", "label": "רש\"י יחזקאל מג:ג", "paytan": "הפייט", "kind": "line", "quotes": ["מַחֲזוֹת הַמְצֻחְצָחוֹת בְּתֵשַׁע מַחֲזוֹת"], "rishonHtml": "<b>וּכְמַרְאֵה הַמַּרְאֶה.</b> תֵּשַׁע מַרְאוֹת כְּתוּבִין בַּמִּקְרָא זֶה, וּמִתּוֹכָן הָיוּ רוֹאִין הַנְּבִיאִים, חוּץ מִמֹּשֶׁה רַבֵּינוּ שֶׁהָיָה רוֹאֶה מִתּוֹךְ מַרְאֶה אַחַת (ויקרא רבה א:יד), לְפִיכָךְ אִיסְפַּקְלַרְיָא שֶׁלּוֹ מְאִירָה (יבמות מט, ב) וְרוֹאֶה מַמָּשׁ; וְזֶהוּ שֶׁיִּסֵּד הַפַּיְּיט (שם בסלוק): ״<mark>מַחֲזוֹת הַמְצֻחְצָחוֹת בְּתֵשַׁע מַחֲזוֹת</mark>״:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Ezekiel_43:3:1", "lit": [], "said": ["editor", "שם בסלוק"], "when": [["sukkos", "editor", "\"שם בסלוק\", המשך ההערה ליחזקאל מב:כ"]]}, {"id": "e09", "sec": "nach", "ref": "Rashi on Ezekiel 48:1:3", "label": "רש\"י יחזקאל מח:א", "paytan": "רבי אלעזר", "kind": "line", "quotes": ["לְעֵת חִלּוּק אַרְצוֹתֶיהָ, כְּשׁוּרַת הַכֶּרֶם לְחוּצוֹתֶיהָ"], "rishonHtml": "<b>וְהָיוּ לוֹ פְּאַת קָדִים הַיָּם.</b> כְּלוֹמַר מִפְּאַת קָדִים וְעַד יָם דָּן אֶחָד, הֲרֵי פֵּרַשׁ הָאֹרֶךְ וְלֹא פֵּרַשׁ הָרֹחַב. וּבִבְרַיְתָא דְסִפְרִי בְּפָרָשַׁת הַאֲזִינוּ מַה תַּלְמוּד לוֹמַר <b>יְהוּדָה אֶחָד</b>, דָּן אֶחָד, <b>אָשֵׁר אֶחָד</b>, מְלַמֵּד שֶׁעֲתִידִין יִשְׂרָאֵל לִיטֹּל אֹרֶךְ מִן הַמִּזְרָח לַמַּעֲרָב בְּרֹחַב עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף קָנִים שֶׁהֵם שִׁבְעִים וַחֲמִשָּׁה מִילִין. וּמֵהֵיכָן לָמְדוּ הַשִּׁיעוּר הַזֶּה? מִן הַתְּרוּמָה שֶׁהִיא כְּאֶחָד מִן הַחֲלָקִים הַלָּלוּ כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן. מָצָאתִי שֶׁכָּךְ כָּתוּב <b>וְאֹרֶךְ כְּאַחַד הַחֲלָקִים</b>, וְהוּא רֹחַב עֶשְׂרִים חֲמֵשׁ אֶלֶף קָנִים, וְאֹרֶךְ מִפְּאַת יָם עַד פְּאַת קָדִים עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף קָנִים, מֵאָה וַחֲמִשִּׁים אֶלֶף אַמָּה, שֶׁהַקָּנֶה שֵׁשׁ אַמָּה. וְכָל אַלְפַּיִם אַמָּה מִיל, כְּמוֹ שֶׁאָנוּ לְמֵדִין בִּמְסֶכֶת יוֹמָא אֵצֶל עֶשֶׂר סֻכּוֹת שֶׁמִּירוּשָׁלַיִם וְעַד צוּק, הֲרֵי מֵאָה וַחֲמִשִּׁים אֶלֶף אַמָּה עוֹלִין לְשִׁבְעִים וַחֲמִשָּׁה מִיל. וְזֶהוּ שֶׁיִּסֵּד רַבִּי אֶלְעָזָר בְּפִיּוּט כִּי אֶקַּח מוֹעֵד (בסלוק דיום שני של סכות) ״<mark>לְעֵת חִלּוּק אַרְצוֹתֶיהָ, כְּשׁוּרַת הַכֶּרֶם לְחוּצוֹתֶיה</mark>ָ, בְּאֹרֶךְ מִפְּאַת קָדִים לִקְצוֹתֶיהָ, עַד יָם אוֹקְיָנוֹס לְמִצְוֹתֶיהָ, בְּרֹחַב שִׁבְעִים וַחֲמִשָּׁה מִיל חֲרִיצוֹתֶיהָ״ (ויש גורסין שִׁבְעִים וַחֲמִשָּׁה מִיל לִשְׁלוֹשׁ עֶשְׂרֵה רְצוּעוֹת, בֵּין רְצוּעוֹת הַשְּׁבָטִים וּרְצוּעוֹת הַקֹּדֶשׁ, יַעֲלוּ לִתְשַׁע מֵאוֹת שִׁבְעִים וַחֲמִשָּׁה מִילִין; וּלְמִנַּיִן אַרְבַּע מֵאוֹת פַּרְסָה עַל אַרְבַּע מֵאוֹת פַּרְסָה שֶׁל אֶרֶץ יִשְׂרָאֵל עוֹלִין הַמִּילִין לְשֵׁשׁ עֶשְׂרֵה מֵאוֹת לִסְכוּם הַקָּלִירִי, שֶׁאָמַר אַרְבַּעַת מִילִין הִיא פַּרְסָה. וְשֶׁמָּא מִילִין שֶׁל חֶשְׁבּוֹן הָרְצוּעוֹת גְּדוֹלִים הֵם, אֵין נִכְנָסִין אַרְבָּעָה מֵהֶם בַּפַּרְסָה. וְאָכֵן בָּא לְמַנּוֹת שְׁנֵי מִילִין לְמַחֲצִית (וּמֶחֱצָה) בְּפַרְסָה יַעֲלוּ כְּאַרְבַּע מֵאוֹת פַּרְסָה לְאֶלֶף מִילִין, וְחֶשְׁבּוֹן מִילִין שֶׁל רְצוּעָה אֵין עוֹלִין אֶלָּא תְשַׁע מֵאוֹת שִׁבְעִים וַחֲמִשָּׁה מִילִין, עֲדַיִן חָסֵר הַמִּנְיָן עֶשְׂרִים וַחֲמִשָּׁה מִילִין, לֹא כִּוֵּן מִנְיַן מִילִין הָרְצוּעוֹת שֶׁל שְׁמוֹנִים וְתֵשַׁע לְמִנְיַן אַרְבַּע מֵאוֹת פַּרְסָה. וּמִנַּיִן לָמַד רַבִּי אֱלִיעֶזֶר אֹרֶךְ הַשּׁוּרוֹת עַד יָם אוֹקְיָנוֹס שֶׁהוּא בְּסוֹף עוֹלָם? וּמִקְרָא מֵעִיד תְּחוּם מַעֲרָב עַד יָם הַגָּדוֹל שֶׁלִּפְנִים מִיָּם אוֹקְיָנוֹס הַרְבֵּה):", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Ezekiel_48:1:3", "lit": [], "said": ["rishon", "בְּפִיּוּט כִּי אֶקַּח מוֹעֵד (בסלוק דיום שני של סכות)"], "when": [["sukkos", "editor", "כי אקח מועד, סלוק דיום שני"]]}, {"id": "e10", "sec": "nach", "ref": "Rashi on Psalms 42:5:4", "label": "רש\"י תהלים מב:ה", "paytan": "הפייט", "kind": "line", "quotes": ["הָמוֹן חוֹגֵג וְשׁוֹטֵף כַּנָּהָר"], "rishonHtml": "<b>הָמוֹן חוֹגֵג.</b> שֶׁהָיוּ הוֹלְכִים לָחֹג, וְעַל כָּכָה יִסֵּד הַפַּיָּט (בשחרית פרשת שקלים ביוצר של אלה אזכרה עיין שם) ״עֹצֶם <b><mark>הָמוֹן חוֹגֵג</b> וְשׁוֹטֵף כַּנָּהָר</mark>״, וּמִדְרַשׁ אַגָּדָה לְשׁוֹן יְוָנִי, שֶׁקּוֹרִין לִבְרֵכַת מַיִם חוֹגְגִין:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Psalms_42:5:4", "lit": [{"src": "shekalim", "seg": 33, "segHtml": "<b>אֵלֶה</b> אֶזְכְּרָה אֵת אֲשֶׁר נַעֲשָׂה. בִּהְיוֹתִי בֶּטַח וְשָׁקֵט בְּנָכוֹן וְנִשָׂא. גּוֹעַלְתִּי בְּעֵבֶר וּשְׁקָלַי אֵיךְ אֶשָׂא: דֵּי שְׁקָלַי עַד לֹא שָׁקַלְתִּי. הִנָם לְמַס עוֹבֵד הַיוֹם שָׁקַלְתִּי. וּבְחֵטְא עִווּל שֶׁקֶל לְרָשָׁע נִשְׁקַלְתִּי: זוּזַי לְלֹא תַתִּי לְשָׁכְנִי בְגִילָה. חַבְתִּי לְתַשְׁלוּם דַּרְכְּמוֹן לְעוֹלֵי גוֹלָה. טֻבְּעוּ גַם הֵם וְהוּעֲרַמְתִּי מְגֻלָּה: יוֹשֶׁר שָׁלֹשׁ קֻפּוֹת מְשֻׁלָּשׁוֹת סְאִים. כְּנוּסוֹת לְמִקַּח שַׁי מְרִיאִים וְשֵׂיִים. לֻקְּחוּ וְאֵין עוֹד בִּצְעִי נוֹשְׂאִים: מִדַּת שׁוֹפְרוֹת תַּקְלִין חַדְתִּין וְעַתִּיקִין. נְדָבוֹת אֲשֶׁר בָּם הָיוּ מְעַתְּקִין. סָרוּ כַּמָּה מֶנִּי וְהַדְּבָרִים עַתִּיקִין: עוֹצֶם <mark>הֲמוֹן חוֹגֵג שׁוֹטֵף כַּנָהָר</mark>. פֻּזַר וְנוֹתַרְתִּי כְּתֹרֶן בְּרֹאשׁ הָהָר. צֶדֶק מְלוֹנִי שׁוּעֲרָר כְּתֵל הָר: קַן צִפּוֹר קָרָא לִמְרוֹם הָרִים. רֹאשׁ נְשׂוּאֶיךָ כְּמֵאָז בּוֹ לְהָרִים. שִׁבְעָה וּשְׁמוֹנָה עֲלֵיהֶם לְרֹאשׁ תָּרִים:", "note": "בנוסח הסידור: \"המון חוגג שוטף כנהר\", בלי וי\"ו.", "a": 31, "b": 34, "head": null}], "said": ["editor", "בשחרית פרשת שקלים ביוצר של אלה אזכרה"], "when": [["shekalim", "text", "יוצר"]]}, {"id": "e11", "sec": "nach", "ref": "Rashi on Psalms 121:1:2", "label": "רש\"י תהלים קכא:א", "paytan": "הקליר", "kind": "line", "quotes": ["וּמִתַּחְתֶּיהָ שְׁלֹשִׁים מַעֲלוֹת, זוֹ לְמַעְלָה מִזּוֹ עַד כִּסֵּא הַכָּבוֹד טָסוֹת וְעוֹלוֹת"], "rishonHtml": "<b>שִׁיר לַמַּעֲלוֹת.</b> רֶמֶז בְּמִּזְמוֹר שֵׁנִי לַמַּעֲלוֹת הָעוֹלוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא מִתַּחַת עֵץ הַחַיִּים לְכִסֵּא הַכָּבוֹד, דְּתַנְיָא בְּסִפְרֵי (ספרי דברים פיסקא מז): שִׁיר הַמַּעֲלוֹת אֵין כָּתוּב כָּאן אֶלָּא שִׁיר לַמַּעֲלוֹת – שִׁיר לְמִי שֶׁעָתִיד לַעֲשׂוֹת מַעֲלוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא. וְזֶהוּ שֶׁיִּסֵּד הַקָּלִיר (בסילוק דיוצר של יום ב׳ דסוכות שיסד ר׳ אליעזר הקליר שהוא בנו של רשב״י בחגיגה פ׳ אין דורשין ע״ש): ״<mark>וּמִתַּחְתֶּיהָ שְׁלֹשִׁים מַעֲלוֹת, זוֹ לְמַעְלָה מִזּוֹ עַד כִּסֵּא הַכָּבוֹד טָסוֹת וְעוֹלוֹת</mark>, בְּשִׂיחַ נְעִימוֹת שִׁיר הַמַּעֲלוֹת״:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Psalms_121:1:2", "lit": [], "said": ["editor", "בסילוק דיוצר של יום ב׳ דסוכות"], "when": [["sukkos", "editor", "סילוק דיוצר של יום ב'"]]}, {"id": "e12", "sec": "nach", "ref": "Rashi on Song of Songs 4:10:1", "label": "רש\"י שיר השירים ד:י", "paytan": "הבבלי", "kind": "line", "quotes": ["מְנוּחָה וּשְׁאָר וִעוּדִים"], "rishonHtml": "<b>מַה יָּפוּ דֹדַיִךְ.</b> כָּל מָקוֹם שֶׁהֶרְאֵית לִי שָׁם חִבָּה יָפֶה הוּא בְעֵינַי: גִּלְגָּל, שִׁילֹה, נוֹב וְגִבְעוֹן, וּבֵית עוֹלָמִים. הוּא שֶׁיָּסַד הַבַּבְלִי: \"<mark>מְנוּחָה וּשְׁאָר וִעוּדִים</mark>\". \"מְנוּחָה\", זוּ יְרוּשָׁלַיִם. \"וּשְׁאָר וִעוּדִים\", מָקוֹם שֶׁנִּתְוַעֲדָה שָׁם שְׁכִינָה לְיִשְׂרָאֵל:", "version": "The Metsudah Five Megillot, Lakewood, N.J., 2001", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002162036", "url": "https://www.sefaria.org/Rashi_on_Song_of_Songs_4:10:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e03", "sec": "nach", "ref": "Rashi on Lamentations 1:6:2", "label": "רש\"י איכה א:ו", "paytan": "הפייט", "kind": "line", "quotes": ["מָלֵא רֻדַּפְתִּי וְחָסְרָה שְׁנַת גְּאוּלַי"], "rishonHtml": "<b>לִפְנֵי רוֹדֶף.</b> כָּל \"רֹדֵף\" שֶׁבַּמִּקְרָא חָסֵר, וְזֶה מָלֵא, שֶׁנִּרְדְּפוּ רְדִיפָה שְׁלֵמָה עַל כֵּן יָסַד הַפַּיָּט, \"<mark>מָלֵא רֻדַּפְתִּי וְחָסְרָה שְׁנַת גְּאוּלַי</mark>\". \"שְׁנַת גְּאֻלַי בָּאָה\" חָסֵר כְּתִיב:", "version": "The Metsudah Five Megillot, Lakewood, N.J., 2001", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002162036", "url": "https://www.sefaria.org/Rashi_on_Lamentations_1:6:2", "lit": [{"src": "selichot2", "seg": 8, "segHtml": "<mark>מָלֵא רֻדַּפְתִּי וְחָסְרָה שְׁנַת גְּאוּל</mark>ַי. מְסוּרִים לְמַכִּים וּמוֹרְטִים וּלְתִקְוָה אוּלַי. וּמַדּוּעַ נִסְחֲפוּ אַבִּירַי וּמְתֵי שִׁיר אַיָּלַי. קַוֹּה קִוִּיתִי אֶל יְהֹוָה וַיֵּט אֵלַי:<br>", "note": null, "a": 2, "b": 14, "head": 0}], "said": ["text", "סליחות, יום ב' של עשרת ימי תשובה"], "when": [["teshuva", "text", "סליחות יום ב'"]]}, {"id": "e13", "sec": "nach", "ref": "Rashi on Lamentations 3:20:1", "label": "רש\"י איכה ג:כ", "paytan": "הפייט", "kind": "line", "quotes": ["בְּזֹאת יָדַעְתִּי כִּי יֵשׁ לְךָ לִזְכּוֹר, אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי עַד שֶׁתִּזְכּוֹר"], "rishonHtml": "<b>זָכוֹר תִּזְכּוֹר.</b> נַפְשִׁי אֶת עָנְיִי וּמְרוּדִי וְתָשׁוֹחַ עָלַי. כַּךְ הוּא פְשׁוּטוֹ לְפִי עִנְיַן שִׁיטַת הַמִּקְרָא. וּמִדְרַשׁ אַגָּדָה: \"זָכוֹר תִּזְכּוֹר\", יָדַעְתִּי שֶׁסּוֹפְךָ לִזְכּוֹר אֶת הֶעָשׂוּי לִי, אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי לְהַמְתִּין עַד זְמַן הַזְּכִירָה, וּמִכַּאן יִסַּד הַפַּיָּט, \"<mark>בְּזֹאת יָדַעְתִּי כִּי יֵשׁ לְךָ לִזְכּוֹר, אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי עַד שֶׁתִּזְכּוֹר</mark>\":", "version": "The Metsudah Five Megillot, Lakewood, N.J., 2001", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002162036", "url": "https://www.sefaria.org/Rashi_on_Lamentations_3:20:1", "lit": [{"src": "zachor", "seg": 20, "segHtml": "<b>אֵל</b> נָא בְּלָשׁוֹן אֲשֶׁר הִזְכַּרְתָּ לְזוֹכְרֶיךָ זְכוֹר. בּוֹ בְלָשׁוֹן הִזְכִּירוּךָ נָא אַתָּה זְכוֹר. וְאִם הֵמָּה כְּאָדָם עָבְרוּ בְרִית מִלִּזְכּוֹר. וְאַתָּה אֵל וְלֹא אִישׁ לָמָּה לֹא תִזְכּוֹר. <mark>בְּזֹאת יָדַעְתִּי כִּי יֵשׁ לְךָ לִזְכּוֹר</mark>. אֲבָל תָּשׁוֹחַ עָלַי נַפְשִׁי עַד זָכוֹר תִּזְכּוֹר. וּמַה כֹּחִי כִּי אֲיַחֵל לְקֵץ זָכוֹר. וּמַה קִּצִּי כִּי אַאֲרִיךְ נַפְשִׁי עַד שֶׁתִּזְכּוֹר. אִם לֹא לְמַעֲנִי תִּזְכּוֹר. לְמַעַנְךָ וּלְמַעַן יְרוּשָׁלַיִם זְכוֹר. חוֹק כִּי לֹא תִשָּׁכַח עֵדוּת זְכוֹר. וְאוֹמֵר אִם אֶשְׁכָּחֵךְ עַתָּה לָהּ זְכוֹר. וְתִפְקוֹד וְתִזְכּוֹר. כְּאֵב צָר לַעֲכוֹר. פִּיהוּ לִסְכּוֹר. לָנוּעַ כַּשִּׁכּוֹר. וְעוֹד בַּל תִּמְכּוֹר. נְקוּבֵי בֵּן בְּכוֹר:", "note": null, "a": 15, "b": 23, "head": null}], "said": ["text", "יוצר לפרשת זכור"], "when": [["zachor", "text", "יוצר"]]}, {"id": "e14", "sec": "nach", "ref": "Rashi on Daniel 8:14:2", "label": "רש\"י דניאל ח:יד", "paytan": "רבי אלעזר הקליר", "kind": "line", "quotes": ["שְׁבוּעִים שִׁשָּׁה"], "rishonHtml": "<b>וְנִצְדַּק קֹדֶשׁ.</b> יְכֻפַּר עֲוֹן יִשְׂרָאֵל, לְבַטֵּל גְּזֵרוֹת מִדְרְסָן וּמְרַפְּסָן מֵאָז גָּלוּ גָּלוּת רִאשׁוֹנָה לְמִצְרַיִם עַד יִגָּאֲלוּ וְיִוָּשְׁעוּ תְּשׁוּעַת עוֹלָמִים בְּמֶלֶךְ מְשִׁיחֵנוּ. וְחֶשְׁבּוֹן זֶה כָּלֶה לְסוֹף אֶלֶף וּמָאתַיִם וְתִשְׁעִים מִיּוֹם הוּסַר הַתָּמִיד, וְהוּא שֶׁנֶּאֱמַר בְּסוֹף הַסֵּפֶר ״וּמֵעֵת הוּסַר הַתָּמִיד לָתֵת שִׁקּוּץ שֹׁמֵם יָמִים אֶלֶף מָאתַיִם וְתִשְׁעִים״ (דניאל יב:יא) יִהְיֶה וְלֹא יוֹתֵר, שֶׁיָּבֹא הַמֶּלֶךְ מְשִׁיחֵנוּ וְיָסִיר שִׁקּוּץ הַשּׁוֹמֵם. וְהַתָּמִיד הוּסַר שֵׁשׁ שָׁנִים לִפְנֵי הַחֻרְבָּן בַּיִת שֵׁנִי וְהֶעֱמִיד צֶלֶם בַּהֵיכָל, וְיוֹם שִׁבְעָה עָשָׂר בְּתַמּוּז הָיָה שֶׁשָּׂרַף אַפּוֹסְטְמוֹס אֶת הַתּוֹרָה וּבִטֵּל אֶת הַתָּמִיד וְהֶעֱמִיד צֶלֶם בַּהֵיכָל, כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת תַּעֲנִית (תענית כו:). וְשֵׁשׁ שָׁנִים שֶׁכָּתַבְתִּי אֵין בְּיָדִי רְאָיָה מְפֹרֶשֶׁת, אַךְ יֵשׁ רְאָיָה שֶׁשָּׁבוּעַ שָׁלֵם לֹא בָּטַל הַתָּמִיד לִפְנֵי הַחֻרְבָּן, שֶׁכֵּן נִבָּא דָּנִיֵּאל עַל טִיטוּס ״וַחֲצִי הַשָּׁבוּעַ יַשְׁבִּית זֶבַח וּמִנְחָה״ (דניאל ט:כז), כְּלוֹמַר: מִקְצָת הַשָּׁבוּעַ שֶׁלִּפְנֵי הַחֻרְבָּן יְבַטְּלוּ הַקָּרְבָּנוֹת; כָּךְ מְפֹרָשׁ לְמַטָּה בָּעִנְיָן (שם). נַחֲזֹר עַל הָרִאשׁוֹנוֹת, כֵּיצַד מְכֻוָּן חֶשְׁבּוֹן <b>עֶרֶב בֹּקֶר אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת</b> מִיּוֹם רֶדֶת יִשְׂרָאֵל לְמִצְרַיִם לִהְיוֹת כָּלֶה לְסוֹף אֶלֶף וּמָאתַיִם וַחֲמִשִּׁים לְיוֹם שֶׁהוּסַר הַתָּמִיד: מָאתַיִם וְעֶשֶׂר הָיוּ בְמִצְרַיִם, אַרְבַּע מֵאוֹת וּשְׁמוֹנִים מִיּוֹם צֵאתָם עַד ״וַיִּבֶן הַבַּיִת״ (מלכים א ו:א); אַרְבַּע מֵאוֹת וְעֶשֶׂר הָיָה הַבַּיִת, וְשִׁבְעִים שָׁנָה גָּלוּת בָּבֶל, וְאַרְבַּע מֵאוֹת וְעֶשְׂרִים בַּיִת שֵׁנִי, תֵּן עֲלֵיהֶם אֶלֶף וּמָאתַיִם וְתִשְׁעִים שֶׁל קֵץ הַיָּמִים, הֲרֵי אַלְפַּיִם וּשְׁמוֹנֶה מֵאוֹת. צֵא מֵהֶן שֵׁשׁ שָׁנִים שֶׁהוּסַר הַתָּמִיד לִפְנֵי הַחֻרְבָּן, שֶׁלֹּא מָנָה הַכָּתוּב אֶלֶף וּמָאתַיִם וְתִשְׁעִים אֶלָּא לְמֵעֵת הוּסַר הַתָּמִיד, הֲרֵי לְךָ חֶשְׁבּוֹן עֶרֶב וָבֹקֶר וְאַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת. עוֹד נוֹסָף בַּחֶשְׁבּוֹן ״אַשְׁרֵי הַמְחַכֶּה וְיַגִּיעַ לְיָמִים״ (דניאל יב:יב) אַרְבָּעִים וְחָמֵשׁ שָׁנָה יְתֵרִים עַל אֶלֶף וּמָאתַיִם וְתִשְׁעִים יֵשׁ לוֹמַר עַל חֶשְׁבּוֹן הָרִאשׁוֹן, יֵצֵא הַמֶּלֶךְ הַמָּשִׁיחַ וְיַחֲזֹר וְיִתְכַּסֶּה מֵהֶם אוֹתָם אַרְבָּעִים וְחָמֵשׁ שָׁנִים. וְרַבִּי אֶלְעָזָר הַקַּלִּיר יִסֵּד בִּיסוֹד שִׁירוֹ (בְּסִלּוּק יוֹצֵר שֶׁל פָּרָשַׁת הַחֹדֶשׁ): <mark>שְׁבוּעִים שִׁשָּׁה</mark> הֲרֵי אַרְבָּעִים וּשְׁתַּיִם; וְיֵשׁ לוֹמַר: הַשָּׁלֹשׁ שָׁנִים שֶׁלֹּא בָּאוּ לְחֶשְׁבּוֹן שָׁבוּעַ לֹא מָנָה. וַאֲנִי מָצָאתִי כָּךְ בְּמִדְרַשׁ רוּת, שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לְהִתְכַּסּוֹת אַרְבָּעִים וְחָמֵשׁ שָׁנִים לְאַחַר שֶׁיִּגָּלֶה, וּמֵבִיא רְאָיָה מִן הַמִּקְרָאוֹת הַלָּלוּ:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Daniel_8:14:2", "lit": [{"src": "hachodesh", "seg": 31, "segHtml": "<b>וְעוֹד</b> בַּל יֻזְכְּרוּ רִאשׁוֹנִים. כִּי יְחֻדְּשׁוּ חֲדָשִׁים וְגַם יְשָׁנִים. פְּלָאִים מִפְּלָאִים מְשֻׁנִּים. וְיָקִיצוּ כָּל יְשֵׁנִים. מְהַלְּלִים וּמְשׁוֹרְרִים שִׁירִים מִשִּׁירִים מְשַׁנְּנִים: וְלֹא יֹאמְרוּ עוֹד אֲשֶׁר הֶעֱלָה בְּנָבִיא. כִּי אִם חַי יְהֹוָה אֲשֶׁר הֶעֱלָה וַאֲשֶׁר הֵבִיא. וְאָז אֵל יִשְׁאַג כְּלָבִיא. לַעֲרוֹךְ קְרָבִי. חֲדָשׁוֹת לְהָבִיא. בְּיַד אִישׁ נָבִיא. מִשֵׁבֶט לֵוִי. לְהָשִׁיב לְבָבִי. לְחַדֵּשׁ קְרָבִי: וְיַצְמִיחַ צֶמַח נָקוּב שִׁבְעָה. וְאִתּוֹ יְהוּ רוֹעִים שִׁבְעָה. וִיחֻדְּשׁוּ לְאוֹם דְּבָרִים שִׁבְעָה. וְיִ<mark>תְכַּסֶּה מֵהֶם שָׁבֻעִים</mark> שִׁבְעָה:", "note": "בנוסח הסידור שבספריא: \"שבעים שבעה\". רש\"י מביא \"שבועים ששה\".", "a": 30, "b": 35, "head": null}], "said": ["editor", "בסלוק יוצר של פרשת החדש"], "when": [["hachodesh", "text", "סלוק היוצר"]]}, {"id": "e15", "sec": "nach", "ref": "Rashi on Daniel 12:12:1", "label": "רש\"י דניאל יב:יב", "paytan": "רבי אליעזר הקליר", "kind": "line", "quotes": ["וְיִתְכַּסֶּה מֵהֶם שְׁבוּעִים שִׁשָּׁה"], "rishonHtml": "<b>אַשְׁרֵי הַמְחַכֶּה וְגוֹ׳.</b> אַרְבָּעִים וְחָמֵשׁ שָׁנִים נוֹסָפִים עַל חֶשְׁבּוֹן הָעֶלְיוֹן, שֶׁעָתִיד מְשִׁיחֵנוּ לְהִתְכַּסּוֹת אַחַר שֶׁנִּגְלָה, וְיָשׁוּב וְיִתְגַּלֶּה. וְכֵן מָצִינוּ בְּמִדְרַשׁ רוּת, וְכֵן יִסַּד רַבִּי אֱלִיעֶזֶר הַקַּלִּיר (בְּסִלּוּק יוֹצֵר פָּרָשַׁת הַחֹדֶשׁ): <mark>וְיִתְכַּסֶּה מֵהֶם שְׁבוּעִים שִׁשָּׁה</mark>:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_Daniel_12:12:1", "lit": [{"src": "hachodesh", "seg": 31, "segHtml": "<b>וְעוֹד</b> בַּל יֻזְכְּרוּ רִאשׁוֹנִים. כִּי יְחֻדְּשׁוּ חֲדָשִׁים וְגַם יְשָׁנִים. פְּלָאִים מִפְּלָאִים מְשֻׁנִּים. וְיָקִיצוּ כָּל יְשֵׁנִים. מְהַלְּלִים וּמְשׁוֹרְרִים שִׁירִים מִשִּׁירִים מְשַׁנְּנִים: וְלֹא יֹאמְרוּ עוֹד אֲשֶׁר הֶעֱלָה בְּנָבִיא. כִּי אִם חַי יְהֹוָה אֲשֶׁר הֶעֱלָה וַאֲשֶׁר הֵבִיא. וְאָז אֵל יִשְׁאַג כְּלָבִיא. לַעֲרוֹךְ קְרָבִי. חֲדָשׁוֹת לְהָבִיא. בְּיַד אִישׁ נָבִיא. מִשֵׁבֶט לֵוִי. לְהָשִׁיב לְבָבִי. לְחַדֵּשׁ קְרָבִי: וְיַצְמִיחַ צֶמַח נָקוּב שִׁבְעָה. וְאִתּוֹ יְהוּ רוֹעִים שִׁבְעָה. וִיחֻדְּשׁוּ לְאוֹם דְּבָרִים שִׁבְעָה. וְיִ<mark>תְכַּסֶּה מֵהֶם שָׁבֻעִים</mark> שִׁבְעָה:", "note": "בנוסח הסידור שבספריא: \"שבעים שבעה\". רש\"י מביא \"שבועים ששה\".", "a": 30, "b": 35, "head": null}], "said": ["editor", "בסלוק יוצר פרשת החדש"], "when": [["hachodesh", "text", "סלוק היוצר"]]}, {"id": "e16", "sec": "nach", "ref": "Rashi on I Chronicles 25:3:1", "label": "פירוש המיוחס לרש\"י, דה\"י א כה:ג", "paytan": "הפייטן", "kind": "line", "quotes": ["רָשׁוּם מִבֶּטֶן לְהִפָּקֵד בְּמִשְׁמֶרֶת הַקֹּדֶשׁ"], "rishonHtml": "<b>וּמַתִּתְיָהוּ שִׁשָּׁה.</b> וְלֹא תִמְצָא אֶלָּא חָמֵשׁ! אִשְׁתּוֹ הָיְתָה מְעֻבֶּרֶת אֶת שִׁמְעִי, וְרָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁגַּם הוּא עָתִיד לִהְיוֹת רֹאשׁ מִשְׁמָרָה, לְפִיכָךְ אָמַר: שִׁשָּׁה; וְזֶהוּ שֶׁנֶּאֱמַר לְפָנֵינוּ <b>הָעֲשִׂירִי שִׁמְעִי.</b> זֶהוּ שֶׁיִּסֵּד הַפַּיְּטָן (בקדשת של יוצר דפרשת שקלים) ״<mark>רָשׁוּם מִבֶּטֶן לְהִפָּקֵד בְּמִשְׁמֶרֶת הַקֹּדֶש</mark>ׁ״:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_I_Chronicles_25:3:1", "lit": [{"src": "shekalim", "seg": 28, "segHtml": "<b>אוֹמֵן</b> בְּשָׁמְעוֹ כִּי תִשָׂא אֶת רֹאשׁ. חָל וַיֵּחַת אֵיךְ אוֹתָם דְּרוֹשׁ: לְעַם אֲשֶׁר לֹא יִמַּד וְלֹא יִסָּפֵר. אֵיכָכָה אֶסְפְּרֵם וְלֹא נִתְּנוּ לְהִסָפֵר: עִקָרָם כְּנֶאֱמַר לוֹ הַבֵּט וּסְפוֹר. שָׁב וַיוּשַׁב אִם תּוּכַל לִסְפּוֹר: זַרְעָם כְּחוֹל יַמִּים וְכוֹכָבִים סְפוּרִים. וַאֲנִי אֵיךְ אֶסְפְּרֵם וְלָעַד פָּרִים: רָם חִוָּה לוֹ אוֹת מִסְפָּרָם. אֵיךְ לִמְנוֹתָם וְלַעֲמוֹד עַל סִפְרָם: בִּקּוּר רָאשֵׁי שְׁמוֹתָם לְחֶשְׁבּוֹן תְּעַלֶּה. וּמִדַּת מִנְיָנָם בְּיָדְךָ אָז תַּעֲלֶה: יָקָר שְׁלִישִׁי בְּתוֹכָם לֹא הָפְקַד. כִּי לִגְיוֹן מֶלֶךְ לְבַדּוֹ נִפְקַד: <mark>רָשׁוּם מִבֶּטֶן לְהִפָּקֵד בְמִשְׁמֶרֶת הַקֹּדֶש</mark>ׁ. וּצְבָאוֹ וּפְקוּדָיו נִמְנִים מִבֶּן חוֹדֶשׁ: בְּשָׁמְעוֹ אֹמֶר וְנָתְנוּ אִישׁ כּוֹפֶר. פָּץ בַּמֶּה יִתְרַצֶּה אֶשְׁכּוֹל הַכּוֹפֶר: יְצִיר מַה יִתֵּן פִּדְיוֹן נַפְשׁוֹ. וְיִמְצָא חֲנִינָה פְּנֵי שָׂם נַפְשׁוֹ: קָדוֹשׁ כְּחָפֵץ לְהַצְדִּיק עַם זֶה. כְּמִין מַטְבֵּעַ אֵשׁ הֶרְאָהוּ בַּמַּחֲזֶה: לִמְּדוֹ זֶה יִתְּנוּ וְלֹא יִתְמַתְנוּ. וְלַכֹּל יְתַנוּ אֵת אֲשֶׁר נָתְנוּ: יָהּ לֹא מְצָאנוּךָ שַׂגִּיא כֹּחַ. כַּאֲשֶׁר נִקֵיתָ חֵטְא גִּבּוֹרֵי כֹּחַ:", "note": null, "a": 22, "b": 29, "head": null}], "said": ["editor", "בקדשת של יוצר דפרשת שקלים"], "when": [["shekalim", "text", "קדושתא של היוצר"]]}, {"id": "e17", "sec": "nach", "ref": "Rashi on I Chronicles 28:9:1", "label": "פירוש המיוחס לרש\"י, דה\"י א כח:ט", "paytan": "הפייט", "kind": "line", "quotes": ["שְׁנֵי לְבָבוֹת לְךָ כְּאֶחָד לְאֶחָד"], "rishonHtml": "<b>בְּלֵב שָׁלֵם.</b> בְּלֵבָב שָׁלֵם לֹא נֶאֱמַר, שֶׁיְּהֵא מַשְׁמַע: שְׁנֵי לְבָבוֹת, אֶלָּא בְּלֵב שָׁלֵם, שֶׁלֹּא יִהְיֶה לְךָ אֶלָּא לֵבָב אֶחָד לְאָבִינוּ שֶׁבַּשָּׁמַיִם; וְכֵן יָסַד הַפַּיָּט (בקדושתא דמוסף של יום ראשון דראש השנה): ״<mark>שְׁנֵי לְבָבוֹת לְךָ כְּאֶחָד לְאֶחָד</mark>״. וְדֻגְמָתוֹ: ״וְהָיָה לְבַבְכֶם שָׁלֵם עִם ה׳ אֱלֹהֵינוּ״ (מלכים א ח:סא) – שְׁלֵמִים לֹא כְתִיב, אֶלָּא ״שָׁלֵם״, כָּל שְׁנֵי לְבוֹתָם יִהְיוּ לֵב אֶחָד שָׁלֵם. וְכֵן מְפֹרָשׁ בִּבְרֵאשִׁית רַבָּה (בראשית רבה מח:א): ״וְסַעֲדוּ לִבְּכֶם אַחַר תַּעֲבֹרוּ״ (בראשית יח:ה) – מְלַמֵּד שֶׁאֵין לַמַּלְאָכִים אֶלָּא לֵב אֶחָד. וְגַם לֶעָתִיד לָבֹא יִהְיֶה כֵּן, כְּדִכְתִיב ״שִׁיתוּ לִבְּכֶם לְחֵילָה״ (תהלים מח:יד):", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_I_Chronicles_28:9:1", "lit": [{"src": "rh1_musaf", "seg": 80, "segHtml": "<b>וְעַמְּךָ </b>תְלוּאִים בִּתְשׁוּבָה לְהִתְיַחֵד. <mark>שְׁנֵי לְבָבוֹת לְךָ כְּאַחַד לְאֶחָד</mark>. רַחֵץ בְּנִקְיוֹן כַּפַּיִם נְשׂוֹא לֵב אֶחָד. קוֹל שׁוֹפָר כָּפוּף כְּפֹף לֵב אֶחָד. צִיּוּן שׁוֹפָר פָּשׁוּט פְּשֹׁט לֵב אֶחָד: פּוּר יָמִים יֻצָּרוּ בָּם לָבוּר אֶחָד. עוֹבְרִים בּוֹ לְהַקְבִּיל פְּנֵי יוֹצֵר אֶחָד: <small>חזן </small>סְמוּכִים בְּצִדְקַת אָב הָיָה אֶחָד. נִשְׁעָנִים בַּסְּבַךְ יָחִיד וּמְיֻחָד. מֻבְטָחִים בְּתָם (<small>נ\"א </small>בְּתֹם) וּבְיֹשֶׁר אָב אֶחָד:", "note": null, "a": 80, "b": 84, "head": 79}], "said": ["editor", "בקדושתא דמוסף של יום ראשון דראש השנה"], "when": [["rh", "text", "קדושתא דמוסף יום א'"]]}, {"id": "e18", "sec": "nach", "ref": "Rashi on II Chronicles 20:1:1", "label": "פירוש המיוחס לרש\"י, דה\"י ב כ:א", "paytan": "הקליר", "kind": "line", "quotes": ["זְכוֹר עָרִיץ בָּעַמּוֹנִים נֶחְבָּא, פָּרַץ כַּרְמֵי עֵין גֶּדִי כְּהוּבָא"], "rishonHtml": "<b>וְעִמָּהֶם מֵהָעַמּוֹנִים.</b> זֶה עֲמָלֵק, וְלָמָּה נִקְרְאוּ עַמּוֹנִים? לְפִי שֶׁשִּׁנָּה כְּסוּתוֹ וּלְשׁוֹנוֹ כְּעַמּוֹנִים וְנִתְעָרְבוּ בָּהֶם, וּבָא לְהִלָּחֵם בְּיִשְׂרָאֵל (ילקוט שמעוני תורה תשסד); וְכֵן מוּכָח לְמַטָּה בָּעִנְיָן <b>וּבְעֵת הַחֵלּוּ בְּרִנָּה וּתְהִלָּה נָתַן ה׳ מְאָרְבִים עַל בְּנֵי עַמּוֹן וּמוֹאָב וְהַר שֵׂעִיר וְגוֹ׳</b> – נִמְצָא שֶׁהָעַמּוֹנִים שֶׁנֶּאֱמַר כָּאן הֵם עֲמָלֵקִים שֶׁשִּׁנּוּ לְשׁוֹנָם וּכְסוּתָם. וְהוּא שֶׁיִּסֵּד הַקַּלִּיר בְּפָרָשַׁת זָכוֹר (בפיוט זכור איש): ״<mark>זְכוֹר עָרִיץ בָּעַמּוֹנִים נֶחְבָּא, פָּרַץ כַּרְמֵי עֵין גֶּדִי כְּהוּבָא</mark>״ – כְּלוֹמַר: זְכוֹר מַה שֶּׁעָשָׂה עֲמָלֵק (דברים כה:יז) הֶעָרִיץ שֶׁנֶּחְבָּא בֵּין הָעַמּוֹנִים, וּבָא לִפְרֹץ כַּרְמֵי יִשְׂרָאֵל בְּאוֹתוֹ זְמַן, כְּדִכְתִיב ״וְהִנָּם בְּחַצְצוֹן תָּמָר הִיא עֵין גֶּדִי״ (דברי הימים ב כ:ב). וְ״עֵין גֶּדִי״ סָמוּךְ לִמְחוֹז שֶׁל עֲמָלֵק, כְּמוֹ שֶׁנֶּאֱמַר בְּלֶךְ לְךָ ״וַיַּכּוּ אֶת כָּל שְׂדֵה הָעֲמָלֵקִי וְגַם אֶת הָאֱמֹרִי הַיּוֹשֵׁב בְּחַצְצוֹן תָּמָר״ (בראשית יד:ז):", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_II_Chronicles_20:1:1", "lit": [{"src": "zachor", "seg": 28, "segHtml": "<b>זָכוֹר</b> אִישׁ אֲשֶׁר הִגְוִיעַ אָב לְלֹא עִתּוֹ. בְּרָצוֹחַ וְגָנוֹב וְנָאוֹף בִּעֲתוֹ. גָּרַע חָמֵשׁ שָׁנִים מִמִחְיָתוֹ: זָכוֹר בּוֹזֶה עַל גְּמִילוּת חֶסֶד. גּוֹעֵל אָח עָשׂ לִזְקֵנוֹ חֶסֶד. דּוֹמֶה לַמָּס מֵרֵעֵהוּ חָסֶד: זָכוֹר גִלָּה עֶרְוַת מְצוּאַת שָׂדֶה. דָּם שָׁפַךְ בְּבוֹאוֹ מִן הַשָׂדֶה. הָפַךְ לֵב אָב שָׂח בַּשָׂדֶה: זָכוֹר דָּחוּי בְּאֹזֶן הָעֲרֵלָה. הַבּוֹזֶה בְּכוֹרָה בְּכוֹס הַתַּרְעֵלָה. וּפָרַק מֶנּוּ עוֹל וּמָשַׁךְ לוֹ עָרְלָה: זָכוֹר הֲפַכְפַּךְ דֶּרֶךְ אִישׁ וָזָר. וְהִכְהָה מְאוֹר אָב בַּעֲשַׁן עֲבוֹדַת זָר. זָמַם בְּלֵב הֱיוֹת לְאָח לְאַכְזָר: זָכוֹר וְנִתְעוֹלֵל לְרֶבַע כְּאִשָּׁה. זְדוֹן לִבּוֹ הִשִׁיאוֹ בָּאְשָׁה. חַתּוּ גִבּוֹרָיו לִהְיוֹת כְּלֵב אִשָּׁה: זָכוֹר זֶרַע מְרֵעִים נִתְעָב וְנֶאֱלָח. חָלַק לְהַשְׁחִית וְלוֹמַר הֶאָח. טָמְנוּ גֵּאִים פַּח לְחַבֵּל אָח: זָכוֹר חָנַט מֶנּוּ עֲמָלֵקִי. טָס כְּיֶלֶק לְאַבֵּד חֶלְקִי. יָרוֹעַ כַּבִּירִים לְעֵין כֹּל לְלוֹקְקִי: זָכוֹר טָפַשׁ מֵהַעֲרִימָה. יָרַד וְכִתֵּת עַמִּי עַד חָרְמָה. כְּמוֹ כֵן חֻיַּב לְהַחֲרִימָה: זָכוֹר יוֹשֵׁב הַנֶּגֶב בְּלִי עוֹל כַּעֲרָד. כְּסוּת וְלָשׁוֹן שִׁנָּה הֱיוֹת מֶלֶךְ עֲרָד. לִשְׁבּוֹת שֶׁבִי מָרַד וְחָרַד: זְכוֹר כְּסִיל שׁוֹנֶה בְּאִוַּלְתּוֹ. לְתַעֲרוּבַת מִדְיָן בַּעֲלוֹתוֹ. מִהֵר יְרֻבֶּשֶׁת וְגִלָּה נַבְלוּתוֹ: זָכוֹר לְקַעֲקֵעַ בִּצָתוֹ מִשׁוֹרֶשׁ. מִלַעֲזוֹב לוֹ עָנָף וְגַם שׁוֹרֶשׁ. נֶעֱנַשׁ קִישִׁי כִּי הִשְׁאִיר לוֹ שׁוֹרֶשׁ: זָכוֹר מַעֲשֵׂה אֲגַג מַעֲדַנּוֹת. נָשִׁים כְּשִׁכְּלָה חַרְבּוֹ לְעַנוֹת. סוֹרַס שְׁאֵרוֹ לְשִׁסוּף יַעֲנוֹת: זָכוֹר נָגִיד לְחָמְלוֹ הִסְכִּים. סָר מִמְּלוּכָה מִבֵּין נְסִיכִים. עוֹלֵל הַנּוֹתָר עָמַד לְשִׂכִּים: זָכוֹר סִבֵּב צִקְלַג וָנֶגֶב. עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. פִּגְרוֹ טוֹב רוֹאִי מְנַשֵׁף בְּעֻגָב: <mark>זָכוֹר עָרִיץ בְּעַמּוֹנִים נֶחְבָּא</mark>. פֶּרֶץ כַּרְמֵי עֵין גֶּדִי כְּהוּבָא. צוֹרְבוּ אִישׁ בְּאָחִיו בְּחֶרֶב לְהוּבָה: זָכוֹר פְּלֵטִים אֲשֶׁר בְּאַף הִסְעִיר. צְבָאַי בְּלֶכְתָּם אֶל הַר שֵּׂעִיר. קַנֹּא לִנְקוֹם עֲיָרוֹת שֵׂעִיר: זָכוֹר צָג בְּפֶרֶק לְהַסְגִּיר שְׂרִידַי. קָם בְּרֹאשׁ דְּרָכִים לִסְעוֹד אֶת רוֹדַי. רָדַף וּמָסַר בְּיָדָם פְּרוּדַי רְפוּדַי: זָכוֹר קָפַץ לְשַׁעַר הַשָׁמַיִם. רָעַשׁ וְשָׁאַג מִי לִי בַּשָׁמַיִם. שָׁלַט וַיִּגְדַּל עַד לַשָׁמָיִם: זָכוֹר רָד אֶל חָנֵף לְהַחֲנִיף מַמְלֶכֶת. שִׁמְשַׁי אֲשֶׁר שִׁמְשׁוֹ מְאַמֶּשֶׁת וְהוֹלֶכֶת. תַּמָה הִלְשִׁין לְרַפּוֹתָהּ מִמְלֶאכֶת: זָכוֹר שָׁקַל אֲלָפִים עֲשָׂרָה. שְׁתִילִים מֵאָה הֶחֶנִיט לְשִׂבְרָה. שִׁעֵר מֵהֶם עֲשָׂרָה לִשְׂרָרָה: זָכוֹר תָּבַע לְהָפֵר חֻמָּשִׁים. תְּמִימָה קָצַב לְכַלּוֹת חֲמֻשִׁים. תַּכְלִית שִׁבְעִים נִתְלָה עַל חֲמִשִׁים:", "note": null, "a": 26, "b": 28, "head": null}], "said": ["rishon", "בְּפָרָשַׁת זָכוֹר"], "when": [["zachor", "text", "זכור איש"]]}, {"id": "e19", "sec": "nach", "ref": "Rashi on II Chronicles 22:11:1", "label": "פירוש המיוחס לרש\"י, דה\"י ב כב:יא", "paytan": "הקליר", "kind": "line", "quotes": ["נָפַץ חֲדַר הַמִּטּוֹת"], "rishonHtml": "<b>בַּחֲדַר הַמִּטּוֹת.</b> תַּרְגּוּם: ״בְּאִדְרוֹן בֵּית עַרְסָתָא״, כְּלוֹמַר: בָּעֲזָרָה, בְּחֶדֶר שְׁכִיבַת הַכֹּהֲנִים. וְרַבֵּינוּ שְׁלֹמֹה זַצַ״ל פֵּירֵשׁ: בַּעֲלִיַּת בֵּית קֹדֶשׁ הַקֳּדָשִׁים, כְּדִכְתִיב בִּמְלָכִים ״וַיְהִי אִתָּהּ״ בְּ״בֵית ה׳ מִתְחַבֵּא וְגוֹ׳״ (מלכים ב י:ג); וְעָלָיו אָמַר דָּוִד: ״כִּי יִצְפְּנֵנִי בְּסֻכֹּה וְגוֹ׳״ (תהלים כז:ה). וְקוֹרֵהוּ ״חֲדַר הַמִּטּוֹת״ בִּמְלָכִים (מלכים ב יא:ב), עַל שֵׁם ״בֵּין שָׁדַי יָלִין״ (שיר השירים א:יג); וְהוּא שֶׁיִּסֵּד הַקַּלִּיר (קרא ר׳ אליעזר ובזכרונות דיום ראשון דראש השנה יסד זה עיין שם): ״אִם פָּץ לְמַטּוֹת, <mark>נָפַץ חֲדַר הַמִּטּוֹת</mark>, לְכַפּוֹר יִזְכּוֹר חֻרְבַּן הַבַּיִת יְכַפֵּר עֲלֵיכֶם״:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_II_Chronicles_22:11:1", "lit": [{"src": "rh1_musaf", "seg": 196, "segHtml": "<b>זֵכֶר </b>תְּחִלַּת כָּל מַעַשׂ. אֲשֶׁר בְּכָל שָׁנָה נַעַשׂ. תּוֹחַלְתָּם לִמְאַס. יוֹצֵר בַּל יִזְכֹּר: תּוֹכַחַת מַעַשׂ. אִם יָצְאָה בְּכַעַס. תּוֹמֵךְ לְמַעֲנוֹ יַעַשׂ. וִיצוּרִים יִזְכֹּר: זֵכֶר שֶׁמִּבְּרֵאשִׁית. תְּבוּאַת רֵאשִׁית. שֹׁרֶשׁ בִּכּוּר רֵאשִׁית. יֵרֶא וְיִזְכֹּר: שֶׁצֶף חֲרִישִׁית. אִם חָר לְהָשִׁית. שׁוּבָה אֲשֶׁר הֵשִׁית. לַשּׁוֹבָבִים יִזְכֹּר: זֵכֶר רֹאשׁ עֲפָרוֹת. וְתוֹלָדוֹת סְפוּרוֹת. רִשּׁוּם סְפוּרוֹת. לְמִסְפַּר חוֹל יִזְכֹּר: רֹבַע מִסְפָּרוֹת. מְחַנְּנֵי לְכַפָּרוֹת. רֶגֶשׁ שׁוֹפָרוֹת. לְשַׁפְרְרָם יִזְכֹּר: זֵכֶר קְרִיאַת סֵפֶר. אֲשֶׁר גָּלְמִי שִׁפֵּר. קָצַב לוֹ בַּסֵּפֶר. בְּכָל דּוֹר וָדוֹר לִזְכֹּר: קֶצֶף אִם הֻחְרַט בַּסֵּפֶר. לְבִלְתִּי מְצֹא כֹפֶר. קִיּוּם זִכְרוֹן זֶה סֵפֶר. לְפָנָיו יִזְכֹּר: זֵכֶר צָפוּן מוֹרְדֵי אוֹר. תְּמִים דּוֹר כָּאוֹר. צִיָּה כְּחָר לֵאוֹר. קְנוּיָו יִזְכֹּר: צְפוּפִים פְּנֵי נָאוֹר. מִשְׁפָּטָם תֵּת לָאוֹר. צַחַן רֹעַ שְׂאוֹר. בְּרִיב בַּל יִזְכֹּר: זֵכֶר פְּעֻלַּת אֶזְרָח. הֵעַרְתָּ מִמִּזְרָח. פָּעֳלוֹ יִזְרָח. בְּקֶרֶב שָׁנִים יִזְכֹּר: פַּח אִם הֻטְרַח. פְּרָחָיו לִמְרַח. פִּלּוּלוֹ יִצְרַח. בַּעֲדָם יִזְכֹּר: זֵכֶר עֲקֵדַת מוֹרִיָּה. כְּהִיַּת רְאִיָּה. עֲדֵי עֵירֹם וְעֶרְיָה. סִבּוּכוֹ יִזְכֹּר: עֶצֶב טְרִיָּה. אִם כֹּאֲבָה פּוֹרִיָּה. עֲתָרוֹ לִרְאִיָּה. וְלִזְכוּת יִזְכֹּר: זֵכֶר סֻלָּם חָלָם. וְעָלָיו מְחוֹלְלָם. שָׂרֵי אַרְבַּע וְעֻלָּם. בּוֹ כְּמֵאָז יִזְכֹּר: שָׂרִיגָיו בְּמָעֳלָם. וְיֹאמַר לְגָעֳלָם. שִׂיחוֹ יוֹעִילָם. בְּרִית לִזְכֹּר: זֵכֶר נְקוּבֵי מַטּוֹת. שְׁבוּעוֹת מַטּוֹת. נְדִידוּת הַמִּטּוֹת. לְאַמְּצָם יִזְכֹּר: נוֹשְׂאֵי עֹל מוֹטוֹת. אִם פָּץ לְהַמְטוֹת. <mark>נֶפֶץ חֲדַר הַמִּטּוֹת</mark>. לְכִפּוּר יִזְכֹּר: זֵכֶר מְצוּקִים. יְסוֹד מוּצָקִים. מִפְעָלָם לְצוֹעֲקִים. בְּפוּט חָשׁ לִזְכֹּר: מִפִּי יוֹנְקִים. אֲשֶׁר בַּסּוּף נוֹאֲקִים. מַאֲמַר בְּרִית וְחֻקִּים. דְּבַר קָדְשׁוֹ יִזְכֹּר: זֵכֶר לִין כְּפָרִים. וְאִמְרֵי שְׁפָרִים. לִמְשַׁלְּמֵי פָרִים. בְּשָׂפָה יִזְכֹּר: לְעֵת בִּקּוּר סְפָרִים. סְתָרִים מְסַפְּרִים. לִשְׁנֵי עֳפָרִים. לְצֶדֶק יִזְכֹּר: זֵכֶר כְּבוֹד מִשְׁכַּן. מְקוֹם דּוֹד שָׁכַן. כְּרוּבִים בּוֹ שִׁכַּן. חֶסֶד נְעוּרִים יִזְכֹּר: כִּיּוֹר עִם כַּן. וְנֹעַם קוֹל דּוּכַן. כַּבִּיר בְּיוֹם מוּכָן. לַנְּבוֹנִים יִזְכֹּר: זֵכֶר יְלִיד נוּן. וּמִשְׁפְּטֵי אוּרִי אֶפְנוּן. יִזָּכְרוּ בְּרִנּוּן. פִּלְאָם לִזְכֹּר: יֹקֶשׁ בְּרַק הַשָּׁנוּן. אִם הֻשְׁלַף לְתַאֲנוּן. יַקְשִׁיב תַּחֲנוּן. חֲנוּנָיו לִזְכֹּר: זֵכֶר טַעַם שׁוֹפְטִים. וְאוֹת קְצִיר חִטִּים. טֶפֶשׁ שׁוֹטִים. יְחַתֵּל מִלִּזְכֹּר: טֹרַח אַרְבָּעָה שְׁפָטִים. אִם נֶעֶנְשׁוּ נִשְׁפָּטִים. טֶבַע מִשְׁפָּטִים. אֲשֶׁר שָׂם יִזְכֹּר: זֵכֶר חֲצוֹת לַיְלָה. וְתוֹדוֹת מִשְׁפְּטֵי לַיְלָה. חֹשֶׁךְ בְּאִישׁוֹן לַיְלָה. נִגּוּנוֹ לָמוֹ יִזְכֹּר: חֵקֶר מִפְקַד לַיְלָה. יַגִּיהַּ בְּלַהַב לַיְלָה. חֹק הֶגֶה יוֹמָם וָלַיְלָה. לְגִיהָם יִזְכֹּר: זֵכֶר זֶה זְבוּל. אֲשֶׁר בְּבִצְעִי חָבוּל. זְדוֹנוֹת סָבוּל. עוֹד בַּל יִזְכֹּר: זַעַם כַּמַּבּוּל. אִם יָצְאָה לְחִבּוּל. זִכְרוֹן יֶרַח בּוּל. לְחֶמְלָה יִזְכֹּר: זֵכֶר וֶכַח כָּל פֹּעַל. בְּקַו וָפֶלֶס יַעַל. וְאִם בְּמֶרֶד וְאִם בְּמַעַל. רַב חֶסֶד יִזְכֹּר: וְאִם טוֹב וְאִם רַע. אֲשֶׁר בּוֹ יֶאֱרַע. וֶסְתּוֹ יִפָּרַע. בְּסַאסְאָה מִלִּזְכֹּר: זֵכֶר הַחַיִּים. עַד כַּמָּה הֵם חַיִּים. הֵן לַמָּוֶת אִם לְחַיִּים. חַי חַי יִזְכֹּר: הֲמוֹן שְׁאוֹן בְּרוּאִים. יַעַבְרוּ לְפָנָיו כִּמְרִיאִים. הֲלֹא כְּמוֹ רְאוּיִים. לְכָל אֶחָד יִזְכֹּר: זֵכֶר דַּלּוּת וָעֹשֶׁר. בַּצֹּרֶת וָחֹשֶׁר. דֹּפִי וְגַם יֹשֶׁר. בַּדִּין הוּא יִזְכֹּר: דְּבַר גָּלוּי וָסֵתֶר. בִּנְיָנוֹת וְסוֹתֵר. דֵּי חָסֵר וְיָתֵר. לְקֶצֶב יִזְכֹּר: זֵכֶר גְּנוּנִים לְיַשֵּׁב. בַּמִּדְבָּר וְיוֹשֵׁב. גֶּשֶׁם וָרוּחַ לְנַשֵּׁב. מֵהַיּוֹם יִזְכֹּר: גָּרוֹן לְהַקְשֵׁב. מֵעַם שְׁמוֹ חוֹשֵׁב. גָּלֻיּוֹת לְהָשֵׁב. בְּיוֹם תֵּקַע יִזְכֹּר: זֵכֶר בַּהַל וְחֵמָה. קְרָב וּמִלְחָמָה. בִּקּוּעַ חוֹמָה. לְחוֹמַת יָם יִזְכֹּר: בָּאָדָם וּבַבְּהֵמָה. אִם הֻקְנַס מְהוּמָה. בִּצּוּר קוֹל הוֹמָה. לַאֲדָמָה יִזְכֹּר: זֵכֶר אֱמוּנָה וָשֶׁקֶר. אִזּוּן שִׂיחַ וָסֶקֶר. אוֹת פְּקֻדַּת בֹּקֶר. לִרְגָעִים יִזְכֹּר: <small>חזן </small>אִם לְזוֹל אִם לְיֹקֶר. אִם לָטַעַת אִם לְעַקֵּר. אֱנוֹשׁ בְּדִקְדּוּק וָחֵקֶר. לַמִּשְׁפָּט יִזְכֹּר:", "note": null, "a": 196, "b": 196, "head": 195}], "said": ["editor", "בזכרונות דיום ראשון דראש השנה"], "when": [["rh", "text", "זכרונות, מוסף יום א'"]]}, {"id": "e20", "sec": "nach", "ref": "Rashi on II Chronicles 35:22:1", "label": "פירוש המיוחס לרש\"י, דה\"י ב לה:כב", "paytan": "הקליר", "kind": "line", "quotes": ["כָּל הֲמוֹנָיו לָלֶכֶת אֲרַם נַהֲרַיִם, לְמַעַן לֹא תַעֲבֹר חֶרֶב כָּל שֶׁהוּא בְּאֶפְרַיִם"], "rishonHtml": "<b>וְלֹא שָׁמַע אֶל דִּבְרֵי נְכוֹ מִפִּי אֱלֹהִים.</b> שֶׁאָמַר לוֹ מִפִּי אֱלֹהִים, כִּי כֵּן אָמַר יְשַׁעְיָה ״וְסִכְסַכְתִּי מִצְרַיִם בְּמִצְרַיִם״ (ישעיה יט:ב); וְזֶהוּ שֶׁיִּסֵּד הַקַּלִּיר (קינות לתשעה באב יב): ״<mark>כָּל הֲמוֹנָיו לָלֶכֶת אֲרַם נַהֲרַיִם, לְמַעַן לֹא תַעֲבֹר חֶרֶב כָּל שֶׁהוּא בְּאֶפְרַיִם</mark>, לֹא שָׁמַע לַחוֹזֶה וְיָשׁוּב אָחוֹרִים, כִּי נִגְזְרָה גְּזֵרָה לְסַכְסֵךְ מִצְרַיִם בְּמִצְרַיִם״:", "version": "Sefaria vocalized edition", "source": "https://www.sefaria.org/", "url": "https://www.sefaria.org/Rashi_on_II_Chronicles_35:22:1", "lit": [], "said": ["editor", "קינות לתשעה באב"], "when": [["tishabav", "editor", "קינות"]]}, {"id": "e21", "sec": "shas", "ref": "Rashi on Yoma 67a:1:2", "label": "רש\"י יומא סז.", "paytan": "רבי אלעזר קליר", "kind": "line", "quotes": ["ובשלשים קנים הוא קצב הריס", "ארחץ בנקיון כפות ברוחב ע\"ה מיל חריצותיה"], "rishonHtml": "שבעה ומחצה ריס לכל מיל - הרי לתשעים ריס י\"ב מיל והם י\"א מסעות מירושלים לסוכה הראשונה מסע אחד ומסוכה לסוכה עד י' סוכות ט' מסעות הרי י' מסעות ומסוכה אחרונה לצוק מסע אחד הרי לכל מסע ומסע מיל חוץ מאחד מהן שיש בו ב' מילין היינו דקתני ומלוין אותו מסוכה לסוכה שהמיל הוא תחום שבת חוץ מאחרון שהוא רחוק ב' מילין ומלויהו מיל ועומד מרחוק ורואה את מעשיו והחשבון הזה אינו שוה לחשבון שיסד רבי אלעזר קליר <mark>ובשלשים קנים הוא קצב הריס</mark> אותו חשבון אינו עולה לאלפים אמה המיל אבל בברייתא דהאזינו בספרי מצינו שם מידת חלוקת ארץ ישראל לעתיד לבוא רוחב גבול כל שבט ושבט שבעים וחמשה מיל וגם רבי אלעזר קליר יסד כן בפיוט <mark>ארחץ בנקיון כפות ברוחב ע\"ה מיל חריצותיה</mark> והם כ\"ה אלף קנים שבספר יחזקאל (מה) שנאמר ומן המדה הזאת תמוד וגו' וכל קנה ו' אמות הרי ק\"נ אלף אמה תן לכל אלפים אמה מיל הרי ע\"ה מיל:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Rashi_on_Yoma_67a:1:2", "lit": [{"src": "shekalim", "seg": 37, "segHtml": "<b>מַתְחִיל</b> בִּמְדִידָה מֵחֲמֵשׁ מֵאוֹת שָׁנָה. עַד שֶׁהוּא מְכַלֶה בְּאֶצְבַּע הַקְטַנָה: דֶּרֶךְ יוֹם הוּא בְּעֶשֶׂר פַּרְסָה. וְאַרְבַּעַת מִיל הִיא כָּל פַּרְסָה: וּמִדַּת הַמִּיל שִׁבְעָה וּמֶחֱצָה רִיס. וּ<mark>בִשְׁלֹשִׁים קָנִים הוּא קֶצֶב הָרִיס</mark>: וְשִׁעוּר הַקָּנֶה שֵׁשׁ אַמּוֹת וָזֶרֶת. וְכָל אַמָּה מוֹדֶדֶת שְׁלִישׁ בַּזֶרֶת: וְהַזֶרֶת מוֹתַחַת עַד שְׁנַיִם בַּסִּיט. וְאַרְבַּע אֶצְבָּעוֹת הוּא הַטֶּפַח וְהַסִּיט: וּכְמוֹ נִתְּנָה מִדָּה לִמְדִידַת הָאָרֶץ. כֵּן נִתַּן כַּיִל לְתוֹלְדוֹת הָאָרֶץ: מַתְחִיל מִמֵּאָה וְשִׁשִׁים וָשֵׁשׁ שָׁנָה עַד שֶׁהוּא מְכַלֶה בִּשְׁתּוּת אֶצְבַּע קְטַנָּה:", "note": "השורה הראשונה נמצאת בסילוק לפרשת שקלים. הפיוט \"ארחץ בנקיון כפות\" לא נמצא בספריא.", "a": 36, "b": 41, "head": null}], "said": ["other", "Shibbolei HaLeket 28:9", "\"ארחץ בנקיון כפות\" של יום טוב שני של סוכות (שבלי הלקט, לפי קטע מחיפוש בלבד)"], "when": [["shekalim", "text", "סלוק אז ראית וספרת"], ["sukkos", "other", "\"ארחץ בנקיון כפות\" ליום ב', לפי שבלי הלקט"]]}, {"id": "e22", "sec": "shas", "ref": "Rashi on Beitzah 33a:9:2", "label": "רש\"י ביצה לג.", "paytan": "אחד מגאוני לומברדיא", "kind": "content", "quotes": ["כך שמעתי בפיוט יוצר שיסד אחד מגאוני לומברדיא\"ה"], "rishonHtml": "מן המים - נותנים מים בכלי זכוכית לבנה ונותנו בחמה כשהשמש חם מאד והזכוכית מוציאה שלהבת ומביאין נעורת ומגיעים בזכוכית והיא בוערת <mark>כך שמעתי בפיוט יוצר שיסד אחד מגאוני לומברדיא\"ה</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Rashi_on_Beitzah_33a:9:2", "lit": [], "said": ["rishon", "פיוט יוצר"], "when": [["unknown", null, null]]}, {"id": "e23", "sec": "shas", "ref": "Rashi on Bava Metzia 69b:8:2", "label": "רש\"י ב\"מ סט:", "paytan": "רבינו משולם", "kind": "line", "quotes": ["חכמי מדות מפריזים"], "rishonHtml": "מפרין על שדהו - לשון פרה ורבה ובגמ' מפרש כיצד מפרין ולי נראה מפריז בזיי\"ן לשון מרחיב ומגדיל כמו (זכריה ב׳:ח׳) פרזות תשב ירושלם וכן מצינו בנדה (דף ד:) לא כהלל שהפריז על מדותיו וכן יסד רבינו משולם בפיוט <mark>חכמי מדות מפריזים</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Rashi_on_Bava_Metzia_69b:8:2", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e24", "sec": "tosafos", "ref": "Tosafot on Berakhot 6a:20:1", "label": "תוס' ברכות ו. ד\"ה מי כעמך ישראל", "paytan": "הפייטן", "kind": "line", "quotes": ["טוטפת כלילו גדלי"], "rishonHtml": "מי כעמך ישראל -  זה שיסד הפייטן (ביום א' דפסח) <mark>טוטפת כלילו גדלי</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Berakhot_6a:20:1", "lit": [], "said": ["rishon", "ביום א' דפסח"], "when": [["pesach", "rishon", "יום א' דפסח"]]}, {"id": "e25", "sec": "tosafos", "ref": "Tosafot on Shabbat 114b:5:1", "label": "תוס' שבת קיד: ד\"ה ואמאי ליתקע", "paytan": "הפייטן", "kind": "line", "quotes": ["אחר גמר מיצוי אכול בדצוי ורצוי"], "rishonHtml": "ואמאי ליתקע כי היכי דלידעו דשרי בשחיטה - לא להודיע די\"ט קיל אלא להודיע שהוא לילה וכן אומר ר\"י מה שתוקעים במוצאי יוה\"כ אינו אלא להודיע שהוא לילה ויאכילו את בניהם שהתענו וגם להכין סעודת מוצאי יוה\"כ שהיא כעין י\"ט כמו שיסד הפייטן <mark>אחר גמר מיצוי אכול בדצוי ורצוי</mark> ולא כמחזורים שכתוב בהן שהתקיעה זכר ליובל כי למה תוקעין בכל שנה ושנה וכי היה יובל בכל שנה ושנה:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Shabbat_114b:5:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e26", "sec": "tosafos", "ref": "Tosafot on Eruvin 19a:19:1", "label": "תוס' עירובין יט. ד\"ה והאיכא תפתה", "paytan": "הפייט", "kind": "line", "quotes": ["יקדו בהבהבי עלק"], "rishonHtml": "והאיכא תפתה - תימה דלא חשיב עלוקה ור\"ת מפרש דעלוקה שם חכם כמו לאיתיאל והא דמוקי ליה במסכת עבודה זרה (דף יז.) בגיהנם היינו משום דכתיב בתריה שאול ועוצר רחם ומיהו קשה דבפסיקתא לא חשיב להם בשמות שלמה וגם בג' דברי' וד' דברים הכתובים באותו ספר לא חשיב עלוקה ואע\"ג דלא חשיב נמי יקא היינו משום דשמא הוי בכלל אגור והפייט נמי יסדו בשם גיהנם בזולת אין צור חלף <mark>יקדו בהבהבי עלק</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Eruvin_19a:19:1", "lit": [], "said": ["rishon", "בזולת אין צור חלף"], "when": [["chanukah", "other", "זולת אין צור חלף, \"זולת של חנוכה\" לפי תוס' ע\"ז יז."]]}, {"id": "e27", "sec": "tosafos", "ref": "Tosafot on Eruvin 21a:18:1", "label": "תוס' עירובין כא. ד\"ה אחד משלשת אלפים", "paytan": "רבי אליעזר הקליר", "kind": "line", "quotes": ["אלפים וארבע מאות בעולם מאריכה", "והזרת מותחת עד שנים בסיט", "גיא וכל עפרה בצרדה הכילו"], "rishonHtml": "אחד משלשת אלפים ומאתים בתורה - בסלוק אז ראית וספרת יסד רבי אליעזר הקליר <mark>אלפים וארבע מאות בעולם מאריכה</mark> וזהו לפי שעושה זרת שליש אמה כמו שיסד <mark>והזרת מותחת עד שנים בסיט</mark> וארבעה אצבעות הוא הטפח והסיט ולפי חשבון דשמעתא הוי זרת חצי אמה וכל אמה כשתחלקנה לשתי וערב יש בה ארבע זרתות אך תימה כי לפי חשבונו היה לו לחלק אמה לתשעה חלקים ואז יהיה בכל חלק זרת על זרת כי העולם זרת על זרת ואז יעלה לשבעת אלפים ומאתים והוא עושה העולם זרת על אמה וזה מנין לו וגם סובר דוכל בשליש עפר הארץ היינו שליש אמה והוא עצמו יסד <mark>גיא וכל עפרה בצרדה הכילו</mark> משמע דאצבע שלישי היינו אצבע הקרוי אמה קרי ליה צרדה ורצה לפרש וכל בשליש באצבע שלישי ובמסכת יומא (ד' יט:) קרי צרדה אצבע שאצל הגודל וצרדה היינו צרה דדא של אגודל:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Eruvin_21a:18:1", "lit": [{"src": "shekalim", "seg": 41, "segHtml": "<b>וְעַד</b> מָקוֹם שֶׁאֱנוֹשׁ יָכוֹל לִמְנוֹת. נִמְסַר לוֹ לִמְדּוֹד וְגַם לִמְנוֹת: לְפִי כֹחוֹ וּלְפִי מִעוּט חֵילוֹ. הָקְצַב לוֹ מִעוּט הוֹן שִׁקְלוֹ. וּלְפִי שִׂכְלוֹ כֵּן יְהִי הִלּוּלוֹ. גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ חֵילוֹ. עַל כֵּן אוֹחִיל לוֹ: כִּי מִדָתוֹ וְשִׁקְלוֹ לְפִי גָדְלוֹ. כָּל אוֹצְרוֹת שֶׁלֶג וְרוּחַ פִּלֵס בְּמִשְׁקָלוֹ: וּמֵי בְּרֵאשִׁית מָדַד מְלֹא שָׁעֳלוֹ. וּשְׁמֵי רוֹם תִּכֵּן זֶרְתּוֹ מְלֹא. וְכָל הַרְרֵי קֶדֶם בְּאֶצְבָּעוֹ שְׁקָלוֹ. וְגִבְעוֹת עוֹלָם תָּמַךְ בְּהוֹד אֲגֻדָּלוֹ. <mark>גֵּיא וְכָל עֲפָרָהּ בִּצְרָדָה הֱכִיל</mark>וֹ. לְחוֹלֵל תַּנִין מְיֻמֶּנֶת הֵכִין לוֹ: נִמְצֵאת כָּל מִדַּת יְצִירַת עוֹלָמוֹ. כִּמְלֹא פִסַּת יָד הִיא רִשׁוּמוֹ. וּכְקָמֵיעַ בְּיַד גִּבּוֹר בִּזְרוֹעַ חוֹתָמוֹ. וְאֵין לִקְצוֹב רוֹב מֶחְקְרֵי תַעֲצוּמוֹ. אֲשֶׁר מָדַד וְקָצַב וְשִׁעֵר בִּמְרוֹמוֹ. עַל כָּל מִדַת כִּסְאוֹ וַהֲדוֹמוֹ: מִדַּת בַּת מֶלֶךְ בַּכֹּל מְעֻלָה. בְּאֹרֶךְ בְּרוֹחַב בְּעוֹמֶק בְּגּוֹבַהּ מִתְעַלָּה. כִּי יֵשׁ קֵץ לְכָל תִּכְלָה. וְאִמְרָהּ רְחָבָה לָעַד לֹא כָלָה: מִדַּת עוֹלָם כִּמְלֹא פִסַּת יָד. וּמִדָּתָהּ נְתוּנָה בִּימִין וּזְרוֹעַ וָיָד: מִדַּת עוֹלָם כְּמִזֶּרֶת וְעַד אֲגֻדָּל. וּמִדָּתָהּ בְּקַו אֲשֶׁר מְאֹד גָּדָל: מִדַּת עוֹלָם נִמְדֶּדֶת בִּשְׁלִישׁ אַמָּה. וּמִדָּתָהּ עוֹלָה וְנוֹסֶבֶת כְּאַלְפַּיִם אַמָּה: כְּמַרְאֵה הַמִּדָּה אֲשֶׁר צִיר רָאָה. מְגִלָּה עֶשְׂרִים עַל עֶשֶׂר אַמָּה. עָפָה אַרְבָּעִים עַל עֶשְׂרִים וּשְׁמוֹנֶה מֵאוֹת אַמָּה. וְכָל הָעוֹלָם כֻּלּוֹ בִּשְׁלִישׁ אַמָּה: נִמְצֵאת דָּת בְּמִדוֹתֶיהָ רְחָבָה וַאֲרֻכָּה. <mark>אַלְפַּיִם וְאַרְבַּע מֵאוֹת בָּעוֹלָם מַאֲרִיכָה</mark>. וְהִיא נָתְנָה לָעוֹלָם מַרְפֵּא וַאֲרוּכָה. וּבִימִינָהּ קוֹצֶבֶת כָּל יְמֵי אַרְכָה, וּבִשְׂמֹאלָהּ שׁוֹקֶלֶת עוֹשֶׁר וְכָבוֹד וּבְרָכָה: וְהִיא הוֹדִיעָה אֶת כָּל חֶבְיוֹן סְתוּרוֹת. וְהוּא קָצְבָה כָּל מִדּוֹת סְפוּרוֹת. וְהִיא פָּתְחָה אֶת כָּל סְגוּרוֹת. וְהִיא שָׁקְלָה וְאָצְרָה אֶת כָּל אוֹצָרוֹת: וְהִיא חָקְרָה הֲמוֹן מִפְקַד תַּחְתּוֹנִים. וְהִיא נָתְנָה מִסְפַּר גְּדוּדֵי עֶלְיוֹנִים: וְהִיא שִׁעֲרָה קוֹמַת אַלְפֵי שִׁנְאַנִּים. אֲשֶׁר זֶה מִזֶּה בְּקוֹמָתָם מְשֻׁנִּים: יֵשׁ כְּמִדַּת הַיָּם הַגָּדוֹל קוֹמָתָם. וְיֵשׁ כַּחֲלָלוֹ שֶׁל עוֹלָם הֲקָמָתָם. וְיֵשׁ כִּמְלֹא כָל הָעוֹלָם תְּקוּמָתָם. יֵשׁ לִשְׁתֵּי טִיסוֹת טָסִים עוֹלָם. וְיֵשׁ לְטִיסָה אַחַת עָפִים עוֹלָם. וְכָל אֶחָד וְאֶחָד בְּמַחֲנֵהוּ נֶעְלָם. וּבִמְחִיצָתוֹ צָג וְחָשׁ וְדוּמָם וְנֶאֱלָם. עַד יִתֵּן רְשׁוּת מֶלֶךְ הָעוֹלָם. וְחָשִׁים עַד יַמְלִיכוּהוּ עַם עוֹלָם. וְאָז יִפְצְחוּ לְפָאֵר אֱלֹהֵי עוֹלָם. וּמִשֶׁהֵם מְפָאֲרִים עוֹד לֹא שׁוֹנִים. כִּי בִנְהַר דִינוֹר שָׂחִים וְנִתָּנִים. וְעוֹד מֶנּוּ נֶחֱצָבִים וּמִתְחַדְשִׁים כָּרִאשׁוֹנִים. שֶׁבַח וְהַלֵל וָרוֹן לָאֵל מְשַׁנְּנִים. וְכִפֵּי קֶשֶׁת עִם כְּנַף רְנָנִים. זֶמֶר וָשִׁיר וְעוֹז וָרֶנֶן מְרַנְּנִים. וּשְׂרָפִים הַמְעֻלִּים עַל כָּל שִׁנְאֲנִּים. שֵׁשׁ שֵׁשׁ כְּנָפַיִם בְּגֶוְיָם חֲנוּנִים. מִמַעַל לְיוֹשֵׁב עֲרָבוֹת בַּכֵּס נְתוּנִים. וּלְיוֹשֵׁב עַל כִּסֵּא בְּחִילָה מְנַגְּנִים. מְצוֹא חֵן בְּנִגּוּנָם הֵם מְחַנְּנִים. וְקוֹדֶם לְכָל צְבָא מַעַל עוֹנִים. וְשִׁלוּשׁ קְדֻשָׁה לְרָם וְנִשָׂא נוֹתְנִים. כּוֹרְעִים וּמִשְׁתַּחֲוִים הֲמוֹנִים הֲמוֹנִים. לְנַעֲרָץ בְּסוֹד הֲמוֹן גְּדוּדֵי עֶלְיוֹנִים. וְנִקְדָּשׁ בְּאַלְפֵי רִבְבוֹת תַּחְתּוֹנִים:", "note": null, "a": 36, "b": 41, "head": null}, {"src": "shekalim", "seg": 37, "segHtml": "<b>מַתְחִיל</b> בִּמְדִידָה מֵחֲמֵשׁ מֵאוֹת שָׁנָה. עַד שֶׁהוּא מְכַלֶה בְּאֶצְבַּע הַקְטַנָה: דֶּרֶךְ יוֹם הוּא בְּעֶשֶׂר פַּרְסָה. וְאַרְבַּעַת מִיל הִיא כָּל פַּרְסָה: וּמִדַּת הַמִּיל שִׁבְעָה וּמֶחֱצָה רִיס. וּבִשְׁלֹשִׁים קָנִים הוּא קֶצֶב הָרִיס: וְשִׁעוּר הַקָּנֶה שֵׁשׁ אַמּוֹת וָזֶרֶת. וְכָל אַמָּה מוֹדֶדֶת שְׁלִישׁ בַּזֶרֶת: וְ<mark>הַזֶרֶת מוֹתַחַת עַד שְׁנַיִם בַּסִּיט</mark>. וְאַרְבַּע אֶצְבָּעוֹת הוּא הַטֶּפַח וְהַסִּיט: וּכְמוֹ נִתְּנָה מִדָּה לִמְדִידַת הָאָרֶץ. כֵּן נִתַּן כַּיִל לְתוֹלְדוֹת הָאָרֶץ: מַתְחִיל מִמֵּאָה וְשִׁשִׁים וָשֵׁשׁ שָׁנָה עַד שֶׁהוּא מְכַלֶה בִּשְׁתּוּת אֶצְבַּע קְטַנָּה:", "note": null, "a": 36, "b": 41, "head": null}], "said": ["rishon", "בסלוק אז ראית וספרת"], "when": [["shekalim", "text", "סלוק אז ראית וספרת"]]}, {"id": "e28", "sec": "tosafos", "ref": "Tosafot on Pesachim 109a:7:1", "label": "תוס' פסחים קט. ד\"ה רביעית של תורה", "paytan": "הפייט", "kind": "line", "quotes": ["הכוס סובב אצבעים על אצבעים", "לריבוע כוס ישועות"], "rishonHtml": "רביעית של תורה אצבעים - מכאן קשה על פירוש רבותיו של רבינו שלמה שפי' דרביעית בכל מקום היינו רובע הקב כי לפי זה החשבון הוא רביעית הלוג פר\"ת רום המקוה ע\"ב אצבעות השלך רביעית ישאר נ\"ד קח מכל עשרים אחד יעלה אצבעים וחצי אצבע וחומש וכן תקח ברוחב אחד מי\"ב וכן באורך הרי אצבעים על אצבעים ברום אצבעים וחצי אצבע וחומש אצבע וכן תעשה במים ויעלה רביעית רביעית הנמצא השלך החוצה ומן הנותרים קח אחד מעשרים ופעמים יוסר חלק שנים עשר או תקח אחד מכ\"ד והם ג' אצבעות חלק על חומשין והשלך העשירית ישארו שלשה עשר חומשין וחצי והם אצבעים וחצי וחומש אצבע או קח רביעית והם י\"ח אצבעים והשלך הרביעי ישארו י\"ג אצבעות וחצי וטול החמישית מהר\"י קחה רובע וככה תשלך וחלק החמישי קח ולך או השלך עשירית המים ישארו ל\"ו יעלה ב' סאין לכל טפח ולג' אצבעות סאה וחצי השלך מג' אצבעות העשירית כאשר השלכנו מן המים. ולפי תלמוד שלנו החשבון מכוון אבל על גירסת ירושלמי דקאמר אצבעים על אצבעים ברום אצבע ומחצה ושליש אצבע וכן עשה הפייט ועל גובה חסר שתות מאצבעים והכל א' קשה כי לפי שיעור המקוה אינו מכוון וי\"ל דבירושלמי איירי באצבעות צפוריית והכא במדבריית ואצבעים וחצי וחומש הם י\"ו שתותים וחומש שתות באו לירושלים נכנס הכל בי\"ג שתותים וחצי באו לצפורי נכנס הכל בי\"א שתותים ורביע שתות שהם אצבעים חסר שתות ונשאר רביע שתות בתלמוד שלנו יתר וכמו כן צריך למעט מרוחב כי בתלמוד שלנו מיירי במרובעות וירושל' בעגולות כמו שיסד הפייט <mark>הכוס סובב אצבעים על אצבעים</mark> סובב משמע עגול ואצבעים על אצבעים עגולות עולה לאצבעים על [אצבע] וחצי דמרובע יתר על העיגול רביע ואצבעים על אצבעים מרובעות מדבריות נכנסות באצבעים על אצבעים עגולות צפוריות ויש בעגולות יותר ד' שתותי שתות שהוא אחד מתשעה הסר ממנו רביע שתות הנשאר בגובה שהוא אחד מכ\"ד ישאר שיעור הירושלמי יתר בדבר מועט ולחומרא לא דק ועוד מפרש דבירושלמי איירי בעגולות שיוכל לרבע אצבעים על אצבעים מתוכם דהוי תילתא טפי כדאמר ריבועא מגו עיגולא פלגא פירוש פלגא של ריבוע הפנימי וכשתסיר שליש מגובה שהם י\"ג חומשין וחצי ישארו ט' חומשין שהם אצבעים חסר חומש והתם נקט חסר שתות נקט כפי הירושלמי והירושלמי לא דק לחומרא והא דיסד הפייט (שם) <mark>לריבוע כוס ישועות</mark> לא שהוא מרובע אלא קאמר שאותו רביעית מוכן לד' כוסות של פסח שניתקנו כנגד גאולה וישועה:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Pesachim_109a:7:1", "lit": [{"src": "shekalim", "seg": 38, "segHtml": "<b>זֶה</b> הַיָּם הַגָּדוֹל בִּשְׁלִישׁ יוֹשֵׁב. בְּמֵאָה וְשִׁשִׁים וְשֵׁשׁ וָעוֹד מִתְחַשֵׁב: וְעָמְקוֹ בְּעֶשְׂרִים וְאַרְבָּעָה לְמֵתַח סוּף. וְסוּף בְּשִׁבְעִים וּשְׁנַיִם לְעוֹגֶל גִיחוֹן. וְגִיחוֹן מַכְפִּיל שִׁשִׁים כְּמִדַּת פְּרָת. וְהַפְּרָת תָּקְפוֹ כְּנֶגֶד שְׁנֵי הַנְּהָרוֹת. וּשְׁנֵי הַנְּהָרוֹת מַעְדִּיפִים בְּאֹרֶךְ הַיַּרְדֵּן. וְהַיַּרְדֵּן מַרְחִיב חֲמִשָׁה כְּיַם הַזְּבוּל. וְיַם הַזְּבוּל מֵאָה וַחֲמִשִׁים מִקְוָאוֹת. וּמִדַּת הַמִּקְוָה כִּשְׁנֵי חֳמָרִים בְּיָבֵשׁ. וְשִׁעוּר כָּל חוֹמֶר כִּשְׁנֵי לְתָכִים. וְכָל לֶתֶךְ יָכִיל חָמֵשׁ אֵיפוֹת. וְכָל אֵיפָה עוֹשָׂה עֲשָׂרָה עֳמָרִים. וְכָל עוֹמֶר שִׁבְעַת רֶבַע וּכְלָה. וְהַכְּלָה אֶחָד מִמֵּאָה וָעוֹבִּסְאָה. וּסְאַת יָבֵשׁ חֲסֵרָה שְׁלִישׁ בַּלַח. וּסְאַת הַלַּח אֶחָד מִשְׁלשָׁה בַּבַּת. וְכָל בַּת מַחֲזֶקֶת שִׁשָׁה בַּהִין. וְהַהִין כֻּלוֹ שְׁנֵים עָשָׂר לוֹג. וָעוֹד, הַלוֹג מִתְחַלֵּק לְאַרְבַּעַת רְבָעִים וְרֶבַע מוּכָן <mark>לְרִבּוּעַ כּוֹס יְשׁוּעות</mark>. וְ<mark>הַכּוֹס סוֹבֵב אֶצְבָּעַיִם עַל אֶצְבָּעַיִם</mark>. וְעַל גוֹבַהּ חָסֵר שְׁתוּת מֵאֶצְבָּעַיִם:", "note": null, "a": 36, "b": 41, "head": null}], "said": ["text", "יוצר לפרשת שקלים"], "when": [["shekalim", "text", "סלוק אז ראית וספרת"]]}, {"id": "e29", "sec": "tosafos", "ref": "Tosafot on Pesachim 115a:1:2", "label": "תוס' פסחים קטו. ד\"ה והדר אכיל חסא", "paytan": "ה\"ר יוסף טוב עלם", "kind": "line", "quotes": ["למה שאר ירקות באין תחלה לפטור חזרת מברכה ראויה לה"], "rishonHtml": "והדר אכיל חסא בלא ברכה - ונראה דאין צריך לברך בפה\"א אע\"ג דהגדה הוי הפסק כדפרישית לעיל ולא מיפטר בברכה של טיבול ראשון מ\"מ ברכת המוציא פוטרתן דהוה להו דברים הבאים בתוך הסעודה מחמת הסעודה שהרי ירקות גוררין הלב וקרי ליה נמי למרור פרפרת הפת וכן אמר בכיצד מברכין (ברכות ד' מב.) בירך על הפת פטר את הפרפרת פרפר' היינו דברים הממשיכים האכילה כגון דגים קטנים ותמרים וירקות והיו רגילים לאוכלם בתוך הסעודה בין מאכל למאכל ולכך פטר את הפרפרת לפי שבא לצורך שעל ידי כך אוכל יותר ואין לומר דפרפרת היינו דבר שבא ללפת בו את הפת דהא הוי בכלל הא דקתני התם דמברך על העיקר ופוטר את הטפילה וקאמר נמי רבי חייא פת פוטרת כל מיני מאכל ורב פפא נמי פסיק התם הלכתא דברים הבאים תוך הסעודה מחמת הסעודה והיינו הפרפרת כדפי' אין טעונין ברכה לא לפניהם ולא לאחריהם שלא מחמת הסעודה תוך הסעודה כגון תאנים וענבים שאינן באין להמשיך המאכל ולא ללפת אלא לתענוג צריכין ברכה לפניהם ולא לאחריהם אחר הסעודה אפילו פרפרת טעונין ברכה בין לפניהם בין לאחריהם וה\"ר יוסף טוב עלם כתב בסדרו <mark>למה שאר ירקות באין תחלה לפטור חזרת מברכה ראויה לה</mark> וליתא דהא משום היכירא באין ולא שייך כאן חבילות אלא בתרי מילי ועוד דרב חסדא מברך שתיהן אחזרת ועוד דמשמע דלא פטר ליה פת ושמא אינו מחשיבו פרפרת הפת כיון שאינו אוכל ממנו אלא כזית:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Pesachim_115a:1:2", "lit": [{"src": "hagadol", "seg": 49, "segHtml": "<b>וְלָמָּה</b> אֲכִילַת חָמֵץ לְשֵׁשׁ שָׁעוֹת. זֵכֶר לְחִפָּזוֹן שְׁכִינָה לְהַעֲבִיר גְּזֵרוֹת רָעוֹת. מְדַלֵּג עַל הֶהָרִים מְקַפֵּץ עַל הַגְּבָעוֹת: וְלָמָּה אֲכִילַת מַצָּה לֶחֶם עוֹנִי. שֶׁלֹּא הִסְפִּיק בָּצֵק לְהַחֲמִיץ עַד שֶׁגְּאָלָם מֵעוֹנִי: וְלָמָּה בְּמָרוֹר שֶׁתְּחִלָּתוֹ רַךְ וְסוֹפוֹ קָשֶׁה. שֶׁנִּמְרְרוּ תְּחִלָּה בְּפֶה רַךְ וְלִבְסוֹף בְּעוֹל קָשֶׁה: וְלָמָּה טִבּוּלוֹ בַּחֲרוֹסֶת. זֵכֶר לְטִיט שֶׁאִשָּׁה וּבַעְלָהּ דּוֹרֶסֶת: וְלָמָּה תַּבְלִין בְּתוֹכוֹ מֻגְבָּלִין כְּמוֹ מַלְבֵּן. זֵכֶר לְנִפּוּץ עַם לְקוֹשֵׁשׁ קַשׁ לַתֶּבֶן: וְלָמָּה שְׁנֵי מִינֵי בָשָׂר בְּצַד עוּגָה. אֶחָד זֵכֶר לַפֶּסַח וְאֶחָד זֵכֶר לַחֲגִיגָה: וְלָמָּה מַגְבִּיהִין קְעָרָה קוֹדֶם זְמַנָּהּ. כְּדֵי שֶׁיִּרְאֶה תִּינוֹק וְיִשְׁאַל מַה נִשְׁתַּנָּה: וְ<mark>לָמָּה שְׁאָר יְרָקוֹת בָּאִין תְּחִלָּה</mark>. לִפְטוֹר חֲזֶרֶת שֶׁל מִצְוָה בְּרָכָה רְאוּיָה לָהּ. וְשֶׁאֵין לוֹמַר שְׁתֵּי בְּרָכוֹת כְּאַחַת שְׁתִיָּה אוֹ אֲכִילָה. וְאִי אֶפְשַׁר לֶאֱכוֹל וְלִשְׁתּוֹת כְּאַחַת בְּשֶׁכְּבָר כְּרֵסוֹ מִלָּא. וְכֵן בִּשְׁתֵּי מַצּוֹת פּוֹטְרִין מֵחַלָּה לְחַלָּה: עַל כִּי אֵין לְשַׁנּוֹת בִּשְׁתֵּי בְרָכוֹת. מְבָרֵךְ עַל זוֹ וְעַל זוֹ וְאֵינוֹ אוֹכֵל עַד שֶׁיִּגְמוֹר שְׁתֵּי בְרָכוֹת:", "note": null, "a": 46, "b": 51, "head": null}], "said": ["rishon", "בסדרו"], "when": [["hagadol", "text", "יוצר, סדר ההגדה"]]}, {"id": "e30", "sec": "tosafos", "ref": "Tosafot on Pesachim 115b:9:1", "label": "תוס' פסחים קטו: ד\"ה למה עוקרין את השלחן", "paytan": "ה\"ר יוסף", "kind": "line", "quotes": ["מושך מהקערה שני תבשילין ומגביה קערה ולימא הא לחמא עניא"], "rishonHtml": "למה עוקרין את השלחן - דוקא שלהן שהן קטנים אבל שלנו שהן גדולים איכא טורח גדול בעקירתו נהגו לסלק הקערה לצד אחד דליהוי כעקירת שלחן ומה שנוהגין לסלק שני תבשילין בשעת הגבהה כדי שלא יהא נראה כמקדיש קדשים בחוץ וכן יסד ה\"ר יוסף בסדרו <mark>מושך מהקערה שני תבשילין ומגביה קערה ולימא הא לחמא עניא</mark> כו' ולא יתכן דהא דאמר בשר אינו צריך להגביה היינו בשעה שאומר פסח זה דאז ודאי נראה כאוכל קדשים:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Pesachim_115b:9:1", "lit": [{"src": "hagadol", "seg": 43, "segHtml": "<b>יַיִן</b> כִּי יִתְאַדָּם. לְמִצְוָה הוּא מֻקְדָּם. לָצֵאת בּוֹ חוֹבַת יְדֵי אָדָם. אִם אַיִן קוּנְדִיטוּן וּמְבֻשָּׁל נֶגְדָּם: וְאַרְבַּע כּוֹסוֹת הַלָּלוּ. צָרִיךְ שֶׁיְהֵא בָהֵן כְּדֵי רְבִיעִית בְּלִי יָקֵלוּ. אֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים אֵלּוּ כָּאֵלּוּ. וּמְחַלְּקִין לְתִינוֹקוֹת קְלָיוֹת וֶאֱגוֹזִין כְּדֵי שֶׁיִּשְׁאָלוּ: סָחוּ שֶׁהַנָּשִׁים צְרִיכוֹת לְאַמְּצָה. בְּכָל מִילֵי דְפִּסְחָא בְּלִי שִׁמְצָה. אַף עַל גַּב דְמִצְוַת עֲשֵׂה שֶׁהַזְמַן גְּרָמָא בָּם לֹא נִמְצָא. שֶׁכָּל שֶׁיֶּשְׁנוֹ בְּבַל תֹּאכַל חָמֵץ יֶשְׁנוֹ בְּקוּם אֱכוֹל מַצָּה: פֵּרְשׁוּ בְשָׂפָה נְדִיבָה. מַצָּה וְיַיִן צָרִיךְ הֲסֵבָּה. מָרוֹר אֵין בּוֹ כֵּן חוֹבָה. וּמִבָּעֵי לֵיהּ לְכַסְכּוּסֵי טוּבָא: הֲסֵבַּת יָמִין הֲסֵבָּהּ אֵינָהּ. וְלֹא עוֹד אֶלָּא שֶׁמָּא יַקְּדִים קָנֶה לְוֵשֶׁט וְיָבֹא לִידֵי סַכָּנָה. פְּרַקְדָּן לָא מִן חוּשְׁבָּנָא. וְאִשָּׁה אֵינָהּ צְרִיכָה וְאִם חֲשׁוּבָה הִיא נְדוֹנָה: קַמֵּי אָב מֵיסַב הַבֵּן בְּדִיצָה. תַּלְמִיד בִּפְנֵי רַבּוֹ אֵינוֹ רָאוּי לְפָרְצָה. אֲבָל בְּשׁוּלְיָא דְנַגְרֵי צָרִיךְ לְהָסֵב בִּמְרוּצָה. וְהַשַּׁמָּשׁ שֶׁאָכַל כְּזַיִת מַצָּה כְּשֶׁהוּא מֵסֵב יָצָא: טָעֲנוּ לַחֲטוֹף מַצָּה בְּלֵילֵי פְסָחִים. כְּדֵי שֶׁלֹּא יִישְׁנוּ הַפְּרָחִים. וְחַיָּבִין בְּרֶגֶל לִהְיוֹת שְׂמֵחִים. בַּמִּקְדָּשׁ בְּבָשָׂר וְהַשְׁתָּא בְּיֵין רִקּוּחִים: נָשִׁים חַיָּבוֹת לִשְׂמוֹחַ וּלְהַרְנִין. בְּבָבֶל בְּבִגְדֵי צִּבְעוֹנִין. בְּאֶרֶץ יִשְׂרָאֵל בְּבִגְדֵי פִשְׁתָּן הַמְּלֻבָּנִין. וְהָאֲנָשִׁים בְּיַיִן מִתְעַדְּנִין: בְּעֶרֶב הַפֶּסַח סָמוּךְ לְמִנְחַת רִאשׁוֹן. לֹא יֹאכַל אָדָם עַד הָאִישׁוֹן. וּבְבֹאוֹ מִבֵּית רַחֲשׁוֹן. מוֹזְגִין לוֹ כּוֹס רִאשׁוֹן: רִאשׁוֹן מְבָרֵךְ עַל הַיַּיִן וְאַחַר כַּךְ קִדּוּשׁ וּזְמָן וְאֵינוֹ אוֹמֵר נֵס עֲדַיִן. שֶׁצָרִיךְ לְאָמְרוֹ בָּאֲגָדָה וְרָאוּי לְכָפְלוֹ אַיִן. וְשָׁתֵי וּמָשֵׁי יָדֵיהּ וְאֵינוֹ מְבָרֵךְ עַל נְטִילַת יָדָיִם: שָׁקִיל גַּרְגִּירָא אוֹ כַרְפְּסָא אוֹ כֻּסְבַּרְתָּא אוֹ חַסָא וְיִטְבּוֹל בַּחֲרוֹסֶת וִיבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה. וְכַד אָכִיל יֶחֱצֶה אַחַת מִשָׁלֹשׁ מַצוֹת וְאֵין בְּרָכָה עִמָּהּ. מַחֲצָה בִקְעָרָה וּמַחֲצָה בְשֻׁלְחָן לְהָשִׂימָה: <mark>מוֹשֵׁךְ מֵהַקְּעָרָה שְׁנֵי תַבְשִׁיל</mark>ֵי דְּאִנּוּן בִּשְׂרָא וְכַוְרָא צְלִילֵי. אִי נַמֵּי גַּרְמָא וּבִשּׁוּלֵי. וּמַגְבִּיהַּ קְעָרָה וְלֵימָא הָא לַחְמָא עַנְיָא כֻּלֵהּ: וּמוֹזְגִין לוֹ כּוֹס שֵׁנִי מֵאַרְבַּעַת הָאֵל. וְכַאן הַבֵּן מֵאָבִיו שׁוֹאֵל. מַה נִּשְׁתַּנָּה מִלֵּילוֹת זֶה לֵיל. וְגוֹמֵר הָאֲגָדָה עַד גָּאַל יִשְׂרָאֵל: אַחַר דְשָׁתֵי מָשֵׁי יָדֵיהּ. וּמְבָרֵךְ עַל נְטִילַת יָדָיִם לְחוֹדֵיהּ. וְשָׁרֵי הַמּוֹצִיא עַל הַשְּׁלֵמָה דְּעִלַּוֵּי תַּרְתֵּי דִידֵיהּ. וְלֹא אָכִיל מִנֵּיהּ אֲכַתֵּי מִדֵּי: לוֹקֵחַ פְּרוּסָה וּמְבָרֵךְ לֶאֱכוֹל מַצָּה בְּמֶלֶל. וּבַהֲדֵי דְהַהִיא דְהַמּוֹצִיא אוֹכֵל וְכוֹלֵל. וּמְבָרֵךְ בַּחֲזֶרֶת לֶאֱכוֹל מָרוֹר וְטוֹבֵל וּבוֹלֵל. וְהָדָר אָכִיל מַצָּה וּמָרוֹר בְּלֹא בְּרָכָה. וְכוֹרְכָן בְּבַת אַחַת כְּהִלֵּל: חָלִיף לְכַמָּה בָתֵּי וְעָבִיד כִּי הַאי גַּוְנָא עַד הָכָא. וְאַחַר כַּךְ עוֹשִׂין סְעוּדָתָן כָּל צָרְכָּהּ. וְכַזַיִת מַצָּה בָּאַחֲרוֹנָה צְרִיכִין לְכָּרְכָה. וְנוֹטְלִין וְלֹא מְבָרְכִין שֶׁמַּיִם אַחֲרוֹנִים חוֹבָה וְאֵין טְעוּנִין בְּרָכָה: זוֹכֵר בַּשְׁלִישִׁי בִּרְכַת מְזוֹנוֹ. וְלִשְׁאָר הַבָּתִּים תְּחִלָּה וְטוֹעֵם הַכּוֹס עַד מִשֶּׁלּוֹ אֵינוֹ. וּבָרְבִיעִי הַלֵּל מִצְרִי לְתַנּוֹ. בַּל יִטְעוֹם כְּלוּם בְּאִישׁוּנוֹ: קִמְעָא לִשְׁתּוֹת מַיִם יְכַנֵּס. אִם חוֹלֶה הוּא אוֹ אִסְטְנֵס. וּבָעֵי לְמִשְׁתֵּי חַמְרָא מִשּׁוּם אוֹנֵס. לוֹמַר בַּחֲמִישִׁי הַלֵּל הַגָּדוֹל יִשְׁתַּנֵּס:", "note": null, "a": 41, "b": 44, "head": null}], "said": ["rishon", "בסדרו"], "when": [["hagadol", "text", "יוצר, סדר ההגדה"]]}, {"id": "e31", "sec": "tosafos", "ref": "Tosafot on Pesachim 116b:4:2", "label": "תוס' פסחים קטז: ד\"ה ונאמר לפניו שירה חדשה", "paytan": "הפייט", "kind": "line", "quotes": ["שירות אלה לשון נקבה מיוסדים כי תשועתם כיולדה"], "rishonHtml": "ה\"ג ונאמר לפניו שירה חדשה וכן נודה לך שיר חדש על גאולתנו - דהכי תניא במכילתא כל השירות לשון נקבה חוץ משירה דלעתיד דלשון זכר כלומר שהנקבה יש לה צער לידה אף כל הנסים יש אחריהם צער חוץ מלעתיד שאין אחריה צער וכן יסד הפייט בזולת אי פתרוס <mark>שירות אלה לשון נקבה מיוסדים כי תשועתם כיולדה</mark> וגו' תוקף שיר אחרון כזכרים לא יולדים שירו לה' שיר חדש כו' וגרסינן שם מן הזבחים ומן הפסחים שחגיגת ארבעה עשר נאכלת קודם לפסח לפי שהפסח נאכל על השובע:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Pesachim_116b:4:2", "lit": [], "said": ["other", "Seder Troyes 10:6", "בשביעי של פסח (סדר טרויש, לפי קטע מחיפוש בלבד)"], "when": [["pesach", "other", "זולת אי פתרוס, שביעי של פסח לפי סדר טרויש"]]}, {"id": "e32", "sec": "tosafos", "ref": "Tosafot on Pesachim 117b:19:1", "label": "תוס' פסחים קיז: ד\"ה רביעי אומר עליו הלל הגדול", "paytan": "ה\"ר יוסף טוב עלם", "kind": "line", "quotes": ["קימעא לשתות מים יכנס אם חולה הוא או איסטניס"], "rishonHtml": "רביעי אומר עליו הלל הגדול - רביעי גרסי' ולא גרסינן חמישי ולה\"ר יוסף טוב עלם שכתב בסדרו <mark>קימעא לשתות מים יכנס אם חולה הוא או איסטניס</mark> ואי בעי משתיא חמרא משום אונס לומר בחמישי הלל הגדול ישתנס תימה כיון שאוסר לשתות איך תיקנו כוס חמישי הא ארבע כוסות תיקנו ולא חמישי וכן מה שאוסר לשתות אפי' מים הא לא מבטלי טעם מצה דאפילו אחר הפסח לא אסר לקמן רק מיני מיכלא אבל מיני מישתיא אפילו יין לא מצינן לאסור והא דאמר בין שלישי לרביעי לא ישתה מפרש בירושלמי שלא ישתכר ושלא יוכל לומר הלל וכן פסק רבי' שמואל לקמן דכל שתיה מותרת ואפי' לפי המפרשים בין שלישי לרביעי לא ישתה שלא יבטל טעם מצה מ\"מ במים לא מיירי אלא ביין דומיא בין ראשון לשני ישתה דמיירי ביין כי היכי דניגרריה לליביה כדאמרי' לעיל [פסחים דף קח.] ומיהו רוב עמא דבר לשתות וגם רב אלפס התיר מים ולא אסר רק יין:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Pesachim_117b:19:1", "lit": [{"src": "hagadol", "seg": 43, "segHtml": "<b>יַיִן</b> כִּי יִתְאַדָּם. לְמִצְוָה הוּא מֻקְדָּם. לָצֵאת בּוֹ חוֹבַת יְדֵי אָדָם. אִם אַיִן קוּנְדִיטוּן וּמְבֻשָּׁל נֶגְדָּם: וְאַרְבַּע כּוֹסוֹת הַלָּלוּ. צָרִיךְ שֶׁיְהֵא בָהֵן כְּדֵי רְבִיעִית בְּלִי יָקֵלוּ. אֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים אֵלּוּ כָּאֵלּוּ. וּמְחַלְּקִין לְתִינוֹקוֹת קְלָיוֹת וֶאֱגוֹזִין כְּדֵי שֶׁיִּשְׁאָלוּ: סָחוּ שֶׁהַנָּשִׁים צְרִיכוֹת לְאַמְּצָה. בְּכָל מִילֵי דְפִּסְחָא בְּלִי שִׁמְצָה. אַף עַל גַּב דְמִצְוַת עֲשֵׂה שֶׁהַזְמַן גְּרָמָא בָּם לֹא נִמְצָא. שֶׁכָּל שֶׁיֶּשְׁנוֹ בְּבַל תֹּאכַל חָמֵץ יֶשְׁנוֹ בְּקוּם אֱכוֹל מַצָּה: פֵּרְשׁוּ בְשָׂפָה נְדִיבָה. מַצָּה וְיַיִן צָרִיךְ הֲסֵבָּה. מָרוֹר אֵין בּוֹ כֵּן חוֹבָה. וּמִבָּעֵי לֵיהּ לְכַסְכּוּסֵי טוּבָא: הֲסֵבַּת יָמִין הֲסֵבָּהּ אֵינָהּ. וְלֹא עוֹד אֶלָּא שֶׁמָּא יַקְּדִים קָנֶה לְוֵשֶׁט וְיָבֹא לִידֵי סַכָּנָה. פְּרַקְדָּן לָא מִן חוּשְׁבָּנָא. וְאִשָּׁה אֵינָהּ צְרִיכָה וְאִם חֲשׁוּבָה הִיא נְדוֹנָה: קַמֵּי אָב מֵיסַב הַבֵּן בְּדִיצָה. תַּלְמִיד בִּפְנֵי רַבּוֹ אֵינוֹ רָאוּי לְפָרְצָה. אֲבָל בְּשׁוּלְיָא דְנַגְרֵי צָרִיךְ לְהָסֵב בִּמְרוּצָה. וְהַשַּׁמָּשׁ שֶׁאָכַל כְּזַיִת מַצָּה כְּשֶׁהוּא מֵסֵב יָצָא: טָעֲנוּ לַחֲטוֹף מַצָּה בְּלֵילֵי פְסָחִים. כְּדֵי שֶׁלֹּא יִישְׁנוּ הַפְּרָחִים. וְחַיָּבִין בְּרֶגֶל לִהְיוֹת שְׂמֵחִים. בַּמִּקְדָּשׁ בְּבָשָׂר וְהַשְׁתָּא בְּיֵין רִקּוּחִים: נָשִׁים חַיָּבוֹת לִשְׂמוֹחַ וּלְהַרְנִין. בְּבָבֶל בְּבִגְדֵי צִּבְעוֹנִין. בְּאֶרֶץ יִשְׂרָאֵל בְּבִגְדֵי פִשְׁתָּן הַמְּלֻבָּנִין. וְהָאֲנָשִׁים בְּיַיִן מִתְעַדְּנִין: בְּעֶרֶב הַפֶּסַח סָמוּךְ לְמִנְחַת רִאשׁוֹן. לֹא יֹאכַל אָדָם עַד הָאִישׁוֹן. וּבְבֹאוֹ מִבֵּית רַחֲשׁוֹן. מוֹזְגִין לוֹ כּוֹס רִאשׁוֹן: רִאשׁוֹן מְבָרֵךְ עַל הַיַּיִן וְאַחַר כַּךְ קִדּוּשׁ וּזְמָן וְאֵינוֹ אוֹמֵר נֵס עֲדַיִן. שֶׁצָרִיךְ לְאָמְרוֹ בָּאֲגָדָה וְרָאוּי לְכָפְלוֹ אַיִן. וְשָׁתֵי וּמָשֵׁי יָדֵיהּ וְאֵינוֹ מְבָרֵךְ עַל נְטִילַת יָדָיִם: שָׁקִיל גַּרְגִּירָא אוֹ כַרְפְּסָא אוֹ כֻּסְבַּרְתָּא אוֹ חַסָא וְיִטְבּוֹל בַּחֲרוֹסֶת וִיבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה. וְכַד אָכִיל יֶחֱצֶה אַחַת מִשָׁלֹשׁ מַצוֹת וְאֵין בְּרָכָה עִמָּהּ. מַחֲצָה בִקְעָרָה וּמַחֲצָה בְשֻׁלְחָן לְהָשִׂימָה: מוֹשֵׁךְ מֵהַקְּעָרָה שְׁנֵי תַבְשִׁילֵי דְּאִנּוּן בִּשְׂרָא וְכַוְרָא צְלִילֵי. אִי נַמֵּי גַּרְמָא וּבִשּׁוּלֵי. וּמַגְבִּיהַּ קְעָרָה וְלֵימָא הָא לַחְמָא עַנְיָא כֻּלֵהּ: וּמוֹזְגִין לוֹ כּוֹס שֵׁנִי מֵאַרְבַּעַת הָאֵל. וְכַאן הַבֵּן מֵאָבִיו שׁוֹאֵל. מַה נִּשְׁתַּנָּה מִלֵּילוֹת זֶה לֵיל. וְגוֹמֵר הָאֲגָדָה עַד גָּאַל יִשְׂרָאֵל: אַחַר דְשָׁתֵי מָשֵׁי יָדֵיהּ. וּמְבָרֵךְ עַל נְטִילַת יָדָיִם לְחוֹדֵיהּ. וְשָׁרֵי הַמּוֹצִיא עַל הַשְּׁלֵמָה דְּעִלַּוֵּי תַּרְתֵּי דִידֵיהּ. וְלֹא אָכִיל מִנֵּיהּ אֲכַתֵּי מִדֵּי: לוֹקֵחַ פְּרוּסָה וּמְבָרֵךְ לֶאֱכוֹל מַצָּה בְּמֶלֶל. וּבַהֲדֵי דְהַהִיא דְהַמּוֹצִיא אוֹכֵל וְכוֹלֵל. וּמְבָרֵךְ בַּחֲזֶרֶת לֶאֱכוֹל מָרוֹר וְטוֹבֵל וּבוֹלֵל. וְהָדָר אָכִיל מַצָּה וּמָרוֹר בְּלֹא בְּרָכָה. וְכוֹרְכָן בְּבַת אַחַת כְּהִלֵּל: חָלִיף לְכַמָּה בָתֵּי וְעָבִיד כִּי הַאי גַּוְנָא עַד הָכָא. וְאַחַר כַּךְ עוֹשִׂין סְעוּדָתָן כָּל צָרְכָּהּ. וְכַזַיִת מַצָּה בָּאַחֲרוֹנָה צְרִיכִין לְכָּרְכָה. וְנוֹטְלִין וְלֹא מְבָרְכִין שֶׁמַּיִם אַחֲרוֹנִים חוֹבָה וְאֵין טְעוּנִין בְּרָכָה: זוֹכֵר בַּשְׁלִישִׁי בִּרְכַת מְזוֹנוֹ. וְלִשְׁאָר הַבָּתִּים תְּחִלָּה וְטוֹעֵם הַכּוֹס עַד מִשֶּׁלּוֹ אֵינוֹ. וּבָרְבִיעִי הַלֵּל מִצְרִי לְתַנּוֹ. בַּל יִטְעוֹם כְּלוּם בְּאִישׁוּנוֹ: <mark>קִמְעָא לִשְׁתּוֹת מַיִם יְכַנֵּס</mark>. אִם חוֹלֶה הוּא אוֹ אִסְטְנֵס. וּבָעֵי לְמִשְׁתֵּי חַמְרָא מִשּׁוּם אוֹנֵס. לוֹמַר בַּחֲמִישִׁי הַלֵּל הַגָּדוֹל יִשְׁתַּנֵּס:", "note": null, "a": 41, "b": 44, "head": null}], "said": ["rishon", "בסדרו"], "when": [["hagadol", "text", "יוצר, סדר ההגדה"]]}, {"id": "e33", "sec": "tosafos", "ref": "Tosafot on Yoma 8a:11:1", "label": "תוס' יומא ח. ד\"ה דכולי עלמא", "paytan": "רבינו אליהו הזקן", "kind": "line", "quotes": ["יתד על אזניך תכסה", "תסקלוהו ויאמר המלך תלוהו"], "rishonHtml": "דכולי עלמא להני תנאי אמרינן טבילה בזמנה מצוה - ר\"ת פסק דטבילה בזמנה לאו מצוה היא אע\"ג דאמר בפרק המפלת (נדה דף ל. ושם) שמע מינה תלת שמע מינה טבילה בזמנה מצוה אין הלכה כן אלא כרבי יוסי בר' יהודה דאמר התם דיה טבילה באחרונה שהרי מעשים בכל יום שאין לך טובלת בזמנה טבילה של נדה ושל זבה ושל שומרת יום ובפרק בתרא דנדה (דף סז: ושם) אמרינן מכדי האידנא כולהו ספק זבות שוינהו רבנן ליטבלינהו ביממא דשבעה משמע שלא היו טובלות ביום בשום פעם ור\"ח פסק כב\"ש וב\"ה דפרק המפלת (נדה דף ל. ושם) דסברי טבילה בזמנה מצוה ולאו ראייה היא מדסברי ב\"ש וב\"ה הכי שיהא הלכה כן דודאי ר' יוסי בר' יהודה לא פליג עלייהו אלא ס\"ל לא נחלקו ב\"ש וב\"ה בדבר זה א\"כ מצי למימר דהלכתא כר' יוסי ברבי יהודה ומה שעשה רבינו אליהו הזקן זכרונו לברכה באזהרות שלו טבילה בזמנה ועל ארבע גדילים <mark>יתד על אזניך תכסה</mark> הגדולים מנהגן היה שלא היה מקפיד לכתוב כהלכתן כמו שיסד על סתם נסקלים דנתם ונתחייב <mark>תסקלוהו ויאמר המלך תלוהו</mark> והיינו כר\"א דפרק נגמר הדין (סנהדרין דף מה:) כל הנסקלין נתלין ודלא כרבנן דאמרי אין נתלה אלא מגדף ועובד עבודת כוכבים ומהא דאמר בשמעתא דכולי עלמא אמרינן טבילה בזמנה מצוה אין להביא ראיה דלא הוה מצי למימר איפכא דכולי עלמא לא אמרינן טבילה בזמנה מצוה דא\"כ מאי טעמא דר\"מ ועוד ר' יוסי נמי על כרחך סבר טבילה בזמנה מצוה כדשמעינן ליה גבי מי שהיה שם כתוב על בשרו:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Yoma_8a:11:1", "lit": [], "said": ["rishon", "באזהרות שלו"], "when": [["azharos", "rishon", "באזהרות"]]}, {"id": "e34", "sec": "tosafos", "ref": "Tosafot on Yoma 20b:3:1", "label": "תוס' יומא כ: ד\"ה משום חולשא", "paytan": "הפייט", "kind": "line", "quotes": ["הוקמו מחצות דשן לנערה כפייס דשן הבערה"], "rishonHtml": "משום חולשא דכ\"ג עבדינן מחצות - משמע דאפי' תרומת הדשן שהיא עבודת הלילה אינה כשירה אלא בו ולהכי מקדמינן ליה כדי שינוח בין עבודה זו לעבודת היום וריב\"א פירש דלא גרסי' כ\"ג אלא הכי גרסי' משום חולשא דכהן קודם שהכהן התורם יהא חלש דאי כ\"ג תורם א\"כ ליחשביה להא טבילה דטביל בהדי חמש טבילות ועשרה קידושין שכ\"ג טובל בו ביום וכן עשה הפייט <mark>הוקמו מחצות דשן לנערה כפייס דשן הבערה</mark> אלמא שהיו מפייסין ביוה\"כ מי תורם ור\"י אומר דשפיר גרס כ\"ג דלהכי מקדמי לתרום ולסדר מערכה ולסלק האברים שלא נתעכלו כדי שימצא כהן גדול מזומן כל מה שצריך מיד כשיעלה עמוד השחר קודם שיהיה רעב וחלש:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Yoma_20b:3:1", "lit": [], "said": null, "when": [["yk", "context", "סדר העבודה (\"שהיו מפייסין ביוה\"כ\")"]]}, {"id": "e35", "sec": "tosafos", "ref": "Tosafot on Sukkah 36b:6:1", "label": "תוס' סוכה לו: ד\"ה מקורזלות", "paytan": "הפייט", "kind": "line", "quotes": ["אשישת שלוחתו בקטב תלה אשישות להניץ בתיחוח קירזולה"], "rishonHtml": "מקורזלות פי' בקונטרס פיקוד\"ש בלע\"ז חדודות וטובות לקנח ולא משמע כן פרק אלו עוברין (פסחים דף מז.) גבי יש חורש תלם אחד דפריך ואי אמרינן הואיל אחרישה לא ליחייב הואיל וחזי לכסות בו דם צפור ומשני באבנים מקורזלות ומה שייך להזכיר שם אבנים חדודות ומפרש רבינו תם דמקורזלות היינו [רכות] דחזו לחרישה ולזריעה וכן יסד הפייט <mark>אשישת שלוחתו בקטב תלה אשישות להניץ בתיחוח קירזולה</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Sukkah_36b:6:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e36", "sec": "tosafos", "ref": "Tosafot on Sukkah 49a:1:1", "label": "תוס' סוכה מט. ד\"ה שכל מזבח", "paytan": "רבינו אליהו הזקן", "kind": "line", "quotes": ["אבני מזבח תוך ובר כן נגוזו ועבר"], "rishonHtml": "שכל מזבח שאין לו קרן. וזה שקרנו נפגמה הוה ליה קרן כמאן דליתיה ולכך נפסל לעבודה דאין לו קרן דפגימה פוסלת באבני מזבח כדי שתחגור בה צפורן כדאמר פ\"ק דחולין (דף יח. ושם) וטעמא פירש שם בקונט' משום דכתיב אבנים שלמות תבנה [ובסידא] פליגי בה תנאי התם ר\"ש בן יוחי אומר טפח ר' אליעזר בן יעקב אומר כזית וי\"ל דהטעם משום דלא חשיב ריבוע למר בהאי שיעורא ולמר בהאי שיעורא וריבוע מעכב כדקתני הכא ומיהו במזבח ניחא דכתיב רבוע יהיה המזבח אבל קרן מנלן דסיד היה בקרן דאע\"פ שפירש כאן בקונט' קרן אבן מרובע אמה על אמה ברום אמה לא יתכן דע\"י מלבן נעשה כדאי' בפ' איזהו מקומן (זבחים נד.) ושמא רבוע דקרן ילפינן ממזבח וא\"ת ואבני מזבח מאי איריא משום דנפגמה תיפוק ליה משום דחסרה האבן ואפילו לא נפגמה לא קרינן בהו שלמות כדמוכח פ' איזהו מקומן (שם) גבי מזרחית דרומית שלא היה לו יסוד דפריך היכי עבדי לה אי דגייז לה אבנים שלמות אמר רחמנא וי\"ל דהכי קאמר ליה התם אי גייז לשבר האבן אי אפשר [לשבר] בלא פגימה ואין כאן שלמות ואם בא לפחות ולהחליק בסכין בלא פגימה איכא איסורא דלא תניף עליהן ברזל וכן משמע במסכת ע\"ז פ' ר' ישמעאל (עבודה זרה דף נב:) גבי אבני מזבח. שקצצום וגנזום בית חשמונאי דקאמר היכי נעביד ניתברינהו אבנים שלמות אמר רחמנא נסרינהו פי' לעשות בלא פגימות לא תניף עליהם ברזל כתיב וא\"ת וליעבדו על ידי שמיר דבבית שני הוה שמיר כדמוכח במסכת סוטה בפ' עגלה ערופה (סוטה דף מח.) דקאמר משמתו נביאים הראשונים בטלו אורים ותומים משחרב בית המקדש בטל שמיר והיינו בית שני דאי בית ראשון ליערבינהו משחרב בית המקדש בטלו אורים ותומים ושמיר דמשמתו נביאים הראשונים היה חורבן הבית כדתניא בגמ' משחרב בהמ\"ק בטלו אורים ותומים והיינו בית ראשון דחמשה דברים חסר בית שני מבית ראשון כדאיתא ביומא (דף כא:) אלא בטל השמיר היינו לאחר בית שני וכן הא דקאמר רשב\"ג התם משחרב בהמ\"ק ניטל טעם הפירות מסתמא לאחר חורבן בית שני קאמר שחרב בימיו תדע דאשכחן בבית שני שהיו פירות מתברכין בימי שמעון בן שטח. שנעשין חטין ככליות של שור הגדול ועוד יש להביא ראיה דהוה שמיר בבית שני מעובדא דדמא בן נתינה דפ\"ק דקידושין (דף לא.) ודפ\"ב דע\"ז (דף כג: ושם) שבקשו ממנו חכמי ישראל אבנים לאפוד ואבני אפוד בעו שמיר כדקאמר ר' נחמיה פ' עגלה ערופה (סוטה מח:) כדכתיב במלואותם ואפי' ר' יהודה דפליג עליה ואמר שמיר שבו בנה שלמה את בהמ\"ק מודה נמי דאבני אפוד בעו שמיר כדמוכח פ' מי שאחזו (גיטין סח. ושם) גבי בנין בהמ\"ק שעשה שלמה דקאמרינן היכי נעביד איכא שמיר דאייתי משה לאבני אפוד וההיא על כרחך רבי יהודה היא דלר' נחמיה לא הוה שמיר לבית המקדש ועובדא דדמא בן נתינה בבית שני הוה דקאמרינן התם לשנה נולדה לו פרה אדומה בעדרו ושבע פרות היו הראשונה שעשה משה שניה שעשה עזרא כדתנן במסכת פרה (פ\"ג מ\"ה) וכיון שהיה שמיר בבית שני כדפרישית אמאי גנזום בית חשמונאי וי\"ל שמיר אין עושה אותן שלמות שלא תחגור בה צפורן וא\"ת א\"כ היאך בנו את המזבח דלא אפשר לומר שהיה מתקן מבחוץ ומכניסו מבפנים דאפילו כי האי גוונא במזבח אסור כדתניא במכילתא בסוף פרשת וישמע יתרו לא תבנה אתהן גזית בו אין אתה בונה גזית אבל אתה בונה גזית בהיכל ובקודש הקדשים ומה אני מקיים ומקבות והגרזן וכל כלי ברזל לא נשמע בבית בהבנותו בבית אינו נשמע אלמא במזבח אפילו בחוץ אינו נשמע וכן יסד רבינו אליהו הזקן באזהרת אמת יהגה חיכי <mark>אבני מזבח תוך ובר כן נגוזו ועבר</mark> והיינו יכולין לחלק בין קודם שהוקדשו אבנים למזבח דעודן חולין לאחר שהוקדשו אבל אין צריך דמשמע בפ' איזהו מקומן (זבחים נד. ושם) שבנו אותו באבנים החלוקות כגון חלוקי אבנים מן הנחל שבחול הים ובחול הים נבראו חלקות מששת ימי בראשית ומיהו קשה דגבי בית המקדש כתיב אבן שלמה מסע נבנה ואמר ר' יהודה דהוה שמיר לבהמ\"ק.:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Sukkah_49a:1:1", "lit": [], "said": ["rishon", "באזהרת אמת יהגה חיכי"], "when": [["azharos", "rishon", "באזהרות"]]}, {"id": "e37", "sec": "tosafos", "ref": "Tosafot on Rosh Hashanah 3a:1:1", "label": "תוס' ר\"ה ג. ד\"ה וישמע הכנעני", "paytan": "הפייט", "kind": "line", "quotes": ["כסות ולשון שינה היות כמלך ערד"], "rishonHtml": "וישמע הכנעני מלך ערד. במדרש אמרינן דהיינו עמלק כמו שיסד הפייט בפזמון של פרשת זכור <mark>כסות ולשון שינה היות כמלך ערד</mark> אבל מ\"מ דייק שפיר דהוה סיחון קיים מדשינה עמלק עצמו לבא כדמותו ונראה דמההוא דמסעי קא דריש דאי מההוא דחקת הא מפרש דשמע כי בא ישראל דרך האתרים ורש\"י לא דק בפי' חומש:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002182132", "url": "https://www.sefaria.org/Tosafot_on_Rosh_Hashanah_3a:1:1", "lit": [{"src": "zachor", "seg": 28, "segHtml": "<b>זָכוֹר</b> אִישׁ אֲשֶׁר הִגְוִיעַ אָב לְלֹא עִתּוֹ. בְּרָצוֹחַ וְגָנוֹב וְנָאוֹף בִּעֲתוֹ. גָּרַע חָמֵשׁ שָׁנִים מִמִחְיָתוֹ: זָכוֹר בּוֹזֶה עַל גְּמִילוּת חֶסֶד. גּוֹעֵל אָח עָשׂ לִזְקֵנוֹ חֶסֶד. דּוֹמֶה לַמָּס מֵרֵעֵהוּ חָסֶד: זָכוֹר גִלָּה עֶרְוַת מְצוּאַת שָׂדֶה. דָּם שָׁפַךְ בְּבוֹאוֹ מִן הַשָׂדֶה. הָפַךְ לֵב אָב שָׂח בַּשָׂדֶה: זָכוֹר דָּחוּי בְּאֹזֶן הָעֲרֵלָה. הַבּוֹזֶה בְּכוֹרָה בְּכוֹס הַתַּרְעֵלָה. וּפָרַק מֶנּוּ עוֹל וּמָשַׁךְ לוֹ עָרְלָה: זָכוֹר הֲפַכְפַּךְ דֶּרֶךְ אִישׁ וָזָר. וְהִכְהָה מְאוֹר אָב בַּעֲשַׁן עֲבוֹדַת זָר. זָמַם בְּלֵב הֱיוֹת לְאָח לְאַכְזָר: זָכוֹר וְנִתְעוֹלֵל לְרֶבַע כְּאִשָּׁה. זְדוֹן לִבּוֹ הִשִׁיאוֹ בָּאְשָׁה. חַתּוּ גִבּוֹרָיו לִהְיוֹת כְּלֵב אִשָּׁה: זָכוֹר זֶרַע מְרֵעִים נִתְעָב וְנֶאֱלָח. חָלַק לְהַשְׁחִית וְלוֹמַר הֶאָח. טָמְנוּ גֵּאִים פַּח לְחַבֵּל אָח: זָכוֹר חָנַט מֶנּוּ עֲמָלֵקִי. טָס כְּיֶלֶק לְאַבֵּד חֶלְקִי. יָרוֹעַ כַּבִּירִים לְעֵין כֹּל לְלוֹקְקִי: זָכוֹר טָפַשׁ מֵהַעֲרִימָה. יָרַד וְכִתֵּת עַמִּי עַד חָרְמָה. כְּמוֹ כֵן חֻיַּב לְהַחֲרִימָה: זָכוֹר יוֹשֵׁב הַנֶּגֶב בְּלִי עוֹל כַּעֲרָד. <mark>כְּסוּת וְלָשׁוֹן שִׁנָּה הֱיוֹת מֶלֶךְ עֲרָד</mark>. לִשְׁבּוֹת שֶׁבִי מָרַד וְחָרַד: זְכוֹר כְּסִיל שׁוֹנֶה בְּאִוַּלְתּוֹ. לְתַעֲרוּבַת מִדְיָן בַּעֲלוֹתוֹ. מִהֵר יְרֻבֶּשֶׁת וְגִלָּה נַבְלוּתוֹ: זָכוֹר לְקַעֲקֵעַ בִּצָתוֹ מִשׁוֹרֶשׁ. מִלַעֲזוֹב לוֹ עָנָף וְגַם שׁוֹרֶשׁ. נֶעֱנַשׁ קִישִׁי כִּי הִשְׁאִיר לוֹ שׁוֹרֶשׁ: זָכוֹר מַעֲשֵׂה אֲגַג מַעֲדַנּוֹת. נָשִׁים כְּשִׁכְּלָה חַרְבּוֹ לְעַנוֹת. סוֹרַס שְׁאֵרוֹ לְשִׁסוּף יַעֲנוֹת: זָכוֹר נָגִיד לְחָמְלוֹ הִסְכִּים. סָר מִמְּלוּכָה מִבֵּין נְסִיכִים. עוֹלֵל הַנּוֹתָר עָמַד לְשִׂכִּים: זָכוֹר סִבֵּב צִקְלַג וָנֶגֶב. עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. פִּגְרוֹ טוֹב רוֹאִי מְנַשֵׁף בְּעֻגָב: זָכוֹר עָרִיץ בְּעַמּוֹנִים נֶחְבָּא. פֶּרֶץ כַּרְמֵי עֵין גֶּדִי כְּהוּבָא. צוֹרְבוּ אִישׁ בְּאָחִיו בְּחֶרֶב לְהוּבָה: זָכוֹר פְּלֵטִים אֲשֶׁר בְּאַף הִסְעִיר. צְבָאַי בְּלֶכְתָּם אֶל הַר שֵּׂעִיר. קַנֹּא לִנְקוֹם עֲיָרוֹת שֵׂעִיר: זָכוֹר צָג בְּפֶרֶק לְהַסְגִּיר שְׂרִידַי. קָם בְּרֹאשׁ דְּרָכִים לִסְעוֹד אֶת רוֹדַי. רָדַף וּמָסַר בְּיָדָם פְּרוּדַי רְפוּדַי: זָכוֹר קָפַץ לְשַׁעַר הַשָׁמַיִם. רָעַשׁ וְשָׁאַג מִי לִי בַּשָׁמַיִם. שָׁלַט וַיִּגְדַּל עַד לַשָׁמָיִם: זָכוֹר רָד אֶל חָנֵף לְהַחֲנִיף מַמְלֶכֶת. שִׁמְשַׁי אֲשֶׁר שִׁמְשׁוֹ מְאַמֶּשֶׁת וְהוֹלֶכֶת. תַּמָה הִלְשִׁין לְרַפּוֹתָהּ מִמְלֶאכֶת: זָכוֹר שָׁקַל אֲלָפִים עֲשָׂרָה. שְׁתִילִים מֵאָה הֶחֶנִיט לְשִׂבְרָה. שִׁעֵר מֵהֶם עֲשָׂרָה לִשְׂרָרָה: זָכוֹר תָּבַע לְהָפֵר חֻמָּשִׁים. תְּמִימָה קָצַב לְכַלּוֹת חֲמֻשִׁים. תַּכְלִית שִׁבְעִים נִתְלָה עַל חֲמִשִׁים:", "note": null, "a": 26, "b": 28, "head": null}], "said": ["rishon", "בפזמון של פרשת זכור"], "when": [["zachor", "text", "פזמון של פרשת זכור"]]}, {"id": "e38", "sec": "tosafos", "ref": "Tosafot on Rosh Hashanah 8b", "label": "תוס' ר\"ה ח: ד\"ה שהחדש מתכסה בו", "paytan": "ר\"א הקלירי", "kind": "content", "quotes": ["מוספי חדש עשתי עשרה"], "rishonHtml": "שהחדש מתכסה בו. שאין הלבנה נראית לרחוקים כגון שחרית לבני מערב וערבית לבני מזרח לפי שקטנה היא סמוך לחדושה כפי' הקונטרס והביא ר\"ת ראיה מויקרא רבה בפרשת אמור אל הכהנים דקאמר התם תקעו בחדש שופר בכסה ליום חגנו והלא ניסן חדש ונכסה ויש בו חג אלא זה שחגו בו ביום ואין לך חדש שהוא נכסה ויש בו חג וחגו ביומו אלא תשרי ועוד מפרש ר\"ת מתכסה מזומן כמו ליום הכסא יבא ביתו דבפרק חלק (סנהדרין דף צו:) גבי עמון ומואב שיבבי בישי דארעא דישראל הוו וכו'. והר\"ר משולם מפרש שהחדש מתכסה בו שאין חטאת ר\"ח קרב בראש השנה כדכתיב מלבד עולת החדש ומנחתה ולא כתיב מלבד חטאת ועולה והקשה לו ר\"ת דבריש תוספתא דשבועות תניא (ל') שעירים מקריבים ישראל בכל שנה וחשיב י\"ב בראשי חדשים ובאופן דמוסף דר\"ה וחיות אשר הנה מרובעות יסד ר\"א הקלירי <mark>מוספי חדש עשתי עשרה</mark> דהיינו פרים בני בקר שנים ואיל אחד כבשים בני שנה שבעה ושעיר לכפר והשיב לר\"ת שלא אמר שאין בו מוסף אלא מתכסה שלא הזכיר הכא חטאת בקרא דמלבד כמו שהזכיר עולה ועוד פי' מתכסה שאין מזכירין מוסף של ר\"ח בתפלה משום דאמרי' רשב\"ג ה\"ל בריה דבסים קליה עייל קמי תיבותא כי מטי לראשי חדשים אישתיק ולא רצה לאמרו פי' דמוטב שיבא זכאי ויכפר על החייב ואל יבא חייב ויכפר על הזכאי פירוש ההוא דר\"ח קרוי חייב משום דאמרי' אמר הקב\"ה הביאו כפרה וכו' עכ\"ל ור\"ת רגיל להזכיר ולומר מלבד עולת החדש ולסיים ושני שעירים לכפר חד דר\"ח וחד דר\"ה:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002182132", "url": "https://www.sefaria.org/Tosafot_on_Rosh_Hashanah_8b", "lit": [], "said": ["rishon", "באופן דמוסף דר\"ה וחיות אשר הנה מרובעות"], "when": [["rh", "rishon", "אופן דמוסף"]]}, {"id": "e39", "sec": "tosafos", "ref": "Tosafot on Rosh Hashanah 27a:15:1", "label": "תוס' ר\"ה כז. ד\"ה כמאן מצלינן", "paytan": "ר\"א הקליר", "kind": "content", "quotes": ["ומה שיסד ר\"א הקליר בגשם דשמיני עצרת כר\"א דאמר בתשרי נברא העולם ובשל פסח יסד כר' יהושע"], "rishonHtml": "כמאן מצלינן זה היום תחלת מעשיך. תימה הא קי\"ל כרבי יהושע כדאמרינן בפ\"ק (דף יב.) לתקופה כר' יהושע ואומר ר\"ת דקי\"ל כרב עינא דפריך משוה יובל ורב עינא ה\"ק והא איכא זה היום תחלת מעשיך דאיתיה בראש השנה וליתיה ביובל אלא ודאי הא דאמרינן ליה לאו משום ברייתו של עולם אלא משום תחלת מעשה דין שהעולם נדון בו להתקיים או לאו וזה שייך נמי ביוה\"כ דיובל דהוקש לר\"ה כדלקמן בפרק בתרא (דף לד.) (אבל בשאר יומי לא) ואע\"ג דמשני ליה שפיר רב עינא לא הדר ביה ומיהו לאידך לישנא קשיא דקאמר מתני' דלא כר\"א הוה ליה לשנויי דזה היום תחלת מעשיך לאו אבריאת עולם קאי <mark>ומה שיסד ר\"א הקליר בגשם דשמיני עצרת כר\"א דאמר בתשרי נברא העולם ובשל פסח יסד כר' יהושע</mark> אומר ר\"ת דאלו ואלו דברי אלהים חיים ואיכא למימר דבתשרי עלה במחשבה לבראות ולא נברא עד ניסן ודכוותה אשכחן בפרק עושין פסין (עירובין דף יח. ושם) גבי אדם שעלה במחשבה לבראות שנים ולבסוף לא נברא אלא אחד:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH002182132", "url": "https://www.sefaria.org/Tosafot_on_Rosh_Hashanah_27a:15:1", "lit": [], "said": ["rishon", "בגשם דשמיני עצרת, ובשל פסח"], "when": [["shmini", "rishon", "גשם"], ["pesach", "rishon", "\"ובשל פסח\""]]}, {"id": "e40", "sec": "tosafos", "ref": "Tosafot on Megillah 25a:4:1", "label": "תוס' מגילה כה. ד\"ה מפני שעושה מדותיו", "paytan": "הקליר", "kind": "line", "quotes": ["צדקו אותו ואת בנו לא תשחטו ביום אחד"], "rishonHtml": "מפני שעושה מדותיו של הקב\"ה רחמים והן אינם אלא גזירות - ק' להר\"ר אלחנן על מה שיסד הקליר בקדושת' שאנו אומרים ביום ב' של פסח <mark>צדקו אותו ואת בנו לא תשחטו ביום אחד</mark> דמשמע שר\"ל שהקב\"ה חס על אותו ואת בנו והוא אינו אלא גזירה:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Megillah_25a:4:1", "lit": [], "said": ["rishon", "בקדושת' שאנו אומרים ביום ב' של פסח"], "when": [["pesach", "rishon", "קדושתא, יום ב'"]]}, {"id": "e41", "sec": "tosafos", "ref": "Tosafot on Moed Katan 27b:1:1", "label": "תוס' מו\"ק כז: ד\"ה בכליכה", "paytan": "", "kind": "line", "quotes": ["עמון ומואב הוציאו את הכרובים וכליכה היו בם מסובבים"], "rishonHtml": "בכליכה. גרס בערוך בשני כפי\"ן ואית דגרסי כליבה בבי\"ת השניה כמו הללו חוזרין לכלובן (ביצה דף כד.) וכמו ככלוב מלא עוף (ירמיהו ה׳:כ״ז) אי נמי כמו מכליב (לעיל מועד קטן דף י.) ופירש הקונטרס כעין סולם והיינו כעין תפירות רחוקות זו מזו ומביא הא דאמרינן במדרש נטלו את הכרובים ונתנום בכליכה ואם כן צריך לגרוס בפיוט של חרבן בית המקדש בתשעה באב <mark>עמון ומואב הוציאו את הכרובים וכליכה היו בם מסובבים</mark> וגרס בב' כפי\"ן לגירסת הערוך וכל זה שלא לבייש מי שאין לו וכן איתא במסכת בכורים (פ\"ג מ\"ז) בראשונה מי שהיה יודע לקרו' כו' ומאותה ההלכ' מביאין ראיה להא דאמר שמנה פסוקים שבתורה יחיד קורא אותם דלא בעי למימר שלא יקרא שליח צבור עמו כי בימיהם לא היה קורא שליח צבור עם הקורא ומה שרגילים עתה לקרות זהו מפני כבודו של קורא שלא לבייש מי שאינו יודע וכדאמר גבי בכורים בראשונה מי שהיה יודע לקרות קורא ומי שאינו יודע לקרות (אינו קורא) מקרין אותו נמנעו מלהביא בכורים התקינו שיהו מקרין את הכל (בכורים פ\"ג מ\"ז):", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Moed_Katan_27b:1:1", "lit": [], "said": ["rishon", "בפיוט של חרבן בית המקדש בתשעה באב"], "when": [["tishabav", "rishon", "פיוט של חרבן"]]}, {"id": "e42", "sec": "tosafos", "ref": "Tosafot on Chagigah 11a:12:4", "label": "תוס' חגיגה יא. ד\"ה ברום ג' אמות", "paytan": "הפייט", "kind": "line", "quotes": ["אדם בקום חיש בשלש אמות והרביעית (וחמישית) אויר מגולה"], "rishonHtml": "ברום ג' אמות. ואע\"ג שאדם מחזיק ד' אמות קומה כדמוכח בשמעתין דכוכין דאורך הכוך ד' אמות קומת האדם אינו אלא ג' אמות לבד הראש ומצי להרכין את ראשו מן הצד והא דנקט ד' אמות משום עובי צידי הארון ואע\"ג דמצינו בפ\"ק דב\"ב (דף ב:) גבי היזק ראייה שיעור ראייה ד' אמות היינו שיכול להגביה עצמו על ראשי אצבעותיו עד שיציץ ד' אמות וכן מוכח בעובדא דבני המן בתרגום של מגילת אסתר שנסדר על פי המדרש שגובה קומתן ג' אמות לבד הראש דקחשיב ואזיל על רום חמשים אמות לפי תליית כל העשרה והיו נהרגים כבר קודם התלייה וכן משתעי קרא בשושן הבירה הרגו היהודים ואבד חמש מאות איש ואת עשרת בני המן משמע שבכלל הריגה היו וגם הפייט יסד בסליחה <mark>אדם בקום חיש בשלש אמות והרביעית (וחמישית) אויר מגולה</mark>:", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/%D7%AA%D7%9C%D7%9E%D7%95%D7%93_%D7%91%D7%91%D7%9C%D7%99", "url": "https://www.sefaria.org/Tosafot_on_Chagigah_11a:12:4", "lit": [{"src": "esther", "seg": 12, "segHtml": "אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אָדָם בְּקוּם עָלֵינוּ חִיל אֲחָזַתְנוּ לִרְעוֹד. בְּהִסְתַּפְּחוֹ לְמַלְכוּת חָנֵף כִּמְעַט כָּשַׁלְנוּ לִמְעוֹד. גָּמְרוּ לְמָכְרֵנוּ כְּתֵל וְחָרִיץ בְּלִי מִסְעוֹד. אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי וְלֹא יִזָּכֵר שֵׁם יִשְׂרָאֵל עוֹד: דַּלּוּ עֵינַי לַמָּרוֹם קְרָאתִיךָ אוֹיְבַי לָקוֹב. הַכְרֵת שֵׁם וּשְׁאָר וּמְחֵה שֵׁם לִרְקוֹב. וְצָר צוֹרְרַי בְּנִכְלֵיהֶם אֲשֶׁר נִכְּלוּ לַעֲקוֹב. וַיֹּאמְרוּ לֹא יִרְאֶה יָהּ וְלֹא יָבִין אֱלֹהֵי יַעֲקֹב: זְרוּיִם עִנָּה וַיַּגֶּה וְלֹא מִלֵּב לְכַלּוֹתָם. חָבוּ לְפָנִים וְרִדָּם בַּהֲסָרַת טַבַּעַת לְהַחֲלוֹתָם. טוֹב דְּבָרוֹ הֵקִים לְעֵינֵי הַגּוֹיִם לְהַעֲלוֹתָם. בְּאֶרֶץ אוֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלּוֹתָם: יִדַּע רֶמֶז הַקּוֹרוֹת לְעַם מְעֻפָּר וּמְהֻדָּס. כְּתָב הַסְתֵּר אַסְתִּיר וּמָר דְּרוֹר מְפֻרְדָּס. לִשְׁבּוֹת הָמָן מִמָּחֳרָת הֲמִן הָעֵץ קֻנְדָּס. תַּחַת הַנַּעֲצוּץ יַעֲלֶה בְרוֹשׁ וְתַחַת הַסִּרְפָּד יַעֲלֶה הֲדָס: מַקְשִׁיב דְבַר שֶׁקֶר כָּתַב שִׂטְנָה וָעֶצֶב. נִתְעַטֵּף בְּבִגְדֵי שְׂרָד כְּטָעָה בְּמִנְיַן קֶצֶב. סָדַּר לְהִשְׁתַּמֵּשׁ בְּשׁוֹנִים כְּלֵי בֵּית הַמַּחֲצֵב. וַיָּבֹא גַם הַשָּׂטָן בְּתוֹכָם לְהִתְיַצֵּב: עַם הַנִּמְצָאִים בְּשׁוּשָׁן בְּאָכְלָם מִזֶּבַח עָכְרָם. פָּעַר פִּיו לְהַשְׂטִינָם וּלְהַסְגִּירָם בְּיַד נוֹתֵן מִכְרָם. צוּר הִסְכִּים לִכְתּוֹב אִגֶּרֶת לְאַבֵּד שִׂבְרָם. אָמַרְתִּי אַפְאֵיהֶם אַשְׁבִּיתָה מֵאֱנוֹשׁ זִכְרָם: קְדוֹשִׁים מַלְאֲכֵי הַשָׁרֵת מַר יִבְכָּיוּן בִּצְעָקָה. רַחוּם הַבֵּט לַבְּרִית וְאַל תָּפֵר לְהַרְחִיקָה. שָׁמְעָה מוֹרָשָׁה וַתִּלְבַּשׁ בִּגְדֵי אַלְמְנוּת וּמוּעָקָה. וַתָּשֶׂם יָדָהּ עַל רֹאשָׁהּ וַתֵּלֶךְ הָלוֹךְ וּזְעָקָה: תִּשְׁבִּי שָׂם אֵזוֹר שַׂק בְּמָתְנָיו תַּחְבֹּשֶׁת. מִהֵר וְהוֹדִיעַ יְשֵׁנֵי מַכְפֵּל אָבוֹת שְׁלֹשֶׁת. נָחַץ לְרוֹעֶה מַה לְּךָ נִרְדָּם לְהִתְעַשֵּׁת. קוּם קְרָא אֶל אֱלֹהֶיךָ אוּלַי יִתְעַשֵּׁת: חוֹתַם טִיט אֲשֶׁר נַעֲשָׂה לְבִלְשָׁן סִפֵּר. מִנִּינְוֵה לָמְדוּ לְאַחַר גְּזֵרָה כַּעַס לְהָפֵר. בֶּן קִישׁ הִקִּישׁ דַּלְתוֹת בֵּית הַסֵּפֶר. וַיְּכַס שַׂק וַיֵּשֶׁב עַל הָאֵפֶר: רִבֵּץ תִּינוֹקוֹת לְפָנָיו יָמִים שְׁלֹשָׁה צָמִים וּמֻכְפָּנִים. בְּקוֹל יַעֲקֹב לַחֲלוֹשׁ יְדֵי עַז פָּנִים. יָדָיו אֱמוּנָה לָאֵל הַצִּילֵנִי מֵעֶלְבּוֹנִים. פֶּן יָבוֹא וְהִכַּנִי אֵם עַל בָּנִים: מִזֶּה אֵלֶּה וּמִזֶּה אֵלֶּה בְּנֵי אֵיתָנַי וְרַבָּנַי. כֻּלָּם צָעֲקוּ וַתַּעַל שַׁוְעָתָם אֶל יְהֹוָה. יָהּ לְקוֹל רִנּוּן כְּבוֹא שָׁאַל לִפְנָי. וּמֶה קוֹל הַצֹּאן הַזֶּה בְּאָזְנָי: רוֹעֶה הֱשִׁיבוֹ הֵם קְטַנֵּי קֹדֶשׁ זֶרַע. יָהּ הַצֵּל לְקוּחִים לַמָּוֶת מֵאוֹיֵב הָרַע. חַנּוּן נִכְמְרוּ רַחֲמָיו וַיְּבַקֵּשׁ לִבְכּוֹת הַמְּאֹרָע. וַיְּהִי כִּקְרוֹא מֶלֶךְ יִשְׂרָאֵל אֶת הַסֵּפֶר וַיִּקְרָע: יְהוּדִי הוֹקִיעַ יְלָדָיו לְמַטָּה וַאֲבִיהֶם מִלְמַעְלָה. <mark>אִישׁ אִישׁ בְּשָׁלֹשׁ אַמּוֹת וְהָרְבִיעִית אַוֵּיר מְגֻלָּה</mark>. מִשְׁנֶה נָקָם חָזָה וְשָׂמַח וְשָׂח תְּהִלָּה. אוֹתִי הֵשִׁיב עַל כַּנִּי וְאוֹתוֹ תָלָה: וַתִּכְתּוֹב אֶסְתֵּר תּוֹקֶף לִקְרוֹת כִּבְהַלֵּל מְהוֹדִים. מִלְּמַעְלָה קִיְּמוּ מַה שֶּׁקִּבְּלוּ לְמַטָּה דּוֹדִים. נֵס יְנוֹסֵס לְפַרְסֵם כְּאָז פִּלְאוֹ מַסְהִידִים. בָּעֵת הַזֹּאת רֶוַח וְהַצָּלָה יַעֲמוֹד לַיְּהוּדִים:", "note": "בטקסט שבספריא: \"איש איש בשלש אמות\". הסליחה פותחת \"אדם בקום עלינו\" וחתומה מנחם ברבי מכיר.", "a": 12, "b": 12, "head": 11}], "said": ["rishon", "בסליחה"], "when": [["esther", "text", "סליחה אדם בקום עלינו"]]}, {"id": "e43", "sec": "tosafos", "ref": "Tosafot on Chagigah 12a:3:1", "label": "תוס' חגיגה יב. ד\"ה מסוף העולם ועד סופו", "paytan": "ה\"ר בנימין", "kind": "line", "quotes": ["זה הים שליש עולמו במאה וששים ושש ועוד"], "rishonHtml": "מסוף העולם ועד סופו. מהלך ת\"ק שנה (לקמן חגיגה יג.) שנאמר שדי שאמר די שלא להרחיב יותר שנאמר אני אל שדי פרה ורבה אני שאמרתי די לעולם ותימה מנא לך הא שיש ת\"ק שנה ולא יותר ולא פחות וי\"ל דנפקא לן מן שדי בשדי יש ג' אותיות שי\"ן דל\"ת יו\"ד קח י\"נ ל\"ת ו\"ד הנעלם מן שדי ויעלה ת\"ק כך שמעתי מר' מנחם ברבי עזריאל וצ\"ע למ\"ד פרק מי שהיה טמא (פסחים צד. ושם) כל העולם כולו תחת כוכב אחד עומד היכי קיימי כל הני כוכבים הנראין ברקיע וי\"מ שעל ים אוקיינוס הן עומדין כדאמרינן בפרקי דר\"א כל השיעורים לא נאמרו רק על שאר ימים אבל ים אוקיינוס בוראו יודע מדתו אך במדרש אחר מצינו ששליש ימים שאמר הוי בים אוקיינוס וכן יסד ה\"ר בנימין ביוצר שלו <mark>זה הים שליש עולמו במאה וששים ושש ועוד</mark> סיימו וצריך למימר שאותו מדרש פליג אההיא דפסחים ומיהו יש להעמיד ההיא דהתם במזלות של גלגל אבל שאר כוכבים קטנים הם ולי נראה דיש ליישב כל אותן מדרשים שהם תלוין בכיפת הרקיע והוא גדול הרבה מן הארץ אם היה נמתח עליה זו כזו לפי גבול הארץ בא וראה אהל מתוח על הארץ כמין כיפה גבוה באמצע שתופס כפלי כפלים אם היה נמתח בקו הארץ אך היה קשה מדכתיב גבי סיסרא (שופטים ה׳:כ׳) מן שמים נלחמו הכוכבים ממסלותם ומוכח מינה בנימוקי רש\"י וכן איתא במדרש שאורך הכוכב מהלך ת\"ק שנה כמן השמים ועד הארץ שהיה ראש אחד תחוב ברקיע והשני היה בארץ והיכי היה יצא באויר העולם כיון דכולו תחת כוכב אחד הוא עומד וצ\"ל שהם חולקין יחד אם לא נחלוק בין מזלות הגלגל לשאר מזלות:", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/%D7%AA%D7%9C%D7%9E%D7%95%D7%93_%D7%91%D7%91%D7%9C%D7%99", "url": "https://www.sefaria.org/Tosafot_on_Chagigah_12a:3:1", "lit": [{"src": "shekalim", "seg": 38, "segHtml": "<b><mark>זֶה</mark></b><mark> הַיָּם הַגָּדוֹל בִּשְׁלִישׁ יוֹשֵׁב. בְּמֵאָה וְשִׁשִׁים וְשֵׁשׁ וָעוֹד</mark> מִתְחַשֵׁב: וְעָמְקוֹ בְּעֶשְׂרִים וְאַרְבָּעָה לְמֵתַח סוּף. וְסוּף בְּשִׁבְעִים וּשְׁנַיִם לְעוֹגֶל גִיחוֹן. וְגִיחוֹן מַכְפִּיל שִׁשִׁים כְּמִדַּת פְּרָת. וְהַפְּרָת תָּקְפוֹ כְּנֶגֶד שְׁנֵי הַנְּהָרוֹת. וּשְׁנֵי הַנְּהָרוֹת מַעְדִּיפִים בְּאֹרֶךְ הַיַּרְדֵּן. וְהַיַּרְדֵּן מַרְחִיב חֲמִשָׁה כְּיַם הַזְּבוּל. וְיַם הַזְּבוּל מֵאָה וַחֲמִשִׁים מִקְוָאוֹת. וּמִדַּת הַמִּקְוָה כִּשְׁנֵי חֳמָרִים בְּיָבֵשׁ. וְשִׁעוּר כָּל חוֹמֶר כִּשְׁנֵי לְתָכִים. וְכָל לֶתֶךְ יָכִיל חָמֵשׁ אֵיפוֹת. וְכָל אֵיפָה עוֹשָׂה עֲשָׂרָה עֳמָרִים. וְכָל עוֹמֶר שִׁבְעַת רֶבַע וּכְלָה. וְהַכְּלָה אֶחָד מִמֵּאָה וָעוֹבִּסְאָה. וּסְאַת יָבֵשׁ חֲסֵרָה שְׁלִישׁ בַּלַח. וּסְאַת הַלַּח אֶחָד מִשְׁלשָׁה בַּבַּת. וְכָל בַּת מַחֲזֶקֶת שִׁשָׁה בַּהִין. וְהַהִין כֻּלוֹ שְׁנֵים עָשָׂר לוֹג. וָעוֹד, הַלוֹג מִתְחַלֵּק לְאַרְבַּעַת רְבָעִים וְרֶבַע מוּכָן לְרִבּוּעַ כּוֹס יְשׁוּעות. וְהַכּוֹס סוֹבֵב אֶצְבָּעַיִם עַל אֶצְבָּעַיִם. וְעַל גוֹבַהּ חָסֵר שְׁתוּת מֵאֶצְבָּעַיִם:", "note": "התאמה חלקית: בסילוק לפרשת שקלים הנוסח \"זה הים הגדול בשליש יושב במאה וששים ושש ועוד\". התוספות מייחסים לה\"ר בנימין ביוצר שלו, וכאן הוא בסילוק המיוחס לקליר.", "a": 36, "b": 41, "head": null}], "said": ["rishon", "ביוצר שלו"], "when": [["shekalim", "text", "סלוק אז ראית וספרת (תוס' מייחסים לה\"ר בנימין)"]]}, {"id": "e44", "sec": "tosafos", "ref": "Tosafot on Chagigah 13a:4:1", "label": "תוס' חגיגה יג. ד\"ה ורגלי החיות", "paytan": "הקליר", "kind": "line", "quotes": ["וחיות אשר הנה מרובעות לכסא כף רגל חמש מאות וחמש עשרה"], "rishonHtml": "ורגלי החיות כנגד כולם. יש מגיהין בקדושתא שיסד הקליר <mark>וחיות אשר הנה מרובעות לכסא כף רגל חמש מאות וחמש עשרה</mark> ומוחקים הוי\"ו ואומרים כי כן עולה לפי חשבון שבכאן למנין ז' רקיעים וח' אוירים הוא ט\"ו פעמים ת\"ק והיינו מנין ישרה ש\"ר ת\"ק וי\"ה לסימנא שכן עולה ט\"ו פעמים כך ומיהו בחנם מחקוהו שיסד דבריו ע\"פ הירושלמי דהרואה א\"ר לוי מארץ ועד לרקיע מהלך ת\"ק שנה אמר ר' ברכיה ור' חלבו בש\"ר (בא) סמוקה גדול מזה רגל אחד כמנין ישר\"ה ראה כמה גבוה מעולמו כו' משמע כמנין שיסד ת\"ק ט\"ו וכן היה דרכו שבכמה מקומות היה מניח שיטת הש\"ס שלנו כדי לאחוז שיטת הש\"ס ירושלמי שהוא היה תנא והוא היה ר\"א ברבי שמעון דקרי עליה מכל אבקת רוכל תנא קרא קרובץ ופייטן (ויקרא רבה פ\"ל) ובימיו מקדשים ע\"פ הראייה שמעולם לא יסד רק קרובץ מיום (אחד):", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/%D7%AA%D7%9C%D7%9E%D7%95%D7%93_%D7%91%D7%91%D7%9C%D7%99", "url": "https://www.sefaria.org/Tosafot_on_Chagigah_13a:4:1", "lit": [], "said": ["rishon", "בקדושתא"], "when": [["rh", "other", "אופן דמוסף, לפי תוס' ר\"ה ח:"]]}, {"id": "e45", "sec": "tosafos", "ref": "Tosafot on Yevamot 16b:6:1", "label": "תוס' יבמות טז: ד\"ה פסוק זה שר העולם", "paytan": "הפייט", "kind": "line", "quotes": ["השר המשרת נער נקרא הוא מטטרון הנכבד והנורא", "תוקף מטטרון שר הנהפך לאש מבשר"], "rishonHtml": "פסוק זה שר העולם אמרו - קשיא לר\"ת דעשה הפייט <mark>השר המשרת נער נקרא הוא מטטרון הנכבד והנורא</mark> אלמא מטטרון הוא שר העולם שנקרא נער ובפיוט אחר יסד <mark>תוקף מטטרון שר הנהפך לאש מבשר</mark> משמע דחנוך הוא מטטרון ואי אפשר שיהיה חנוך שר העולם דבפרק אלו טרפות (חולין ס. ושם) אמר דבששת ימי בראשית פתח שר העולם ואמר ישמח ה' במעשיו וחנוך לא היה במעשה בראשית וי\"ל דמטטרון אין זה שר העולם והא דנקרא נער לא משום דכתיב נער הייתי וגם זקנתי אלא נער שכן היה שמו ובפסיקתא בח' שמות של מטטרון מונה נמי נער ועוד דאגדות חולקות זו על זו דבבראשית רבה י\"א דחנוך מת כדמתרגמי' כי לקח אותו (בראשית ה׳:כ״ד) המית יתיה ובריש מסכת דרך ארץ משמע דנכנס לג\"ע בחייו:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Yevamot_16b:6:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e46", "sec": "tosafos", "ref": "Tosafot on Bava Batra 14a:13:1", "label": "תוס' ב\"ב יד. ד\"ה שבהן עמודים עומדין", "paytan": "הפייט", "kind": "line", "quotes": ["תבנית אות יוסף עמודיו עשה כסף"], "rishonHtml": "שבהן עמודים עומדין. נראה לר\"ת דסימן להעמדת ישראל היה ולא עשאום של זהב שלא להזכיר מעשה העגל דאין קטיגור נעשה סניגור וכן אמרינן [בר\"ה] (דף כו.) דמשום הכי לא היה כהן משמש לפני ולפנים ביוה\"כ בבגדי זהב משום דאין קטיגור נעשה סניגור והתם פריך והא הוה ארון שהיה של זהב והיה לפנים ומשני מכפר קאמרי' והני עמודים נמי היו כמו מכפר שהם עשוים סימן להעמדת ישראל והוא שיסר הפייט <mark>תבנית אות יוסף עמודיו עשה כסף</mark> בשביל תבנית אות יוסף סימן של יוסף דהיינו עגל דיוסף נקרא שור שנאמר (דברים ל״ג:י״ז) בכור שורו הדר לו לכך עמודיו עשה כסף ולא זהב שלא להזכיר במעשה העגל:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Bava_Batra_14a:13:1", "lit": [], "said": ["user", "יוצר ליום א' של ראש השנה (לפי מסירת מרדכי, טרם אומת בטקסט)"], "when": [["rh", "user", "יוצר יום א'"]]}, {"id": "e47", "sec": "tosafos", "ref": "Tosafot on Bava Batra 145b:2:1", "label": "תוס' ב\"ב קמה: ד\"ה ואין השביעית משמטתה", "paytan": "ר' אליהו הזקן", "kind": "line", "quotes": ["זמן עשר כסף כי ילונו בחצי ימיו יעזבנו"], "rishonHtml": "ואין השביעית משמטתה דלא קרי ביה לא יגוש. מכאן היה מביא ר\"ת ראיה דקיימא לן כלישנא בתרא דפרק קמא דמכות (דף ג: ושם ד\"ה א\"ד) דאמר רב יהודה אמר שמואל המלוה את חבירו לעשר שנים אין שביעית משמטתו ואע\"ג דאתי לידי לא יגוש השתא מיהא לא קרינן ביה לא יגוש דהכי נמי משמע הכא דכיון דלא קרינא ביה בשושבינות לא שייך ביה למימר דשביעית משמטתה ועל ידי כן מגיה ר' יעקב מה שיסד הפייט ר' אליהו הזקן <mark>זמן עשר כסף כי ילונו בחצי ימיו יעזבנו</mark> ולישנא קמא דפרק קמא דמכות (שם) אית ליה דהמלוה לחבירו לי' שנים שביעית משמטתו ואין ר\"ת פוסק כן אלא כלישנא בתרא דאית ליה אין שביעית משמטתו ומגיה זמן עשר כסף כי ילונו ולא במשפט בחצי ימיו יעזבנו ואין נראה לר\"י ראיה מכאן דלא שייכא כלל שושבינות למלוה שהרי מכמה דברים הם חלוקים זה מזה כדמשמע הכא והכא הכי פירושו אין שביעית משמטתו דלא קרינא ביה לא יגוש ושמא לעולם לא יבא לידי לא יגוש שיכול לומר לו בבתולה אני עושה עמך או שמא לא ישא אשה אבל מלוה שלבסוף בא לידי לא יגוש שביעית משמטתה:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Bava_Batra_145b:2:1", "lit": [], "said": null, "when": [["azharos", "rishon", "באזהרות"]]}, {"id": "e48", "sec": "tosafos", "ref": "Tosafot on Avodah Zarah 17a:7:1", "label": "תוס' ע\"ז יז. ד\"ה לעלוקה", "paytan": "הפייט", "kind": "line", "quotes": ["יקדו בהבהבי עלק"], "rishonHtml": "לעלוקה -  לפי הפשט היינו גיהנם וכן יסד הפייט בזולת של חנוכה <mark>יקדו בהבהבי עלק</mark> ור\"ת הקשה דבפ\"ב דעירובין (דף יט. ושם ד\"ה והאיכא) דחשיב שמות גיהנם לא קחשיב האי לכך נראה לו דשם חכם הוא כמו (משלי ל) לאיתיאל (ושם לא) למואל אבל אין לומר שהוא משמות שלמה כמו אגור וקהלת דבמדרש של ג' דברים קחשיב איתיאל בשמות שלמה ולא קחשיב האי בהדייהו:", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/תלמוד_בבלי", "url": "https://www.sefaria.org/Tosafot_on_Avodah_Zarah_17a:7:1", "lit": [], "said": ["rishon", "בזולת של חנוכה"], "when": [["chanukah", "rishon", "זולת של חנוכה"]]}, {"id": "e49", "sec": "tosafos", "ref": "Tosafot on Avodah Zarah 35a:7:1", "label": "תוס' ע\"ז לה. ד\"ה מאי שנא האי קרא", "paytan": "הקליר", "kind": "line", "quotes": ["אין להרהר על מה נחקקה שכולם נתנו בנשיקה"], "rishonHtml": "מאי שנא האי קרא דשייליה -  ומסיק מרישא דקרא ירושלמי אם להפליגו נתכוין הוה לו להפליגו בדברים אחרים בה' מקראות שבתורה שהסימן ממ\"ש א\"ו מחר משוקדים שאת ארור וקם א\"ר אילא דברים שמשיקין עליהם את הפה שנאמר ישקני מנשיקות פיהו ר\"ש בר חגי בשם ר' שמואל בר נחמני כבשים ללבושך וגו' כבשים כתיב הא כיצד בשעה שתלמידיך קטנים כבוש לפניהם ד\"ת הגדילו ונעשו כעתודים גלה להם רזי תורה וקתני התם דר' ישמעאל קטן היה באותה שעה ומסייע להדא דתני ר\"ש בן יוחי ואלה המשפטים אשר תשים לפניהם מה הסימן הזאת אינה נגלית לכל בריה ובריה כך אין לך רשות לשקע עצמך על ד\"ת אלא בפני אדם כשר ונראה כי זהו טעם תלמוד שלנו דקאמר בסמוך כי גזרי גזירתא במערבא כו' אלא שאינו מפרשו כאן היטב ואומר מורי הר\"ר אלחנן שזהו מה שיסד הקליר בפרשת פרה אדומה <mark>אין להרהר על מה נחקקה שכולם נתנו בנשיקה</mark> לשון משיקין עליהם את הפה:", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/תלמוד_בבלי", "url": "https://www.sefaria.org/Tosafot_on_Avodah_Zarah_35a:7:1", "lit": [{"src": "parah", "seg": 26, "segHtml": "<b>בְּכֵן</b> אֵין לְהָבִין סוֹד תּוֹרָתֶךָ. וְלֹא זִקּוּק אִמְרָתֶךָ. וְלֹא צֵרוּף גְּזֵרוֹתֶיךָ: בְּכֵן אֵין לְהָמִיר. וְלֹא לְהַתְמִיר. אֵין לְהַרְהֵר. וְלֹא לְחַרְחֵר. אֵין לֵידַע וְלֹא לְיַדַּע. עֲמוּקָּה מִשְּׁאוֹל מַה תֵּדָע. נָעוּ מַעְגְּלוֹתֶיהָ לֹא תֵדָע: זוֹ בַּאֲמִירָה וְזוֹ בִּגְזֵרָה. זוֹ בַּאֲסִיפָה וְזוֹ בַּחֲסִיפָה. זוֹ בִּנְשִׁיקָה וְזוֹ בִּתְשׁוּקָה. זוֹ בִּכְבִישָׁה וְזוֹ בְּהַפְרָשָׁה. זוֹ בִדְרִישָׁה וְזוֹ בַּחֲרִישָׁה: וְכָל אִמְרָהּ הֶחָקוּק בָּהּ חֻקָּה. <mark>אֵין לְהַרְהֵר וְלוֹמַר עַל מַה נֶחֱקָקָה</mark>. שֶׁכַּךְ נִתְּנָה בִּנְשִׁיקָה: וְכֻלָּם נְכוֹחִים לַמֵּבִין. וְכָל הַמַּשְׂכִּיל יָבִין. חוּץ מִטַּעֲמֵי פָרָה שֶׁאֵין לְהָבִין. וְכָל חֲכַם לֵב יִדַּל מִבִּין. חֲפָצֶיהָ אֵין לְהָבִין: וּבִשְׁמוֹת תְּעוּדָה הִיא נְקוּבָה. לְכָל קָרְבַּן שַׁי לֹא שָׁוָה. שֶׁהֵם זְכָרִים וְהִיא נְקֵבָה. לְטַהֵר שִׁמְצַת עֵגֶל תּוֹעֵבָה:", "note": "בנוסח הסידור נוספה המילה \"ולומר\".", "a": 25, "b": 28, "head": null}], "said": ["rishon", "בפרשת פרה אדומה"], "when": [["parah", "text", "יוצר"]]}, {"id": "e50", "sec": "tosafos", "ref": "Tosafot on Avodah Zarah 74b:8:1", "label": "תוס' ע\"ז עד: ד\"ה דרש רבא נעוה ארתחו", "paytan": "רבינו יוסף ט\"ע", "kind": "line", "quotes": ["קדירות אין צריך לפלחא כו' וקערות מותרות כי שקיל מדורא עלייהו לאנחא"], "rishonHtml": "דרש רבא נעוה ארתחו -  פירוש הגעילו הגתיות הגדולים מכאן אומר ר\"ת דעירוי ככלי ראשון מדאמר הכא דעל ידי עירוי מפליט היין הבלוע בגת דעל כרחך ע\"י עירוי קאמר הכא שהרי הגת גדולה וכבידה שאין יכולין לתתה לתוך יורה מרותחת כדי להגעילה אלא ע\"כ על ידי עירוי קאמר והשתא כיון דהוה ככלי ראשון אם כן הני כלים שנאסרו ע\"י כלי ראשון סגי להו בהגעלה ע\"י עירוי אבל רשב\"ם חולק על ר\"ת ואומר דעירוי ככלי שני הוא לגמרי והא דמשמע הכא דגת סגי לה בעירוי שאני יין נסך דתשמישו ע\"י צונן ועיקר דברי רשב\"ם ור\"ת במסכת שבת פרק כירה (שבת דף מב. ושם) האילפס והקדרה שהעבירן מרותחין ושם האריכו ומסקנא דמילתא פי' רבינו ברוך דמילתא דעירוי תליא בפלוגתא דרב ושמואל דפ' כיצד צולין בפסחים (דף עו.) דפליגי אי תתאה גבר אי עילאה גבר וקיימא לן כמאן דאמר תתאה גבר מיהו גם עילאה מבשל ומבליע כדי קליפה דאדמיקר ליה בלע כדאמרינן פ' כיצד צולין הלכך עירוי אינו לא ככלי ראשון ולא ככלי שני לגמרי אלא מבשל ומבליע הוא כדי קליפה ולא יותר וא\"כ כלים שנאסרו ע\"י כלי ראשון שהם בלועים מעבר לעבר לא סגי בעירוי שהרי העירוי אינו מפליט אלא כדי קליפה ולא יותר והני קערות שהם בולעות על ידי עירוי היה נראה כמו כן דסגי להו בעירוי להגעילן וכן פירשתי בסדר ביעור חמץ בקרובץ שבת הגדול שיסד רבינו יוסף ט\"ע (פחז) <mark>קדירות אין צריך לפלחא כו' וקערות מותרות כי שקיל מדורא עלייהו לאנחא</mark> ומיהו אין הלכה כך אלא צריך להגעילן בכלי ראשון משום דפעמים שתוחבין הקערות בתוך הכלי ראשון ותוך יורה מרותחת והשתא דפירשתי עירוי אינו לא מבליע ולא מפליט רק כדי קליפה אם כן הני חביות של עובדי כוכבים סגי להו בעירוי דומיא דגת דקאמר הכא נעוה ארתחו ואם היה מנסרן הנגר וקולפן במלקט וברהיטני ומסיר הקליפה של צד היין סגי בהכי בלא עירוי דהא כי נעביד להו עירוי אינו מפליט עירוי כי אם כדי קליפה כו':", "version": "Vilna Edition", "source": "https://he.wikisource.org/wiki/תלמוד_בבלי", "url": "https://www.sefaria.org/Tosafot_on_Avodah_Zarah_74b:8:1", "lit": [{"src": "hagadol", "seg": 42, "segHtml": "<b>אֱלֹהֵי</b> הָרוּחוֹת לְכָל בָּשָׂר. חוֹק לְעַמּוֹ מָסָר. וְהִזְהִירָם בִּכְתָב מוּסָר. לִבְדּוֹק חָמֵץ אוֹר לְאַרְבָּעָה עָשָׂר: בְּשָׁעָה שֶׁאֵין בְּנֵי אָדָם מְצוּיִים בְּשׁוּקָא. אוֹר הַנֵּר יָפֶה לִבְדִיקָה. אֵין בּוֹדְקִין לֹא לְאוֹר הַחַמָּה וְלֹא לְאוֹר הַלְּבָנָה וְלֹא לְאוֹר הָאֲבוּקָה. וְצָרִיךְ לְבָרֵךְ עַל בִּעוּר חָמֵץ כְּחֻקָּה: גָּמַר מְנַטְּרֵהּ עַד דְּבַתְרָא. וּמִיַד צָרִיךְ לְבַטֵל הַשְׁאָר בַּאֲמִירָה. וְלֵימָא הָכִי כָּל חֲמִירָא דְּאִיכָּא בַּהֲדָא דִירָה. דְּלָא חֲמִתֵּיהּ וּדְלָא בִעַרְתֵּיהּ לִבָּטֵל וְלֶהֱוֵי כְּעַפְרָא: דְּאִי מִשְׁתַּכַּח לְאַחַר אוֹתָהּ שָׁעָה. אֵינוֹ חַיָּב בְּבַל יֵרָאֶה וּבְבַל יִמָּצֵא לְפוֹשְׁעָה. וְהָרוֹצֶה אַחַר בְּדִיקָתוֹ לֶאֱכוֹל חָמֵץ וּלְשָׂבְעָה. מַה שֶׁמְּשַׁיֵּר יַנִּיחֶנּוּ בְּצִנְעָה: הֵיכָא דְבָדַק בְּחוֹרֵי בֵיתָא. וְהִנִיחַ אַרְבַּע אוֹ חָמֵשׁ רִפְתָּא. וְאַשְׁכַּח דְּחָדָא מִנַּיְהוּ פַּחֲתָא. לִבְדּוֹק מֵרֵישָׁא שֶׁמָּא חוּלְדָא לְקָחַתָּהּ: וְכֵן תָּנוּ רַבָּנָן בְּפִרְקִין. דְּחוֹרֵי בֵיתָא וּנְקִיקִין. עִילָאֵי וְתַתָּאֵי אֵינָן נִבְדָּקִין. וְאֶמְצָעִים זְקוּקִין: זִהֲרוּ גַּג הַיָּצִיעַ וְגַג מִגְדָּלִין. וְרֶפֶת בָּקָר וּמַתְבֵּן וְלוּלִין. וְאוֹצְרוֹת יַיִן וְשֶׁמֶן הַנְעוּלִין. לִבְדּוֹק חָמֵץ בְּלִי עוֹלִין: חוֹר שֶׁבֵּין אָדָם לַחֲבֵרוֹ. זֶה וְזֶה בּוֹדֵק עַד שֶׁמַּגִיעַ וּמְבַטֵּל שְׁאָרוֹ. וְכֵן בֵּין יְהוּדִי וְעוֹבֵד כּוֹכָבִים חַיָּב לְבַעֲרוֹ. פְּלֵימוֹ מֵקַל שֶׁמָּא יֹאמַר הָעוֹבֵד כּוֹכָבִים כְּשָׁפוֹ וַחֲבָרוֹ: טָעֲנוּ הַמְפָרֵשׁ וְהַיּוֹצֵא בִשְׁיָרָא. וְאֵין דַּעְתּוֹ קוֹדֶם פֶּסַח לְחָזְרָה. תּוֹךְ שְׁלֹשִׁים יוֹם בָּעֵי לְבָעֵר חֲמִירָא. לִפְנֵי שְׁלֹשִׁים יוֹם אֵין זָקוּק לְבַעֲרָה: יִשְׂרָאֵל דְּחָמֵץ אִתְפַּקֵּד לֵיהּ. וְלֵיתֵיהּ לְמָרֵיהּ לְמִשְׁקְלֵיהּ נַטְרֵיהּ עַד אַרְבַּע דְּחָזֵי לְאָכְלֵיהּ. שְׁלִים אַרְבַּע וְלֹא אָתָא לְנָכְרִי מְזַבִּין לֵיהּ: כְּשֶׁנָפְלָה מַפּוֹלֶת עַל חָמֵץ בְּעַרְבֵי פְּסָחִים. וְכֶלֶב אֵין יָכוֹל לְחַפֵּשׂ אַחֲרָיו בְּטוּחִים. הֲרֵי הוּא כִּמְבוּעָר לְרֵעִים פִּקְחִים. וְכַמָּה חֲפִישַׂת הַכֶּלֶב שְׁלֹשָׁה טְפָחִים: לִמְּדוּ בֵּי מִלְחֵי וּבֵי קִירֵי נְקוּבִים. וּבֵי תְמָרִים וְצִיבִים. לִבְדוֹק אוֹתָם חַיָּבִים. וְחָצֵר פְּטוּרָה מִפְּנֵי הָעוֹרְבִים: מוֹצֵא חָמֵץ בַּפֶּסַח בְּתוֹךְ בֵּיתוֹ. כּוֹפֶה עָלָיו כֶּלִי בְּלִי רְאוֹתוֹ. וְאִם שֶׁל הֶקְדֵּשׁ הוּא אֵין צָרִיךְ לְכַסּוֹתוֹ. לְפִי שֶׁבְּדֵלִין מֵאוֹתוֹ: נָפֵי וּפַתִּילֵי וְיוֹרָה. דְּאִשְׁתַּמֵּשׁ בְּהוּ חַמִּין חֲמִירָא. צָרִיךְ לְגַעֲלִינְהוּ וְיַנִּיחַ בְּגוֹ רַבָּא זְעֵירָא. וּלְרַבָּא לֶעֱבַד גְּדַנְפָא וּלְרַתְחֵיהּ בְּנוּרָא: סַכִּינֵי דְּאִשְׁתַּמֵּשׁ בְּהוּ חֲמִירָא לַאֲרוּחִין. אִם אֶפְשַׁר לַעֲשׂוֹתָן חֲדָשִׁים הֵם מְשֻׁבָּחִין. וְאִי לָא מַגְעִילָן בְּרוֹתְחִין. וּבִכְלִי רִאשׁוֹן הֵם מְצוּחֲצָחִין. וְעֵץ פָּרוּר מַגְעִילָן בְּרוֹתְחִין: עִנְּדוּ אַגָּנֵי וּקְצִיעֵי דְקוּנְיָא וּפַחֲרָא. אַף עַל גַּב דְּמַפְלִיט לְהוּ שַׁפִּיר לְאִשְׁתַּמּוּשֵׁי בְהוּ אֲסִירָא. וְאַף עַל גַּב דִּרְוִיחָן וְאִכָּא לְמֵימָר דְּשַׁלִּיט בְּהוּ אַוִּירָא. אֲפִילוּ הָכִי קַיְמָא אִסּוּרָא: פְּחַר <mark>קְדֵרוֹת אֵין צָרִיךְ לְפַלְחָא</mark>. אֲבָל מַשְׁהֵי לֵיהּ עַד בָּתַר פִּסְחָא. וּקְעָרוֹת מֻתָּרוֹת כִּי שָׁקִיל מִדּוּדָא עֲלַיְהוּ לְאַנָּחָא. וּבוּרְמֵי דִּגְלָלָא שַׁרְיָן בַּהֲדָחָה: צָעֵי דְמַשְׁהֵי בְּהוּ חֲמִירָא בִּשְׁאָר יוֹמֵי. כְּבֵית שְׂאוֹר שֶׁחִמּוּצוֹ קָשֶׁה דָּמֵי. וְאִי אַקְרָאֵי אוֹתִיבֵיהּ וְלֹא אִשְׁתָּהֵי עִמֵּיהּ. לְאִשְׁתַּמּוּשֵׁי בְּהוּ שַׁפִּיר דָּמֵי: קִטּוּף בְּיַיִן וְשֶׁמֶן עֲבִידִין. מִלְמֵילַשׁ בְּהוּ לֵילֵי קַמָּאֵי קַפְּדִין. וְאַמְהָן דְּלָא טְבִילָן וְעַבְדִּין. דְלָא לְמֵילַשׁ בְּהוּ הוּא הַדִּין: רְקִיקֵי מַצּוֹת עוֹשִׂין זֵכֶר לְעִגּוּן. וְלִשְׁמָן צָרִיךְ לְשָׁמְרָן מֵחִמּוּץ כְּהָגוּן. וְחֵרֵשׁ שׁוֹטֶה וְקָטָן אֵין לָשִׁין דִּלְמָא יִשְׁגּוּן. אַף עַל גַּב דְאַפְיֵה יִשְׂרָאֵל בַּר דֵּעָה לָא יְנַהֲגוּן: שָׁנוּ שֶׁאֵין לָשִׁין בְּבַת אַחַת לְמַעְלָה מֵחֲמֵשֶׁת רְבָעִים קֶמַח וְכֵן לְחַלָּה. וְהֵן בֵּיצִים כְּמִנְיַן חַלָּה. וְהָעוֹמֶר מוּכַח לָהּ. וְהָאִשָׁה לֹא תָלוּשׁ אֶלָא בְּמַיִם שֶׁלָּנוּ הַלַּיְלָה. תְּמִימִים שָׁנוּ בְּמִשְׁנָה הַמְּהֻלָּלָה. מֵי תַּשְׁמִישׁוֹ שֶׁל נַחְתּוֹם יִשָּׁפֵכוּ. מִפְּנֵי שֶׁמַּחֲמִיצִין סֶלָה. וְאַמְרִינָן שָׁדֵי לְהוּ בְּמָקוֹם מוּדְרָן דְּלָא לֵיתֵי בְּהוּ לִידֵי תַקָּלָה. תַּמוּ הִלְכוֹת בִּעוּר וְהַגְעָלָה:", "note": null, "a": 41, "b": 44, "head": null}], "said": ["rishon", "בסדר ביעור חמץ בקרובץ שבת הגדול"], "when": [["hagadol", "rishon", "קרובץ שבת הגדול"]]}, {"id": "e51", "sec": "tosafos", "ref": "Tosafot on Makkot 3b:4:1", "label": "תוס' מכות ג: ד\"ה איכא דאמרי", "paytan": "אזהרות (הגהת ר\"ת)", "kind": "line", "quotes": ["זמן עשר (כסף) כי ילונו ולא במשפט בחצי ימיו יעזבנו"], "rishonHtml": "איכא דאמרי המלוה חבירו (בשטר) לעשר שנים אין שביעית משמטתו. אומר ר\"ת דהלכה כלישנא בתרא דה\"נ מתני' מסייע ליה וקשיא ללישנא קמא ובאזהרות הגיה ר\"ת <mark>זמן עשר (כסף) כי ילונו ולא במשפט בחצי ימיו יעזבנו</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Makkot_3b:4:1", "lit": [], "said": null, "when": [["azharos", "rishon", "באזהרות"]]}, {"id": "e52", "sec": "tosafos", "ref": "Tosafot on Zevachim 86b:6:1", "label": "תוס' זבחים פו: ד\"ה משום חולשא דכהן גדול", "paytan": "הפייט", "kind": "line", "quotes": ["הוקמו מחצות אפרה לבערה בפייס דשן הבערה"], "rishonHtml": "משום חולשא דכהן גדול מחצות - כאן משמע שעבודת לילה כמו תרומת הדשן וסידור המערכה היו מוטלות עליו והשתא אתי שפיר משום חולשא דכהן גדול שיוכל לנוח אחר תרומת הדשן ולהפסיק כדי לעשות בנחת שחיטת התמיד ועבודת היום אבל אי עבודת לילה בשאר כהנים מאי חולשא איכא וריב\"א פירש ביומא (דף כ:) דלא גרס הכא כהן גדול דתרומת הדשן לא הויא בכהן גדול מדלא חשיב טבילת תרומת הדשן בהדי ה' טבילות וי' קידושין שהיה עושה ביום הכפורים ועוד דפייס דתרומת הדשן חשיב בסדר יום הכפורים ואילו היה בכהן גדול למה ליה להזכיר בסדר יום הכפורים וכן יסד הפייט <mark>הוקמו מחצות אפרה לבערה בפייס דשן הבערה</mark> ומיהו רבינו היה מפרש דאין צריך למוחקו דה\"פ משום חולשא דכהן גדול מקדימין תרומת הדשן וסידור המערכה ושריפת אברים שלא נתעכלו מבערב בשאר כהנים כדי שעל ידי כן יהא מזומן כה\"ג להתחיל מהבקר כשיעלה עמוד השחר עבודת היום קודם שיהא רעב וחלש:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Zevachim_86b:6:1", "lit": [], "said": null, "when": [["yk", "context", "\"פייס דתרומת הדשן חשיב בסדר יום הכפורים\""]]}, {"id": "e53", "sec": "tosafos", "ref": "Tosafot on Menachot 35b:5:1", "label": "תוס' מנחות לה: ד\"ה וכמה שיעורייהו", "paytan": "ר\"א קליר", "kind": "line", "quotes": ["גיא וכל עפרה בצרדה הכילו"], "rishonHtml": "וכמה שיעורייהו. לכאורה בתפילין של ראש איירי דמר פשיט שדי להו על כתפיו לאחוריו ומר מתלית להו אבל הערוך פי' בערך צרדה דכתב בילמדנו בסוף בא אל פרעה ושיעור רצועה של יד עד אצבע צרדה ומאי צרדה אמצעי פי' היא אצבע ארוכה ועוד הביא בערוך דתניא בתוספתא איזוהי אצבע צרדה זו אצבע גדולה של ימין ובקונט' פי' דהיא אצבע הסמוכה לגודל ור\"א קליר יסד כפי' הערוך בסילוק של פרשת שקלים <mark>גיא וכל עפרה בצרדה הכילו</mark> פי' משום דכתיב (ישעיהו מ׳:י״ב) וכל בשליש עפר הארץ והיינו אצבע אמצעי שהוא שלישי ובפ\"ק דיומא (דף יט:) דאמרינן גבי כ\"ג שמכין לפניו באצבע צרדה הדבר ידוע שא\"א להשמיע קול אלא כשמכה באמצעי ולפי' זה דחזי פשוט היינו מגודל עד אמה וכפוף מאצבע עד אמה ובערוך פי' בערך כף דכפוף היינו מעיקר גודל עד ראש אצבע. כשהן דבוקות זו בזו ופשוט מראש אצבע עד ראש גודל כשהן פשוטות וי\"מ עד אצבע צרדה שצריך לעשות הרצועות ארוכות ממקום הנחתן עד אצבע צרדה וכפוף היינו שכופף את אצבעו ומשער הרצועה עד שם ופשוטה היינו שמשער הרצועה ממקום הנחה עד ראש אצבע פשוטה ובתפילין של ראש משערין הרצועות שתגיע ראש האחד עד טיבורו וראש השני עד הלב ושמא שום מדרש יש וגבי תפילין של יד הוא דאמרינן בפ' שני דברכות (דף יג:) ושמתם את דברי אלה על לבבכם שתהא שימה כנגד הלב ובשימושא רבה דתפילין יש דליפשו רצועי עד דלימטי לחדא כנגד מילה מימינא ולחדא כנגד הלב משמאלא עוד יש אומר דמצות שיעור רוחב הרצועות יותר מכחטה ופחות מכשעורה ואם יותר כשר. מ\"ר:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Menachot_35b:5:1", "lit": [{"src": "shekalim", "seg": 41, "segHtml": "<b>וְעַד</b> מָקוֹם שֶׁאֱנוֹשׁ יָכוֹל לִמְנוֹת. נִמְסַר לוֹ לִמְדּוֹד וְגַם לִמְנוֹת: לְפִי כֹחוֹ וּלְפִי מִעוּט חֵילוֹ. הָקְצַב לוֹ מִעוּט הוֹן שִׁקְלוֹ. וּלְפִי שִׂכְלוֹ כֵּן יְהִי הִלּוּלוֹ. גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ חֵילוֹ. עַל כֵּן אוֹחִיל לוֹ: כִּי מִדָתוֹ וְשִׁקְלוֹ לְפִי גָדְלוֹ. כָּל אוֹצְרוֹת שֶׁלֶג וְרוּחַ פִּלֵס בְּמִשְׁקָלוֹ: וּמֵי בְּרֵאשִׁית מָדַד מְלֹא שָׁעֳלוֹ. וּשְׁמֵי רוֹם תִּכֵּן זֶרְתּוֹ מְלֹא. וְכָל הַרְרֵי קֶדֶם בְּאֶצְבָּעוֹ שְׁקָלוֹ. וְגִבְעוֹת עוֹלָם תָּמַךְ בְּהוֹד אֲגֻדָּלוֹ. <mark>גֵּיא וְכָל עֲפָרָהּ בִּצְרָדָה הֱכִיל</mark>וֹ. לְחוֹלֵל תַּנִין מְיֻמֶּנֶת הֵכִין לוֹ: נִמְצֵאת כָּל מִדַּת יְצִירַת עוֹלָמוֹ. כִּמְלֹא פִסַּת יָד הִיא רִשׁוּמוֹ. וּכְקָמֵיעַ בְּיַד גִּבּוֹר בִּזְרוֹעַ חוֹתָמוֹ. וְאֵין לִקְצוֹב רוֹב מֶחְקְרֵי תַעֲצוּמוֹ. אֲשֶׁר מָדַד וְקָצַב וְשִׁעֵר בִּמְרוֹמוֹ. עַל כָּל מִדַת כִּסְאוֹ וַהֲדוֹמוֹ: מִדַּת בַּת מֶלֶךְ בַּכֹּל מְעֻלָה. בְּאֹרֶךְ בְּרוֹחַב בְּעוֹמֶק בְּגּוֹבַהּ מִתְעַלָּה. כִּי יֵשׁ קֵץ לְכָל תִּכְלָה. וְאִמְרָהּ רְחָבָה לָעַד לֹא כָלָה: מִדַּת עוֹלָם כִּמְלֹא פִסַּת יָד. וּמִדָּתָהּ נְתוּנָה בִּימִין וּזְרוֹעַ וָיָד: מִדַּת עוֹלָם כְּמִזֶּרֶת וְעַד אֲגֻדָּל. וּמִדָּתָהּ בְּקַו אֲשֶׁר מְאֹד גָּדָל: מִדַּת עוֹלָם נִמְדֶּדֶת בִּשְׁלִישׁ אַמָּה. וּמִדָּתָהּ עוֹלָה וְנוֹסֶבֶת כְּאַלְפַּיִם אַמָּה: כְּמַרְאֵה הַמִּדָּה אֲשֶׁר צִיר רָאָה. מְגִלָּה עֶשְׂרִים עַל עֶשֶׂר אַמָּה. עָפָה אַרְבָּעִים עַל עֶשְׂרִים וּשְׁמוֹנֶה מֵאוֹת אַמָּה. וְכָל הָעוֹלָם כֻּלּוֹ בִּשְׁלִישׁ אַמָּה: נִמְצֵאת דָּת בְּמִדוֹתֶיהָ רְחָבָה וַאֲרֻכָּה. אַלְפַּיִם וְאַרְבַּע מֵאוֹת בָּעוֹלָם מַאֲרִיכָה. וְהִיא נָתְנָה לָעוֹלָם מַרְפֵּא וַאֲרוּכָה. וּבִימִינָהּ קוֹצֶבֶת כָּל יְמֵי אַרְכָה, וּבִשְׂמֹאלָהּ שׁוֹקֶלֶת עוֹשֶׁר וְכָבוֹד וּבְרָכָה: וְהִיא הוֹדִיעָה אֶת כָּל חֶבְיוֹן סְתוּרוֹת. וְהוּא קָצְבָה כָּל מִדּוֹת סְפוּרוֹת. וְהִיא פָּתְחָה אֶת כָּל סְגוּרוֹת. וְהִיא שָׁקְלָה וְאָצְרָה אֶת כָּל אוֹצָרוֹת: וְהִיא חָקְרָה הֲמוֹן מִפְקַד תַּחְתּוֹנִים. וְהִיא נָתְנָה מִסְפַּר גְּדוּדֵי עֶלְיוֹנִים: וְהִיא שִׁעֲרָה קוֹמַת אַלְפֵי שִׁנְאַנִּים. אֲשֶׁר זֶה מִזֶּה בְּקוֹמָתָם מְשֻׁנִּים: יֵשׁ כְּמִדַּת הַיָּם הַגָּדוֹל קוֹמָתָם. וְיֵשׁ כַּחֲלָלוֹ שֶׁל עוֹלָם הֲקָמָתָם. וְיֵשׁ כִּמְלֹא כָל הָעוֹלָם תְּקוּמָתָם. יֵשׁ לִשְׁתֵּי טִיסוֹת טָסִים עוֹלָם. וְיֵשׁ לְטִיסָה אַחַת עָפִים עוֹלָם. וְכָל אֶחָד וְאֶחָד בְּמַחֲנֵהוּ נֶעְלָם. וּבִמְחִיצָתוֹ צָג וְחָשׁ וְדוּמָם וְנֶאֱלָם. עַד יִתֵּן רְשׁוּת מֶלֶךְ הָעוֹלָם. וְחָשִׁים עַד יַמְלִיכוּהוּ עַם עוֹלָם. וְאָז יִפְצְחוּ לְפָאֵר אֱלֹהֵי עוֹלָם. וּמִשֶׁהֵם מְפָאֲרִים עוֹד לֹא שׁוֹנִים. כִּי בִנְהַר דִינוֹר שָׂחִים וְנִתָּנִים. וְעוֹד מֶנּוּ נֶחֱצָבִים וּמִתְחַדְשִׁים כָּרִאשׁוֹנִים. שֶׁבַח וְהַלֵל וָרוֹן לָאֵל מְשַׁנְּנִים. וְכִפֵּי קֶשֶׁת עִם כְּנַף רְנָנִים. זֶמֶר וָשִׁיר וְעוֹז וָרֶנֶן מְרַנְּנִים. וּשְׂרָפִים הַמְעֻלִּים עַל כָּל שִׁנְאֲנִּים. שֵׁשׁ שֵׁשׁ כְּנָפַיִם בְּגֶוְיָם חֲנוּנִים. מִמַעַל לְיוֹשֵׁב עֲרָבוֹת בַּכֵּס נְתוּנִים. וּלְיוֹשֵׁב עַל כִּסֵּא בְּחִילָה מְנַגְּנִים. מְצוֹא חֵן בְּנִגּוּנָם הֵם מְחַנְּנִים. וְקוֹדֶם לְכָל צְבָא מַעַל עוֹנִים. וְשִׁלוּשׁ קְדֻשָׁה לְרָם וְנִשָׂא נוֹתְנִים. כּוֹרְעִים וּמִשְׁתַּחֲוִים הֲמוֹנִים הֲמוֹנִים. לְנַעֲרָץ בְּסוֹד הֲמוֹן גְּדוּדֵי עֶלְיוֹנִים. וְנִקְדָּשׁ בְּאַלְפֵי רִבְבוֹת תַּחְתּוֹנִים:", "note": null, "a": 36, "b": 41, "head": null}], "said": ["rishon", "בסילוק של פרשת שקלים"], "when": [["shekalim", "text", "סילוק"]]}, {"id": "e54", "sec": "tosafos", "ref": "Tosafot on Menachot 41b:13:1", "label": "תוס' מנחות מא: ד\"ה בית שמאי אומרים ארבע", "paytan": "רבי שלמה ספרדי", "kind": "line", "quotes": ["המשולשל יהא נפשל כדי אצבעות ארבע"], "rishonHtml": "בית שמאי אומרים ארבע. פירש בקונטרס הפתיל יהא ארבע נמצא הגדיל שנים ורבינו תם פירש דאגדיל קאי והענף שמנה הרי שנים עשר וכן אנו נוהגין וכן משמע בספרי בפרשת כי תצא גדילים למה נאמר לפי שנאמר ועשו להם ציצית שומע אני יעשה חוט א' בפני עצמו ת\"ל גדילים כמה גדיל נעשית אין פחות משלשה חוטין כדברי בית הלל ובית שמאי אומרים מארבע חוטין של תכלת וארבעה של לבן על ארבע ארבע אצבעות משמע דאגדיל קאי והקונטרס נמי פירש כן בל\"א פרק על אלו מומין (בכורות דף לט:) וכן יסד רבי שלמה ספרדי <mark>המשולשל יהא נפשל כדי אצבעות ארבע</mark> ונפשל קורא הגדיל כמו מפשילין חבלים לתוכן פרק אלו הן הגולין (מכות דף י.) וכמו אין מפשילין חבלים לתוכן דבפ' בני העיר (מגילה דף כח.):", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Menachot_41b:13:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e55", "sec": "tosafos", "ref": "Tosafot on Chullin 42a:5:2", "label": "תוס' חולין מב. ד\"ה דרוסת הנץ", "paytan": "הפייט", "kind": "line", "quotes": ["תוחלת ישראל מדרס הגס ונץ אפרוחים קרוצים"], "rishonHtml": "דרוסת הנץ - גרסי' בתוספתא [פ\"ג] ובערוך [ערך נץ ד'] וכן יסד הפייט בסליחות <mark>תוחלת ישראל מדרס הגס ונץ אפרוחים קרוצים</mark> וטעמא לא משום דסופו לינקב דא\"כ בכלל נקובה היא ומהאי טעמא לא תני במתניתין דמיא לדיותא ודמיא לבישרא אלא טעמא דדרוסה שהארס שורף וסופה למות:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Chullin_42a:5:2", "lit": [], "said": ["rishon", "בסליחות"], "when": [["selichot", "rishon", "בסליחות"]]}, {"id": "e56", "sec": "tosafos", "ref": "Tosafot on Chullin 60a:10:1", "label": "תוס' חולין ס. ד\"ה פסוק זה שר העולם", "paytan": "הפייט", "kind": "line", "quotes": ["תקיף מטטרון שנהפך לאש מבשר", "שר המשרת נער נקרא הוא מטטרון הנכבד והנורא"], "rishonHtml": "פסוק זה שר העולם אמרו - לפי מה שמפרשין דחנוך זה מטטרון כמו שיסד הפייט <mark>תקיף מטטרון שנהפך לאש מבשר</mark> ואומר דהוא שר העולם כמו שיסד הפייט <mark>שר המשרת נער נקרא הוא מטטרון הנכבד והנורא</mark> ואמרינן בפרק קמא דיבמות (דף טז: ושם) נער הייתי גם זקנתי ולא ראיתי פסוק זה שר העולם אמרו וקשה מכאן דמשמע דשר העולם היה בששת ימי בראשית ושמא אגדות הם שחלוקות זו על זו ומי שסובר דמטטרון הוא שר העולם לית ליה דחנוך זה מטטרון א\"נ מה שקרא הפייט למטטרון נער לא בשביל הפסוק של נער הייתי אלא לפי שכתוב בספר יוסיפון דלמטטרון יש לו שבע שמות וחשיב נער וגם מצינו דנער שם מלאך הוא כדכתיב (זכריה ב) רוץ אל הנער הלז:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Chullin_60a:10:1", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e57", "sec": "tosafos", "ref": "Tosafot on Chullin 109b:12:1", "label": "תוס' חולין קט: ד\"ה נדה דם טוהר", "paytan": "ר' אליעזר הקליר", "kind": "line", "quotes": ["מן הדם טחול הדם מטומאת נדה (אשה) טהרת בתולי אשה ומאשת איש יפת תואר לאיש"], "rishonHtml": "נדה דם טוהר - בסלוק של פרשת פרה יסד ר' אליעזר הקליר <mark>מן הדם טחול הדם מטומאת נדה (אשה) טהרת בתולי אשה ומאשת איש יפת תואר לאיש</mark> וכנגד כותית לא פירש והכל עשה ע\"פ הירושלמי:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Chullin_109b:12:1", "lit": [{"src": "parah", "seg": 25, "segHtml": "<b>אֵין</b> לְשׂוֹחֵחַ עוֹצֶם נִפְלְאוֹתֶיךָ. <small>(בכ\"י נוסף אֵין לְהַרְהֵר אַחַר מִדוֹתֶיךָ)</small> אֵין לְהַגִּיד חֵקֶר דָּתוֹתֶיךָ. אֵין לְהָבִין תּוֹקֶף מִפְעֲלוֹתֶיךָ. אֵין לְפַעֲנֵחַ עוֹמֶק פְּלָאוֹתֶיךָ. אֵין לַעֲמוֹד עַל סֵפֶן מִדּוֹתֶיךָ. אֵין לַחֲקוֹר סוֹד <small>(נ\"א חֵקֶר)</small> חִידוֹתֶיךָ. אֵין לְהַשְׁמִיעַ כָּל תְּהִלּוֹתֶיךָ. אֵין לְגַלּוֹת סוֹד עֵדוֹתֶיךָ: הַמְפוֹרָשׁוֹת סְתוּמוֹת. הַגְּלוּיוֹת עֲלוּמוֹת. הַמְּבֹאָרוֹת חֲתוּמוֹת. הַמְּשֻׁנָּנוֹת עֲצוּמוֹת. הַחֲקוּקוֹת רְשׁוּמוֹת: הַחֲסֵרוֹת מְיֻתָּרוֹת. הָאֲסוּרוֹת מֻתָּרוֹת. הַשְּׁחוֹרוֹת צְחוֹרוֹת. הַחֲשׂוּפוֹת אֲטוּרוֹת. הַפְּרוּטוֹת אֲצוּרוֹת. הַכְּלוּלוֹת עֲצוּרוֹת. הַקַּלּוֹת חֲמוּרוֹת. מוֹצִיא מִזָּלוֹת יְקָרוֹת. מַתִּיר מֵאֲסוּרוֹת מֻתָּרוֹת. נוֹתֵן מִטְּמֵאוֹת טְהוֹרוֹת: מִן הַחֵלֶב. שֹׁמֶן הַלֵּב. וּ<mark>מִן הַדָּם טְחוֹל</mark> <small>(נ\"א וְכָּבֵד)</small> הַדָּם. וּמִבָּשָׂר בֶּחָלָב. כְּחַל הֶחָלָב. מִכִּלְאֵי בְגָדִים. תְּכֵלֶת בַּסָּדִין. מֵאֵשֶׁת אָח. יִבּוּם הֶאָח. מֵאֵשֶׁת אִישׁ. יְפַת תּוֹאַר לְאִישׁ. מִטֻּמְאַת נִדַּת אִשָׁה. טָהֳרַת בְּתוּלֵי אִשָּׁה: מֵהַתֵּר אִסּוּר. וּמֵאִסּוּר הַתֵּר. מִטָּמֵא טָהוֹר. וּמִטָּהוֹר טָמֵא. בַּהֶרֶת מְמוּעָט תְּטַמֵּא. פָּרְחָה בְּכֻלּוֹ עוֹד בַּל תְּטַמֵּא. הַמֵּת בַּבַּיִת אֵינוֹ טָמֵא. יָצָא מִמֶּנּוּ אוֹתוֹ מְטַמֵּא. שְׂעִיר יוֹם כִּפּוּר מְכַפֵּר עַל כָּל טָמֵא. וְכָל מַעֲסִיקָיו בְּגָדִים מְטַמֵא. פָּרָה אֲדֻמָּה עוֹשֶׂיהָ מְטַמְּאָה. וְהִיא עֲשׂוּיָה לְטַהֵר כָּל טֻמְאָה. וְאֶפְרָהּ נַעֲשֶׂה אַב הַטֻּמְאָה. וְהִיא מְטַהֶרֶת אֲבִי אֲבוֹת הַטֻּמְאָה:", "note": null, "a": 25, "b": 28, "head": null}], "said": ["rishon", "בסלוק של פרשת פרה"], "when": [["parah", "text", "סלוק"]]}, {"id": "e58", "sec": "tosafos", "ref": "Tosafot on Bekhorot 55b:3:1", "label": "תוס' בכורות נה: ד\"ה הוא פרת דמעיקרא", "paytan": "רבי אליעזר הקליר", "kind": "line", "quotes": ["פרת תוקפו כנגד שני נהרות"], "rishonHtml": "הוא פרת דמעיקרא - פירוש ולא מפני שהוא קטן קורהו רביעי דהוא פרת דמעיקרא ששמו פרת מקודם שמתחיל ליפרד לד' ראשים וכשמתחיל ליפרד יוצאים הנהרים זה לצד זה [וזה לצד זה] ופרת הולך ביושר לדרך הילוכו ובפרשת שקלים יסד רבי אליעזר הקליר בסילוק ד<mark>פרת תוקפו כנגד שני נהרות</mark> וכן משמע בבראשית רבה שהוא גדול שאומרים לפרת מפני מה אין קולך הולך והוא אומר פירותי מעידין עלי אומרים לחדקל מפני מה קולך הולך והוא אומר הלואי אשמיע קולי ואראה משמע דחדקל קטן מפרת וקצת קשה דאמר בפרק כל הנשבעין (שבועות דף מז:) עד הנהר הגדול נהר פרת עבד מלך כמלך דמשמע דוקא משום א\"י קורהו גדול:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Bekhorot_55b:3:1", "lit": [{"src": "shekalim", "seg": 38, "segHtml": "<b>זֶה</b> הַיָּם הַגָּדוֹל בִּשְׁלִישׁ יוֹשֵׁב. בְּמֵאָה וְשִׁשִׁים וְשֵׁשׁ וָעוֹד מִתְחַשֵׁב: וְעָמְקוֹ בְּעֶשְׂרִים וְאַרְבָּעָה לְמֵתַח סוּף. וְסוּף בְּשִׁבְעִים וּשְׁנַיִם לְעוֹגֶל גִיחוֹן. וְגִיחוֹן מַכְפִּיל שִׁשִׁים כְּמִדַּת פְּרָת. וְ<mark>הַפְּרָת תָּקְפוֹ כְּנֶגֶד שְׁנֵי הַנְּהָרוֹת</mark>. וּשְׁנֵי הַנְּהָרוֹת מַעְדִּיפִים בְּאֹרֶךְ הַיַּרְדֵּן. וְהַיַּרְדֵּן מַרְחִיב חֲמִשָׁה כְּיַם הַזְּבוּל. וְיַם הַזְּבוּל מֵאָה וַחֲמִשִׁים מִקְוָאוֹת. וּמִדַּת הַמִּקְוָה כִּשְׁנֵי חֳמָרִים בְּיָבֵשׁ. וְשִׁעוּר כָּל חוֹמֶר כִּשְׁנֵי לְתָכִים. וְכָל לֶתֶךְ יָכִיל חָמֵשׁ אֵיפוֹת. וְכָל אֵיפָה עוֹשָׂה עֲשָׂרָה עֳמָרִים. וְכָל עוֹמֶר שִׁבְעַת רֶבַע וּכְלָה. וְהַכְּלָה אֶחָד מִמֵּאָה וָעוֹבִּסְאָה. וּסְאַת יָבֵשׁ חֲסֵרָה שְׁלִישׁ בַּלַח. וּסְאַת הַלַּח אֶחָד מִשְׁלשָׁה בַּבַּת. וְכָל בַּת מַחֲזֶקֶת שִׁשָׁה בַּהִין. וְהַהִין כֻּלוֹ שְׁנֵים עָשָׂר לוֹג. וָעוֹד, הַלוֹג מִתְחַלֵּק לְאַרְבַּעַת רְבָעִים וְרֶבַע מוּכָן לְרִבּוּעַ כּוֹס יְשׁוּעות. וְהַכּוֹס סוֹבֵב אֶצְבָּעַיִם עַל אֶצְבָּעַיִם. וְעַל גוֹבַהּ חָסֵר שְׁתוּת מֵאֶצְבָּעַיִם:", "note": null, "a": 36, "b": 41, "head": null}], "said": ["rishon", "בפרשת שקלים ... בסילוק"], "when": [["shekalim", "text", "סילוק"]]}, {"id": "e59", "sec": "tosafos", "ref": "Tosafot on Arakhin 2b:6:2", "label": "תוס' ערכין ב: ד\"ה היודע להתעטף", "paytan": "הר' יוסף ט\"ע", "kind": "content", "quotes": ["ומצאתי בסילוק א' שעשה הר' יוסף ט\"ע שנותן ציצית א' מלפניו ואחד מלאחריו מימין וכן לשמאל"], "rishonHtml": "היודע להתעטף - משום דאמר במ\"ק (דף כד.) כל עטיפה שאינה כעטיפת ישמעאלים אינה עטיפה שמעטפין טליתם עד שפמם כדאיתא במדרש. <mark>ומצאתי בסילוק א' שעשה הר' יוסף ט\"ע שנותן ציצית א' מלפניו ואחד מלאחריו מימין וכן לשמאל</mark>:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Arakhin_2b:6:2", "lit": [], "said": null, "when": [["unknown", null, null]]}, {"id": "e60", "sec": "tosafos", "ref": "Tosafot on Niddah 30a:17:1", "label": "תוס' נדה ל. ד\"ה ושמע מינה טבילה בזמנה", "paytan": "רבינו אליהו הזקן", "kind": "content", "quotes": ["רבינו אליהו הזקן שיסד באזהרות טבילה בזמנה על ד' גדילים"], "rishonHtml": "ושמע מינה טבילה בזמנה מצוה. כך פסק ר\"ח דהלכה כב\"ש וב\"ה ותימה דפשיטא דר' יוסי בר' יהודה יאמר דלא פליגי עליה ב\"ש וב\"ה ומעשים בכל יום שאין לך אשה טובלת בזמן טבילת נדה ולא בזמן טבילת שומרת יום כנגד יום וזבה ובפ' בתרא (לקמן נדה דף סז:) נמי אמר מכדי האידנא כולהו ספק זבות שוינהו ניטבלינהו ביממא דז' משמע שלא היו טובלין ביום בשום פעם ו<mark>רבינו אליהו הזקן שיסד באזהרות טבילה בזמנה על ד' גדילים</mark> כולו יסד דלא כהילכתא דה\"נ יסד כר\"א (סנהדרין דף מה.) דאמר כל נסקלין נתלין דדריש ריבוי ומיעוט וקי\"ל דדרשינן כללי ופרטי דהא קיימא לן דקרקע אינה נגזלת:", "version": "Vilna Edition", "source": "https://www.nli.org.il/he/books/NNL_ALEPH001300957", "url": "https://www.sefaria.org/Tosafot_on_Niddah_30a:17:1", "lit": [], "said": ["rishon", "באזהרות"], "when": [["azharos", "rishon", "באזהרות"]]}], "built": "2026-10-07"};
